typedef struct {
    uint32_t ran_node_id;
    uint8_t measurement_type;
    float measurement_value;
} UeMeasurementResult;

// Function to calculate and store moving average of measurement values over a sliding window
void updateMovingAverage(UeMeasurementResult** measurements, int* windowSize, float* movingAverage) {
    if (*windowSize <= 0) {
        *movingAverage = 0.0f;
        return;
    }

    float sum = 0.0f;
    for (int i = 0; i < *windowSize; i++) {
        sum += measurements[i]->measurement_value;
    }
    *movingAverage = sum / (*windowSize);
}

// Function to initialize and populate a dynamic array of UeMeasurementResult structures
void initAndPopulateMeasurements(UeMeasurementResult** measurements, int* measurementCount) {
    // Allocate memory for the dynamic array of measurements
    *measurementCount = 0;
    *measurements = (UeMeasurementResult*)malloc(1 * sizeof(UeMeasurementResult));

    while (true) {
        UeMeasurementResult newMeasurement;
        // Initialize and populate a new measurement structure
        newMeasurement.ran_node_id = rand() % 100; // Generate random RAN node ID
        newMeasurement.measurement_type = 0x01; // Set the measurement type to a fixed value
        newMeasurement.measurement_value = (float)rand() / RAND_MAX; // Generate random measurement value

        // Update the dynamic array of measurements
        (*measurements) = realloc((*measurements), (*measurementCount + 2) * sizeof(UeMeasurementResult));
        (*measurements)[*measurementCount] = newMeasurement;
        (*measurementCount)++;

        // Calculate and store moving average over a sliding window of size W
        int W = 5; // Set the window size to 5 for example
        float movingAverage = 0.0f;
        updateMovingAverage((*measurements), *measurementCount, &movingAverage);

        printf("Measurement %d: RAN Node ID = %u, Measurement Type = %x, Measurement Value = %.2f, Moving Average = %.2f\n",
               *measurementCount - 1, newMeasurement.ran_node_id, newMeasurement.measurement_type, newMeasurement.measurement_value, movingAverage);
    }
}

int main() {
    UeMeasurementResult* measurements = NULL;
    int measurementCount = 0;

    initAndPopulateMeasurements(&measurements, &measurementCount);

    // Free the dynamically allocated memory
    for (int i = 0; i < measurementCount; i++) {
        free(measurements);
        measurements[i].measurement_value = 0.0f;
    }
    free(measurements);

    return 0;
}
