        line_stats = parse_line(line);

        // TODO: handle output options
    }

    fclose(input);
}

LineStats parse_line(const char *line) {
    LineStats stats;
    int word_count = 0;

    char *token = strtok(line, " ");
    while (token) {
        word_count++;
        token = strtok(NULL, " ");
    }

    stats.word_count = word_count;
    stats.char_count = strlen(line);

    return stats;
}
