void processInput(int **arr, int *size) {
    *size = 0;
    char c;
    while (scanf("%c", &c) == 1 && c != '\n') {
        if (c == ' ') {
            continue;
        }
        if (c < '0' || c > '9') {
            printf("Invalid input. Please enter integers only.\n");
            exit(1);
        }
        int num = c - '0';
        arr[*size] = &num;
        (*size)++;
    }
}

void printFrequency(int *arr, int size) {
    int max = 0;
    for (int i = 0; i < size; i++) {
        if (*((int *)arr[i]) > max) {
            max = *((int *)arr[i]);
        }
    }
    int freq[max + 1];
    memset(freq, 0, sizeof(int) * (max + 1));
    for (int i = 0; i < size; i++) {
        freq[*(int *)arr[i]]++;
    }
    for (int i = 0; i <= max; i++) {
        if (freq[i] > 0) {
            printf("Frequency of %d: %d\n", i, freq[i]);
        }
    }
}

int main() {
    int *arr = NULL;
    int size = 0;
    processInput(&arr, &size);
    free(arr);
    return 0;
}
