import logging
from logging.handlers import RotatingFileHandler
from threading import Lock, Condition
import queue
import time
import atexit

class LogProcessor:
    def __init__(self):
        self.log_file = 'logs.txt'
        self.max_log_size = 1000000  # 1MB
        self.backup_interval = 60  # 1 minute
        self.max_backup_files = 5
        self.log_queue = queue.Queue()
        self.log_lock = Lock()
        self.condition = Condition(self.log_lock)
        self.logger = logging.getLogger('LogProcessor')
        self.logger.setLevel(logging.INFO)

    def start(self):
        self.rotate_file_handler = RotatingFileHandler(
            self.log_file, maxBytes=self.max_log_size, backupCount=self.max_backup_files
        )
        self.logger.addHandler(self.rotate_file_handler)
        atexit.register(self.rotate_file_handler.doRollover)
        self.logger.info('LogProcessor started')

    def log_message(self, message):
        with self.condition:
            while not self.log_queue.empty():
                try:
                    self.log_queue.get_nowait().flush()
                except queue.Empty:
                    break
            self.log_queue.put(message)

    def async_log_to_external_service(self):
        # implement external service logging
        pass

    def process_logs(self):
        while True:
            with self.condition:
                if not self.log_queue.empty():
                    try:
                        log_message = self.log_queue.get_nowait()
                        self.rotate_file_handler.handle(log_message)
                        self.async_log_to_external_service()
                    except queue.Empty:
                        break
            time.sleep(0.01)  # process logs in batches

if __name__ == '__main__':
    log_processor = LogProcessor()
    log_processor.start()
    for i in range(10000):
        log_processor.log_message(f'Log entry {i}')
