import hashlib
import requests
import os
import time
from urllib.parse import urlparse

def calculate_hashes(file_path=None, url=None):
    if file_path:
        with open(file_path, 'rb') as f:
            return calculate_hashes_from_file(f)
    elif url:
        retry_count = 0
        while True:
            try:
                r = requests.get(url, stream=True)
                r.raise_for_status()
                break
            except (requests.exceptions.RequestException, TimeoutError) as e:
                if retry_count < 3:
                    print(f"Failed to download {url}. Retrying in {2 ** (retry_count + 1)} seconds...")
                    time.sleep(2 ** (retry_count + 1))
                    retry_count += 1
                else:
                    raise Exception(f"Failed to download {url} after 3 retries. Error: {e}")
        return calculate_hashes_from_response(r)

def calculate_hashes_from_file(file):
    md5 = hashlib.md5()
    sha256 = hashlib.sha256()

    chunk_size = 4096
    for chunk in iter(lambda: file.read(chunk_size), b''):
        md5.update(chunk)
        sha256.update(chunk)

    return {
        'md5': md5.hexdigest(),
        'sha256': sha256.hexdigest()
    }

def calculate_hashes_from_response(response):
    md5 = hashlib.md5()
    sha256 = hashlib.sha256()

    chunk_size = 4096
    for chunk in iter(lambda: response.raw.read(chunk_size), b''):
        md5.update(chunk)
        sha256.update(chunk)

    return {
        'md5': md5.hexdigest(),
        'sha256': sha256.hexdigest()
    }

def verify_hashes(hashes, expected):
    if expected:
        if hashes['md5'] != expected['md5']:
            print(f"MD5 hash mismatch. Expected {expected['md5']} but got {hashes['md5']}.")
        if hashes['sha256'] != expected['sha256']:
            print(f"SHA-256 hash mismatch. Expected {expected['sha256']} but got {hashes['sha256']}.")
    return hashes

# Example usage:
file_path = 'path/to/file.txt'
url = 'https://example.com/example.txt'

hashes = calculate_hashes(file_path, url)
print(hashes)

expected_md5 = 'expected-md5-hash'
expected_sha256 = 'expected-sha-256-hash'

verified_hashes = verify_hashes(hashes, {'md5': expected_md5, 'sha256': expected_sha256})
print(verified_hashes)
```']

