import os
import yaml
import subprocess
import time

class NetworkConfig:
    def __init__(self):
        self.environments = {}

    def load_config(self, config_file):
        with open(config_file, 'r') as file:
            config = yaml.safe_load(file)
            for env, settings in config.items():
                self.environments[env] = settings

    def update_interface(self, env, interface, ip, subnet_mask, gateway):
        if interface not in self.environments[env]:
            return False
        self.environments[env][interface]['ip'] = ip
        self.environments[env][interface]['subnet_mask'] = subnet_mask
        self.enuments[env][interface]['gateway'] = gateway

    def validate_config(self, env, interface):
        if not self.environments[env].get(interface):
            return False
        ping_cmd = f"ping -c 1 {self.environments[env][interface]['ip']}"
        ping_out = subprocess.check_output(ping_cmd, shell=True)
        if not ping_out:
            return False
        return True

    def apply_config(self, env, interface):
        if not self.validate_config(env, interface):
            raise Exception(f"Failed to validate config for {env} on {interface}")
        ip_cmd = f"ip addr add {self.environments[env][interface]['ip']}/{self.environments[env][interface]['subnet_mask']} brd {self.environments[env][interface]['gateway']} dev {interface}"
        os.system(ip_cmd)
        time.sleep(2)  # Allow changes to take effect
        return True

    def revert_config(self, env, interface):
        if not self.environments[env].get(interface):
            return False
        ip_cmd = f"ip addr flush {interface}"
        os.system(ip_cmd)
        return True

def main():
    config_file = 'config.yaml'
    network_config = NetworkConfig()
    network_config.load_config(config_file)

    for env, settings in network_config.environments.items():
        for interface, details in settings.items():
            try:
                if not network_config.apply_config(env, interface):
                    raise Exception(f"Failed to apply config for {env} on {interface}")
            except Exception as e:
                print(f"Error: {e}")
                network_config.revert_config(env, interface)

if __name__ == "__main__":
    main()
