#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>

typedef struct {
    const char* name;
    void* (*func)(void);
} HashFunction;

HashFunction* get_available_hash_functions() {
    // Load configuration service library
    void* config_service = dlopen("config_service.so", RTLD_LAZY);
    if (!config_service) {
        return NULL;  // Handle error
    }

    // Initialize list of available hash functions
    HashFunction** hash_functions = (HashFunction**)malloc(sizeof(HashFunction*) * 10);  // Reserve space for up to 10 hash functions
    size_t num_hash_functions = 0;

    // Retrieve and add hash functions from configuration service
    void* config_service_func = dlsym(config_service, "get_available_hash_functions");
    if (!config_service_func) {
        dlclose(config_service);
        return NULL;  // Handle error
    }
