['```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

// Structure to represent a semaphore with a specified value
typedef struct {
    int value;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} semaphore_t;

// Function to initialize a semaphore with a given value
semaphore_t* sem_init(int value) {
    semaphore_t* sem = (semaphore_t*)malloc(sizeof(semaphore_t));
    if (!sem) return NULL; // Error: unable to allocate memory

    sem->value = value;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);

    return sem;
}

// Function to wait on a semaphore
void sem_wait(semaphore_t* sem) {
    pthread_mutex_lock(&sem->mutex); // Acquire the mutex
    while (sem->value <= 0) { // Wait until there are available slots
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    --sem->value; // Decrement the semaphore value
    pthread_mutex_unlock(&sem->mutex); // Release the mutex
}

// Function to signal a semaphore
void sem_signal(semaphore_t* sem) {
    pthread_mutex_lock(&sem->mutex); // Acquire the mutex
    ++sem->value; // Increment the semaphore value
    pthread_cond_broadcast(&sem->cond); // Wake up all waiting threads
    pthread_mutex_unlock(&sem->mutex); // Release the mutex
}

// Function to destroy a semaphore
void sem_destroy(semaphore_t* sem) {
    pthread_mutex_lock(&sem->mutex); // Acquire the mutex
    free(sem);
    pthread_mutex_unlock(&sem->mutex); // Release the mutex
}
