use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::thread;
use log::{info, warn};

struct LlvmIrGenerator {
    cache: Arc<Mutex<HashMap<String, String>>>,
}

impl LlvmIrGenerator {
    fn new() -> Self {
        LlvmIrGenerator {
            cache: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    fn generate_ir(&self, dir_path: &Path) -> Result<(), Box<dyn std::error::Error>> {
        let mut queue = Vec::new();
        queue.push(dir_path.to_path_buf());

        while let Some(path) = queue.pop() {
            if !path.is_dir() {
                self.process_file(&path)?;
            } else {
                for entry in fs::read_dir(&path)? {
                    let entry = entry?;
                    let path = entry.path();
                    queue.push(path);
                }
            }
        }

        Ok(())
    }

    fn process_file(&self, file_path: &Path) -> Result<(), Box<dyn std::error::Error>> {
        if self.cache.lock().unwrap().contains_key(file_path.to_str().unwrap()) {
            info!("Caching hit for {}", file_path.display());
            return Ok(());
        }

        let ll_file = match crate::ll_file::LLFile::open(&file_path) {
            Ok(file) => file,
            Err(e) => return Err(Box::new(e)),
        };

        let ir_code = match ll_file.to_ir() {
            Ok(ir) => ir,
            Err(e) => return Err(Box::new(e)),
        };

        self.cache.lock().unwrap().insert(file_path.to_str().unwrap(), ir_code);

        info!("Generated LLVM IR for {}", file_path.display());

        Ok(())
    }
}

fn main() {
    env_logger::init();

    let generator = LlvmIrGenerator::new();
    generator.generate_ir(Path::new("/path/to/directory")).expect("Failed to generate LLVM IR");
}
