#include <vector>
#include <string>

void replaceStrings(std::vector<std::string>& vec, const std::string& target, const std::string& replacement) {
    auto it = vec.begin();
    while (it != vec.end()) {
        if (*it == target) {
            *it = replacement;
        } else {
            ++it;
        }
    }

    if (find(vec.begin(), vec.end(), target) == vec.end()) {
        vec.push_back(replacement);
    }
}
