using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading;
using System.Threading.Tasks;

public class TransactionProcessor
{
    private readonly Dictionary<string, (SqlConnection Connection, string Command)> _connections = new();
    private readonly Random _random = new();

    public async Task<IList<TransactionResult>> ProcessTransactions(IList<Transaction> transactions)
    {
        var results = new List<TransactionResult>();

        foreach (var transaction in transactions)
        {
            try
            {
                using (var connection = GetConnection(transaction.AccountID))
                {
                    using (var command = new SqlCommand(transaction.Command, connection))
                    {
                        connection.Open();

                        using (var transactionScope = new TransactionScope())
                        {
                            try
                            {
                                await command.ExecuteNonQueryAsync();
                                results.Add(new TransactionResult { Description = transaction.Description, Amount = transaction.Amount, Result = "Success" });
                            }
                            catch (Exception ex)
                            {
                                if (!ShouldRetry(ex))
                                {
                                    throw;
                                }

                                await RetryTransaction(transaction, connection, command);
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                results.Add(new TransactionResult { Description = transaction.Description, Amount = transaction.Amount, Result = "Failure", ErrorMessage = ex.Message });
            }
        }

        return results;
    }

    private SqlConnection GetConnection(string accountID)
    {
        // Dynamic connection selection based on account ID
        // ...
    }

    private bool ShouldRetry(Exception ex)
    {
        // Exponential backoff and circuit breaker pattern implementation
        // ...
    }

    private async Task RetryTransaction(Transaction transaction, SqlConnection connection, SqlCommand command)
    {
        var delay = GetRetryDelay();

        while (delay <= 0 || await ShouldBreakCircuit())
        {
            try
            {
                await command.ExecuteNonQueryAsync();
                return;
            }
            catch (Exception ex) when (ex is TimeoutException || ex is SqlException)
            {
                // Wait and retry
                await Task.Delay(delay);
                delay *= 2; // Exponential backoff
            }
        }

        throw new CircuitBrokenException("Transaction failed repeatedly");
    }

    private int GetRetryDelay()
    {
        return _random.Next(100, 500); // Randomized delay between 0.1 and 5 seconds
    }

    public class TransactionResult
    {
        public string Description { get; set; }
        public decimal Amount { get; set; }
        public string Result { get; set; }
        public string ErrorMessage { get; set; }
    }

    public class Transaction
    {
        public string Description { get; set; }
        public decimal Amount { get; set; }
        public string AccountID { get; set; }
        public string Command { get; set; }
    }
}

public class CircuitBrokenException : Exception
{
    public CircuitBrokenException(string message) : base(message)
    {
    }
}
