    public List<string> ProcessXmlFiles(string[] xmlFilePaths, string tagName, int batchSize = 10, bool throwExceptionOnMultipleMatches = true)
    {
        List<string> directoryPaths = new List<string>();

        foreach (string filePath in xmlFilePaths)
        {
            using (FileStream fileStream = File.OpenRead(filePath))
            {
                XmlDocument xmlDoc = new XmlDocument();
                xmlDoc.Load(fileStream);

                XmlNodeList elements = xmlDoc.SelectNodes($"//{tagName}");
                if (elements == null || elements.Count == 0)
                {
                    Console.WriteLine($"No matching elements found in {filePath}.");
                    continue;
                }
                else if (elements.Count > 1 && !throwExceptionOnMultipleMatches)
                {
                    Console.WriteLine($"Multiple matches found in {filePath}. Processing all matches...");
                }

                using (var directoryCreator = new DirectoryCreator())
                {
                    foreach (XmlNode element in elements)
                    {
                        string path = GetDirectoryPathFromElement(element);
                        if (!directoryCreator.CreateDirectory(path))
                        {
                            throw new Exception($"Failed to create directory: {path}");
                        }
                        directoryPaths.Add(path);

                        if (directoryPaths.Count % batchSize == 0)
                        {
                            // Integration with external API for validation
                            ValidateDirectories(directoryPaths, tagName);
                        }
                    }
                }
            }
        }

        return directoryPaths;
