function manageUserAccount($action, $params) {
    require_once 'config.php';

    // Initialize cache for listing users
    $cache = new Memcached();
    $cache->connect('localhost', 11211);

    switch ($action) {
        case 'create':
            if (!isset($params['name']) || !preg_match('/^[a-zA-Z0-9_]{2,50}$/', $params['name'])) {
                echo json_encode(['error' => 'Invalid name']);
                return;
            }
            if (!filter_var($params['email'], FILTER_VALIDATE_EMAIL)) {
                echo json_encode(['error' => 'Invalid email']);
                return;
            }
            if (strlen($params['password']) < 8) {
                echo json_encode(['error' => 'Password too short']);
                return;
            }

            // Create user
            $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
            $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
            $stmt->execute([':name' => $params['name'], ':email' => $params['email'], ':password' => password_hash($params['password'], PASSWORD_DEFAULT)]);

            echo json_encode(['success' => 'User created successfully']);
            break;
        case 'update':
            if (!isset($params['userId']) || !is_numeric($params['userId'])) {
                echo json_encode(['error' => 'Invalid user ID']);
                return;
            }
            if (isset($params['name']) && (!preg_match('/^[a-zA-Z0-9_]{2,50}$/', $params['name'])) {
                echo json_encode(['error' => 'Invalid name']);
                return;
            }
            if (isset($params['email']) && !filter_var($params['email'], FILTER_VALIDATE_EMAIL)) {
                echo json_encode(['error' => 'Invalid email']);
                return;
            }
            if (isset($params['password']) && strlen($params['password']) < 8) {
                echo json_encode(['error' => 'Password too short']);
                return;
            }

            // Update user
            $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
            $stmt = $db->prepare("UPDATE users SET name = :name, email = :email, password = :password WHERE id = :userId");
            $stmt->execute([':name' => $params['name'], ':email' => $params['email'], ':password' => password_hash($params['password'], PASSWORD_DEFAULT), ':userId' => $params['userId']]);

            echo json_encode(['success' => 'User updated successfully']);
            break;
        case 'delete':
            if (!isset($params['userId']) || !is_numeric($params['userId'])) {
                echo json_encode(['error' => 'Invalid user ID']);
                return;
            }
            if (!isset($params['sessionToken']) || strlen($params['sessionToken']) < 32) {
                echo json_encode(['error' => 'Invalid session token']);
                return;
            }

            // Delete user
            $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
            $stmt = $db->prepare("DELETE FROM users WHERE id = :userId");
            $stmt->execute([':userId' => $params['userId']]);

            echo json_encode(['success' => 'User deleted successfully']);
            break;
        case 'list':
            // Get users from cache
            $users = $cache->get('users');
            if ($users === false) {
                // Retrieve users from database and store in cache
                $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
                $stmt = $db->prepare("SELECT * FROM users ORDER BY created DESC");
                $stmt->execute();
                $users = $stmt->fetchAll(PDO::FETCH_ASSOC);
                $cache->set('users', $users, 3600); // Cache for 1 hour
            }

            echo json_encode(['success' => 'Users listed successfully', 'data' => $users]);
            break;
        default:
            echo json_encode(['error' => 'Invalid action']);
    }
}
