    public class UpdateElementController : ControllerBase
    {
        private readonly IUpdateService _updateService;
        private readonly ICacheService _cacheService;
        private readonly IDistributedTracingService _distributedTracingService;
        private readonly IFeatureToggleService _featureToggleService;

        public UpdateElementController(IUpdateService updateService, ICacheService cacheService, IDistributedTracingService distributedTracingService, IFeatureToggleService featureToggleService)
        {
            _updateService = updateService;
            _cacheService = cacheService;
            _distributedTracingService = distributedTracingService;
            _featureToggleService = featureToggleService;
        }

        [HttpPost]
        public async Task<IActionResult> UpdateElement([FromBody]UpdateElementRequest request, bool dryRun = false)
        {
            if (!ValidateRequest(request))
                return BadRequest("Invalid request");

            try
            {
                await _updateService.UpdateElementAsync(request.PageSectionId, request.ElementId, request.HtmlContent, dryRun);
            }
            catch (TimeoutException ex)
            {
                // Handle timeout exception and retry if necessary
                await _updateService.RetryUpdateAsync(request.PageSectionId, request.ElementId, request.HtmlContent, dryRun);
            }
            catch (TransientFailureException ex)
            {
                // Handle transient failure and retry if necessary
                await _updateService.RetryUpdateAsync(request.PageSectionId, request.ElementId, request.HtmlContent, dryRun);
            }
            catch (PersistentFailureException ex)
            {
                // Handle persistent failure and gracefully degrade
                await _updateService.GradeDegradeAsync(request.PageSectionId, request.ElementId, request.HtmlContent, dryRun);
            }

            return Ok();
        }

        private bool ValidateRequest(UpdateElementRequest request)
        {
            if (string.IsNullOrEmpty(request.PageSectionId))
                return false;
            if (string.IsNullOrEmpty(request.ElementId))
                return false;
            if (request.HtmlContent.Length > 1024 * 10) // 10KB limit
                return false;

            return true;
        }
    }

    public class UpdateElementRequest
    {
        public string PageSectionId { get; set; }
        public string ElementId { get; set; }
        public string HtmlContent { get; set; }
    }
}
