const fs = require('fs');
const path = require('path');
const logging = require('./logging');

function aggregateFiles(dirPath, extensionsToInclude) {
  const aggregatedString = '';
  let lastUpdateTimestamp = Date.now();

  function refreshFileList() {
    if (Date.now() - lastUpdateTimestamp > 1000 * 60) { // update every minute
      fs.readdir(dirPath, (err, files) => {
        if (err) {
          logging.error(`Failed to read directory: ${err}`);
        } else {
          const fileSet = new Set();
          for (const file of files) {
            const filePath = path.join(dirPath, file);
            if (fs.lstatSync(filePath).isFile() && extensionsToInclude.has(path.extname(file))) {
              fileSet.add(filePath);
            }
          }
          // process updated file list
        }
      });
    }
  }

  function aggregateContents(files) {
    return Promise.all(files.map((file) => {
      return fs.readFile(file, 'utf8').then((content) => {
        aggregatedString += content;
      }).catch((err) => {
        logging.error(`Failed to read file: ${err}`);
      });
    }));
  }

  function processAggregatedString() {
    // further processing of the aggregated string
  }

  setInterval(refreshFileList, 1000 * 60); // update every minute

  refreshFileList().then(() => {
    const files = Array.from(fileSet);
    aggregateContents(files).then(() => {
      processAggregatedString();
    });
  });
}

module.exports = aggregateFiles;
