function runTestSuite(moduleName) {
  const moduleCache = {};
  const blueslipMocker = require('blueslip').mocker();

  async function runTest(testName, testFn) {
    try {
      await blueMock.reset(); // Reset blueslip library
      const result = await testFn();
      console.log(`Test ${testName} in module ${moduleName} passed`);
    } catch (error) {
      console.error(`Test ${testName} in module ${moduleName} failed: ${error}`);
    }
  }

  async function runModuleTests() {
    const tests = [
      { name: 'Test1', testFn: () => Promise.resolve(true) },
      { name: 'Test2', testFn: () => Promise.reject(new Error('Test failed')) },
      // Add more tests here
    ];

    for (const test of tests) {
      await runTest(test.name, test.testFn);
    }
  }

  async function runModule(moduleName) {
    if (!moduleCache[moduleName]) {
      try {
        moduleCache[moduleName] = require(moduleName); // Load the module efficiently with caching
      } catch (error) {
        console.error(`Error loading module ${moduleName}: ${error}`);
        return;
      }
    }

    await runModuleTests();
  }

  async function logAndTrackTestResults() {
    const testSummary = {
      passed: 0,
      failed: 0,
    };

    try {
      await runModule(moduleName);
      testSummary.passed++;
    } catch (error) {
      console.error(`Error running module ${moduleName}: ${error}`);
      testSummary.failed++;
    }

    console.log(`Test summary for module ${moduleName}:
  Passed: ${testSummary.passed}
  Failed: ${testSummary.failed}`);

    // Log results to external logging service
    const logService = require('log-service');
    await logService.log({
      message: `Module ${moduleName} test suite complete`,
      data: { passed: testSummary.passed, failed: testSummary.failed },
      level: 'info',
    });
  }

  try {
    await logAndTrackTestResults();
  } catch (error) {
    console.error(`Error tracking test results: ${error}`);
  }
}
