function StreamProcessor(stream, command) {
  const { Transform } = require('stream');

  class PauseResumeTransform extends Transform {
    constructor() {
      super({ objectMode: true });
      this.paused = false;
    }

    _transform(chunk, encoding, callback) {
      if (this.paused) {
        setTimeout(() => this.push(chunk), 0);
      } else {
        this.push(chunk);
      }
      callback();
    }

    _pause() {
      this.paused = true;
    }

    _resume() {
      this.paused = false;
    }
  }

  class ShellCommandTransform extends Transform {
    constructor(command) {
      super({ objectMode: true });
      this.command = command;
    }

    _transform(chunk, encoding, callback) {
      const { exec } = require('child_process');
      exec(this.command, (error, stdout, stderr) => {
        if (error) {
          this.emit('error', error);
        }
        this.push(stdout);
        callback();
      });
    }
  }

  class DataCollector extends Transform {
    constructor(stream) {
      super({ objectMode: true });
      this.stream = stream;
    }

    _transform(chunk, encoding, callback) {
      if (this.stream) {
        this.stream.pause();
        setTimeout(() => {
          this.push(chunk);
          this.stream.resume();
        }, 0);
      } else {
        this.push(chunk);
      }
      callback();
    }
  }

  function processStream(stream, command) {
    const dataCollector = new DataCollector(stream);
    const pauseResumeTransform = new PauseResumeTransform();
    const shellCommandTransform = new ShellCommandTransform(command);

    stream.pipe(dataCollector).pipe(pauseResumeTransform).pipe(shellCommandTransform);
  }

  module.exports = processStream;
