function mergeBufferedChunks(chunks) {
  const buffer = Buffer.allocUnsafe(0);
  let prevEnd = 0;

  for (const chunk of chunks) {
    if (!chunk || !chunk.length) continue;

    const end = prevEnd + chunk.length;
    buffer.copy(chunk, 0, prevEnd, end);

    if (!buffer.writeUInt32LE(0, end - 4)) throw new Error('Write failure');
    buffer.write(chunk.hash(), prevEnd, end, 'hex');

    prevEnd = end;
  }

  return buffer;
}
