function generateReport(selector, batchSize = 100) {
  const report = [];
  let batches = [];

  async function traverseDOM(root) {
    for await (const node of root.querySelectorAll(selector)) {
      if (node.children.length > 0) {
        await traverseDOM(node);
      } else {
        const metadata = await fetchMetadata(node);
        report.push({ node, metadata });
        if (report.length >= batchSize) {
          batches.push(report.slice());
          report.length = 0;
        }
      }
    }
  }

