class ModuleLoader {
  constructor(config) {
    this.config = config;
    this.modules = {};
    this.moduleGraph = {};
    this.loadOrder = [];
  }

  async loadModule(moduleName) {
    if (!this.modules[moduleName]) {
      try {
        const moduleSource = await this.getSource(moduleName);
        const module = new Function(`return ${moduleSource}`)();
        this.modules[moduleName] = module;
        this.moduleGraph[moduleName] = {};
      } catch (error) {
        console.error(`Failed to load module '${moduleName}': ${error}`);
      }
    }
  }

  async getSource(moduleName) {
    const absolutePath = this.config.getAbsolutePath(moduleName);
    if (!absolutePath) {
      throw new Error(`Module '${moduleName}' not found`);
    }
    return await fetch(absolutePath).then(response => response.text());
  }

  async resolveDependencies() {
    for (const moduleName in this.moduleGraph) {
      const dependencies = this.moduleGraph[moduleName];
      for (const dependency of dependencies) {
        if (!this.modules[dependency]) {
          await this.loadModule(dependency);
        }
      }
    }
  }

  async executeModules() {
    for (const moduleName in this.loadOrder) {
      try {
        await this.modules[moduleName]();
      } catch (error) {
        console.error(`Error executing module '${moduleName}': ${error}`);
      }
    }
  }

  async loadAndExecuteModules() {
    await this.resolveDependencies();
    await this.executeModules();
  }

  async verifyModuleIntegrity(moduleName, expectedHash) {
    try {
      const moduleSource = await this.getSource(moduleName);
      const actualHash = await crypto.createHash('sha256').update(moduleSource).digest('hex');
      if (actualHash !== expectedHash) {
        throw new Error(`Module '${moduleName}' integrity check failed`);
