import java.io.*;
import java.util.*;

public class Main {

    public static int countDisjointPairs(int[] array) {
        UnionFind uf = new UnionFind(array.length);
        for (int i : array) {
            uf.union(i % array.length, i);
        }
        return uf.getCount() - 1;
    }

    public static String modifyFileExtension(String filePath, int disjointPairCount) {
        String fileName = filePath.substring(filePath.lastIndexOf("\\") + 1);
        String fileExt = fileName.substring(fileName.lastIndexOf("."));
        int uniqueCount = countUniqueElements(arrayFromConfigFile(filePath));
        return fileName.substring(0, fileName.length() - fileExt.length()) + uniqueCount;
    }

    public static int[] arrayFromConfigFile(String filePath) {
        // implement this method to read the configuration file
        // for demonstration purposes, we'll just return a sample array
        return new int[]{1, 2, 3, 4, 5};
    }

    public static void processArrayAndConfigFile(String filePath) throws IOException {
        int disjointPairCount = countDisjointPairs(arrayFromConfigFile(filePath));
        String modifiedFilePath = modifyFileExtension(filePath, disjointPairCount);
        // implement this part to handle actual file operations
        long startTime = System.currentTimeMillis();
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(modifiedFilePath))) {
            writer.write("Modified File Content");
        }
        long endTime = System.currentTimeMillis();
        System.out.println("Time taken for writing: " + (endTime - startTime) + " ms");

        startTime = System.currentTimeMillis();
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        }
        endTime = System.currentTimeMillis();
        System.out.println("Time taken for reading: " + (endTime - startTime) + " ms");
    }

    public static class UnionFind {
        private int[] parent;
        private int count;

        public UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
            count = n;
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                parent[rootX] = rootY;
                count--;
            }
        }

        public int getCount() {
            return count;
        }

        private int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }
    }
