public class ConnectionManager {
    private static final int MAX_CONCURRENT_CONNECTIONS = 10;
    private Map<String, List<Connection>> connectionsMap = new HashMap<>();
    private ExecutorService executorService = Executors.newCachedThreadPool();

    public void connect(String endpoint) {
        if (!connectionsMap.containsKey(endpoint)) {
            connectionsMap.put(endpoint, new ArrayList<>());
        }
        Connection connection = new Connection(endpoint);
        connectionsMap.get(endpoint).add(connection);
        executorService.submit(() -> {
            try {
                connection.connect();
            } catch (Exception e) {
                logError("Failed to connect to " + endpoint, e);
            }
        });
    }

    public void disconnect(String endpoint) {
        if (!connectionsMap.containsKey(endpoint)) {
            return;
        }
        for (Connection connection : connectionsMap.get(endpoint)) {
            connection.disconnect();
        }
        connectionsMap.remove(endpoint);
    }

    public void reconnect(String endpoint) {
        if (!connectionsMap.containsKey(endpoint)) {
            return;
        }
        for (Connection connection : connectionsMap.get(endpoint)) {
            try {
                connection.reconnect();
            } catch (Exception e) {
                logError("Failed to reconnect to " + endpoint, e);
            }
        }
    }

    private void logError(String message, Exception e) {
        // implement logging mechanism here
    }

    public static class Connection implements Runnable {
        private final String endpoint;
        private boolean connected = false;

