class TextureResourceManager:
    def __init__(self):
        self.resource_directories = {}
        self.cache = {}
        self.lock = threading.Lock()
        self.queued_loads = Queue()

    def set_resource_directory(self, name, path):
        self.resource_directories[name] = path

    def load_texture(self, resource_name):
        if resource_name in self.cache:
            return self.cache[resource_name]

        for dir_path in self.resource_directories.values():
            file_path = os.path.join(dir_path, f"{resource_name}.png")
            if os.path.exists(file_path):
                with open(file_path, 'rb') as f:
                    img = Image.open(f)
                    self.cache[resource_name] = BytesIO()
                    img.save(self.cache[resource_name], format='PNG')
                    return self.cache[resource_name]

        # Try cloud storage
        try:
            uploader = Uploader('cloudinary_api_key', 'cloudinary_api_secret')
            response = urlopen(Request(f'https://res.cloudinary.com/{resource_name}.png'))
            img_data = BytesIO(response.read())
            self.cache[resource_name] = img_data
            return img_data
        except Exception as e:
            print(f"Error loading {resource_name}: {str(e)}")

        # Try local network shares
        try:
            for dir_path in self.resource_directories.values():
                file_path = os.path.join(dir_path, f"{resource_name}.png")
                if os.path.exists(file_path):
                    with open(file_path, 'rb') as f:
                        img = Image.open(f)
                        self.cache[resource_name] = BytesIO()
                        img.save(self.cache[resource_name], format='PNG')
                        return self.cache[resource_name]
        except Exception as e:
            print(f"Error loading {resource_name}: {str(e)}")

        # Fallback to default texture
        self.cache[resource_name] = open('default_texture.png', 'rb').read()
        return self.cache[resource_name]

    def load_textures_async(self, resource_names):
        for name in resource_names:
            if not self.queued_loads.full():
                self.queued_loads.put(name)
                threading.Thread(target=self.load_texture_queue).start()

    def load_texture_queue(self):
        while True:
            if self.queued_loads.empty():
                break
            name = self.queued_loads.get()
            try:
                texture_data = self.load_texture(name)
                with self.lock:
                    # Cache and process the loaded texture data
                    pass
            except Exception as e:
                print(f"Error loading {name}: {str(e)}")

    def get_cached_textures(self):
        return self.cache

    def clear_cache(self):
        self.cache = {}
