['```rust
use reqwest;
use log::log_enabled;
use std::sync::{Arc, Mutex};

pub struct HttpClient {
    pub timeout: u64,
    pub redirect_limit: u32,
    pub disable_certificate_validation: bool,
}

impl HttpClient {
    pub async fn get(&self, url: &str) -> Result<reqwest::Response, reqwest::Error> {
        let mut client = self.create_client().await?;

        let resp = client
            .get(url)
            .timeout(std::time::Duration::from_millis(self.timeout as u128))
            .redirect_limit(self.redirect_limit as usize)
            .send()
            .await?
            .error_for_status()
            .map_err(|e| e.to_string())
            .unwrap_or_else(|| "Request failed".to_string());

        if self.disable_certificate_validation {
            client = reqwest::Client::builder()
                .danger_accept_invalid_certs(true)
                .build()?;
        }

        Ok(resp)
    }

    fn create_client(&self) -> Result<Arc<Mutex<reqwest::Client>>, reqwest::Error> {
        let mut client = Arc::new(Mutex::new(reqwest::Client::builder()
            .timeout(std::time::Duration::from_millis(self.timeout as u128))
            .build()?));

        if self.disable_certificate_validation {
            *client.get_mut().unwrap() = client.get_mut().unwrap().danger_accept_invalid_certs(true);
        }

        Ok(client)
    }
}
