function validateSessionToken($token) {
    // Query the database to get the token's associated username and expiration time
    $dbQuery = "SELECT username, expires_at FROM session_tokens WHERE token='$token'";
    $result = mysqli_query($GLOBALS['conn'], $dbQuery);
    $row = mysqli_fetch_assoc($result);

    if ($row) {
        // Check if the token has expired
        if (time() > $row['expires_at']) {
            // Token is expired, invalidate it and notify user
            invalidateSessionToken($token);
            return false;
        } else {
            // Token is valid, update its expiration time
            $newExpirationTime = time() + (int)getSessionTimeout();
            $dbQuery = "UPDATE session_tokens SET expires_at=$newExpirationTime WHERE token='$token'";
            mysqli_query($GLOBALS['conn'], $dbQuery);
            return true;
        }
