async function generateCombinedCertificate(oauthRequest) {
  const { privateKeyPath, certificatePath, outputFilename } = oauthRequest;

  if (!privateKeyPath || !certificatePath || !outputFilename) {
    return null;
  }

  let privateKey = '';
  let certificate = '';

  for (let i = 0; i < 3; i++) {
    try {
      privateCert = await fs.promises.readFile(privateKeyPath, 'utf8');
      cert = await fs.promises.readFile(certificatePath, 'utf8');
      break;
    } catch (err) {
      if (i < 2) {
        console.log(`Error reading file: ${err.message}. Retrying in 1 second...`);
        await new Promise(resolve => setTimeout(resolve, Math.pow(2, i + 1) * 1000));
      } else {
        console.error('Failed to read files after three attempts. Returning null.');
        return null;
      }
    }
  }

  if (!privateKey || !certificate) {
    return null;
  }

  const combinedCert = `${privateKey}-----END RSA PRIVATE KEY-----\n${cert}-----END CERTIFICATE-----`;

  fs.promises.writeFile(outputFilename, combinedCert);
  return combinedCert;
}
