function authenticateWithOAuth($client_id, $client_secret, $redirect_url) {
    session_start();

    if (!isset($_SESSION['oauth_access_token'])) {
        // Pause initial setup and resume when interrupted
        $_SESSION['oauth_initial_setup'] = true;

        // Set up client credentials
        $client_credentials = array('client_id' => $client_id, 'client_secret' => $client_secret);

        // Request authorization code using HTTP redirect
        $auth_url = 'https://example.com/oauth/authorize?' . http_build_query(array('client_id' => $client_id, 'redirect_uri' => $redirect_url));
        header('Location: ' . $auth_url);
        exit;
    } elseif ($_SESSION['oauth_initial_setup']) {
        // Resume initial setup
        unset($_SESSION['oauth_initial_setup']);

        // Get access token using authorization code
        $token_url = 'https://example.com/oauth/token';
        $token_params = array('grant_type' => 'authorization_code', 'code' => $_GET['code'], 'redirect_uri' => $redirect_url);
        $ch = curl_init($token_url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($token_params));
        $response = curl_exec($ch);
        curl_close($ch);

        // Store access token in session
        $_SESSION['oauth_access_token'] = json_decode($response)->access_token;

        // Use access token to retrieve user information
        $user_info_url = 'https://example.com/api/user';
        $headers = array('Authorization' => 'Bearer ' . $_SESSION['oauth_access_token']);
        $ch = curl_init($user_info_url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
        $response = curl_exec($ch);
        curl_close($ch);

        // Collect data from stream and save to array
        $stream_data = array();
        while (!feof(STDIN)) {
            $stream_data[] = trim(fgets(STDIN));
        }

        return $stream_data;
    } else {
        // Resume authentication using access token
        $headers = array('Authorization' => 'Bearer ' . $_SESSION['oauth_access_token']);

        // Use access token to retrieve user information
        $user_info_url = 'https://example.com/api/user';
        $ch = curl_init($user_info_url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
        $response = curl_exec($ch);
        curl_close($ch);

        // Collect data from stream and save to array
        $stream_data = array();
        while (!feof(STDIN)) {
            $stream_data[] = trim(fgets(STDIN));
        }

        return $stream_data;
    }
}
