int resolve_dns(char* hostname, u_char** ip_addr) {
    struct hostent* host;
    struct sockaddr_in sin;

    // Perform DNS resolution using standard library functions
    if ((host = gethostbyname(hostname)) == NULL) {
        // Log failure and return error code
        fprintf(stderr, "DNS resolution failed for %s\n", hostname);
        return -3;
    }

    // Store IP address in a u_char array
    sin.sin_family = AF_INET;
    memcpy(&sin.sin_addr.s_addr, host->h_addr, sizeof(sin.sin_addr.s_addr));
    *ip_addr = (u_char*)malloc(sizeof(u_char) * INET_ADDRSTRLEN);
    inet_ntop(AF_INET, &sin.sin_addr, *ip_addr, INET_ADDRSTRLEN);

    return 0;
}

