        return NULL; // invalid input or out-of-bounds request
    }

    State* stateList = (State*)malloc((end - start + 1) * sizeof(State));
    if (!stateList) {
        return NULL; // memory allocation failed
    }

    for (int i = start; i <= end; i++) {
        stateList[i - start] = fsa[states[i]];
