class Node {
public:
    int id;
    std::vector<Node*> children;
};

void initOctree(Node** root, int size, int leafSize) {
    *root = new Node();
    (*root)->id = 0;

    // Initialize the octree recursively
    for (int i = 0; i < 8; ++i) {
        if ((size & (1 << i)) != 0) {
            Node* child = new Node();
            child->id = i;
            (*root)->children.push_back(child);
            initOctree(&child, size >> 3, leafSize);
        }
    }

    // Handle node rotations and re-balancing
    if (size > leafSize && (*root)->children.size() == 8) {
        Node* newRoot = (*root)->children[0];
        for (int i = 1; i < 8; ++i) {
            newRoot->children.push_back((*root)->children[i]);
        }
        delete[] *root;
        *root = newRoot;
    }

    // Optimize memory allocation and node rotation
    if (size <= leafSize) {
        Node* newLeaf = new Node();
        newLeaf->id = size;
        (*root)->children.push_back(newLeaf);
    }
}

