#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_TRANSACTIONS 5000000
#define RECENT_ACTIVITY_WINDOW 5 // seconds
#define WEIGHTED_SUM_UPDATE_INTERVAL 1 // second

typedef struct Transaction {
    int id;
    time_t timestamp;
    double amount;
    double weightFactor;
} Transaction;

typedef struct {
    double maxWeightedSum;
    Transaction* recentTransactions;
    int recentActivityCount;
} ProcessingState;

void processTransaction(Transaction* transaction, ProcessingState* state) {
    // Filter transactions based on age and recent activity
    if (time(NULL) - transaction->timestamp > 10) return; // discard old transactions
    if (transaction->timestamp < time(NULL) - RECENT_ACTIVITY_WINDOW) {
        state->recentActivityCount++;
        return;
    }

    // Update weighted sum
    double newWeightedSum = transaction->weightFactor * transaction->amount + state->maxWeightedSum;
    state->maxWeightedSum = newWeightedSum;

    // Evict old transactions from the recentTransactions array
    int i;
    for (i = 0; i < state->recentActivityCount - 1; i++) {
        state->recentTransactions[i] = state->recentTransactions[i + 1];
    }
    state->recentTransactions[--state->recentActivityCount].amount = transaction->amount;

    // Update the recent transactions array
    if (state->recentTransactions[state->recentActivityCount]) {
        state->recentTransactions[state->recentActivityCount]->timestamp = time(NULL);
    }
}

int main() {
    ProcessingState state;
    Transaction* maxTransaction;
    int i;

    // Initialize processing state
    state.maxWeightedSum = 0.0;
    state.recentTransactions = (Transaction*)malloc(MAX_TRANSACTIONS * sizeof(Transaction));
    state.recentActivityCount = 0;

    // Process transactions
    for (i = 0; i < MAX_TRANSACTIONS; i++) {
        // Simulate receiving a new transaction
        Transaction transaction;
        transaction.id = i;
        transaction.timestamp = time(NULL);
        transaction.amount = (double)i / 1000.0;
        transaction.weightFactor = (double)i % 10 + 1;

        processTransaction(&transaction, &state);

        // Update metrics every second
        if (i % WEIGHTED_SUM_UPDATE_INTERVAL == 0) {
            printf("Max weighted sum: %.2f\n", state.maxWeightedSum);
            printf("Recent activity count: %d\n", state.recentActivityCount);
        }
    }

    free(state.recentTransactions);

    return 0;
}
