#include <vector>
#include <algorithm>

void manageInventory(std::vector<Item>& items) {
    std::sort(items.begin(), items.end(),
        [](const Item& a, const Item& b) {
            if (a.type != b.type)
                return a.type < b.type;
            else if (a.rarity != b.rarity)
                return a.rarity < b.rarity;
            else
                return a.usageCount < b.usageCount;
        });

    for (auto& item : items) {
        if (!isLegendary(item)) {
            // non-legendary items can be used immediately
            std::cout << "Selected: " << item.type << " - " << item.rarity << " (" << item.usageCount << ")" << std::endl;
            item.usageCount++;
        } else {
            // legendary items have a cooldown period
            if (cooldownElapsed(item)) {
                // legenday item can be used after the cooldown
                std::cout << "Selected: " << item.type << " - " << item.rarity << " (" << item.usageCount << ")" << std::endl;
                item.usageCount++;
                startCooldown(item);
            } else {
                // legendary item is on cooldown, skip it
                continue;
            }
        }
    }
}

bool isLegendary(const Item& item) {
    return item.rarity == Item::Rarity::LEGENDARY;
}

bool cooldownElapsed(const Item& item) {
    return std::chrono::steady_clock::now().time_since_epoch() > item.lastUse + std::chrono::seconds(15);
}

void startCooldown(Item& item) {
    item.lastUse = std::chrono::steady_clock::now();
}
