using System;
using System.Threading;

namespace DynamicValueGenerator
{
    public class DynamicValueGenerator
    {
        private static readonly Random _random = new();
        private int _min;
        private int _max;
        private bool _exclusiveUpperBound;

        public DynamicValueGenerator(int min, int max)
            : this(min, max, false)
        {
        }

        public DynamicValueGenerator(float min, float max)
            : this((int)min, (int)max, false)
        {
        }

        public DynamicValueGenerator(int min, int max, bool exclusiveUpperBound)
        {
            if (!IsValidRange(min, max))
            {
                _logger.Warn($"Invalid range provided: min={min}, max={max}");
                _min = Math.Min(min, max);
                _max = _min;
            }
            else
            {
                _min = min;
                _max = max;
                _exclusiveUpperBound = exclusiveUpperBound;
            }
        }

        public int GetRandomInt()
        {
            return _random.Next(_min, _GetActualMax());
        }

        public float GetRandomFloat()
        {
            if (_exclusiveUpperBound)
            {
                return (float)_random.NextDouble() * (_GetActualMax() - _min) + _min;
            }
            else
            {
                return (float)_random.Next(_min, _GetActualMax());
            }
        }

        private int _GetActualMax()
        {
            return _exclusiveUpperBound ? _max - 1 : _max;
        }
    }
}
