const { map, reduce } = require('rxjs/operators');
const { from } = require('rxjs');

function asyncReduce(arr, callback, initialValue) {
  return from(arr).pipe(
    map((num, index) => ({ num, index })),
    reduce((acc, curr) => {
      try {
        const result = callback(acc[0], curr.num, acc[1]);
        if (result instanceof Promise || typeof result.then === 'function') {
          return { ...acc, awaiting: true };
        } else {
          return { ...acc, result };
        }
      } catch (error) {
        return { error, awaiting: false };
      }
    }, { result: initialValue, awaiting: false }),
    map((result) => {
      if (!result.awaiting) {
        return result.result;
      } else {
        return new Promise((resolve) => {
          setTimeout(() => {
            resolve(result.result);
          });
        }).then((val) => val).catch((error) => error);
      }
    }),
    reduce((acc, curr) => (curr.error ? acc : { ...acc, result: curr.result }), initialValue)
  );
}

// Example usage:
asyncReduce([1, 2, 3], (acc, num, index) => {
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve(acc + num);
    }, Math.random() * 1000);
  });
}, 0).subscribe({
  next: (result) => console.log(`Current sum: ${result}`),
  complete: () => console.log('Computation complete!'),
  error: (error) => console.error('Error occurred:', error)
});
