#include <string.h>
#include <limits.h>

char* process_file_path(char* path, int max_depth, int follow_links) {
    char* result = NULL;
    char* current_dir = NULL;
    char* parent_dir = NULL;
    int depth = 0;

    if (path == NULL || strlen(path) == 0) {
        return "/"; // default placeholder string
    }

    current_dir = strdup(path);
    if (current_dir == NULL) {
        return "/"; // error handling
    }

    parent_dir = current_dir;
    depth = 1;

    while (parent_dir != NULL && depth <= max_depth) {
        char* slash = strchr(parent_dir, '/');
        if (slash == NULL) {
            break; // no more directories in the path
        }
        *slash = '\0'; // truncate directory name
        parent_dir = current_dir;
        depth++;
    }

    if (depth > max_depth) {
        free(current_dir);
        return "/"; // exceeded maximum depth limit
    }

    result = strdup(current_dir);
    if (result == NULL) {
        free(current_dir);
        return "/"; // error handling
    }
    free(current_dir);

    // follow symbolic links if necessary
    if (follow_links && slash != NULL) {
        char* link_target = realpath(slash + 1, NULL);
        if (link_target == NULL) {
            free(result);
            return "/"; // error handling
        }
        free(link_target);
    }

    return result;
}
