// Define a struct to represent a log record
typedef struct {
    char* fields;
    int num_fields;
} LogRecord;

// Define a function to split a line into separate fields
LogRecord* split_line(char* line) {
    LogRecord* record = (LogRecord*)malloc(sizeof(LogRecord));
    char* token = strtok(line, ",");
    int i = 0;
    record->fields = (char*)malloc(strlen(token) + 1);
    strcpy(record->fields, token);

    while (token != NULL && i < 10) {
        token = strtok(NULL, ",");
        if (token == NULL)
            break;

        char* new_token = (char*)malloc(strlen(token) + 1);
        strcpy(new_token, token);
        record->fields = realloc(record->fields, strlen(record->fields) + strlen(new_token) + 2);
        strcat(record->fields, ",");
        strcat(record->fields, new_token);
        free(new_token);
        i++;
    }
    record->num_fields = i;
    return record;
}

// Define a function to compute the average of the last two numeric fields
double compute_average(LogRecord* record) {
    int i = 0;
    double sum = 0.0;

    for (i = record->num_fields - 2; i < record->num_fields; i++) {
        if (!strcmp(record->fields + strlen(record->fields) - strlen(record->fields) - i, "last_field1") && !strcmp(record->fields + strlen(record->fields) - strlen(record->fields) - i, "last_field2")) {
            sum += atof(record->fields + strlen(record->fields) - strlen(record->fields) - i);
        }
    }

    return sum / (record->num_fields - 1);
}

// Define a function to validate the computed average
int validate_average(double average) {
    // Add your validation criteria here
    if (average > 10.0)
        return 1;
    else
        return 0;
}

// Define a function to process each log record
void process_record(LogRecord* record) {
    double average = compute_average(record);
    int result = validate_average(average);

    // Add your further processing logic here
    if (result == 1)
        printf("Valid average: %f\n", average);
    else
        printf("Invalid average: %f\n", average);
}

int main() {
    FILE* file = fopen("log.txt", "r");
    char line[1024];

    while (fgets(line, sizeof(line), file)) {
        LogRecord* record = split_line(line);

        if (record->num_fields < 10) {
            printf("Warning: Malformed input\n");
            free(record->fields);
            free(record);
        } else {
            process_record(record);

            // Free memory allocated for each record
            free(record->fields);
            free(record);
        }
    }

    fclose(file);

    return 0;
}
