#define MAX_FILENAME_LENGTH 256
#define ALLOWED_FILE_TYPES "allowed_file_types.txt"

typedef struct {
    char *extension;
    int count;
} extension_t;

char* generate_new_filename(char* input_filename) {
    FILE *file = fopen(ALLOWED_FILE_TYPES, "r");
    if (!file) {
        return "error_generate_new_filename";
    }

    // Parse allowed file types
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Process line
        free(line);
        line = NULL;
        len = 0;
    }
    fclose(file);

    // Analyze input filename to determine primary component (extension)
    char *temp_filename = strdup(input_filename);
    char *dot_pos = strrchr(temp_filename, '.');
    if (!dot_pos) {
        free(temp_filename);
        return "error_generate_new_filename";
    }

    *dot_pos = '\0';
    char *primary_component = temp_filename;
    free(temp_filename);

    // Generate new extension
    time_t t = time(NULL);
    srand((unsigned int)t);
    int i, j;
    for (i = 0; i < 8; i++) {
        for (j = 0; j < 2; j++) {
            int random_char_index = rand() % strlen(primary_component);
            char random_char = primary_component[random_char_index];
            // Ensure uniqueness
            int found = 0;
            FILE *unique_file = fopen("unique_extensions.txt", "r");
            if (unique_file) {
                while ((read = getline(&line, &len, unique_file)) != -1) {
                    if (strcmp(line, &random_char) == 0) {
                        found = 1;
                        break;
                    }
                }
                fclose(unique_file);
                free(line);
                line = NULL;
                len = 0;
            }

            if (!found) {
                strcat(primary_component, &random_char);
            } else {
                i--;
                j++;
            }
        }
    }

    // Return new filename
    char *new_filename = malloc(strlen(primary_component) + 5);
    sprintf(new_filename, "%s_%d.txt", primary_component, time(NULL));
    free(primary_component);
    return new_filename;
}
