void initialize_aes_cipher(const char* password) {
    // Initialize OpenSSL libraries
    EVP_add_global_lock(EVP_LOCK_MTH, NULL);
    ENGINE_load_dynamic();

    // Generate a salt for the KDF
    unsigned char salt[16];
    RAND_bytes(salt, 16);

    // Derive the key from the given password using PBKDF2
    const EVP_PKEY* pkey = EVP_PKEY_new();
    BURN_CTX* burn_ctx = BN_mq_pkey_to_burn(pkey);
    unsigned char derived_key[32];
    int key_len = PBKDF2_KEY Derivation(password, strlen(password), salt, 16, "PBKDF2", 10000, &derived_key);

    // Initialize the AES-256-CBC cipher
    AES_CTR_CTX aes_ctx;
    EVP_CIPHER_CTX* ctx = AES_CTR_new_ctx(&aes_ctx);
    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, AES_BLOCK_SIZE);
    int iv_len = AES_BLOCK_SIZE;

    // Adjust key and IV lengths based on input constraints and performance requirements
    if (key_len < 32) {
        key_len = 32;
    }
    if (iv_len < 16) {
        iv_len = 16;
    }

    // Initialize the cipher
    AES_CTR_init(ctx, &aes_ctx, derived_key, key_len, iv, iv_len);

    // Handle weak passwords
    if (key_len < 64) {
        printf("Warning: Weak password detected. Consider strengthening your password.\n");
    }
}
