void executeAndDeserialize(const std::string& command, const std::vector<char>& data, void (*callback)(int, void*)) {
    pid_t pid = fork();
    if (pid == 0) {
        try {
            // Run the command in the background
            int status = system(command.c_str());
            if (status != 0)
                std::cerr << "Error running command: " << command << "\n";
            exit(status);
        } catch (...) {
            std::cerr << "Exception caught during command execution\n";
            _exit(1);
        }
    } else {
        int status;
        waitpid(pid, &status, 0);
        if (WEXITSTATUS(status) != 0)
            callback(0, nullptr);
        else
            callback(1, data); // Deserialize the byte array using a specified deserialization library

        // Handle potential exceptions gracefully and log any issues that occur during execution
    }
}
