import java.io.File;
import java.io.IOException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicBoolean;

public class CommandExecutor {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final File fileToDelete;
    private final Logger logger;

    public CommandExecutor(File fileToDelete, Logger logger) {
        this.fileToDelete = fileToDelete;
        this.logger = logger;
    }

    public void executeCommand(String command) {
        try {
            Process process = Runtime.getRuntime().exec(command);

            // Start and end times
            long startTime = System.nanoTime();
            long endTime = 0;

            // CPU and memory usage, exit code
            double cpuUsage = 0.0;
            double memoryUsage = 0.0;
            int exitCode = 0;

            // Process the command output
            ProcessOutputProcessor processor = new ProcessOutputProcessor(process.getInputStream());
            executor.submit(() -> {
                try {
                    process.waitFor();
                    endTime = System.nanoTime();

                    // CPU and memory usage, exit code
                    cpuUsage = process.getProcfs().getSystemCpuLoad();
                    memoryUsage = process.getMemoryInfo().getResidentSetSize();

                    // Exit code
                    exitCode = process.exitValue();

                    logger.logCommandMetrics(startTime, endTime, cpuUsage, memoryUsage, exitCode);
                } catch (IOException e) {
                    logger.error("Error processing command output: " + e.getMessage());
                }
            });

            // Wait for the command to finish
            executor.shutdown();
            while (!executor.isTerminated()) {
                // Do nothing
            }

            if (fileToDelete.exists() && fileToDelete.delete()) {
                logger.info("Temporary file deleted");
            } else {
                logger.error("Failed to delete temporary file");
            }
        } catch (IOException e) {
            logger.error("Error executing command: " + e.getMessage());
        }
    }

    public interface Logger {
        void logCommandMetrics(long startTime, long endTime, double cpuUsage, double memoryUsage, int exitCode);

        void error(String message);

        void info(String message);
    }

    private class ProcessOutputProcessor implements Runnable {
        private final InputStream inputStream;

        public ProcessOutputProcessor(InputStream inputStream) {
            this.inputStream = inputStream;
        }

        @Override
        public void run() {
            try {
                // Process the command output here
                BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));
                String line;
                while ((line = reader.readLine()) != null) {
                    // Do something with each line of output
                }
                reader.close();
            } catch (IOException e) {
                logger.error("Error processing command output: " + e.getMessage());
            }
        }
    }
}
