    while (retries > 0) {
        // Simulate a connection attempt with error handling
        if (!db_connect(config.database_url)) {
            if (--retries == 0)
                LOG_ERROR("Database connection failed after %d retries: %s", retries, config.database_url);
            else {
                LOG_WARNING("Transient database failure; retrying in 1 second...");
                sleep(1); // Simulate a delay
            }
        } else {
            break;
        }
    }

    if (retries == 0) {
        LOG_ERROR("Failed to connect to the database: %s", config.database_url);
        return -3;
    }

    if (!config.event_handler || *(void*)&config.event_handler != '\0') {
