        public async Task<string> DecryptAsync(string base64EncodedMessage, string key, string iv)
        {
            try
            {
                var desTripleCipher = new DESCryptoServiceProvider { Key = Convert.FromBase64String(key), IV = Convert.FromBase64String(iv) };
                using (var ms = new MemoryStream())
                {
                    var cryptoStream = new CryptoStream(ms, desTripleCipher.CreateDecryptor());
                    var buffer = new byte[1024];
                    int read;
                    while ((read = base64EncodedMessage.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        cryptoStream.Write(buffer, 0, read);
                    }
                    cryptoStream.FlushFinalBlock();
                    var plainBytes = ms.ToArray();
                    return Convert.ToBase64String(plainBytes);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError("Error decrypting message: " + ex.Message);
                throw;
            }
        }

        public async Task<string> AuthenticateAsync(string decryptedToken)
        {
            try
            {
                var authenticationResult = await _authenticationService.Authenticate(decryptedToken);
                if (!string.IsNullOrEmpty(authenticationResult))
                {
                    return authenticationResult;
                }
                else
                {
                    throw new Exception("Invalid or expired token");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError("Error authenticating token: " + ex.Message);
                throw;
            }
        }

        public async Task InvalidateAsync(string decryptedToken, TimeSpan timeout)
        {
            try
            {
                await Task.Delay(timeout, CancellationToken.None);
                if (!string.IsNullOrEmpty(decryptedToken))
                {
                    await _authenticationService.Invalidate(decryptedToken);
                    _logger.LogInformation("Token invalidated: " + decryptedToken);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError("Error invalidating token: " + ex.Message);
                throw;
            }
        }
    }

    public interface IDecryptionService
    {
        Task<string> DecryptAsync(string base64EncodedMessage, string key, string iv);
        Task<string> AuthenticateAsync(string decryptedToken);
        Task InvalidateAsync(string decryptedToken, TimeSpan timeout);
    }

    public interface ILogger
    {
        void LogError(string message);
        void LogInformation(string message);
    }

    public interface IAuthenticationService
    {
        Task<string> Authenticate(string token);
        Task Invalidate(string token);
    }
}
