using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Threading;

public class MD5Hasher
{
    private readonly Dictionary<string, string> _hashes = new();
    private readonly object _lock = new();

    public Dictionary<string, string> ProcessBatch(Stream input)
    {
        using var md5 = MD5.Create();
        string hashValue;
        string currentValue;

        while (input.Position < input.Length)
        {
            byte[] buffer = new byte[4096];
            int bytesRead = input.Read(buffer, 0, buffer.Length);
            string line = Encoding.UTF8.GetString(buffer, 0, bytesRead);

            lock (_lock)
            {
                if (!_hashes.TryGetValue(line, out currentValue) || currentValue != hashValue)
                {
                    using var hasher = MD5.Create();
                    byte[] hashBytes = hasher.ComputeHash(Encoding.UTF8.GetBytes(line));
                    hashValue = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

                    _hashes.Add(line, hashValue);
                }
            }
        }

        return _hashes;
    }
}
