using Ionic.Zlib;

public class LogProcessor
{
    private const int CompressionThreshold = 1024 * 1024; // 1MB

    public bool ProcessLogEntry(byte[] logEntry, byte[] hashValue)
    {
        try
        {
            if (logEntry.Length > CompressionThreshold)
            {
                // Compress the data to meet storage requirements
                using var memoryStream = new MemoryStream();
                using var gzipStream = new GZipStream(memoryStream, CompressionMode.Compress);
                logEntry.CopyTo(gzipStream);
                gzipStream.Flush();

                // Verify the integrity of the log entry using the provided hash value
                var calculatedHash = CalculateHash(memoryStream.ToArray());
                if (!hashValue.SequenceEqual(calculatedHash))
                {
                    LogCompressionFailure();
                    return false;
                }

                memoryStream.Position = 0;
                logEntry = memoryStream.ReadAllBytes();

                // Decompress and store the log entry for retrieval
                using var decompressedMemoryStream = new MemoryStream();
                using var gzipStreamDecompressor = new GZipStream(new MemoryStream(logEntry), CompressionMode.Decompress);
                gzipStreamDecompressor.CopyTo(decompressedMemoryStream);

                return true;
            }
            else
            {
                // No compression required; store the log entry as is
                return true;
            }
        }
        catch (Exception ex)
        {
            LogIntegrityFailure(ex.Message);
            return false;
        }
    }

    private byte[] CalculateHash(byte[] data)
    {
        using var md5 = MD5.Create();
        return md5.ComputeHash(data);
    }

    private void LogCompressionFailure()
    {
        Console.WriteLine("Log compression failure: unable to compress log entry.");
    }

    private void LogIntegrityFailure(string message)
    {
        Console.WriteLine($"Log integrity failure: {message}");
    }
}
