import com.fasterxml.jackson.databind.exc.InvalidDefinitionException;

public class JSONProcessor {
    public static <T> T processJSON(byte[] json, Class<T> clazz) {
        try (JsonParser parser = JsonFactory.defaultObjectMapper().createParser(json)) {
            return parser.readValueAs(clazz);
        } catch (InvalidDefinitionException e) {
            logger.warn("Invalid JSON definition. Returning default object.", e);
            return (T) new DefaultPlaceholder();
        }
    }

    private static final Logger logger = LoggerFactory.getLogger(JSONProcessor.class);

    private static class DefaultPlaceholder {}
}
