    double MEASUREMENT_VALUE;
} UeMeasurementResult;

// Function to initialize and populate a dynamic array of UeMeasurementResult structures
void* populate_array(int W, UeMeasurementResult** arr) {
    // Initialize the dynamic array with a minimum size based on the window size
    *arr = (UeMeasurementResult**)malloc(W * sizeof(UeMeasurementResult*));

    // Populate the array with initial measurements
    for (int i = 0; i < W; i++) {
        (*arr)[i] = (UeMeasurementResult*)malloc(sizeof(UeMeasurementResult));
        (*arr)[i]->RAN_NODE_ID = i;
        (*arr)[i]->MEASUREMENT_TYPE = i % 2;
        (*arr)[i]->MEASUREMENT_VALUE = (double)i / W;
    }

    return *arr;
}

// Function to calculate and store the moving average of measurement values over a sliding window
void* calculate_moving_average(UeMeasurementResult** arr, int W) {
    double sum = 0.0;
    for (int i = 0; i < W; i++) {
        sum += (*arr)[i]->MEASUREMENT_VALUE;
    }

    // Calculate the moving average
    double moving_average = sum / W;

    return &moving_average;
}

