import json
import weakref

class Registry:
    def __init__(self):
        self.registry = {}

    def register(self, unique_id, factory_function):
        self.registry[unique_id] = weakref.ref(factory_function)

    def get_factory(self, unique_id):
        return self.registry.get(unique_id).().__call__


class JSONSerializable:
    def to_json(self):
        raise NotImplementedError

    @classmethod
    def from_json(cls, json_data):
        raise NotImplementedError


class JSONRegistry(Registry):
    def register_object_type(self, unique_id, factory_function):
        super().register(unique_id, factory_function)

    def get_object_type(self, unique_id):
        return super().get_factory(unique_id)


class CircularReferenceError(Exception):
    pass


def serialize(obj, registry=None):
    if registry is None:
        registry = JSONRegistry()

    serialized_obj = {}
    for key, value in obj.__dict__.items():
        if isinstance(value, JSONSerializable):
            if hasattr(value, 'circular_reference'):
                circular_refs = value.circular_reference
                if circular_refs and isinstance(circular_refs[0], weakref.ref):
                    raise CircularReferenceError(f"Circular reference detected: {value}")
            serialized_obj[key] = serialize(getattr(value, 'serialized_data', value), registry)
        else:
            serialized_obj[key] = value

    return json.dumps(serialized_obj)


def deserialize(json_data, registry=None):
    if registry is None:
        registry = JSONRegistry()

    obj = json.loads(json_data)

    def deserialize_object(obj, registry):
        cls_name = type(obj). __name__
        for unique_id, factory_function in registry.registry.items():
            if factory_function().__class__.__name__ == cls_name:
                return factory_function()(obj)
        raise ValueError(f"Unknown object type: {cls_name}")

    serialized_obj = deserialize_object(obj, registry)

    return serialized_obj


class JSONEncoder(json.JSONEncoder):
    def default(self, obj):
        try:
            return serialize(obj)
        except CircularReferenceError as e:
            raise json.JSONEncodeError(e)


class JSONDecoder(json.JSONDecoder):
    def object_hook(self, d):
        if '_type' in d:
            unique_id = d.pop('_type')
            factory_function = registry.get_object_type(unique_id)
            obj = factory_function()
            for key, value in d.items():
                setattr(obj, key, deserialize(value, registry))
            return obj
        else:
            return d


registry = JSONRegistry()

class Person(JSONSerializable):
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def to_json(self):
        return {'_type': 'Person', 'name': self.name, 'age': self.age}

    @classmethod
    def from_json(cls, json_data):
        obj = cls(json_data['name'], json_data['age'])
        return obj


class Address(JSONSerializable):
    def __init__(self, street, city, state, zip):
        self.street = street
        self.city = city
        self.state = state
        self.zip = zip

    def to_json(self):
        return {'_type': 'Address', 'street': self.street, 'city': self.city, 'state': self.state, 'zip': self.zip}

    @classmethod
    def from_json(cls, json_data):
        obj = cls(json_data['street'], json_data['city'], json_data['state'], json_data['zip'])
        return obj


registry.register_object_type('Person', Person.from_json)
registry.register_object_type('Address', Address.from_json)

