double calculate_moving_average(UeMeasurementResult measurements[], int window_size, int num_measurements) {
    if (num_measurements <= 0 || window_size > num_measurements) return -1.0; // Handle edge cases

    double sum = 0.0;
    for (int i = 0; i < window_size && i < num_measurements; i++) {
        sum += measurements[i].measurement_value;
    }

    if (num_measurements > window_size) {
        for (int i = window_size; i < num_measurements; i++) {
            sum -= measurements[i - window_size].measurement_value;
            sum += measurements[i].measurement_value;
        }
    }

    return sum / window_size;
}

