namespace FileHasher {
    class FileReader {
        public:
            FileReader(const std::string& filePath) : filePath_(filePath), fileSize_(0) {}

            void openFile() {
                fileStream_.open(filePath_, std::ios::binary);
                if (!fileStream_) {
                    throw std::runtime_error("Failed to open the file");
                }
                fseek(fileStream_.rdbuf(), 0, SEEK_END);
                fileSize_ = ftell(fileStream_.rdbuf());
                rewind(fileStream_.rdbuf());
            }

            ~FileReader() {
                closeFile();
            }

            void closeFile() {
                if (fileStream_) {
                    fileStream_.close();
                }
            }

            void readChunk(size_t chunkSize, std::string& buffer) {
                if (!fileStream_) return;

                size_t bytesRead = fileStream_.readsome(&buffer[0], chunkSize);
                if (bytesRead == 0) throw std::runtime_error("End of file reached");

                buffer.resize(bytesRead);
            }

        private:
            std::string filePath_;
            long fileSize_;
            std::fstream fileStream_;
    };

    class PerformanceMonitor {
        public:
            void logTime(const std::chrono::duration<double>& time, const std::string& message) {
                if (logLevel_ > 0) {
                    auto now = std::chrono::high_resolution_clock::now();
                    auto elapsedTime = now - start_;
                    if (logLevel_ > 1) {
                        std::cout << "Chunk processing time: " << elapsedTime.count() << " seconds, " << message << std::endl;
                    } else {
                        std::cout << "Processing time: " << elapsedTime.count() << " seconds" << std::endl;
                    }
                }

                start_ = now;
            }

        private:
            int logLevel_;
            std::chrono::high_resolution_clock::time_point start_;
    };

    MD5(const void* buffer, size_t bufferSize) {
        // Efficient MD5 computation algorithm implementation
    }

    void computeMD5Hash(const std::string& filePath, const PerformanceMonitor& performanceMonitor = PerformanceMonitor()) {
        FileReader reader(filePath);
        reader.openFile();

        auto start = std::chrono::high_resolution_clock::now();
        MD5 hashValue;

        while (reader.fileSize_ > 0) {
            size_t chunkSize = 1024 * 1024; // 1MB chunk
            std::string buffer;
            reader.readChunk(chunkSize, buffer);

            auto chunkProcessingTime = performanceMonitor.logTime(std::chrono::high_resolution_clock::now() - start, "Chunk processing time");

            // Perform MD5 computation on the chunk
            hashValue.update(buffer);
        }

        performanceMonitor.logTime(std::chrono::high_resolution_clock::now() - start, "Total processing time");
    }
}
