typedef struct {
    Algorithm **algorithms;
    int size;
    int capacity;
    xmlParserCtxtPtr configCtx;
} AlgorithmCollection;

// Function to load algorithm definitions from XML file
AlgorithmCollection* loadAlgorithmsFromConfig(const char *filename) {
    // Load the XML configuration file
    xmlParserCtxtPtr configCtx = xmlNewParserContext(NULL, NULL);
    xmlDocPtr doc = xmlReadFile(filename, NULL, XML_PARSE_NOERROR | XML_PARSE_NOWARNING);

    AlgorithmCollection *collection = malloc(sizeof(AlgorithmCollection));
    collection->algorithms = NULL;
    collection->size = 0;
    collection->capacity = 10;

    // Parse the configuration file
    xmlDocPtr node = doc->children;
    while (node != NULL) {
        char *name = xmlGetProp(node, "name");
        void *algorithm = loadAlgorithm(name);
        if (algorithm == NULL) {
            printf("Error loading algorithm: %s\n", name);
            free(collection);
            return NULL;
        }
        Algorithm *alg = malloc(sizeof(Algorithm));
        alg->name = name;
        alg->algorithm = algorithm;
        collection->algorithms = realloc(collection->algorithms, sizeof(Algorithm*) * (collection->size + 1));
        collection->algorithms[collection->size] = alg;
        collection->size++;
    }
    xmlFreeDoc(doc);
    return collection;
}

// Function to load an algorithm from a shared object file
void *loadAlgorithm(const char *name) {
    // Load the shared object file
    void *algorithm = dlopen(name, RTLD_NOW);
    if (algorithm == NULL) {
        printf("Error loading algorithm: %s\n", name);
        return NULL;
    }
    return algorithm;
}

// Function to register an algorithm with the collection
int registerAlgorithm(AlgorithmCollection *collection, Algorithm *alg) {
    // Check for collisions or duplicates
    for (int i = 0; i < collection->size; i++) {
        if (strcmp(alg->name, collection->algorithms[i]->name) == 0) {
            printf("Error: duplicate algorithm registration\n");
            return -1;
        }
    }

    // Add the algorithm to the collection
    collection->algorithms = realloc(collection->algorithms, sizeof(Algorithm*) * (collection->size + 1));
    collection->algorithms[collection->size] = alg;
    collection->size++;
    return 0;
}

// Function to unregister an algorithm from the collection
int unregisterAlgorithm(AlgorithmCollection *collection, char *name) {
    // Find the algorithm in the collection
    for (int i = 0; i < collection->size; i++) {
        if (strcmp(name, collection->algorithms[i]->name) == 0) {
            free(collection->algorithms[i]);
            memmove(&collection->algorithms[i], &collection->algorithms[i + 1], sizeof(Algorithm*) * (collection->size - i));
            collection->size--;
            return 0;
        }
    }
    printf("Error: algorithm not found\n");
    return -1;
}

// Function to iterate over the algorithms in the collection
