using System.Threading.Tasks;

public class DatabaseReader
{
    public async Task<DataTable> ExecuteQueryAsync(string connectionString, string query, SqlParameter[] parameters)
    {
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            await connection.OpenAsync();

            using (SqlCommand command = new SqlCommand(query, connection))
            {
                foreach (SqlParameter parameter in parameters)
                {
                    command.Parameters.Add(parameter);
                }

                using (SqlDataReader reader = command.ExecuteReader())
                {
                    DataTable table = new DataTable();
                    while (await reader.ReadAsync())
                    {
                        table.Load(reader);
                    }
                    return table;
                }
            }
        }
    }
}

public class JsonApi
{
    public async Task<string> GetDataAsync(string connectionString, string query, SqlParameter[] parameters)
    {
        DataTable data = await DatabaseReader.ExecuteQueryAsync(connectionString, query, parameters);
        return JsonConvert.SerializeObject(data, Formatting.Indented);
    }
}
