using log4net;

public class XmlProcessor
{
    private readonly ILog _log = LogManager.GetLogger(typeof(XmlProcessor));

    public XmlNode RetrieveFirstNodeWithXPath(XDocument doc, string xPath)
    {
        DateTime start = DateTime.Now;
        var result = doc.Descendants().FirstOrDefault(x => x.XPathEvaluate(xPath).BooleanValue);
        DateTime end = DateTime.Now;

        if (result == null)
            _log.Info($"No matching node found for XPath query '{xPath}' in {end - start}ms.");
        else
        {
            _log.Warn($"Multiple nodes match the XPath query '{xPath}'. Potential ambiguity detected. Time taken: {end - start}ms.");
        }

        return result;
    }
}

public class DisjointPairAnalyzer
{
    public static void AnalyzeDisjointElementPairs(int[] arr)
    {
        UnionFind uf = new UnionFind(arr.Length);
        int count = 0;

        for (int i = 0; i < arr.Length; i++)
        {
            if (!uf.IsConnected(i, i))
                count++;
        }

        DateTime start = DateTime.Now;
        for (int i = 0; i < arr.Length; i++)
        {
            for (int j = i + 1; j < arr.Length; j++)
            {
                if (!uf.IsConnected(i, j) && arr[i] != arr[j])
                {
                    uf.Unite(i, j);
                    count++;
                }
            }
        }
        DateTime end = DateTime.Now;

        _log.Info($"Disjoint pair analysis completed in {end - start}ms. Count: {count}");
    }
}

public class UnionFind
{
    private int[] parent;
    private int[] rank;

    public UnionFind(int n)
    {
        parent = new int[n];
        rank = new int[n];

        for (int i = 0; i < n; i++)
        {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public bool IsConnected(int p, int q)
    {
        return Find(p) == Find(q);
    }

    public void Unite(int p, int q)
    {
        int rootP = Find(p);
        int rootQ = Find(q);

        if (rootP != rootQ)
        {
            if (rank[rootP] > rank[rootQ])
                parent[rootQ] = rootP;
            else
            {
                parent[rootP] = rootQ;
                if (rank[rootP] == rank[rootQ])
                    rank[rootQ]++;
            }
        }
    }

    private int Find(int p)
    {
        if (parent[p] != p)
            parent[p] = Find(parent[p]);

        return parent[p];
    }
}
