import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.security.MessageDigest;
import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;

public class TextFileProcessor {

    private static Log logger = LogFactory.getLog(TextFileProcessor.class);

    public void processTextFile(String filePath) {
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                line = line.toLowerCase();
                byte[] checksumBytes = getSha256Checksum(line);
                logger.info("Processed line: " + line + ", Checksum: " + bytesToHex(checksumBytes));
            }
        } catch (IOException e) {
            logger.error("Error processing file: " + e.getMessage());
        }
    }

    private byte[] getSha256Checksum(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return digest.digest(input.getBytes());
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder builder = new StringBuilder();
        for (byte b : bytes) {
            builder.append(String.format("%02x", b));
        }
        return builder.toString();
    }
}
