#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

int executeCommand(char* cmd) {
    pid_t pid = fork();
    if (pid == 0) {
        // Child process executes the command
        system(cmd);
        exit(0);
    } else if (pid > 0) {
        int status;
        waitpid(pid, &status, 0);
        return WEXITSTATUS(status);
    } else {
        perror("Fork failed");
        return 0; // Failure
    }
}

