class MeasurementHandler {
public:
    MeasurementHandler(int W, std::vector<UeMeasurementResult>& measurements)
        : windowSize(W), measurements(measurements) {}

    void handleMeasurement(const UeMeasurementResult& measurement) {
        // Check if the buffer is full and calculate the moving average
        if (measurements.size() >= windowSize) {
            double sum = 0;
            for (int i = 0; i < windowSize; ++i) {
                sum += measurements[i].measurementValue;
            }
            double movingAverage = sum / windowSize;

            // Update the array and slide the window
            measurements.erase(measurements.begin());
            measurements.push_back(measurement);
        } else {
            // Add new measurement to the end of the buffer
            measurements.push_back(measurement);
        }
    }

private:
    int windowSize;
    std::vector<UeMeasurementResult>& measurements;
};

