typedef struct {
    int* states;
    int num_states;
    int** transitions;
    int last_state;
} FSA;

FSA* create_state_list(int* states, int num_states, int** transitions, int last_state) {
    FSA* new_fsm = (FSA*)malloc(sizeof(FSA));
    if (!new_fsm) {
        return NULL;
    }

    new_fsm->states = (int*)malloc(num_states * sizeof(int));
    if (!new_fsm->states) {
        free(new_fsm);
        return NULL;
    }

    new_fsm->num_states = num_states;

    int* current_state_list = states;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    for (int i = 0; i < last_state; i++) {
        if (current_state_list[i] >= num_states) {
            // Ignore transition leading to a state outside the current state list
            continue;
        }
        new_fsm->states[i] = current_state_list[i];
    }

    new_fsm->transitions = transitions;

    return new_fsm;
}
