int main() {
    FILE *fp;
    char line[LINE_LENGTH], *token, *buf = NULL, *temp_buf = NULL;
    double avg_sum = 0.0, avg_count = 0.0, total_avg = 0.0;
    int line_num = 0;

    fp = fopen("input.txt", "r");
    if (fp == NULL) {
        printf("Error opening file.\n");
        return 1;
    }

    while (fgets(line, LINE_LENGTH, fp)) {
        temp_buf = malloc(strlen(line) + AVG_BUF_SIZE);
        strcpy(temp_buf, line);

        token = strtok(line, " ");
        double sum = 0.0;
        int count = 0;

        while (token != NULL) {
            if (strlen(token) > 0 && !strcmp(token, "")) {
                sum += atof(token);
                count++;
            }
            token = strtok(NULL, " ");
        }

        avg_sum += sum;
        avg_count += count;
        total_avg = avg_sum / avg_count;

        char *ptr = temp_buf + strlen(line);
        sprintf(ptr, " %.2f", total_avg);
        ptr += strlen(".2f") + 1; // leave space for newline and NULL terminator
        strcpy(ptr, "\n");
        ptr += strlen("\n") - 1; // move back to overwrite the original line

        printf("%s", temp_buf);
        free(temp_buf);
    }

    fclose(fp);

    return 0;
}
