#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <semaphore.h>

#define DNS_PORT 53
#define MAX_HOSTNAME_LENGTH 256
#define MAX_CACHE_SIZE 1000
#define TTL_DEFAULT 3600 // 1 hour

typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    uint32_t ip;
    int64_t ttl;
} CacheEntry;

int cache_size = 0;
sem_t semaphore;

void *cache = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_cache() {
    if ((cache = malloc(MAX_CACHE_SIZE * sizeof(CacheEntry))) == NULL) {
        printf("Failed to allocate memory for the cache.\n");
        exit(1);
    }
    sem_init(&semaphore, 0, 1); // Initialize the semaphore
}

int get_cached_ip(const char *hostname, uint32_t *ip) {
    pthread_mutex_lock(&lock);
    if (cache_size == 0) {
        pthread_mutex_unlock(&lock);
        return -1; // Cache is empty
    }

    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            *ip = cache[i].ip;
            sem_wait(&semaphore); // Decrease the semaphore count
            pthread_mutex_unlock(&lock);
            return 0; // Found in cache
        }
    }

    pthread_mutex_unlock(&lock);
    return -1; // Not found in cache
}

int add_to_cache(const char *hostname, uint32_t ip) {
    pthread_mutex_lock(&lock);

    if (cache_size >= MAX_CACHE_SIZE) {
        pthread_mutex_unlock(&lock);
        return 0; // Cache is full
    }

    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            sem_post(&semaphore); // Increase the semaphore count
            pthread_mutex_unlock(&lock);
            return 0; // Already in cache
        }
    }

    CacheEntry entry;
    strcpy(entry.hostname, hostname);
    entry.ip = ip;
    entry.ttl = TTL_DEFAULT;
    cache[cache_size] = entry;

    cache_size++;

    sem_post(&semaphore); // Increase the semaphore count

    pthread_mutex_unlock(&lock);

    return 0; // Successfully added to cache
}

int main() {
    initialize_cache();

    // Test adding and retrieving hostnames from the cache
    uint32_t ip;
    int result = add_to_cache("example.com", inet_addr("192.0.2.1"));
    if (result == 0) printf("Added 'example.com' to the cache.\n");
    else printf("Failed to add 'example.com' to the cache.\n");

    result = get_cached_ip("example.com", &ip);
    if (result == 0) printf("Found 'example.com' in the cache with IP %d.\n", ip);
    else printf("'example.com' not found in the cache.\n");

    return 0;
}
