char* modify_filename(char* filename) {
    char new_filename[MAX_FILENAME_LENGTH];
    int i = strlen(filename);
    while (i > 0 && !isdigit(filename[i-1])) i--;
    char* ext = malloc(i+1);
    strncpy(ext, &filename[i], i);
    ext[i] = '\0';

    i -= 2;
    while (i > 0 && !strchr("JPHB", filename[i-1])) i--;
    char* type = malloc(3);
    strncpy(type, &filename[i], 2);
    type[2] = '\0';

    if (strlen(filename) + strlen(ext) + strlen(type) + 4 > MAX_FILENAME_LENGTH) {
        free(ext);
        free(type);
        return "Error: File name too long";
    }

    char* new_ext = NULL;
    for (char* p = strtok(SUPPORTED_TYPES, ""); p; p = strtok(NULL, "")) {
        if (!strcmp(p, type)) {
            new_ext = p;
            break;
        }
    }
    if (!new_ext) {
        free(ext);
        free(type);
        return "Error: Invalid file type";
    }

    for (i = strlen(filename); i > 0; ) {
        char* dot = strrchr(&filename[0], '.');
        if (dot) {
            char temp[MAX_FILENAME_LENGTH];
            strncpy(temp, filename, dot-filename);
            temp[dot-filename] = '\0';
            strcat(new_filename, temp);
            strcat(new_filename, ".");
        } else {
            strcpy(new_filename, filename);
        }
        i -= dot ? dot - filename : strlen(filename);
    }

    if (new_ext) {
        strcat(new_filename, new_ext);
        free(ext);
        free(type);
    } else {
        return "Error: No valid extension found";
    }

    return new_filename;
}
