#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>

#define MAX_CONCURRENT_EXEC 10
#define LOG_LEVEL_ERROR 1
#define LOG_LEVEL_INFO 0

typedef struct {
    pid_t pid;
    char* command;
} CommandInfo;

void sigchild_handler(int signum) {
    int status;
    while(waitpid(-1, &status, WNOHANG) > 0) {}
}

int execute_commands(char* command, char* env, int max_concurrent) {
    if (max_concurrent < 1 || max_concurrent > MAX_CONCURRENT_EXEC)
        return -1;

    pid_t pids[max_concurrent];
    CommandInfo commands[max_concurrent];

    for (int i = 0; i < max_concurrent; i++) {
        int status;
        pids[i] = fork();
        if (pids[i] == 0) { // Child process
            setenv("PATH", env, 1);
            execvp(command, NULL); // Execute the command
            exit(0);
        } else if (pids[i] < 0) {
            return -1; // Error forking
        }
    }

    signal(SIGCHLD, sigchild_handler);

    int failed = 0;
    for (int i = 0; i < max_concurrent; i++) {
        pid_t pid = waitpid(pids[i], &status, WNOHANG);
        if (pid <= 0) { // Child process is still running
            failed = 1;
            break;
        }
        if (!WIFEXITED(status)) { // Command execution failed
            failed = 1;
            break;
        }
    }

    for (int i = 0; i < max_concurrent; i++) {
        if (pids[i] != 0) {
            kill(pids[i], SIGTERM); // Terminate the command
            waitpid(pids[i], &status, 0);
            if (!WIFEXITED(status)) { // Command termination failed
                return 0;
            }
        }
    }

    return failed ? 0 : 1;
}

int main() {
    char* command = "ls";
    char* env = "PATH=/usr/bin:/bin";
    int max_concurrent = 5;

    if (execute_commands(command, env, max_concurrent) == -1)
        printf("Error setting up concurrency management\n");
    else if (execute_commands(command, env, max_concurrent) != 0)
        printf("Command execution failed\n");
    else
        printf("Commands executed successfully\n");

    return 0;
}
