function executeShellCommands(commands, envVars) {
  const whitelist = ['ls', 'mkdir', 'rm', 'cp', 'mv'];
  const childProcess = require('child_process');
  const fs = require('fs');
  const path = require('path');
  const util = require('util');

  function executeCommand(command, env, cb) {
    try {
      if (whitelist.includes(command)) {
        const proc = childProcess.spawn(command, [], { stdio: 'pipe', env });
        let out = '';
        proc.stdout.on('data', data => {
          out += data.toString();
        });
        proc.stderr.on('data', data => {
          console.error(`Error running ${command}:`, data.toString());
        });
        proc.on('close', code => {
          if (code === 0) {
            cb(null, out);
          } else {
            cb(new Error(`Command ${command} failed with code ${code}`));
          }
        });
      } else {
        cb(new Error(`Unauthorized command: ${command}`));
      }
    } catch (err) {
      cb(err);
    }
  }

  function parseArgs() {
    const args = {};
    process.argv.slice(2).forEach(arg => {
      if (arg.startsWith('--')) {
        const [key, value] = arg.split('=');
        args[key.replace('--', '')] = value;
      } else {
        args._ = arg;
      }
    });
    return args;
  }

  function getEnvVars() {
    return Object.keys(process.env).reduce((env, key) => ({ ...env, [key]: process.env[key] }), {});
  }

  const args = parseArgs();
  const env = getEnvVars();

  if (args._) {
    executeCommand(args._, env, err => {
      if (err) {
        console.error('Error running command:', err);
      } else {
        console.log('Command executed successfully');
      }
    });
  } else {
    Object.keys(commands).forEach(command => {
      executeCommand(command, env, err => {
        if (err) {
          console.error(`Error running ${command}:`, err);
        } else {
          console.log(`Command ${command} executed successfully`);
        }
      });
    });
  }

  function logCommandExecution(status, command) {
    const logger = require('morgan');
    logger.log(status, `Executed command: ${command}`);
  }

  function monitorCommandExecution(command) {
    // implement monitoring mechanism here
  }

  module.exports = executeShellCommands;
