#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    float* data;
    int capacity;
    int size;
} FloatDataset;

FloatDataset* create_dataset(int initial_capacity) {
    FloatDataset* dataset = (FloatDataset*)malloc(sizeof(FloatDataset));
    dataset->data = (float*)calloc(initial_capacity, sizeof(float));
    dataset->capacity = initial_capacity;
    dataset->size = 0;
    return dataset;
}

void destroy_dataset(FloatDataset* dataset) {
    free(dataset->data);
    free(dataset);
}

int process_data_stream(FloatDataset* dataset, float threshold, FILE* log_file) {
    int processed_count = 0;
    float sum = 0.0f;

    while (1) {
        // Receive data from the stream
        // Assume this is done through some existing function or library call
        float num;
        if (!scanf("%f", &num)) {
            break; // End of file or invalid input
        }

        if (dataset->size >= dataset->capacity) {
            int new_capacity = dataset->capacity * 2;
            FloatDataset* temp = create_dataset(new_capacity);
            temp->data[0] = num;
            temp->size = 1;

            for (int i = 0; i < dataset->size; ++i) {
                temp->data[i + 1] = dataset->data[i];
            }
            destroy_dataset(dataset);
            dataset = temp;
        } else {
            dataset->data[dataset->size++] = num;
        }

        // Filter out numbers greater than the threshold
        if (num > threshold) {
            continue;
        }

        sum += num;
        processed_count++;
    }

    fclose(log_file);

    printf("Count of filtered numbers: %d\n", processed_count);
    printf("Sum of filtered numbers: %.2f\n", sum);
    printf("Average of filtered numbers: %.2f\n", sum / processed_count);

    return processed_count;
}

int main() {
    FloatDataset* dataset = create_dataset(10);
    float threshold = 5.0f;

    FILE* log_file = fopen("process.log", "w");
    if (!log_file) {
        printf("Error opening log file.\n");
        return -1;
    }

    int processed_count = process_data_stream(dataset, threshold, log_file);

    destroy_dataset(dataset);
    fclose(log_file);
    return 0;
}
