// Function to perform HTTP requests using libcurl
int http_request(char *url, u_char **response_body) {
    CURL *curl;
    CURLcode res;
    char errorbuf[CURL_ERROR_SIZE];
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) return -1; // Error: unable to initialize libcurl

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_memory_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)response_body);

    res = curl_multi_perform(NULL, 0);
    if (res != CURLE_OK) {
        fprintf(stderr, "cURL error: %s\n", curl_easy_strerror(res));
        return -2; // Error: cURL request failed
    }

    curl_easy_cleanup(curl);
    curl_global_cleanup();

    return 0; // Success
}

// Function to parse JSON configuration entries and compute weighted averages
int process_config_file(char *filename, u_char **response_body) {
    int i;
    json_object *config_json = json_object_from_file(filename);

    if (!config_json) return -1; // Error: unable to load JSON file

    for (i = 0; i < json_object_array_length(config_json); i++) {
        json_object *entry_json = json_object_array_get_idx(config_json, i);
        int num_values;
        double sum = 0.0;
        double weights[256]; // Assume max 256 weights
        int weight_count = 0;

        if (json_object_object_get_ex(entry_json, "values", &num_values) &&
            json_object_object_get_ex(entry_json, "weights", &weight_count)) {
            for (int j = 0; j < num_values; j++) {
                double value;
                if (json_object_object_get_ex(entry_json, "values", &value)) {
                    sum += value * weights[j];
                }
            }

            printf("Weighted average: %.2f\n", sum);
        }
    }

    return 0; // Success
}

int main() {
    u_char *response_body[MAX_URL_LENGTH];

    // Read multiple JSON configuration files concurrently
    for (int i = 0; i < MAX_URL_LENGTH; i++) {
        char filename[256];
        FILE *file = fopen(filename, "r");
        if (!file) continue; // Skip invalid file

        process_config_file(filename, response_body);
    }

    return 0;
}

