void *read_list_thread(void *args) {
    int *list = (int *)args;
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    int count = 0;
    double sum = 0.0;
    int max_val = INT_MIN;

    while (1) {
        uint64_t val;
        if (!fscanf(stdin, "%llu", &val)) {
            break; // end of file or error
        }

        if (val > 0) {
            list[count] = (int)val;
            sum += val;
            max_val = val > max_val ? val : max_val;
            count++;
        } else if (ferror(stdin)) {
            fprintf(stderr, "Error reading from standard input.\n");
            exit(EXIT_FAILURE);
        }
    }

    pthread_mutex_lock(&mutex);
    printf("Largest integer: %d\n", max_val);
    printf("Average of positive integers: %.2lf\n", sum / count);
    pthread_mutex_unlock(&mutex);

    free(list);
    return NULL;
}

int main() {
    int num_threads = 4; // adjust the number of threads as needed
    pthread_t threads[num_threads];
    int *lists[num_threads];

    for (int i = 0; i < num_threads; i++) {
        lists[i] = (int *)malloc(sizeof(int) * 10000);
    }

    pthread_create(&threads[0], NULL, read_list_thread, lists[0]);
    pthread_create(&threads[1], NULL, read_list_thread, lists[1]);
    pthread_create(&threads[2], NULL, read_list_thread, lists[2]);
    pthread_create(&threads[3], NULL, read_list_thread, lists[3]);

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < num_threads; i++) {
