#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct node {
    int key;
    char* value;
    struct node* next;
} Node;

typedef struct hash_table {
    int size;
    Node** buckets;
} HashTable;

HashTable* hash_table_create(int size) {
    HashTable* table = malloc(sizeof(HashTable));
    table->size = size;
    table->buckets = (Node**)malloc(size * sizeof(Node*));
    for (int i = 0; i < size; i++) {
        table->buckets[i] = NULL;
    }
    return table;
}

void hash_table_destroy(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        Node* node = table->buckets[i];
        while (node != NULL) {
            Node* next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    free(table);
}

void add_node(HashTable* table, int key, char* value) {
    Node* node = malloc(sizeof(Node));
    node->key = key;
    node->value = value;
    node->next = NULL;

    int index = hash(key, table->size);
    Node* current = table->buckets[index];
    if (current == NULL) {
        table->buckets[index] = node;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
}

Node* get_node(HashTable* table, int key) {
    int index = hash(key, table->size);
    Node* current = table->buckets[index];
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    return current;
}

int remove_node(HashTable* table, int key) {
    int index = hash(key, table->size);
    Node* prev = NULL;
    Node* current = table->buckets[index];
    while (current != NULL && current->key != key) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) {
        return 0; // not found
    }

    if (prev == NULL) {
        table->buckets[index] = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    return 1; // removed
}

int hash(int key, int size) {
    return key % size;
}
