typedef struct {
    int userId;
    time_t startTime;
    time_t lastActiveTime;
} UserSession;

// Define the inactivity timeout in seconds
int T = 300; // default to 5 minutes

// Define a linked list node for the user sessions
typedef struct Node {
    UserSession* userSession;
    struct Node* next;
} Node;

// Initialize the head of the linked list
Node* head = NULL;

// Lock for thread-safe operations
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new user session
void addUserSession(int userId, time_t startTime) {
    pthread_mutex_lock(&lock);

    // Create a new node with the given user ID and start time
    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->userSession = (UserSession*) malloc(sizeof(UserSession));
    newNode->userSession->userId = userId;
    newNode->userSession->startTime = startTime;
    newNode->lastActiveTime = startTime;
    newNode->next = NULL;

    // Add the new node to the front of the list
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

// Function to update a user session's last active time
void updateUserSessionLastActive(int userId, time_t currentTime) {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        if (current->userSession->userId == userId) {
            current->lastActiveTime = currentTime;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

// Function to detect inactive sessions
void detectInactiveSessions() {
    time_t currentTime = time(NULL);

    Node* current = head;
    while (current != NULL) {
        if (currentTime - current->lastActiveTime > T) {
            // Session is inactive, remove it from the list
            Node* next = current->next;
            free(current);
            head = next;
            current = next;
        } else {
            break;
        }
    }
}

