// Define hash table
#define TABLE_SIZE 1024
int table[TABLE_SIZE];

// Define memory pool
void* bestFit(void** pool, size_t size) {
    void* best = NULL;
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (pool[i] == NULL && (best == NULL || size <= strlen(pool[best]))) {
            best = &pool[i];
        }
    }
    return best;
}

void worstFit(void** pool, size_t size) {
    void* worst = NULL;
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (pool[i] == NULL && (worst == NULL || strlen(pool[worst]) <= size)) {
            worst = &pool[i];
        }
    }
}

void firstFit(void** pool, size_t size) {
    void* first = NULL;
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (pool[i] == NULL) {
            first = &pool[i];
            break;
        }
    }
}

// Define custom logging system
void logEvent(const char* message) {
    // TO DO: Implement logging system
}

// Node management function
Node** manageNodes(int* numNodes, void** nodePool, int key, const char* value) {
    Node* newNode = (Node*)bestFit(nodePool, sizeof(Node));
    if (!newNode) return NULL;  // Out-of-memory condition

    newNode->key = key;
    newNode->value = strdup(value);
    table[key % TABLE_SIZE] = (int)newNode;

    (*numNodes)++;
    return nodePool;
}

void removeNode(int* numNodes, void** nodePool, int key) {
    Node* node = (Node*)table[key % TABLE_SIZE];
    if (!node) return;  // Key not found

    table[key % TABLE_SIZE] = 0;

    free(node->value);
    free(node);

    (*numNodes)--;
}

char* getNodeValue(int* numNodes, void** nodePool, int key) {
    Node* node = (Node*)table[key % TABLE_SIZE];
    if (!node) return NULL;  // Key not found

    return node->value;
}
