    Record **records;
    pthread_mutex_t mutex;
} HashTable;

HashTable* create_hash_table(int size) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    table->size = size;
    table->records = (Record**)calloc(size, sizeof(Record*));
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

void free_hash_table(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        if (table->records[i] != NULL) {
            free(table->records[i]);
        }
    }
    free(table->records);
    pthread_mutex_destroy(&table->mutex);
    free(table);
}

HashTable* resize_hash_table(HashTable* table, int new_size) {
    HashTable *new_table = create_hash_table(new_size);
    for (int i = 0; i < table->size; i++) {
        Record *record = table->records[i];
        while (record != NULL) {
            record = find_record_in_new_table(record, new_table);
        }
    }
    free(table->records);
    table->size = new_size;
    table->records = new_table->records;
    return table;
}

Record* find_record_in_new_table(Record *record, HashTable* table) {
    int index = hash_function(record->identifier, table->size);
    while (table->records[index] != NULL && strcmp(table->records[index]->identifier, record->identifier) < 0) {
        index = (index + 1) % table->size;
    }
    return table->records[index];
}

int main() {
    // Create hash table with initial size and records
    HashTable *table = create_hash_table(DEFAULT_HASH_TABLE_SIZE);

    // Populate the hash table with records
    for (...) {
        Record *record = (Record*)malloc(sizeof(Record));
        record->identifier = ...;
        record->value = ...;

        int index = hash_function(record->identifier, table->size);
        while (table->records[index] != NULL && strcmp(table->records[index]->identifier, record->identifier) < 0) {
            index = (index + 1) % table->size;
        }
        table->records[index] = record;
    }

    // Resize the hash table when necessary
