#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netdb.h>

#define DNS_CACHE_TTL 3600 // one hour in seconds
#define DNS_QUERY_TIMEOUT 5000 // five seconds
#define MAX_DNS_RECORDS 1024

typedef struct {
    uint32_t ip;
    time_t expires_at;
} cached_dns_entry;

// Thread-safe DNS cache with TTL-based expiration
static pthread_mutex_t dns_cache_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t dns_cache_cond = PTHREAD_COND_INITIALIZER;
static cached_dns_entry dns_cache[MAX_DNS_RECORDS];
static int dns_cache_size = 0;

void *gethostname_to_ip(const char *hostname) {
    int sockfd, retcode;
    struct addrinfo hints, *res;
    struct sockaddr_in *sockaddr;
    char ipstr[INET6_ADDRSTRLEN], hostname_copy[64];

    // Copy hostname to prevent modification
    strncpy(hostname_copy, hostname, sizeof(hostname_copy));
    hostname_copy[sizeof(hostname_copy) - 1] = '\0';

    // Initialize DNS resolver hints
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = 0;
    hints.ai_flags = AI_CANONNAME | AI_NUMERICHOST;

    // Perform DNS lookup with caching
    pthread_mutex_lock(&dns_cache_lock);
    for (int i = 0; i < dns_cache_size; i++) {
        if (!strcmp(hostname_copy, (const char *)dns_cache[i].ip)) {
            // Found cached record, check TTL
            if (time(NULL) <= dns_cache[i].expires_at) {
                pthread_mutex_unlock(&dns_cache_lock);
                return (void *)&(dns_cache[i].ip);
            } else {
                // Record has expired, remove from cache
                memmove(&dns_cache[i], &dns_cache[i + 1], sizeof(cached_dns_entry) * (dns_cache_size - i));
                dns_cache_size--;
            }
        }
    }

    // Perform DNS lookup if record not found or expired
    retcode = getaddrinfo(hostname_copy, NULL, &hints, &res);
    if (retcode != 0) {
        pthread_mutex_unlock(&dns_cache_lock);
        return (void *)-1; // No such host or failed query
    }

    // Store DNS record in cache with TTL
    sockaddr = (struct sockaddr_in *)res->ai_addr;
    inet_ntop(AF_INET, &sockaddr->sin_addr, ipstr, sizeof(ipstr));
    dns_cache[dns_cache_size].ip = *((uint32_t *)&sockaddr->sin_addr);
    dns_cache[dns_cache_size].expires_at = time(NULL) + DNS_CACHE_TTL;
    dns_cache_size++;

    pthread_mutex_unlock(&dns_cache_lock);

    // Return the IP address
    return (void *)(&(sockaddr->sin_addr));
}
