typedef struct node {
    int key;
    char *value;
} Node;

Node *create_node(int key, const char *value);
void destroy_node(Node *node);

int generate_filename(char *input_filename, char **new_filename) {
    // Predefined list of allowed file types and extensions
    const char *allowed_extensions[] = {"txt", "docx", "pdf"};

    // Check if input filename is valid
    if (strlen(input_filename) > 256 || !strchr(allowed_extensions, strrchr(input_filename, '.') + 1)) {
        *new_filename = "invalid_input.txt";
        return -1;
    }

    char *primary_component = strrchr(input_filename, '.');
    int key = atoi(primary_component);
    Node *node = create_node(key, primary_component);

    // Generate new extension
    char new_extension[10];
    for (int i = 0; i < 8; i++) {
        sprintf(new_extension + i, "%c", ('a' + (key % 26)));
        key /= 26;
    }
    sprintf(new_extension + strlen(new_extension), ".%s", new_extension);

    *new_filename = (char *)malloc(strlen(input_filename) + strlen(new_extension) + 1);
    strcpy(*new_filename, input_filename);
    strcat(*new_filename, new_extension);

    destroy_node(node);

    return 0;
}

Node *create_node(int key, const char *value) {
    Node *node = (Node *)malloc(sizeof(Node));
    node->key = key;
    node->value = strdup(value);
    return node;
}

void destroy_node(Node *node) {
    free(node->value);
    free(node);
}
