    if (entry->str && strlen(entry->str) > 0) {
        printf("Longest string: %s (%zu characters)\n", entry->str, entry->len);
    }

    free(entry->str);
    free(entry);

    return NULL;
}

void manage_strings(string_entry* entries, int count) {
