    pthread_t threads[MAX_COUNT];
    for (int i = 0; i < count; i++) {
        pthread_create(&threads[i], NULL, process_string, &entries[i]);
    }

    for (int i = 0; i < count; i++) {
        pthread_join(threads[i], NULL);
    }
}

void release_memory(string_entry* entries, int count) {
    for (int i = 0; i < count; i++) {
        free(entries[i].str);
        free(&entries[i]);
    }
}

