        char buffer[BUFFER_SIZE];
        fgets(buffer, BUFFER_SIZE, stdin);

        if (strlen(buffer) > 0 && buffer[strlen(buffer) - 1] != '\n') {
            // Handle malformed input
            continue;
        }

        entries = realloc(entries, (count + 1) * sizeof(string_entry));
        entries[count].str = strdup(buffer);
        entries[count++].len = strlen(entries[count-1].str);

        if (count >= MAX_COUNT) {
            break;
        }
    }

    manage_strings(entries, count);

    release_memory(entries, count);

    return 0;
}

