#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define a structure to represent a record
typedef struct {
    int value;
} Record;

// Function to generate random integers within a specified range
int getRandomInt(int min, int max) {
    return (rand() % ((max + 1) - min)) + min;
}

// Function to sort records based on the 'int' key values in ascending order
void quickSort(Record *records, int left, int right) {
    if (left < right) {
        int pivotIndex = left;
        Record pivot = records[pivotIndex];
        int i = left + 1, j = right;

        while (1) {
            while (i <= j && records[i].value <= pivot.value)
                i++;
            while (i <= j && records[j].value >= pivot.value)
                j--;

            if (i <= j) {
                Record temp = records[i];
                records[i] = records[j];
                records[j] = temp;
                i++;
                j--;
            } else
                break;
        }

        if (pivotIndex != j) {
            records[pivotIndex] = records[j];
            records[j] = pivot;
        }
    }
}

// Function to modify each record's 'int' field by adding a weighted average of its adjacent records' 'int' fields
void modifyRecords(Record *records, int *weights, int n) {
    for (int i = 0; i < n; i++) {
        if (i > 0)
            records[i].value += (weights[1] / sumWeights(weights)) * records[i - 1].value;
        if (i < n - 1)
            records[i].value += (weights[2] / sumWeights(weights)) * records[i + 1].value;
    }
}

// Function to log all operations, including memory allocations, sorting, and modifications
void logOperations(const char *filename, Record *records, int *offsetValues, int n) {
    FILE *file = fopen(filename, "a");
    if (file != NULL) {
        for (int i = 0; i < n; i++) {
            fprintf(file, "Record %d: %d\n", i, records[i].value);
        }
        fclose(file);
    }
}

// Function to sum the weights
int sumWeights(int *weights) {
    int sum = 0;
    for (int i = 1; i <= 2; i++)
        sum += weights[i];
    return sum;
}

int main() {
    // Initialize random number generation
    srand(time(NULL));

    // Initialize variables and arrays
    int n, offsetValuesSize, keysSize;
    Record *records;
    int *keys, *offsetValues;

    // Validate user input for size of 'long' offset values array, 'int' keys array, and the number of 'record' structures
    printf("Enter the size of the offset values array: ");
    scanf("%d", &offsetValuesSize);
    printf("Enter the size of the keys array: ");
    scanf("%d", &keysSize);
    printf("Enter the number of record structures: ");
    scanf("%d", &n);

    // Dynamically allocate memory for 'long' offset values array and 'int' keys array
    offsetValues = (int *)malloc(offsetValuesSize * sizeof(int));
    keys = (int *)malloc(keysSize * sizeof(int));

    // Dynamically allocate memory for the 'record' structures, each containing a single 'int' value
    records = (Record *)malloc(n * sizeof(Record));

    // Generate random 'int' values within a specified range and assign them to each record’s 'int' field
    for (int i = 0; i < n; i++) {
        int min = 1, max = 100;
        records[i].value = getRandomInt(min, max);
    }

    // Sort the records based on the 'int' key values in ascending order
    quickSort(records, 0, n - 1);

    // Modify each record's 'int' field by adding a weighted average of its adjacent records' 'int' fields
    int weights[] = {0.3, 0.4, 0.3};
    modifyRecords(records, weights, n);

    // Log all operations, including memory allocations, sorting, and modifications
    const char *filename = "log.txt";
    logOperations(filename, records, offsetValues, n);

    // Deallocate memory
    free(offsetValues);
    free(keys);
    free(records);

    return 0;
}
