// Structure for record data
typedef struct {
    int value;
    char status;
    char* metadata;
} Record;

// Function to dynamically allocate and initialize arrays
Record** dynamic_array_init(int num_records, int max_length) {
    // Initialize array pointers
    Record** records = (Record**)malloc(sizeof(Record*) * num_records);
    if (!records) return NULL;  // Memory allocation failed

    // Initialize offset array
    long* offsets = (long*)malloc(sizeof(long) * num_records);
    if (!offsets) {
        free(records);  // Free previously allocated memory
        return NULL;
    }

    // Initialize key array
    int* keys = (int*)malloc(sizeof(int) * num_records);
    if (!keys) {
        free(offsets);
        free(records);
        return NULL;
    }

    // Initialize record structures
    for (int i = 0; i < num_records; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            free(keys);
            free(offsets);
            free(records);
            return NULL;
        }

        // Initialize record fields
        records[i]->value = rand() % 100;  // Random value within range
        records[i]->status = (records[i]->value & 1) ? 'O' : 'E';  // Set status based on parity
        char* metadata_buffer = (char*)malloc(sizeof(char) * max_length);
        if (!metadata_buffer) {
            free(keys);
            free(offsets);
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }
        strcpy(metadata_buffer, "Metadata");  // Initialize metadata string
        records[i]->metadata = metadata_buffer;
    }

    return records;
}

// Function to deallocate memory
void dynamic_array_free(Record** records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(records[i]->metadata);
        free(records[i]);
    }
    free((char*)records);
}
