// Define a custom record structure with an int field
typedef struct {
    int key;
    int value;
} Record;

void my_function(int max_offset, int num_records) {
    // Dynamically allocate memory for offset and key arrays
    long* offsets = (long*)malloc(max_offset * sizeof(long));
    int* keys = (int*)malloc(max_offset * sizeof(int));

    // Initialize the arrays with user input values
    for (int i = 0; i < max_offset; i++) {
        offsets[i] = i;
        keys[i] = i % 10;
    }

    // Dynamically allocate memory for record array
    Record* records = (Record*)malloc(num_records * sizeof(Record));

    // Initialize the record array with user input values
    for (int i = 0; i < num_records; i++) {
        records[i].key = i % 10;
        records[i].value = i;
    }

    // Sort the records based on key values in ascending order
    qsort(records, num_records, sizeof(Record), my_compare);

    // Modify each record's value by adding a weighted average of its adjacent records' values to it
    for (int i = 1; i < num_records - 1; i++) {
        int sum = records[i-1].value + records[i+1].value;
        int weight = 2; // evenly distributed weights
        records[i].value += (sum / weight);
    }

    // Free the memory allocated for arrays and structures
    free(offsets);
    free(keys);
    free(records);

    // Log all operations, including memory allocations, sorting, and modifications
    FILE* log_file = fopen("my_log.txt", "a");
    fprintf(log_file, "Memory allocation: %d bytes\n", max_offset * sizeof(long));
    fprintf(log_file, "Sorting completed in O(%d) time complexity\n", num_records);
    for (int i = 0; i < num_records; i++) {
        fprintf(log_file, "Record %d: key=%d value=%d\n", i, records[i].key, records[i].value);
    }
    fclose(log_file);
}

// Custom compare function for qsort
int my_compare(const void* a, const void* b) {
    Record* record1 = (Record*)a;
    Record* record2 = (Record*)b;
    return record1->key - record2->key;
}
