#define RECORDS_THRESHOLD 1000
#define MIN_RANDOM_VALUE 1
#define MAX_RANDOM_VALUE 100

typedef struct {
    int value;
} record_t;

typedef struct {
    unsigned char crcflag;
    unsigned short rnti;
    unsigned short rx_ue_info_tag;
} NFAPI_CRC_INDICATION_PDU_T;

record_t* process_records(int* array_size) {
    srand(time(NULL));

    *array_size = 0;
    record_t** records = NULL;

    while (1) {
        int new_size = *array_size + 1;
        records = realloc(records, sizeof(record_t*) * new_size);

        if (!fgets((char*)(records[*array_size]), sizeof(record_t), stdin)) {
            break;
        }

        records[(*array_size)++] = (record_t*)malloc(sizeof(record_t));
        (*records[*array_size-1]).value = rand() % (MAX_RANDOM_VALUE - MIN_RANDOM_VALUE + 1) + MIN_RANDOM_VALUE;
    }

    int max_value = find_largest_value(records, *array_size);

    NFAPI_CRC_INDICATION_PDU_T* crc_indications = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * (*array_size));

    for (int i = 0; i < *array_size; i++) {
        crc_indications[i].rnti = rand();
        crc_indications[i].rx_ue_info_tag = rand();
        crc_indications[i].crcflag = (rand() % 2);
    }

    return records;
}

int find_largest_value(record_t** records, int size) {
    int max_value = records[0]->value;

    for (int i = 1; i < size; i++) {
        if (records[i]->value > max_value)
            max_value = records[i]->value;
    }

    return max_value;
}

void shrink_records(record_t** records, int* array_size) {
    while (*array_size >= RECORDS_THRESHOLD && *array_size > 0) {
        record_t** new_records = realloc(records, sizeof(record_t*) * --(*array_size));

        for (int i = 0; i < *array_size; i++) {
            records[i] = &new_records[i];
        }

        free(new_records);
    }
}

void free_records(record_t** records, int size) {
    for (int i = 0; i < size; i++)
        free(records[i]);

    free(records);
}
