void manageCharacterAttacks() {
    // Initialize JSON parser and load configuration settings
    Json::Value root = Json::loadFile("config.json");

    // Validate configuration entries and apply default values for missing or malformed entries
    if (root["attack_cooldown"].isInt()) {
        int cooldown = root["attack_cooldown"].asInt();
    } else {
        int cooldown = 9; // Default value
    }

    // Initialize last attack timestamp
    auto lastAttackTimestamp = chrono::high_resolution_clock::now().time_since_epoch().count() - (cooldown * 1000); // In milliseconds

    // Select one of three available attacks for the character to use, considering cooldown and print selected attack number
    vector<AttackRecord> attacks = {
        {"Fireball", 0},
        {"Ice Shard", 1},
        {"Thunderbolt", 2}
    };

    int selectedAttack = rand() % 3;

    if (chrono::high_resolution_clock::now().time_since_epoch().count() - lastAttackTimestamp >= cooldown * 1000) {
        // Attack can be executed, print the selected attack number
        cout << "Selected attack: " << attacks[selectedAttack].type << endl;
    } else {
        // Cooldown not met, wait for the specified time before executing the next attack
        chrono::milliseconds timeout(cooldown * 1000);
        this_thread::sleep_for(timeout);

        // Re-select an attack after cooldown is met
        selectedAttack = rand() % 3;
        cout << "Selected attack: " << attacks[selectedAttack].type << endl;
    }
}

int main() {
    manageCharacterAttacks();
    return 0;
}
