    if (dataset == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize random seed
    srand(time(NULL));

    for (int i = 0; i < numRecords; i++) {
        dataset[i].value = rand() % 100 + 1; // Random value within [1, 100]
        dataset[i].offset = rand() % ((maxOffsetSum - 1) / numRecords) + 1; // Random offset within allowed limit
    }

    return dataset;
}

void freeDataset(Record* dataset) {
    if (dataset != NULL) {
        free(dataset);
    }
}

long sumOffsets(const Record* dataset, int numRecords) {
    long totalOffset = 0;

    for (int i = 0; i < numRecords; i++) {
        totalOffset += dataset[i].offset;
    }

    return totalOffset;
}

void verifyDataset(Record* dataset, int maxOffsetSum) {
    long totalOffset = sumOffsets(dataset, sizeof(dataset) / sizeof(dataset[0]));

    if (totalOffset > maxOffsetSum) {
        printf("Dataset integrity issue: Total offset exceeds maximum limit.\n");
    } else {
        printf("Dataset integrity verified: Total offset within allowed limit.\n");
    }
}

int main() {
    int numRecords = 100;
    int maxOffsetSum = 1000000;

    Record* dataset = createDataset(numRecords, maxOffsetSum);

    if (dataset == NULL) {
        return -1; // Error handling
    }

    verifyDataset(dataset, maxOffsetSum);

    freeDataset(dataset);

    return 0;
}

