record* generateRecords(int numRecords, int minKey, int maxKey, long minOffset, long maxOffset) {
    // Check for potential memory allocation issues and potential errors
    if (numRecords <= 0 || minKey > maxKey || minOffset > maxOffset) {
        return NULL;
    }

    record* records = (record*)malloc(numRecords * sizeof(record));
    if (!records) {
        return NULL;
    }

    // Initialize random number generator for reproducibility
    srand(time(NULL));

    for (int i = 0; i < numRecords; i++) {
        records[i].key = rand() % (maxKey - minKey + 1) + minKey;
        records[i].offset = (long)rand() % (maxOffset - minOffset + 1) + minOffset;

        // Verification mechanism to ensure values fall within the range
        if (records[i].key < minKey || records[i].key > maxKey ||
            records[i].offset < minOffset || records[i].offset > maxOffset) {
            free(records);
            return NULL;
        }
    }

    return records;
}

