class DynamicValueGenerator {
public:
    DynamicValueGenerator(double min = 0.0, double max = 1.0) : min_(min), max_(max) {}

    double generateRandomFloat(bool inclusive = true) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<double> dis(min_, max_);
        return inclusive ? dis(gen) : (dis(gen) < 1.0 - (max_ - min_) / (1.0 - min_) ? min_ : max_);
    }

    int generateRandomInt(bool inclusive = true) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<double> dis(min_, max_);
        return static_cast<int>(inclusive ? dis(gen) + 0.5 : (dis(gen) < 1.0 - (max_ - min_) / (1.0 - min_) ? min_ : max_));
    }

private:
    double min_;
    double max_;
};
