<?php

class SessionTokenManager {
    private $tokenStore;
    private $invalidationPeriod;

    public function __construct($tokenStorePath, $invalidationPeriod = 3600) {
        $this->tokenStore = new TokenStore($tokenStorePath);
        $this->invalidationPeriod = $invalidationPeriod;
    }

    public function generateToken($userId) {
        while (true) {
            $token = random_bytes(16);
            if (!$this->tokenStore->exists($token)) {
                return $token;
            }
        }
    }

    public function validateToken($token, $userId) {
        if (!$this->tokenStore->isValid($token, $this->invalidationPeriod)) {
            throw new TokenInvalidException("Invalid or expired token: $token");
        }
    }

    public function invalidateToken($token) {
        $this->tokenStore->remove($token);
    }

    public function logTokenEvent($event, $token = null) {
        if ($token) {
            Logger::log("Session Token $event: $token");
        } else {
            Logger::log("Session Token $event");
        }
    }
}

class TokenStore {
    private $store;

    public function __construct($path) {
        $this->store = new \SplFileObject($path);
    }

    public function exists($token) {
        return $this->store->exists($token);
    }

    public function isValid($token, $invalidationPeriod) {
        $lastAccessTime = unserialize($this->store->read($token));
        if ($lastAccessTime + $invalidationPeriod < time()) {
            return false;
        }
        return true;
    }

    public function remove($token) {
        $this->store->delete($token);
    }
}

class Logger {
    private static $logPath;

    public static function log($message, $token = null) {
        if ($token) {
            file_put_contents(self::$logPath, "$token: $message\n", FILE_APPEND);
        } else {
            file_put_contents(self::$logPath, "$message\n", FILE_APPEND);
        }
    }
}

class TokenInvalidException extends Exception {}

