int count_fields(const char* line);

// Global variables
FILE* db_file;
int max_depth = 5; // Maximum record depth

int main() {
    FILE* file = fopen("input.txt", "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return 1;
    }

    // Initialize database connection
    db_file = fopen("database.db", "w");
    if (db_file == NULL) {
        printf("Error opening database file\n");
        fclose(file);
        return 2;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        process_record(line);
    }

    // Close files
    fclose(file);
    fclose(db_file);

    return 0;
}

void process_record(char* record) {
    int field_count = count_fields(record);

    double total = 0.0; // Initialize total sum for current record
    int last_three_fields = 0; // Keep track of the number of last three numeric fields

    char* token = strtok(record, " ");
    while (token != NULL) {
        if (strspn(token, ".0123456789-") > 0) { // Check if field contains numeric data
            double num;
            sscanf(token, "%lf", &num);
            total += num; // Add to total sum

            last_three_fields++;

            // If we've processed the last three fields, calculate and log average
            if (last_three_fields >= 3) {
                double average = total / last_three_fields;
                fprintf(stderr, "Record average: %.2lf\n", average);

                // Store result in database
                fprintf(db_file, "%f\n", average);
                last_three_fields = 0; // Reset counter for next record
            }
        } else {
            printf("Error: Non-numeric field '%s' in record\n", token);
        }

        token = strtok(NULL, " ");
    }
}

int count_fields(const char* line) {
    int fields = 1;
    while (*line != '\0') {
        if (isspace(*line)) {
            fields++;
        } else if (*line == '(') { // Check for nested records
            int depth = 1;
            while (depth > 0 && *line != '\0') {
                line++;
                if (*line == '(') {
                    depth++;
                } else if (*line == ')') {
                    depth--;
                }
            }
        }
    }
    return fields;
}
