entry* allocate_entries(int n, int max_data_size) {
    // Initialize the total size of 'data' structures
    int total_data_size = 0;

    // Allocate memory for the array of 'entry' structures
    entry* entries = (entry*)malloc(n * sizeof(entry));

    if (entries == NULL) {
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < n; i++) {
        // Allocate memory for the 'data' structure
        void* data = malloc(max_data_size);
        if (data == NULL) {
            free(entries); // Free allocated entries array
            return NULL;
        }

        entry current_entry;
        current_entry.value = (double)(rand() % 1000);
        current_entry.data = data;

        entries[i] = current_entry; // Store the entry in the entries array

        total_data_size += max_data_size; // Update the total size of 'data' structures
    }

    return entries;
}

compact_entry* compress_entries(entry* entries, int n) {
    compact_entry* compressed_entries = (compact_entry*)malloc(n * sizeof(compact_entry));
    if (compressed_entries == NULL) {
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        compressed_entries[i].value = entries[i].value;
        compressed_entries[i].data = entries[i].data;
    }

    return compressed_entries;
}

void verify_data(entry* entries, int n) {
    int total_size = 0;

    for (int i = 0; i < n; i++) {
        total_size += sizeof(entry); // Add the size of each entry to the total
    }

    if (total_size > max_allowed_limit) {
        printf("Data integrity verification failed: Total size exceeds maximum allowed limit.\n");
    } else {
        printf("Data integrity verification passed: Total size within acceptable limits.\n");
    }
}

int main() {
