    if (entries == NULL) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    compact_entry* compressed_entries = compress_entries(entries, n);
    free(entries); // Free the allocated entries array

    if (compressed_entries == NULL) {
        printf("Compression failed.\n");
        return -2;
    }

    verify_data(compressed_entries, n);

    free(compressed_entries); // Free the compressed entries array

