int calculate_moving_average(float* values, int window_size) {
    int sum = 0;
    for (int i = 0; i < window_size; i++) {
        sum += values[i];
    }
    return sum / window_size;
}

void init_population(UeMeasurementResult** measurement_results, int num_measurements, int window_size) {
    *measurement_results = (UeMeasurementResult*)malloc(num_measurements * sizeof(UeMeasurementResult));

    // Initialize and populate the dynamic array
    for (int i = 0; i < num_measurements; i++) {
        (*measurement_results)[i].ran_node_id = rand() % 100;
        (*measurement_results)[i].measurement_type = 'A';
        (*measurement_results)[i].measurement_value = (float)(rand() % 100) / 10.0f;
    }

    // Calculate and store the moving average
    float* values = (float*)malloc(window_size * sizeof(float));
    for (int i = 0; i < num_measurements; i++) {
        values[i % window_size] = (*measurement_results)[i].measurement_value;
        if (i >= window_size) {
            int sum = 0;
            for (int j = 0; j < window_size; j++) {
