class Event {
public:
    std::time_t timestamp;
    unsigned long id;
    std::vector<double> records;

    // constructor
    Event(std::time_t t, unsigned long i) : timestamp(t), id(i) {}

    // destructor
    ~Event() {
        for (auto& record : records)
            delete[] record;
    }
};

class EventStreamSystem {
public:
    static const int MAX_EVENTS = 10000; // adjust this value as needed
    static const int MAX_RECORDS_PER_EVENT = 100; // adjust this value as needed

    static void processEvents(std::ifstream& logFile) {
        std::vector<Event> events(MAX_EVENTS);
        Event* currentEvent = nullptr;
        unsigned long eventCount = 0;

        while (logFile.read((char*)&currentEvent->timestamp, sizeof(currentEvent->timestamp))) {
            if (eventCount >= MAX_EVENTS)
                break;

            logFile.read((char*)&currentEvent->id, sizeof(currentEvent->id));
            currentEvent->records.resize(MAX_RECORDS_PER_EVENT);

            for (int i = 0; i < MAX_RECORDS_PER_EVENT && logFile) {
                double record;
                logFile.read((char*)&record, sizeof(record));
                currentEvent->records.push_back(record);
            }

            events[eventCount++] = *currentEvent;
        }

        // parse and process the events
        for (auto& event : events) {
            if (event.id == 0) {
                std::cout << "Parsing event with no ID...\n";
                continue;
            }

            std::cout << "Event: " << event.id << "\n";

            // compute average value of last 10 numerical fields
            double sum = 0.0;
            int count = 0;

            for (int i = 0; i < event.records.size() && count < 10; ++i) {
                if (event.records[i] != (double)INT_MIN) { // handle INT_MIN value
                    sum += event.records[i];
                    count++;
                }
            }

            if (count > 0)
                std::cout << "Average of last 10 numerical fields: " << sum / count << "\n";

            // compute maximum value among the last 15 numerical fields
            double max = INT_MIN;

            for (int i = 0; i < event.records.size() && i < 15; ++i) {
                if (event.records[i] > max)
                    max = event.records[i];
            }

            std::cout << "Maximum value among the last 15 numerical fields: " << max << "\n";
        }
    }
};
