#include <pthread.h>
#include <crc32.h>

#define MAX_USER_SESSIONS 1000
#define CHECKSUM_SIZE 16
#define SESSION_EXPIRATION_HOURS 24

typedef struct {
    int user_id;
    time_t session_start_time;
    time_t last_active_time;
    int login_attempt_count;
    char checksum[CHECKSUM_SIZE];
} UserSession;

UserSession *user_sessions[MAX_USER_SESSIONS];
int session_count = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void calculate_checksum(UserSession* session) {
    unsigned long crc = crc32(0, NULL, 0);
    char data[1024] = {0};
    sprintf(data, "%d %ld %ld %d", session->user_id, session->session_start_time, session->last_active_time, session->login_attempt_count);
    crc = crc32(crc, (unsigned char*)data, strlen(data));
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, &crc, sizeof(unsigned long));
    unsigned char md5[16] = {0};
    MD5_Final(&ctx, md5);
    for (int i = 0; i < CHECKSUM_SIZE; i++) {
        session->checksum[i] = (char)(md5[i] >> 4);
    }
}

void* session_manager_thread(void* arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        if (session_count == 0) {
            pthread_cond_wait(&cond, &lock);
        }

        for (int i = 0; i < session_count; i++) {
            UserSession* session = user_sessions[i];
            time_t current_time = time(NULL);

            if ((current_time - session->last_active_time) > SESSION_EXPIRATION_HOURS * 3600) {
                // Session timeout, remove session
                session->login_attempt_count = 0;
                for (int j = i; j < session_count - 1; j++) {
                    user_sessions[j] = user_sessions[j + 1];
                }
                session_count--;
                break;
            }

            if (session->login_attempt_count >= 5) {
                // Lockout, wait for some time before allowing login again
                sleep(60); // 1 minute
                session->login_attempt_count = 0;
            }
        }

        pthread_mutex_unlock(&lock);
    }
}

void add_session(int user_id, int login_attempt_count) {
    if (session_count >= MAX_USER_SESSIONS) {
        return; // Session limit reached
    }

    UserSession* new_session = malloc(sizeof(UserSession));
    new_session->user_id = user_id;
    new_session->login_attempt_count = login_attempt_count;

    pthread_mutex_lock(&lock);
    for (int i = 0; i < session_count; i++) {
        if (user_sessions[i]->user_id == user_id) {
            // Update existing session
            free(user_sessions[i]);
            user_sessions[i] = new_session;
            break;
        }
    }

    if (i == session_count) {
        // New session, add it to the end
        user_sessions[session_count++] = new_session;
    }

    pthread_mutex_unlock(&lock);

    calculate_checksum(new_session);
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, &session_manager_thread, NULL);

    while (1) {
        // Handle API service requests for external authentication
    }

    return 0;
}
