    pool->size = initial_size;
    return pool;
}

// Custom allocator for the key array
void* custom_malloc(size_t size, MemoryPool* pool) {
    if (pool->size < size) {
        // Reallocate memory if needed
        pool->base = realloc(pool->base, pool->size + size);
        pool->size += size;
    }
    return ((char*)pool->base) + (pool->size - size);
}

