void* custom_record_malloc(size_t size, MemoryPool* overflow_pool) {
    // Use a separate memory pool for the overflow buffer
    if (overflow_pool->size < size) {
        overflow_pool->base = realloc(overflow_pool->base, overflow_pool->size + size);
        overflow_pool->size += size;
    }
    return ((char*)overflow_pool->base) + (overflow_pool->size - size);
