namespace LogSystem {
    namespace {
        enum LogLevel { DEBUG, INFO, WARNING, ERROR };

        class Logger {
        public:
            Logger(const std::string& envVarPrefix = "LOG_") :
                logLevel_(INFO), envVarPrefix_(envVarPrefix) {
                loadConfig();
            }

            ~Logger() {}

            void setLogLevel(LogLevel level) {
                logLevel_ = level;
            }

            template <typename... Args>
            void log(LogLevel level, const std::string& message, Args&&... args) {
                if (level >= logLevel_) {
                    std::lock_guard<std::mutex> lock(mutex_);
                    buffer_.push_front({ std::chrono::high_resolution_clock::now(), level, message, std::forward<Args>(args)... });
                }
            }

        private:
            void loadConfig() {
                // Load configuration from environment variables and files
            }

            LogLevel logLevel_;
            const std::string envVarPrefix_;
            std::mutex mutex_;
            std::deque<std::tuple<std::chrono::high_resolution_clock::time_point, LogLevel, std::string>> buffer_;

            void asyncLog() {
                while (true) {
                    std::unique_lock<std::mutex> lock(mutex_);
                    if (!buffer_.empty()) {
                        auto& logEntry = buffer_.front();
                        buffer_.pop_front();

                        // Log the message to file and/or send to monitoring framework
                        std::cout << "Logged: " << std::get<2>(logEntry) << " at " << std::get<0>(logEntry).time_since_epoch().count() << std::endl;

                        if (std::get<1>(logEntry) == ERROR) {
                            // Send alert to monitoring framework
                        }
                    }

                    lock.unlock();
                    std::this_thread::sleep_for(std::chrono::milliseconds(10)); // Log in batches with some delay
                }
            }
        };

    }  // namespace

    class LoggingSystem {
    public:
        LoggingSystem() : logger_(std::thread(&Logger::asyncLog, &logger_)) {}

        ~LoggingSystem() {
            logger_.join();
        }

        void setLogLevel(LogLevel level) {
            logger_.setLogLevel(level);
        }

        template <typename... Args>
        void log(LogLevel level, const std::string& message, Args&&... args) {
            logger_.log(level, message, std::forward<Args>(args)...);
        }
    private:
        Logger logger_;
    };
}  // namespace LogSystem

int main() {
    LogSystem::LoggingSystem loggingSystem;

    loggingSystem.setLogLevel(LogSystem::DEBUG);

    loggingSystem.log(LogSystem::INFO, "Some info message");
    loggingSystem.log(LogSystem::WARNING, "Warning: Something went wrong");
    loggingSystem.log(LogSystem::ERROR, "Critical error: System failure");

    return 0;
}
