    return (rand() % (max - min + 1)) + min;
}

// Structure for record with an 'int' field
typedef struct Record {
    int data;
} Record;

// Function to sort the records based on the 'int' key values in ascending order
void sort_records(Record *records, int n) {
    int i, j, temp;
    for (i = 0; i < n - 1; i++) {
        for (j = 0; j < n - i - 1; j++) {
            if (records[j].data > records[j + 1].data) {
                // Swap the 'int' field values
                temp = records[j].data;
                records[j].data = records[j + 1].data;
                records[j + 1].data = temp;
            }
        }
    }
}

// Function to modify each record’s 'int' field by adding a weighted average of its adjacent records’ 'int' fields
void modify_records(Record *records, int n, int *weights) {
    int i, sum;
    for (i = 0; i < n; i++) {
        sum = 0;
        for (int j = -1; j <= 1; j++) {
            if (i + j >= 0 && i + j < n) {
                sum += records[i + j].data * weights[abs(j)];
            }
        }
        records[i].data = (sum / weights[0]) + records[i].data;
    }
}

