using System;
using System.Collections.Generic;
using System.Threading;

public class TransactionProcessor {
    private readonly Dictionary<string, Func<Dictionary<string, object>>> _dbConnections;
    private readonly List<Transaction> _transactions;

    public TransactionProcessor(Dictionary<string, Func<Dictionary<string, object>>> dbConnections) {
        _dbConnections = dbConnections;
        _transactions = new List<Transaction>();
    }

    public void ProcessTransaction(Transaction transaction) {
        try {
            // Acquire a database connection
            var dbConnection = _dbConnections[transaction.AccountId];
            var dbContext = dbConnection();

            // Execute the SQL command
            dbContext.Execute(transaction.SqlCommand);

            // Commit the transaction
            dbContext.Commit();
        } catch (Exception ex) {
            // Log the error and retry with exponential backoff
            Console.WriteLine($"Transaction failed: {ex.Message}");
            Thread.Sleep(Timeout.InfiniteTimeSpan);
        }
    }

    public List<TransactionResult> GetTransactionResults() {
        var results = new List<TransactionResult>();

        foreach (var transaction in _transactions) {
            try {
                // Acquire a database connection
                var dbConnection = _dbConnections[transaction.AccountId];
                var dbContext = dbConnection();

                // Execute the SQL command and get the result
                var result = dbContext.Execute(transaction.SqlCommand);

                results.Add(new TransactionResult { Success = true, Result = result });
            } catch (Exception ex) {
                results.Add(new TransactionResult { Success = false, Error = ex.Message });
            }
        }

        return results;
    }
}

public class Transaction {
    public string Description { get; set; }
    public decimal Amount { get; set; }
    public int AccountId { get; set; }
    public string SqlCommand { get; set; }
}

public class TransactionResult {
    public bool Success { get; set; }
    public object Result { get; set; }
    public string Error { get; set; }
}
