    return { status: 400, message: 'Invalid request body' };
  }

  // update resource in database with new data and version
  const updatedResource = updateDatabase(id, requestBody);

  // check for concurrent updates
  if (updatedResource.version !== version) {
    return { status: 409, message: 'Concurrent update detected. Please retry.' };
  }

  return { status: 200, body: updatedResource };
}

// DELETE /resources/:id
function deleteResource(id) {
  // optimistic locking
  const version = getResourceVersion(id);

  // delete resource from database with correct version
  const deleted = deleteDatabase(id, version);

  if (!deleted) {
    return { status: 404, message: 'Resource not found' };
  }

  return { status: 200, message: 'Resource deleted successfully' };
}

