angular.module('app').factory('refreshDialogFields', function() {
  return function(resourceId, url) {
    // 1. Iterate through all dialog fields and send message to parent window
    var fields = [];
    for (var i = 0; i < $scope.dialogs.length; i++) {
      if ($scope.dialogs[i].name === resourceId) {
        fields.push($scope.dialogs[i]);
        $.post(url, { field: $scope.dialogs[i].name }, function(data) {
          // update dialog field values
          for (var j = 0; j < fields.length; j++) {
            if (data[j] !== undefined) {
              $scope.dialogs[fields[j]].value = data[j];
            }
          }
        });
      }
    }

    // 2. Ensure message sent to parent window is serialized correctly
    var serialize = function(obj) {
      var str = '';
      for (var p in obj) {
        if (obj.hasOwnProperty(p)) {
          str += p + '=' + obj[p] + '&';
        }
      }
      return str.substring(0, str.length - 1);
    };

    // 3. Handle asynchronous communication with parent window
    $.ajax({
      type: 'POST',
      url: url,
      data: serialize({ field: resourceId }),
      success: function(data) {
        // update dialog field values
        for (var j = 0; j < fields.length; j++) {
          if (data[j] !== undefined) {
            $scope.dialogs[fields[j]].value = data[j];
          }
        }
      },
      error: function() {
        // fallback mechanism for refreshing dialog fields
        for (var k = 0; k < fields.length; k++) {
          if ($scope.dialogs[fields[k]].dirty) {
            // save unsaved changes before reloading
            $.post(url, { field: $scope.dialogs[fields[k]].name }, function(data) {
              // update dialog field values
              $scope.dialogs[fields[k]].value = data;
            });
          }
        }
      }
    });

    return true;
  };
});
