typedef struct {
    Node* head;
    Node* tail;
    int size;
} LinkedList;

// Function to create a new node with given value and string
Node* newNode(int value, const char* str) {
    Node* node = (Node*) malloc(sizeof(Node));
    node->value = value;
    node->str = (char*) malloc(strlen(str) + 1);
    strcpy(node->str, str);
    return node;
}

// Function to create a new linked list with given size
LinkedList* newList(int size) {
    LinkedList* list = (LinkedList*) malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return list;
}

// Function to insert a new node at the end of the linked list
void insertNode(LinkedList* list, Node* node) {
    if (list->tail == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
}

// Function to remove a node from the linked list
void removeNode(LinkedList* list, Node* node) {
    if (list->head == node) {
        list->head = node->next;
    } else {
        Node* current = list->head;
        while (current != NULL && current->next != node) {
            current = current->next;
        }
        if (current != NULL) {
            current->next = node->next;
            if (node == list->tail) {
                list->tail = current;
            }
        }
    }
}

