    if (isset($requestBody['id'])) {
        // Update user
        $userController->createOrUpdateUser($requestBody);
        return new JsonResponse(array('message' => 'User updated successfully'));
    } elseif (isset($requestBody['sub_action']) && $requestBody['sub_action'] === 'delete') {
        // Delete user
