            printf("Error: Key %d is not unique.\n", records[i].key);
            return;
        }
        key_count[records[i].key]++;
    }

    // Initialize offsets
    for (int i = 0; i < num_records; i++) {
        offsets[i] = i * sizeof(record);
    }
}

