        log_data = compress_log(log_data);
    }
}

void handle_out_of_memory(int num_records) {
    if (num_records > MAX_RECORDS) {
        printf("Error: Out of memory.\n");
    } else {
        // Reuse previously freed memory blocks
        void* block = realloc(NULL, MEMORY_THRESHOLD);
        if (!block) {
            printf("Error: Primary memory allocation failed.\n");
            return;
        }
        records = (record*)block;
        keys = (int*)malloc(MAX_KEY * sizeof(int));
        offsets = (long*)malloc(MAX_RECORDS * sizeof(long));

        // Initialize records and keys
        for (int i = 0; i < num_records; i++) {
            records[i].value = rand() % 100;
            records[i].key = i;
        }
    }
}

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        // Attempt alternative allocation strategies
        ptr = reuse_freed_memory(size);
        if (!ptr) {
            ptr = use_external_storage(size);
            if (!ptr) {
                ptr = request_distributed_memory(size);
            }
        }
    }
    return ptr;
}

void deallocate_memory(void* ptr, size_t size) {
