use std::fs::{create_dir_all, read_dir};
use std::path::{Path, PathBuf};
use std::collections::HashMap;
use crc32fast::Crc32Fast;
use sha2::{Sha256, Digest};

struct UeMeasurementResult {
    ran_node_id: u64,
    measurement_type: String,
    measurement_value: f64,
    moving_average: f64,
}

fn initialize_measurement_directory() -> Result<(), std::io::Error> {
    let measurement_dir = get_measurement_dir()?;
    create_dir_all(&measurement_dir, 0o755)?;

    let mut record_array = vec![UeMeasurementResult {
        ran_node_id: 0,
        measurement_type: "unknown".to_string(),
        measurement_value: 0.0,
        moving_average: 0.0
    }; 100];

    for record in &mut record_array {
        *record.ran_node_id = rand::random::<u64>();
        *record.measurement_type = format!("measurement_{}", rand::random::<u32>());
        *record.measurement_value = rand::random::<f64>() * 10.0;
        *record.moving_average = (record.measurement_value + record.moving_average) / 2.0;
    }

    let mut file_array: Vec<PathBuf> = vec![];
    for i in 0..100 {
        let mut pathbuf = Path::new(&measurement_dir).join(format!("measurement_{}.bin", i));
        create_file(&pathbuf)?;

        let mut crc32 = Crc32Fast::new();
        crc32.update_pathbuf(&pathbuf)?;
        let mut sha256 = Sha256::new();
        sha256.update_pathbuf(&pathbuf)?;

        let data = format!("{} {} {}", record_array[i].measurement_type, record_array[i].measurement_value, record_array[i].moving_average);
        write_file(&pathbuf, &data, crc32.result(), sha256.finalize())?;
    }

    Ok(())
}

fn get_measurement_dir() -> Result<PathBuf, std::io::Error> {
    let measurement_dir = match dirs::home_dir() {
        Some(path) => path.join("measurement"),
        None => return Err(std::io::Error::new(std::io::ErrorKind::NotFound, "Home directory not found")),
    };

    if !measurement_dir.exists() {
        create_dir_all(&measurement_dir, 0o755)?;
    }

    Ok(measurement_dir)
}

fn create_file(path: &Path) -> Result<(), std::io::Error> {
    match fs::create_dir_all(path) {
        Ok(_) => Ok(()),
        Err(err) => Err(err),
    }
}

fn write_file(path: &Path, data: &str, crc32: u32, sha256: Vec<u8>) -> Result<(), std::io::Error> {
    let mut file = match fs::OpenOptions::new().write(true).create(true).open(path) {
        Ok(file) => file,
        Err(err) => return Err(err),
    };

    match file.write_all(data.as_bytes()) {
        Ok(_) => {}
        Err(err) => return Err(err),
    };

    match file.write_all(&[0, 0, 0, 0]) {
        Ok(_) => {}
        Err(err) => return Err(err),
    };

    match file.write_all(&crc32.to_le_bytes()) {
        Ok(_) => {}
        Err(err) => return Err(err),
    };

    match file.write_all(sha256.as_slice()) {
        Ok(_) => {}
        Err(err) => return Err(err),
    };

    Ok(())
}
