const fs = require('fs');
const path = require('path');
const { promisify } = require('util');
const { parallelLimit } = require('async');

function readFiles(directory, extensions, maxFileSizeThreshold, maxConcurrency) {
  const logFile = 'read_files.log';
  const logger = (message) => fs.appendFileSync(logFile, `${new Date().toISOString()}: ${message}\n`);

  async function processFile(file) {
    if (!extensions.includes(path.extname(file))) return;
    try {
      const fileStat = await promisify(fs.stat)(file);
      if (fileStat.size > maxFileSizeThreshold) return;

      logger(`Processing: ${file} (${fileStat.size} bytes)`);
      const fileContent = await fs.promises.readFile(file, 'utf8');
      logger(`Finished processing: ${file}`);
      return fileContent;
    } catch (err) {
      logger(`Error reading: ${file} - ${err.message}`);
    }
  }

  async function readFilesInParallel() {
    const files = await fs.readdir(directory);
    const tasks = files.map((file) => processFile(path.join(directory, file)));
    return parallelLimit(tasks, maxConcurrency);
  }

  try {
    const contents = await readFilesInParallel();
    logger(`Read ${contents.length} files`);
    return contents.join('');
  } catch (err) {
    logger(`Error reading files: ${err.message}`);
    throw err;
  }
}

module.exports = readFiles;
