async function executeTestSuite(label, f) {
  import('path/to/module').then((module) => {
    if (!module) {
      console.error(`Failed to load module: ${label}`);
      return;
    }

    // Set up and reset blueslip
    const blueslip = await require('blueslip');
    let blueResetPromise;

    async function runTest() {
      try {
        await f();
        console.log(`${label} passed`);
      } catch (error) {
        if (error instanceof Error) {
          console.error(`Error in ${label}: ${error.message}`);
        } else {
          console.error(`Error in ${label}: ${error}`);
        }
      } finally {
        blueResetPromise = blueslip.reset();
      }
    }

    // Run the test
    runTest().then(() => {
      if (blueResetPromise) {
        return blueResetPromise;
      } else {
        return Promise.resolve();
      }
    }).timeout(10000, () => {
      console.warn(`Timeout in ${label}. Skipping further tests`);
    });
  }, () => {
    console.error('Failed to load module');
  });
}
