#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>

#define BUFFER_SIZE 1024
#define MAX_MESSAGES 1000
#define PRIORITY_LEVELS 5

typedef struct {
    int id;
    int priority;
    char* payload;
} Message;

Message buffer[BUFFER_SIZE];
int messageCount = 0;
int head = 0, tail = 0;

sem_t empty, full, mutex;
pthread_cond_t producerCond, consumerCond;

void produceMessage(Message msg) {
    sem_wait(&full);
    sem_wait(&mutex);

    buffer[tail] = msg;
    tail = (tail + 1) % BUFFER_SIZE;
    messageCount++;

    if (messageCount == BUFFER_SIZE)
        pthread_cond_signal(&producerCond);

    sem_post(&mutex);
}

Message consumeMessage() {
    Message msg;
    sem_wait(&empty);
    sem_wait(&mutex);

    msg = buffer[head];
    head = (head + 1) % BUFFER_SIZE;

    if (--messageCount == 0)
        pthread_cond_signal(&consumerCond);

    sem_post(&mutex);
    return msg;
}

void* producerThread(void*) {
    int i;
    for(i=0; i<MAX_MESSAGES; i++) {
        Message msg;
        // Generate message contents...
        produceMessage(msg);
    }
    return NULL;
}

void* consumerThread(void*) {
    while(1) {
        Message msg = consumeMessage();
        // Process the message...
    }
    return NULL;
}

int main() {
    pthread_t producer, consumer;

    sem_init(&empty, 0, BUFFER_SIZE);
    sem_init(&full, 0, 0);
    sem_init(&mutex, 0, 1);

    pthread_cond_init(&producerCond, NULL);
    pthread_cond_init(&consumerCond, NULL);

    pthread_create(&producer, NULL, producerThread, NULL);
    pthread_create(&consumer, NULL, consumerThread, NULL);

    pthread_join(producer, NULL);
    pthread_join(consumer, NULL);

    sem_destroy(&empty);
    sem_destroy(&full);
    sem_destroy(&mutex);
    pthread_cond_destroy(&producerCond);
    pthread_cond_destroy(&consumerCond);

    return 0;
}
