// Define the SensorData structure
typedef struct {
    int SENSOR_ID;
    time_t TIME_STAMP;
    char SENSORDATA_TYPE[16];
    double VALUE;
} SensorData;

// Function to initialize and populate a dynamic array of SensorData structures
SensorData* init_and_populate_array(int capacity) {
    SensorData* arr = (SensorData*)malloc(sizeof(SensorData) * capacity);
    return arr;
}

// Calculate the exponential moving average (EMA)
double calculate_ema(double value, double prev_ema, double alpha) {
    return alpha * value + (1 - alpha) * prev_ema;
}

// Function to initialize and populate a dynamic array of SensorData structures
void process_sensor_data(SensorData* arr, int capacity, double alpha) {
    for (int i = 0; i < capacity; i++) {
        // Initialize the first data point with some default values
        if (i == 0) {
            arr[i].SENSOR_ID = 1;
            arr[i].TIME_STAMP = time(NULL);
            strcpy(arr[i].SENSORDATA_TYPE, "Temperature");
            arr[i].VALUE = 25.5;
        } else {
            // Calculate the EMA for each subsequent data point
            double prev_ema = calculate_ema(arr[i-1].VALUE, 0, alpha);
            arr[i].SENSOR_ID = i + 1;
            arr[i].TIME_STAMP = time(NULL);
            strcpy(arr[i].SENSORDATA_TYPE, "Temperature");
            arr[i].VALUE = prev_ema; // Update the EMA
        }
    }
}

int main() {
    int capacity = 1000;
    double alpha = 0.3;

