#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

// Define a record structure containing an integer value
typedef struct {
    int val;
} record_t;

// Define a hash table entry with a key, value, and collision flag
typedef struct {
    int key;
    record_t *value;
    bool is_collision;
} ht_entry_t;

// Define the custom memory allocator structure
typedef struct {
    void **primary_pool;      // Primary memory pool for records
    uint32_t primary_pool_size;
    void **secondary_pool;     // Secondary memory pool for arrays and entries
    uint32_t secondary_pool_size;
    pthread_mutex_t lock;      // Lock for concurrent access
} allocator_t;

// Initialize the custom memory allocator
allocator_t *init_allocator(uint32_t primary_pool_size, uint32_t secondary_pool_size) {
    allocator_t *allocator = (allocator_t *)malloc(sizeof(allocator_t));
    allocator->primary_pool = (void **)malloc(primary_pool_size * sizeof(void *));
    allocator->secondary_pool = (void **)malloc(secondary_pool_size * sizeof(void *));
    allocator->primary_pool_size = primary_pool_size;
    allocator->secondary_pool_size = secondary_pool_size;
    pthread_mutex_init(&allocator->lock, NULL);
    return allocator;
}

// Deallocate memory from the custom allocator
void dealloc_allocator(allocator_t *allocator) {
    for (uint32_t i = 0; i < allocator->primary_pool_size; i++)
        free((record_t *)allocator->primary_pool[i]);
    free(allocator->primary_pool);
    for (uint32_t i = 0; i < allocator->secondary_pool_size; i++)
        free(allocator->secondary_pool[i]);
    free(allocator->secondary_pool);
    pthread_mutex_destroy(&allocator->lock);
    free(allocator);
}

// Custom hash function using a simple modulo operation
size_t hash_function(int key) {
    return key % (allocator->primary_pool_size / 2);
}

// Find an entry in the hash table with a given key, handling collisions
ht_entry_t *find_entry(allocator_t *allocator, int key) {
    size_t index = hash_function(key);
    while (true) {
        ht_entry_t *entry = (ht_entry_t *)allocator->secondary_pool[index];
        if (!entry || entry->key == key)
            return entry;
        index = (index + 1) % allocator->primary_pool_size / 2;
    }
}

// Insert a new record into the hash table, handling collisions
void insert_record(allocator_t *allocator, int key, int val) {
    ht_entry_t *entry = find_entry(allocator, key);
    if (!entry) {
        // Allocate a new record and entry
        record_t *record = (record_t *)malloc(sizeof(record_t));
        record->val = val;
        allocator->primary_pool[hash_function(key)] = record;
        entry = (ht_entry_t *)malloc(sizeof(ht_entry_t));
        entry->key = key;
        entry->value = record;
    } else {
        // Update the existing record
        entry->value->val = val;
    }
}

// Update the value of a record given its key, handling collisions
void update_record(allocator_t *allocator, int key, int new_val) {
    ht_entry_t *entry = find_entry(allocator, key);
    if (entry && entry->is_collision)
        printf("Collision detected while updating record with key %d.\n", key);
    else
        entry->value->val = new_val;
}

// Print statistics on memory usage and cache hit/miss rates
void print_stats(allocator_t *allocator) {
    uint32_t hits = 0, misses = 0;
    for (size_t i = 0; i < allocator->primary_pool_size / 2; i++) {
        ht_entry_t *entry = (ht_entry_t *)allocator->secondary_pool[i];
        if (!entry)
            continue;
        if (entry->key == hash_function(i)) {
            hits++;
        } else {
            misses++;
        }
    }
    printf("Memory usage: %u/%u (%.2f%%) primary, %.2f%% secondary\n",
           allocator->primary_pool_size / 2 - misses,
           allocator->primary_pool_size / 2, (double)(allocator->primary_pool_size / 2 - misses) / (allocator->primary_pool_size / 2) * 100.0,
           (double)misses / (allocator->primary_pool_size / 2) * 100.0);
    printf("Cache hit rate: %.2f%%, miss rate: %.2f%%\n",
           (double)hits / (hits + misses) * 100.0, (double)misses / (hits + misses) * 100.0);
}
