```c
#include <stdlib.h>
#include <pthread.h>

// Structure to represent a semaphore with its initial value
typedef struct {
    int value;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} semaphore_t;

// Function to create a new semaphore with the given initial value
semaphore_t* sem_create(int value) {
    semaphore_t* sem = (semaphore_t*) malloc(sizeof(semaphore_t));
    if (!sem) return NULL; // Memory allocation failed

    sem->value = value;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);

    return sem;
}

// Function to destroy a semaphore and release its resources
void sem_destroy(semaphore_t* sem) {
    if (!sem) return; // Semaphore is not valid

    pthread_mutex_destroy(&sem->mutex);
    pthread_cond_destroy(&sem->cond);
    free(sem); // Release the memory allocated for the semaphore
}

// Function to wait for a semaphore and decrement its value
void sem_wait(semaphore_t* sem) {
    if (!sem) return; // Semaphore is not valid

    pthread_mutex_lock(&sem->mutex);
    while (sem->value <= 0) {
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    --sem->value;
    pthread_mutex_unlock(&sem->mutex);
}

// Function to signal a semaphore and increment its value
void sem_signal(semaphore_t* sem) {
    if (!sem) return; // Semaphore is not valid

    pthread_mutex_lock(&sem->mutex);
    ++sem->value;
    pthread_cond_broadcast(&sem->cond);
    pthread_mutex_unlock(&sem->mutex);
}

// Function to get the current value of a semaphore
int sem_get_value(semaphore_t* sem) {
    if (!sem) return -1; // Semaphore is not valid

    return sem->value;
}
```']

