#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_THRESHOLD 1000 // in megabytes
#define MEMORY_OVERHEAD 2 // additional memory overhead for each allocation
#define RANDOM_INT_RANGE 10000 // initial random integer range

typedef struct {
    long value;
    char* str;
} node;

int init_data(int num_nodes, int min_int, int max_int) {
    if (num_nodes <= 0 || min_int > max_int) return -1; // error checking

    // Calculate total memory requirements
    size_t mem_req = sizeof(double*) * num_nodes + 
                     sizeof(char*) * num_nodes + 
                     sizeof(node*) * num_nodes + 
                     sizeof(long) * num_nodes + 
                     sizeof(char) * num_nodes;

