const W: usize = 10; // Sliding window size

fn initialize_measurement_directory() -> PathBuf {
    let measurement_dir = std::env::var("MEASUREMENT_DIR")
        .map_or_else(|_| {
            let timestamp = Utc::now().timestamp();
            let random_uuid = Uuid::new_random();
            let dir_name = format!("measurement_{}-{}", timestamp, random_uuid.to_string());
            let path = PathBuf::from(dir_name);
            fs::create_dir_all(&path)?;
            path
        }, |dir| {
            let path = PathBuf::from(dir);
            if !path.exists() {
                panic!("Measurement directory does not exist");
            }
            validate_directory_integrity(&path)?;
            path
        })
}

fn validate_directory_integrity(path: &PathBuf) -> Result<(), String> {
    let crc32_sum = calculate_crc32_sum(path)?;
    let sha256_hash = calculate_sha256_hash(path)?;

    let existing_checksum = fs::read_to_string(path.join("checksum.txt"))?;
    if crc32_sum != U16::from_le_bytes(existing_checksum.as_bytes().try_into().unwrap()[0..2].try_into().unwrap())
        || &sha256_hash.to_string() != &existing_checksum.trim_end_matches('\n') {
        Err("Directory integrity mismatch".to_string())
    } else {
        Ok(())
    }
}

fn calculate_crc32_sum(path: &PathBuf) -> Result<u32, String> {
    let mut crc = Crc32Fast::new();
    for entry in fs::read_dir(path)? {
        let entry = entry?;
        let path = entry.path();
        if path.is_file() {
            crc.update(&fs::read(&path)?;
        } else if path.is_dir() {
            crc.update(&calculate_crc32_sum(&path)?)?
        }
    }
    Ok(crc.sum())
}

fn calculate_sha256_hash(path: &PathBuf) -> String {
    let mut sha = Sha256::new();
    for entry in fs::read_dir(path)? {
        let entry = entry?;
        let path = entry.path();
        if path.is_file() {
            sha.update(&fs::read(&path)?;
        } else if path.is_dir() {
            sha.update(&calculate_sha256_hash(&path)?)?
        }
    }
    format!("{:x}", sha.finalize())
}

