#define MAX_RECORDS 1000000
#define MAX_MEMORY 102400 // 100MB

typedef struct record {
    int key;
} record;

record* add_vertices_and_edges(int num_records, int num_keys) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    record* records = NULL;
    long* offsets = NULL;
    int* keys = NULL;
    int max_key = 0;

    // Allocate memory for arrays
    records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        free(records);
        return NULL;
    }

    keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        free(records);
        free(offsets);
        return NULL;
    }

    // Initialize records
    for (int i = 0; i < num_records; i++) {
        record r;
        r.key = rand() % (num_keys - 1); // Random key value within range
        if (r.key > max_key) {
            max_key = r.key;
        }
        records[i] = r;

        // Update offsets and keys arrays
        offsets[i] = i * sizeof(record);
        keys[i] = r.key;
    }

    pthread_mutex_unlock(&mutex);

    return records;
}

void sort_records(record* records, int num_records) {
    qsort(records, num_records, sizeof(record), (int (*)(const void*, const void*))NULL); // Timsort
}

int main() {
    // Initialize variables
    int num_records = 0; // User input for number of records
    int num_keys = 0; // User input for range of key values

    // Read user input and validate inputs
    printf("Enter the number of records: ");
    scanf("%d", &num_records);
    printf("Enter the maximum value for keys: ");
    scanf("%d", &num_keys);

    // Check if memory allocation will exceed maximum threshold
    long total_size = num_records * sizeof(record) + num_records * sizeof(long) + num_records * sizeof(int);
    if (total_size > MAX_MEMORY * 1024) {
        printf("Memory allocation failed due to exceeding the maximum threshold.\n");
        return -1;
    }

    // Allocate memory for records, offsets, and keys
    record* records = add_vertices_and_edges(num_records, num_keys);

    // Check if memory allocation was successful
    if (!records) {
        printf("Memory allocation failed. Aborting operation.\n");
        return -1;
    }

    // Sort the records based on key values
    sort_records(records, num_records);

    // Print sorted records
    for (int i = 0; i < num_records; i++) {
        printf("%d ", records[i].key);
    }
    printf("\n");

    return 0;
}
