#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SIZE 1048576 // 1MB in bytes
#define MIN_KEY 0
#define MAX_KEY 100000
#define OFFSET_RANGE 1024*1024*8 // 8MB in bytes
#define STATUS_FLAG_RANGE 256

typedef struct {
    int key;
    long offset;
    int status;
} Record;

Record* allocate_records(int num_records, size_t *total_allocated);
void initialize_records(Record*, int, int);
int verify_unique_keys(const Record*, int);
void log_memory_usage(size_t, const char*);

size_t total_allocated = 0;

Record* allocate_records(int num_records, size_t *total_allocated) {
    if (num_records < 1) {
        return NULL;
    }

    Record* records = (Record*) malloc(num_records * sizeof(Record));
    if (!records) {
        log_memory_usage(total_allocated, "Out of memory");
        return NULL;
    }

    size_t allocated = num_records * sizeof(Record);
    *total_allocated += allocated;

    if (*total_allocated > MAX_SIZE) {
        log_memory_usage(*total_allocated, "Memory allocation exceeded maximum size");
        free(records);
        records = NULL;
        *total_allocated = 0;
    }

    return records;
}

void initialize_records(Record* records, int num_records, int max_key) {
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = i;
        records[i].offset = rand() % OFFSET_RANGE;
        records[i].status = rand() % STATUS_FLAG_RANGE;
    }
}

int verify_unique_keys(const Record* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        for (int j = i + 1; j < num_records; j++) {
            if (records[i].key == records[j].key) {
                return 0;
            }
        }
    }
    return 1;
}

void log_memory_usage(size_t allocated, const char* message) {
    printf("%s: %zu bytes\n", message, allocated);
}

void resize_records(Record** records, int num_records, size_t *total_allocated) {
    if (!records || !num_records) {
        return;
    }

    size_t allocated = num_records * sizeof(Record);
    if (allocated > MAX_SIZE - *total_allocated) {
        log_memory_usage(MAX_SIZE - *total_allocated, "Resizing exceeded maximum size");
        return;
    }

    Record* new_records = (Record*) realloc(*records, allocated);
    if (!new_records) {
        log_memory_usage(total_allocated, "Out of memory during resizing");
        free(*records);
        *records = NULL;
        *total_allocated = 0;
        return;
    }

    *records = new_records;
    *total_allocated += allocated - (*total_allocated - *num_records);
}

void deallocate_records(Record** records) {
    if (!records || !*records) {
        return;
    }

    free(*records);
    *records = NULL;
}

int main() {
    // Example usage:
    int num_records = 1000;
    size_t total_alloc = 0;

    Record* records = allocate_records(num_records, &total_alloc);
    if (!records) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    initialize_records(records, num_records, MAX_KEY);

    // Verify unique keys
    int key_verification = verify_unique_keys(records, num_records);
    if (!key_verification) {
        printf("Error: duplicate keys found.\n");
        deallocate_records(&records);
        return -2;
    }

    // Resize the collection (optional)
    int new_num_records = 2000;
    resize_records(&records, new_num_records, &total_alloc);

    deallocate_records(&records);

    return 0;
}
