#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>

#define MAX_DOMAIN 256
#define MAX_HOSTNAME 1024
#define DNS_PORT 53

// DNS resolution function with error handling and allowed domain restriction
char* resolve_dns(const char* hostname, const char* domain) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        return "DNS resolution failed: cannot create socket";
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(DNS_PORT);
    inet_pton(AF_INET, domain, &server_addr.sin_addr);

    char query[MAX_HOSTNAME + 1];
    strcpy(query, "_-");
    strcat(query, hostname);
    strcat(query, "\0");

    sendto(sockfd, query, strlen(query), 0, (struct sockaddr*)&server_addr, sizeof(server_addr));
    close(sockfd);

    return "DNS resolution successful";
}

// Main program for file processing with DNS resolution
int main() {
    FILE* file = fopen("large_file.txt", "r");
    if (!file) {
        return -1;
    }

    // List of allowed domains
    const char* allowed_domains[] = {"example.com", "test.io"};
    int num_allowed_domains = sizeof(allowed_domains) / sizeof(const char*);

    char line[1024];
    while (fgets(line, 1024, file)) {
        char* token = strtok(line, ",");
        double sum = 0.0;
        int count = 0;

        // Compute average of the last three numeric fields
        for (int i = 0; i < strlen(line); i++) {
            if (isdigit(line[i])) {
                int num = 0;
                while (i < strlen(line) && isdigit(line[i])) {
                    num = num * 10 + line[i] - '0';
                    i++;
                }
                sum += num;
                count++;
            } else {
                i--;
                break;
            }

            // Limit DNS resolution to allowed domains
            char* domain_token = strtok(token, ".");
            if (domain_token && strchr(allowed_domains, domain_token)) {
                printf("%s,%f\n", line, sum / (double)count);
            }
        }
    }

    fclose(file);

    return 0;
}
```

