class DataProcessor {
public:
    void process(const std::forward_list<std::string>& records) {
        for (const auto& record : records) {
            std::stringstream ss(record);
            std::vector<std::unique_ptr<std::string>> fields;
            while (ss >> field) {
                fields.push_back(std::make_unique<std::string>(field));
            }

            double sum = 0.0;
            int count = 0;
            for (int i = fields.size() - 3; i < fields.size(); ++i) {
                if (isdigit(fields[i]->front())) {
                    sum += stod(*fields[i]);
                    ++count;
                }
            }

            double average = count > 0 ? sum / count : 0.0;

            int max = INT_MIN;
            for (int i = fields.size() - 5; i < fields.size(); ++i) {
                if (isdigit(fields[i]->front())) {
                    max = std::max(max, stod(*fields[i]));
                }
            }

            std::cout << "Record: " << record << "\n";
            std::cout << "Average value of last 3 numerical fields: " << average << "\n";
            std::cout << "Maximum value among last 5 numerical fields: " << max << "\n\n";
        }
    }

    void insertAfter(const std::forward_list<std::string>& list, const std::string& target, const std::string& insertion) {
        auto it = list.begin();
        bool found = false;
        while (it != list.end()) {
            if (*it == target) {
                found = true;
                break;
            }
            ++it;
        }

        if (!found) {
            it = list.end();
        }

        list.insert_after(it, insertion);
    }
};

int main() {
    DataProcessor processor;
    std::forward_list<std::string> records = {"Sensor1: 12.5, 10.2, 15.8", "Sensor2: 20.0, 30.1, 25.4", "Sensor3: 40.9, 50.8, 35.7"};

    processor.process(records);
    processor.insertAfter(records, "Sensor2", "Sensor4");

    return 0;
}

