    time_t currentTime = time(NULL);
    newSession->startTime = currentTime;
    newSession->lastActiveTime = currentTime;
    newSession->metadata = metadata;

    if (!manager->sessions) {
        manager->sessions = (UserSession**)malloc(sizeof(UserSession*));
        manager->numSessions = 1;
    } else {
        int newSize = manager->numSessions + 1;
        UserSession** newSessions = (UserSession**)realloc(manager->sessions, sizeof(UserSession*) * newSize);
        for (int i = 0; i < manager->numSessions; i++) {
            newSessions[i] = manager->sessions[i];
        }
        newSessions[manager->numSessions++] = newSession;
        free(manager->sessions);
        manager->sessions = newSessions;
    }

    if (manager->numSessions > manager->sessionLimit) {
        callback(manager->numSessions - 1);
    }

    return 0;
}

void updateLastActiveTime(SessionManager* manager, int userId) {
    for (int i = 0; i < manager->numSessions; i++) {
        if (manager->sessions[i]->userId == userId) {
            time_t currentTime = time(NULL);
            manager->sessions[i]->lastActiveTime = currentTime;
            return;
        }
    }
}

void pruneOldSessions(SessionManager* manager) {
    for (int i = 0; i < manager->numSessions; i++) {
        if ((time(NULL) - manager->sessions[i]->startTime) > manager->retentionPeriod) {
            free(manager->sessions[i]);
            int newSize = manager->numSessions - 1;
            UserSession** newSessions = (UserSession**)realloc(manager->sessions, sizeof(UserSession*) * newSize);
            for (int j = i; j < manager->numSessions - 1; j++) {
                newSessions[j] = manager->sessions[j + 1];
            }
            free(manager->sessions[manager->numSessions--]);
            manager->sessions = newSessions;
        }
    }
}

void runSessionManager(SessionManager* manager) {
    while (1) {
        for (int i = 0; i < manager->numSessions; i++) {
            if ((time(NULL) - manager->sessions[i]->lastActiveTime) > manager->inactivityTimeout) {
                pruneOldSessions(manager);
                return;
            }
        }
        usleep(100000); // adjust sleep duration based on system load and performance requirements
    }
}
