rolling_average_data rolling_average = {PTHREAD_MUTEX_INITIALIZER, 0, 0.0};

void *process_strings(void *arg) {
    char **strings = (char **)malloc(MAX_ENTRIES * sizeof(char *));
    for(int i = 0; i < MAX_ENTRIES; i++) {
        strings[i] = NULL;
    }
    int string_count = 0;
    FILE *input_file = stdin;
    while(fscanf(input_file, "%s", &strings[string_count]) == 1) {
        if(strlen(strings[string_count]) > MAX_STRING_LENGTH - 1) {
            fprintf(stderr, "Error: String length exceeds maximum allowed.\n");
            exit(EXIT_FAILURE);
        }
        string_count++;
        if(string_count >= MAX_ENTRIES) {
            break;
        }
    }

    int max_length = 0;
    char *longest_string = NULL;
    for(int i = 0; i < string_count; i++) {
        if(strlen(strings[i]) > max_length) {
            max_length = strlen(strings[i]);
            longest_string = strings[i];
        }
    }

    pthread_mutex_lock(&rolling_average.lock);
    rolling_average.count += string_count - (string_count / 10);
    for(int i = 0; i < string_count; i++) {
        if(strlen(strings[i]) > 0) {
            rolling_average.average_length += strlen(strings[i]);
        }
    }
    rolling_average.average_length /= (rolling_average.count > 0 ? rolling_average.count : 1);
    pthread_mutex_unlock(&rolling_average.lock);

    printf("Longest string: %s\n", longest_string);
    printf("Average length: %.2f characters\n", rolling_average.average_length);

    free(strings);

    return NULL;
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, process_strings, NULL);
    pthread_join(thread, NULL);

    FILE *log_file = fopen("process_strings.log", "w");
    if(log_file != NULL) {
        fprintf(log_file, "Longest string: %s\n", longest_string);
        fprintf(log_file, "Average length: %.2f characters\n", rolling_average.average_length);
        fclose(log_file);
    }

    return 0;
}
