#include <json-c/json.h>

#define MAX_FILE_SIZE (50 * 1024 * 1024) // 50 MB
#define MAX_ENTRIES 100000
#define BUFFER_SIZE 4096

typedef struct {
    char* str;
    size_t len;
} StringEntry;

void print_longest_strings(StringEntry* entries, int count, int max_len) {
    printf("Longest strings: ");
    for (int i = 0; i < count; i++) {
        if (entries[i].len == max_len) {
            printf("%s ", entries[i].str);
        }
    }
    printf("\n");
}

StringEntry* process_config_file(char* url, int* count, char** longest_strings) {
    CURL* curl;
    CURLcode res;
    FILE* file;
    size_t bytes_read;
    StringEntry* entries = NULL;
    int entry_count = 0;

    // Initialize libcurl
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "curl initialization failed\n");
        return NULL;
    }

    // Set URL and options for the download
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &bytes_read);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);

    do {
        res = curl_easy_perform(curl);
    } while ((res == CURLE_PARTIAL) && (entry_count < MAX_ENTRIES));

    if (res != CURLE_OK) {
        fprintf(stderr, "curl error: %s\n", curl_easy_strerror(res));
        return NULL;
    }

    // Handle the file contents
    entries = malloc(sizeof(StringEntry) * entry_count);
    char* json_str = (char*)malloc(bytes_read + 1);
    json_str[bytes_read] = '\0';
    JSON_Object* obj;

    // Parse the JSON data
    FILE* fptr;
    fptr = fopen("temp.json", "w");
    fwrite(json_str, sizeof(char), bytes_read, fptr);
    fclose(fptr);

    json_file_result result;
    if ((result = json_object_from_file("temp.json")) == NULL) {
        fprintf(stderr, "Invalid JSON format\n");
        return entries;
    }

    for (int i = 0; i < entry_count; i++) {
        obj = json_object_object_get(result, sprintf("%d", i));
        if (!obj) continue;

        char* str = json_object_get_string(obj);
        if (!str || strlen(str) == 0) {
            free(entries[i].str);
            entries[i].str = NULL;
            entries[i].len = 0;
        } else if (isspace(*str)) {
            // Filter out strings with only whitespace
            free(entries[i].str);
            entries[i].str = NULL;
            entries[i].len = 0;
        } else {
            entries[i].str = strdup(str);
            entries[i].len = strlen(str);
        }
    }

    *count = entry_count;

    // Print the longest strings
    int max_len = 0;
    for (int i = 0; i < entry_count; i++) {
        if (entries[i].len > max_len) {
            max_len = entries[i].len;
        }
    }

    print_longest_strings(entries, *count, max_len);

    // Free all dynamically allocated memory
    free(json_str);
    for (int i = 0; i < entry_count; i++) {
        if (entries[i].str) free(entries[i].str);
    }
    free(entries);

    return NULL;
}

size_t write_data(void* contents, size_t size, size_t nmemb, void* userp) {
    char* buffer = (char*)userp;
    size_t bytes_read = 0;

    while (bytes_read < size * nmemb && bytes_read < MAX_FILE_SIZE) {
        int chunk_size = BUFFER_SIZE;
        if (size * nmemb - bytes_read < BUFFER_SIZE) chunk_size = size * nmemb - bytes_read;

        memcpy(buffer + bytes_read, contents, chunk_size);
        bytes_read += chunk_size;
    }

    return bytes_read;
}

int main() {
    char* url = "http://example.com/config.json";
    int count = 0;
    char** longest_strings = NULL;

    process_config_file(url, &count, &longest_strings);

    // Handle the output
    printf("Number of entries: %d\n", count);
    if (count > 0) {
        for (int i = 0; i < count; i++) {
            printf("Entry %d: %s (%ld bytes)\n", i + 1, longest_strings[i], strlen(longest_strings[i]));
        }
    }

    // Free the dynamically allocated memory
    for (int i = 0; i < count; i++) {
        free(longest_strings[i]);
    }
    free(longest_strings);

    return 0;
}
