#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Custom memory allocator structure
typedef struct {
    int* keys;
    long* offsets;
    record* records;
    int size;
} allocator;

// Record structure
typedef struct {
    int value;
    time_t timestamp;
} record;

// Function to manage memory allocation and initialization
allocator* allocate_memory(int num_records, int max_key) {
    allocator* alloc = (allocator*)malloc(sizeof(allocator));
    if (!alloc) return NULL; // Allocation failed

    alloc->size = num_records;
    alloc->keys = (int*)calloc(num_records, sizeof(int));
    alloc->offsets = (long*)calloc(num_records, sizeof(long));

    for (int i = 0; i < num_records; i++) {
        alloc->keys[i] = rand() % max_key;
        alloc->offsets[i] = i * sizeof(record);
    }

    return alloc;
}

// Function to deallocate memory
void deallocate_memory(allocator* alloc) {
    if (!alloc) return;

    free(alloc->keys);
    free(alloc->offsets);
    free(alloc);

    alloc = NULL; // Ensure pointer is set to NULL
}

// Main function to process input and allocate memory
int main() {
    int num_records, max_key;
    scanf("%d %d", &num_records, &max_key);

    allocator* alloc = allocate_memory(num_records, max_key);
    if (!alloc) {
        printf("Memory allocation failed. Exiting.\n");
        return 1; // Exit with error
    }

    // Process input and print results
    int largest_int = INT_MIN;
    int sum_positive_ints = 0;

    for (int i = 0; i < num_records; i++) {
        if (alloc->keys[i] > largest_int) largest_int = alloc->keys[i];
        if (alloc->keys[i] > 0) sum_positive_ints += alloc->keys[i];
