#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int user_id;
    time_t session_start_time;
    time_t last_active_time;
    int login_attempt_count;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *sessions;
    size_t capacity;
    size_t used;
} SessionManager;

SessionManager* session_manager_create(size_t initial_capacity) {
    SessionManager* manager = malloc(sizeof(SessionManager));
    manager->capacity = initial_capacity;
    manager->used = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void session_manager_destroy(SessionManager* manager) {
    for (size_t i = 0; i < manager->used; i++) {
        free(manager->sessions[i].rx_ue_info_tag);
    }
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int session_manager_insert(SessionManager* manager, NFAPI_CRC_INDICATION_PDU_T* new_session) {
    if (manager->used >= manager->capacity) {
        // Reallocate memory
        manager->capacity *= 2;
        SessionManager* temp = malloc(sizeof(SessionManager));
        temp->capacity = manager->capacity;
        temp->used = 0;
        pthread_mutex_init(&temp->lock, NULL);

        // Copy existing sessions to new array
        for (size_t i = 0; i < manager->used; i++) {
            NFAPI_CRC_INDICATION_PDU_T* session = &manager->sessions[i];
            temp->sessions = realloc(temp->sessions, (temp->used + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(&temp->sessions[temp->used], session, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            temp->used++;
        }

        // Update original manager
        manager->capacity = 0;
        manager->used = 0;
        free(manager->sessions);
        pthread_mutex_destroy(&manager->lock);
        manager->sessions = temp->sessions;
        temp = NULL;
    }

    // Insert new session
    if (manager->used < manager->capacity) {
        manager->sessions[manager->used++] = *new_session;
    } else {
        return -1; // Session not inserted due to capacity limit
    }

    return 0; // Session inserted successfully
}

void session_manager_remove(SessionManager* manager, int user_id) {
    for (size_t i = 0; i < manager->used; i++) {
        if (manager->sessions[i].user_id == user_id) {
            free(manager->sessions[i].rx_ue_info_tag);
            memmove(&manager->sessions[i], &manager->sessions[i + 1], (manager->used - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            manager->used--;
            break;
        }
    }
}

void session_manager_purge(SessionManager* manager, time_t cutoff_time) {
    for (size_t i = 0; i < manager->used; i++) {
        if (manager->sessions[i].last_active_time <= cutoff_time) {
            free(manager->sessions[i].rx_ue_info_tag);
            memmove(&manager->sessions[i], &manager->sessions[i + 1], (manager->used - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            manager->used--;
        }
    }
}

int main() {
    SessionManager* manager = session_manager_create(10);

    // Insert sessions
    NFAPI_CRC_INDICATION_PDU_T new_session1 = {"user1", time(NULL), time(NULL), 0};
    NFAPI_CRC_INDICATION_PDU_T new_session2 = {"user2", time(NULL), time(NULL), 0};
    session_manager_insert(manager, &new_session1);
    session_manager_insert(manager, &new_session2);

    // Remove a session
    session_manager_remove(manager, "user1");

    // Purge inactive sessions
    session_manager_purge(manager, time(NULL) - 3600); // Purge sessions older than an hour

    session_manager_destroy(manager);
    return 0;
}

