void loadResourceBundle(const char* path, struct record** records, int* numRecords) {
    FILE *fp = fopen(path, "rb");
    if (fp == NULL) {
        printf("Error: Unable to open file %s\n", path);
        return;
    }

    fseek(fp, 0, SEEK_END);
    long fileSize = ftell(fp);
    rewind(fp);

    int numItems = (int)(fileSize / sizeof(struct record));
    if (numItems > 10000) {
        printf("Error: File contains too many items (max allowed is 10,000)\n");
        fclose(fp);
        return;
    }

    *numRecords = numItems;

    *records = malloc(numItems * sizeof(struct record));
    if (*records == NULL) {
        printf("Error: Out of memory\n");
        fclose(fp);
        return;
    }

    int i;
    for (i = 0; i < numItems; i++) {
        struct record* record = &(*records)[i];
        record->value = rand() % 100;
    }

    fclose(fp);
}

int main() {
    srand(time(NULL));
    struct record* records = NULL;
    int numRecords = 0;

    loadResourceBundle("path_to_your_resource_bundle_file", &records, &numRecords);

    // Use the loaded bundle here...

    free(records);
    return 0;
}
