public class DataProcessor {

    private static final int DEFAULT_HASH_ITERATIONS = 3;
    private static final int MAX_HASH_ITERATIONS = 10;

    public String processString(String input) throws Exception {
        if (input == null || input.isEmpty()) {
            return null; // or throw exception
        }

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < DEFAULT_HASH_ITERATIONS; i++) {
            MessageDigest digest = getHashAlgorithm();
            byte[] hashBytes = digest.digest(input.getBytes(StandardCharsets.UTF_8));
            output.append(hashToHexadecimal(hashBytes));
        }
        return output.toString();
    }

    private MessageDigest getHashAlgorithm() throws NoSuchAlgorithmException {
        // implement your custom SHA-256 algorithm
        // or use Java's built-in MessageDigest.getInstance("SHA-256");
        throw new UnsupportedOperationException("Custom hash algorithm not implemented yet");
    }

    private String hashToHexadecimal(byte[] hashBytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(b & 0xFF);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public static void main(String[] args) throws Exception {
        DataProcessor processor = new DataProcessor();
        String result = processor.processString("Hello, World!");
        System.out.println(result);
    }
}
