    }

    *probabilities = (float*)malloc(MAX_PROBABILITY * sizeof(float));
    for (int i = 0; i < MAX_PROBABILITY; i++) {
        (*probabilities)[i] = i / (float)MAX_PROBABILITY;
    }
}

void manage_memory_event_descriptions(char*** event_descriptions, int* event_types) {
    *event_descriptions = (char**)malloc(EVENT_TYPES * sizeof(char*));
    for (int i = 0; i < EVENT_TYPES; i++) {
        (*event_descriptions)[i] = (char*)malloc(MAX_EVENT_DESCRIPTION * sizeof(char));
        sprintf((*event_descriptions)[i], "Event %d", i);
    }
}

void free_memory(data_record*** records, long*** timestamps, float** probabilities) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        if ((*records)[i]->description != NULL)
            free((*records)[i]->description);
        free((*records)[i]);
    }
    free(*timestamps);
    free(*probabilities);
}

void free_memory_event_descriptions(char*** event_descriptions) {
    for (int i = 0; i < EVENT_TYPES; i++) {
        if ((*event_descriptions)[i] != NULL)
            free((*event_descriptions)[i]);
    }
