typedef struct {
    char* key;
    double value;
} entry;

entry* initEntries(int size, const char* prefix) {
    int maxPrefixLength = 16;
    if(strlen(prefix) > maxPrefixLength) {
        printf("Error: Prefix length exceeds maximum allowed limit.\n");
        return NULL;
    }

    entry* entries = (entry*)malloc(size * sizeof(entry));
    if(entries == NULL) {
        printf("Error: Unable to allocate memory for array.\n");
        return NULL;
    }

    char suffix[] = "abcdefghijklmnopqrstuvwxyz";
    int suffixIndex = 0;

    for(int i = 0; i < size; i++) {
        entries[i].key = (char*)malloc((strlen(prefix) + strlen(suffix) + 1) * sizeof(char));
        if(entries[i].key == NULL) {
            printf("Error: Unable to allocate memory for key.\n");
            for(int j = 0; j < i; j++) {
                free(entries[j].key);
            }
            free(entries);
            return NULL;
        }

        sprintf(entries[i].key, "%s%c", prefix, suffix[suffixIndex++]);
        entries[i].value = (double)rand() / RAND_MAX;

        if(suffixIndex >= strlen(suffix)) {
            suffixIndex = 0;
        }
    }

    return entries;
}

void freeEntries(entry* entries, int size) {
    for(int i = 0; i < size; i++) {
        free(entries[i].key);
    }
    free(entries);
}
