void* alloc_entries(int size, int keys_size) {
    void* entries = malloc(sizeof(entry) * size);
    if (entries == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize each entry with a random key and value
    for (int i = 0; i < size; i++) {
        entry* current_entry = (entry*) (entries + i * sizeof(entry));
        char* key = malloc((keys_size + 1) * sizeof(char));
        sprintf(key, "key_%d", i);
        current_entry->key = key;
        current_entry->value = (double) rand() / RAND_MAX;
    }

    return entries;
}

