import json
import time
from threading import Lock
from concurrent.futures import ThreadPoolExecutor

class Task:
    def __init__(self, id, title, description, priority, status):
        self.id = id
        self.title = title
        self.description = description
        self.priority = priority
        self.status = status
        self.modified_timestamp = int(time.time())

class TaskManager:
    def __init__(self):
        self.tasks = {}
        self.lock = Lock()
        self.pool = ThreadPoolExecutor(max_workers=100)

    def validate(self, data):
        errors = []
        if 'title' not in data or len(data['title']) < 2 or len(data['title']) > 50:
            errors.append('Invalid title')
        if 'description' in data and len(data['description']) >= 255:
            errors.append('Description too long')
        if 'priority' in data and not isinstance(data['priority'], int) or data['priority'] < 1 or data['priority'] > 5:
            errors.append('Invalid priority')
        if 'status' in data and data['status'] not in ['pending', 'in_progress', 'completed']:
            errors.append('Invalid status')
        return {'message': 'error', 'data': []} if errors else {'message': 'success'}

    def create(self, data):
        if self.validate(data)['message'] == 'error':
            return json.dumps(self.validate(data))
        with self.lock:
            task = Task(len(self.tasks) + 1, data['title'], data['description'], data.get('priority', 1), data.get('status', 'pending'))
            self.tasks[task.id] = task
            return json.dumps({'message': 'success'})

    def update(self, data):
        if 'id' not in data:
            return json.dumps({'message': 'error'})
        with self.lock:
            task = self.tasks.get(data['id'])
            if task:
                for key, value in data.items():
                    setattr(task, key, value)
                task.modified_timestamp = int(time.time())
                return json.dumps({'message': 'success'})
            else:
                return json.dumps({'message': 'error'})

    def delete(self, data):
        if 'id' not in data or 'task_id' not in data:
            return json.dumps({'message': 'error'})
        with self.lock:
            task = self.tasks.get(data['id'])
            if task and task.id == data['task_id']:
                del self.tasks[task.id]
                return json.dumps({'message': 'success'})
            else:
                return json.dumps({'message': 'error'})

    def list(self):
        sorted_tasks = sorted(self.tasks.values(), key=lambda x: (x.priority, -x.status))
        return json.dumps({'message': 'success', 'data': [task.__dict__ for task in sorted_tasks]})

    def retrieve(self, data):
        if 'id' not in data:
            return json.dumps({'message': 'error'})
        with self.lock:
            task = self.tasks.get(data['id'])
            if task:
                return json.dumps({'message': 'success', 'data': task.__dict__})
            else:
                return json.dumps({'message': 'error'})

    def handle_error(self, exception):
        # Implement retry logic here
        pass

    def save_tasks(self):
        # Save tasks to external system or database
        pass
