#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netdb.h>
#include <arpa/inet.h>

#define MAX_ENTRIES 10000
#define DNS_MAXLEN 256

typedef struct {
    int num_entries;
    int* integers;
    char** fields;
} LogRecord;

LogRecord* process_log_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        return NULL;
    }

    LogRecord* records = (LogRecord*)malloc(sizeof(LogRecord));
    records->num_entries = 0;
    records->integers = NULL;
    records->fields = NULL;

    int total_length = 0;
    while (fscanf(file, "%d %*[^\n]%*c", &records->integers[records->num_entries]) == 1) {
        if (records->num_entries >= MAX_ENTRIES) {
            break;
        }

        char buffer[DNS_MAXLEN];
        if (fscanf(file, "%255s", buffer) != 1 || strlen(buffer) < 0) {
            // Skip malformed input
            continue;
        }

        // Resolve DNS name
        struct hostent* host = gethostbyname(buffer);
        if (host == NULL) {
            // Handle DNS resolution failure
            continue;
        }

        char* ip_address = inet_ntoa(*((struct in_addr*)host->h_addr));
        char** field = (char**)malloc(sizeof(char*));
        *field = strdup(ip_address);
        records->fields = (char**)realloc(records->fields, sizeof(char*) * (records->num_entries + 1));
        records->fields[records->num_entries] = field;

        total_length += strlen(ip_address) + 1;
    }

    fclose(file);

    if (total_length > 0) {
        // Compute and print statistics
        int sum = 0, max = 0;
        for (int i = records->num_entries - 3; i >= 0; i--) {
            sum += records->integers[i];
            if (records->integers[i] > max) {
                max = records->integers[i];
            }
        }

        int average = sum / 3;

        printf("Fields: ");
        for (int i = 0; i < records->num_entries; i++) {
            printf("%s, ", records->fields[i]);
        }
        puts("");
        printf("Average value of last three numerical fields: %d\n", average);
        printf("Maximum value among the last five numerical fields: %d\n", max);
    }

    free(records);

    return NULL;
}
