        free(keys);
        return -1;
    }

    // Initialize arrays with random values
    for (size_t i = 0; i < record_count; i++) {
        records[i].field = rand() % ((high - low) + 1) + low;
    }

    // Load configuration settings and resource bundles from files
    if ((config_file = fopen("config.txt", "r")) == NULL || 
        (resource_file = fopen("resources.txt", "r")) == NULL) {
        free(offsets);
        free(keys);
        return -1;
    }

    // Log messages for each record
    for (size_t i = 0; i < record_count; i++) {
        printf("Record %zu: Key %d, Offset %ld, Field %d\n", i, keys[i], offsets[i], records[i].field);
    }

    // Clean up and return the number of successfully initialized records
    fclose(config_file);
    fclose(resource_file);
    free(offsets);
    free(keys);
    free(records);
