#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define HASH_TABLE_SIZE 1024
#define PRUNE_INTERVAL 3600 // 1 hour in seconds
#define STATUS_RECORD_MAX_AGE 86400 // 24 hours in seconds

typedef struct {
    int device_id;
    time_t timestamp;
    int status_code;
    char *status_message;
} DeviceStatus;

typedef struct {
    DeviceStatus record;
    size_t crc32_checksum;
    unsigned char md5_checksum[16];
} HashTableEntry;

HashTableEntry* hash_table = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int prune_thread_running = 0;

void init_hash_table(int initial_size) {
    if (hash_table != NULL) return;
    hash_table = calloc(HASH_TABLE_SIZE, sizeof(HashTableEntry));
}

void insert_device_status(DeviceStatus* status) {
    pthread_mutex_lock(&mutex);
    int idx = status->device_id % HASH_TABLE_SIZE;
    HashTableEntry* entry = &hash_table[idx];
    while (entry->record.device_id != -1) {
        if (entry->record.timestamp < status->timestamp) break; // find the oldest record
        entry = &hash_table[++idx % HASH_TABLE_SIZE];
    }
    *entry = *status;
    pthread_mutex_unlock(&mutex);
}

void prune_hash_table() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        HashTableEntry* entry = &hash_table[i];
        while (entry->record.device_id != -1) {
            if ((time(NULL) - entry->timestamp) > STATUS_RECORD_MAX_AGE) break;
            *entry = (HashTableEntry){.device_id = -1, .timestamp = 0};
        }
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    // Initialize the hash table
    init_hash_table(HASH_TABLE_SIZE);

    // Start the pruning thread
    prune_thread_running = 1;
    pthread_t prune_thread;
    pthread_create(&prune_thread, NULL, &prune_hash_table, NULL);

    // Process device status updates in real-time
    for (int i = 0; i < 10000000; i++) {
        DeviceStatus status = { .device_id = i, .timestamp = time(NULL), .status_code = 200, .status_message = "OK" };
        insert_device_status(&status);
        sleep(1); // simulate real-time updates
    }

    return 0;
}
