#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} record_t;

// Custom memory pool structure
typedef struct {
    void* blocks[1024];
    size_t used;
    size_t capacity;
} mem_pool_t;

mem_pool_t* mem_pool_create(size_t capacity) {
    mem_pool_t* pool = malloc(sizeof(mem_pool_t));
    if (!pool) return NULL;
    pool->used = 0;
    pool->capacity = capacity;
    for (size_t i = 0; i < capacity; i++) {
        pool->blocks[i] = NULL;
    }
    return pool;
}

void* mem_pool_alloc(mem_pool_t* pool, size_t size) {
    if (pool->used >= pool->capacity) return NULL; // Out of memory
    for (size_t i = 0; i < pool->capacity; i++) {
        if (!pool->blocks[i]) {
            void* ptr = malloc(size);
            if (!ptr) return NULL;
            pool->blocks[i] = ptr;
            pool->used++;
            return ptr;
        }
    }
    return NULL; // No free blocks
}

void mem_pool_free(mem_pool_t* pool, void* block) {
    for (size_t i = 0; i < pool->capacity; i++) {
        if (pool->blocks[i] == block) {
            free(block);
            pool->used--;
            pool->blocks[i] = NULL;
            return;
        }
    }
}

int main() {
    // Initialize random number generator
    srand(time(NULL));

    int key_range = 100; // External configuration
    size_t record_count = 1024; // External configuration

    mem_pool_t* pool = mem_pool_create(16); // Initial capacity for memory pool

    // Allocate arrays and initialize records
    long* offsets = (long*)mem_pool_alloc(pool, record_count * sizeof(long));
    int* keys = (int*)mem_pool_alloc(pool, record_count * sizeof(int));
    record_t* records = (record_t*)mem_pool_alloc(pool, record_count * sizeof(record_t));

    for (size_t i = 0; i < record_count; i++) {
        records[i].key = rand() % key_range;
        records[i].offset = (long)rand();
    }

    // Example usage:
    printf("Record %zu: Key=%d, Offset=%ld\n", 0, records[0].key, records[0].offset);

    // Free memory and pool
    for (size_t i = 0; i < record_count; i++) {
        mem_pool_free(pool, &records[i]);
    }
    mem_pool_free(pool, offsets);
    mem_pool_free(pool, keys);
    free(pool);

    return 0;
}
