    if (!script.key || !activeKeys.includes(script.key)) continue;

    if (shallowClone) {
      script = JSON.parse(JSON.stringify(script));
    }

    const key = script.key;
    let exists = false;

    // Check if the script is already in the map
    for (const existingScript of Object.values(scriptMap)) {
      if (existingScript.key === key && isEquivalent(existingScript, script)) {
        exists = true;
        break;
      }
    }

    // If not unique, skip rendering
    if (!exists) {
      html += `<script src="${script.src}" async>${script.async ? '' : 'defer'}</script>`;
      scriptMap[key] = script;
    }
  }

  return html;
}

function isEquivalent(a, b) {
  const aKeys = Object.keys(a);
  const bKeys = Object.keys(b);

  if (aKeys.length !== bKeys.length) return false;

  for (const key of aKeys) {
    if (!Object.prototype.hasOwnProperty.call(b, key)) return false;
  }

  return true;
}
