typedef struct {
    int value;
} Record;

Record* findContiguousStates(int* states, int stateCount, int* startState, int* endState) {
    // Initialize the memory for arrays
    long* offsetValues = (long*)malloc(stateCount * sizeof(long));
    int* keys = (int*)malloc(stateCount * sizeof(int));
    Record* records = (Record*)malloc((stateCount + 1) * sizeof(Record));

    // Initialize the number of successfully initialized records
    int recordCount = 0;

    for (int i = 0; i < stateCount; i++) {
        // Fill in the offset values, keys, and records as needed
        offsetValues[i] = (long)(i + 1);
        keys[i] = i;
        if (states[i] >= *startState && states[i] <= *endState) {
            records[recordCount].value = i;
            recordCount++;
        }
    }

    // Initialize the 'next' pointer of the last state
    records[recordCount].value = -1; // or any sentinel value

    free(offsetValues);
    free(keys);

    return (recordCount > 0) ? records : NULL;
}
