#define MAX_FILENAME_LENGTH 255
#define FILE_TYPE_FORMAT "%s%d%s"
#define SHA256_HEX_LENGTH 64

typedef struct {
    int length;
    unsigned char* data;
} filename_t;

filename_t generate_filename(const char* original_filename) {
    // Analyze the characters of the input filename to determine the file type
    const char* file_type = "txt";
    if (strchr(original_filename, '.') != NULL) {
        char* dot_pos = strrchr(original_filename, '.');
        *dot_pos = '\0';
        file_type = dot_pos + 1;
    }

    // Calculate the SHA-256 hash of the original filename
    unsigned char sha256_hash[SHA256_HEX_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, original_filename, strlen(original_filename));
    SHA256_Final(sha256_hash, &ctx);

    // Generate a new filename based on the characters of the original filename
    char* generated_filename = (char*)malloc(MAX_FILENAME_LENGTH + 1);
    sprintf(generated_filename, FILE_TYPE_FORMAT "_%x", file_type, strlen(original_filename), sha256_hash);
    return (filename_t){strlen(generated_filename), generated_filename};
}

void free_filename(filename_t* filename) {
    free((void*)filename->data);
}

int main() {
    // Process a list of filenames
    const char* original_filenames[] = {"file1.txt", "file2.pdf", "file3.txt"};
    for (size_t i = 0; i < sizeof(original_filenames) / sizeof(original_filenames[0]); ++i) {
        filename_t generated_filename = generate_filename(original_filenames[i]);
        printf("Original filename: %s, Generated filename: %s\n", original_filenames[i], generated_filename.data);
        free_filename(&generated_filename);
    }
}
