function domTraverser(reportLimit = 10000) {
  const report = [];
  let currentBatchSize = 0;
  let throttleTimeout = null;

  function processElement(element) {
    if (currentBatchSize >= reportLimit) {
      return false; // batch limit reached
    }
    currentBatchSize++;

    const matches = document.querySelectorAll(`:${selector}`);
    matches.forEach((match) => {
      if (!report.includes(match)) {
        report.push(match);
      }
    });

    if (throttleTimeout) {
      clearTimeout(throttleTimeout);
    }
    throttleTimeout = setTimeout(() => {
      currentBatchSize = 0;
    }, 100);

    return true;
  }

  function handleDOMUpdate() {
    const newReport = [];
    document.querySelectorAll(`:${selector}`).forEach((element) => {
      if (!report.includes(element)) {
        report.push(element);
        newReport.push(element);
      }
    });
    report = newReport;
  }

  function takeSnapshot() {
    return JSON.stringify(report.map((element) => element.outerHTML));
  }

  function restoreSnapshot(snapshot) {
    const restoredReport = JSON.parse(snapshot).map((html) => document.createElement('div').innerHTML = html);
    report = restoredReport;
  }

  function handleError(error) {
    console.error(error);
    // todo: implement retry logic or graceful error handling
  }

  return {
    setSelector(selectorArg) {
      selector = selectorArg;
    },
    process() {
      if (processElement()) {
        // throttle and limit report size to prevent memory issues
      }
    },
    handleDOMUpdate,
    takeSnapshot,
    restoreSnapshot,
    setErrorHandler(handler) {
      handle = handler;
    },
  };
}
