class ScriptLoader {
  constructor() {
    this.scripts = {};
    this.loadOrder = [];
    this.errorHandler = null;
    this.cache = new Map();
  }

  setLoadOrder(order) {
    this.loadOrder = order;
  }

  setExceptionHandler(handler) {
    this.errorHandler = handler;
  }

  loadScript(url, callback) {
    if (this.scripts[url]) return; // already loaded
    this.scripts[url] = { loading: true };
    const script = document.createElement('script');
    script.src = url;
    script.onload = () => {
      this.scripts[url].loading = false;
      callback && callback();
    };
    script.onerror = (err) => {
      this.handleError(err, url);
    };
    document.body.appendChild(script);
  }

  loadScripts(order, callback) {
    const orderedScripts = order.map((script) => this.loadScript(script));
    Promise.all(orderedScripts).then(() => callback()).catch((err) => {
      console.error('Error loading scripts:', err);
    });
  }

  async executeScripts() {
    for (const url of this.loadOrder) {
      await new Promise((resolve) => this.loadScript(url, resolve));
    }
  }

  handleError(err, scriptUrl) {
    const errorReport = {
      message: err.message,
      stack: err.stack,
      file: scriptUrl,
      lineNumber: -1,
    };
    if (this.errorHandler) this.errorHandler(errorReport);
  }

  logExecutionOrder() {
    console.log('Script execution order:', this.loadOrder.map((script) => script));
  }
}

// Example usage:
const loader = new ScriptLoader();
loader.setLoadOrder(['script1.js', 'script2.js', 'script3.js']);
loader.setExceptionHandler((errorReport) =>
  console.error(`Error loading ${errorReport.file} at line ${errorReport.lineNumber}:`, errorReport.message, '\n', errorReport.stack)
);
loader.loadScripts(loader.loadOrder, () => loader.logExecutionOrder());
