void insertNode(TreeNode** root, double value) {
    TreeNode* newNode = malloc(sizeof(TreeNode));
    newNode->value = value;
    newNode->parent = NULL;

    if (*root == NULL || (*root)->parent != NULL) {
        *root = newNode;
    } else {
        // Find the correct position for the new node
        TreeNode* current = *root;
        while (comparator(value, current->value) > 0 && current->parent != NULL) {
            if (current->value < value) {
                if (current->parent->right == current) {
                    current = current->parent;
                    break;
                } else {
                    current = current->parent->left;
                }
            } else {
                if (current->parent->left == current) {
                    current = current->parent;
                    break;
                } else {
                    current = current->parent->right;
                }
            }
        }

        // Insert the new node
        if (comparator(value, current->value) > 0) {
            current->right = newNode;
            newNode->parent = current;
        } else {
            current->left = newNode;
            newNode->parent = current;
        }
    }
}

// Function to periodically check and update the balance factor of each node
void balanceTree(TreeNode** root) {
