import importlib.util
import importlib.machinery
import os
import logging
from collections import deque
from functools import lru_cache

class ModuleLoader:
    def __init__(self):
        self.module_deps = {}
        self.module_hashes = {}
        self.module_logs = []
        self.config = {}

    @lru_cache(maxsize=None)
    def load_module(self, module_path):
        spec = importlib.util.spec_from_file_location(module_path, module_path)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)

    def resolve_deps(self, module_path):
        deps = self.module_deps.get(module_path, [])
        if not deps:
            return []
        resolved_deps = []
        for dep in deps:
            if not self.module_hashes.get(dep):
                raise ValueError(f"Module {dep} is not loaded")
            resolved_deps.append(dep)
        return resolved_deps

    def load_module_deps(self, module_path):
        queue = deque([module_path])
        visited = set()
        while queue:
            current_module = queue.popleft()
            if current_module in visited:
                continue
            visited.add(current_module)
            deps = self.module_deps.get(current_module, [])
            for dep in deps:
                if not self.module_hashes.get(dep):
                    raise ValueError(f"Module {dep} is not loaded")
                queue.append(dep)

    def check_circular_deps(self, module_path):
        visited = set()
        stack = [module_path]
        while stack:
            current_module = stack.pop()
            if current_module in visited:
                return True
            visited.add(current_module)
            deps = self.module_deps.get(current_module, [])
            for dep in deps:
                if not self.module_hashes.get(dep):
                    raise ValueError(f"Module {dep} is not loaded")
                stack.append(dep)
        return False

    def load_modules(self, module_paths):
        for module_path in module_paths:
            try:
                self.load_module(module_path)
                self.module_logs.append((module_path, "Loaded successfully"))
            except ImportError as e:
                self.module_logs.append((module_path, f"Failed to load: {str(e)}"))

    def verify_modules(self, module_paths):
        for module_path in module_paths:
            try:
                hash_value = importlib.util.get_data(module_path)
                if not self.module_hashes.get(module_path) == hash_value:
                    raise ValueError(f"Module {module_path} has unexpected hash")
            except ImportError as e:
                print(f"Error verifying module {module_path}: {str(e)}")

    def configure(self, config):
        self.config = config

    def get_logs(self):
        return self.module_logs

    @property
    def module_hashes(self):
        return self._module_hashes

    @module_hashes.setter
    def module_hashes(self, value):
        self._module_hashes = value

    @property
    def module_deps(self):
        return self._module_deps

    @module_deps.setter
    def module_deps(self, value):
        self._module_deps = value


if __name__ == "__main__":
    loader = ModuleLoader()
    # Load modules and verify their integrity
    loader.load_modules(["module1.py", "module2.py"])
    loader.verify_modules(["module1.py", "module2.py"])

