void init_memory_pool(int max_size) {
    pool_size = max_size * sizeof(record_t);
    mem_pool = malloc(pool_size);
}

void allocate_record(record_t** new_records, int key, long value) {
    pthread_mutex_lock(&lock);
    record_t* record = (record_t*)mem_pool + current_records++;
    record->value = key;
    *(long*)(&(record->value)) = value;
    new_records[current_records - 1] = record;
    pthread_mutex_unlock(&lock);
}

void set_record_value(record_t** records, int idx, int value) {
    pthread_mutex_lock(&lock);
    records[idx]->value = value;
    pthread_mutex_unlock(&lock);
}

