// Data structure for storing sensor readings
typedef struct {
    SensorReading* sensor_readings;
    int reading_count;
    int buffer_size;
} SensorData;

// Function to store sensor data
void store_sensor_data(SensorData* data, SensorReading* reading) {
    // Check if the buffer is full
    if (data->reading_count >= MAX_SENSOR_READINGS) {
        printf("Buffer is full. Cannot store more data.\n");
        return;
    }

    // Copy the sensor reading to the buffer
    strcpy(data->sensor_readings[data->reading_count].timestamp, reading->timestamp);
    data->sensor_readings[data->reading_count].sensor_id = reading->sensor_id;
    strcpy(data->sensor_readings[data->reading_count].measurement_type, reading->measurement_type);
    data->sensor_readings[data->reading_count].value = reading->value;

    // Increment the read count
    data->reading_count++;
}

// Function to retrieve sensor data
void retrieve_sensor_data(SensorData* data, int start_index, int end_index) {
    for (int i = start_index; i <= end_index; i++) {
        printf("Timestamp: %s, Sensor ID: %d, Measurement Type: %s, Value: %.2f\n",
            data->sensor_readings[i].timestamp,
            data->sensor_readings[i].sensor_id,
            data->sensor_readings[i].measurement_type,
            data->sensor_readings[i].value);
    }
}

int main() {
    SensorData sensor_data;
    sensor_data.sensor_readings = (SensorReading*)malloc(MAX_SENSOR_READINGS * sizeof(SensorReading));
    sensor_data.reading_count = 0;
    sensor_data.buffer_size = MAX_SENSOR_READINGS;

    // Store sensor readings
    SensorReading reading1 = {"2022-01-01 00:00:00", 1, "temperature", 25.5};
    store_sensor_data(&sensor_data, &reading1);

    SensorReading reading2 = {"2022-01-02 00:00:00", 2, "pressure", 1013.2};
    store_sensor_data(&sensor_data, &reading2);

    // Retrieve sensor data
    retrieve_sensor_data(&sensor_data, 0, 1);

    return 0;
}
