public class ServiceManager {
    private Map<String, ServiceInstance> services;
    private ConfigManager configManager;
    private MonitoringSystem monitoringSystem;

    public ServiceManager() {
        services = new HashMap<>();
        configManager = new ConfigManager();
        monitoringSystem = new MonitoringSystem();
    }

    public void startService(String serviceName) throws Exception {
        ServiceInstance service = new ServiceInstance(serviceName, configManager.getConfig(serviceName));
        services.put(serviceName, service);
        service.start();
    }

    public void stopService(String serviceName) throws Exception {
        ServiceInstance service = services.get(serviceName);
        if (service != null) {
            service.stop();
            services.remove(serviceName);
        }
    }

    public void pauseService(String serviceName) throws Exception {
        ServiceInstance service = services.get(serviceName);
        if (service != null) {
            service.pause();
        }
    }

    public void resumeService(String serviceName) throws Exception {
        ServiceInstance service = services.get(serviceName);
        if (service != null) {
            service.resume();
        }
    }

    public void modifyConfig(String serviceName, String configKey, Object value) throws Exception {
        configManager.updateConfig(serviceName, configKey, value);
    }

    public void monitorServices() throws IOException {
        for (ServiceInstance service : services.values()) {
            monitoringSystem.sendStatusUpdate(service.getStatus());
        }
    }

    private class ServiceInstance extends Thread {
        private String serviceName;
        private Config config;
        private boolean active = true;
        private boolean paused = false;
