            cache_error_messages[error_type] = value  # store in cache
            return value
        except (requests.exceptions.RequestException, KeyError):
            LOG.error("Failed to fetch error message.")
            return None

def optimize_memory_usage() -> None:
    @lru_cache(maxsize=None)
