class CombatActionManager {
public:
    enum AttackType { LIGHTNING = 0, FIREBALL = 1, POISONOUS_STING = 2 };

    CombatActionManager() : attackProbabilities({ 30, 40, 30 }), currentAttack(0), lastAttackTime(std::chrono::steady_clock::now()), 
                            serviceState(false), pendingActionsQueue(), serviceDelayTimer(std::chrono::seconds(45)), 
                            actionHandlerTimer(std::chrono::minutes(5)) {}

    void StartService() {
        std::unique_lock<std::mutex> lock(serviceMutex);
        if (!serviceState) {
            serviceState = true;
            std::cout << "Combat Action Manager: Service started." << std::endl;
            serviceDelayTimer = std::chrono::seconds(std::rand() % 30 + 30);
            actionHandlerTimer = std::chrono::minutes(5);
        }
    }

    void StopService() {
        std::unique_lock<std::mutex> lock(serviceMutex);
        if (serviceState) {
            serviceState = false;
            std::cout << "Combat Action Manager: Service stopped." << std::endl;
        }
    }

    AttackType SelectAttack() {
        int randomValue = rand() % 100;
        for (int i = 0; i < 3; ++i) {
            if (randomValue < attackProbabilities[i]) {
                currentAttack = static_cast<AttackType>(i);
                break;
            }
            randomValue -= attackProbabilities[i];
        }
        return currentAttack;
    }

    void HandleAction() {
        AttackType attack = SelectAttack();
        pendingActionsQueue.push(attack);
        std::cout << "Combat Action Manager: Chose attack " << (int)attack << "." << std::endl;

        // Send message to remote server
        std::cout << "Combat Action Manager: Sent message to server." << std::endl;
    }

    void UpdateServiceState() {
        std::unique_lock<std::mutex> lock(serviceMutex);
        if (!serviceState && serviceDelayTimer <= 0) {
            StartService();
        }
        else if (serviceState && actionHandlerTimer <= 0) {
            StopService();
        }
        --actionHandlerTimer;
    }

private:
    std::vector<int> attackProbabilities;
    AttackType currentAttack;
    std::chrono::time_point<std::chrono::steady_clock> lastAttackTime;
    bool serviceState;
    std::queue<AttackType> pendingActionsQueue;
    std::chrono::duration<double> serviceDelayTimer;
    std::chrono::duration<int> actionHandlerTimer;
    std::mutex serviceMutex;
};

int main() {
    CombatActionManager combatActionManager;
    // Code for handling the game loop and updating the combat action manager
}
