#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long* offset_ptr;
} record;

void manage_memory(int offset_count, int key_count, int record_count) {
    // Ensure alignment to 16-byte boundaries
    void* aligned_offset = memalign(16, sizeof(long) * offset_count);
    if (aligned_offset == NULL) {
        printf("Error: Offset allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    void* aligned_key = memalign(16, sizeof(int) * key_count);
    if (aligned_key == NULL) {
        printf("Error: Key allocation failed.\n");
        free(aligned_offset);
        exit(EXIT_FAILURE);
    }

    void* aligned_records = memalign(16, sizeof(record) * record_count);
    if (aligned_records == NULL) {
        printf("Error: Record allocation failed.\n");
        free(aligned_key);
        free(aligned_offset);
        exit(EXIT_FAILURE);
    }

    // Initialize records
    srand(time(NULL));
    for (int i = 0; i < record_count; i++) {
        record* current_record = aligned_records + i;
        current_record->value = rand() % 1001;
        current_record->offset_ptr = aligned_offset + sizeof(long) * i;
    }

    // Set corresponding long pointers
    for (int i = 0; i < record_count; i++) {
        record* current_record = aligned_records + i;
        *current_record->offset_ptr = current_record->value * 2;
    }

    void* aligned_offsets = reallocate(aligned_offset, sizeof(long) * offset_count);
    if (aligned_offsets == NULL) {
        printf("Error: Offset reallocation failed.\n");
        free(aligned_records);
        free(aligned_key);
        exit(EXIT_FAILURE);
    }
    void* aligned_keys = reallocate(aligned_key, sizeof(int) * key_count);
    if (aligned_keys == NULL) {
        printf("Error: Key reallocation failed.\n");
        free(aligned_offsets);
        free(aligned_records);
        exit(EXIT_FAILURE);
    }

    // Free allocated memory
    free(aligned_offsets);
    free(aligned_keys);
    free(aligned_records);
}

void* reallocate(void* ptr, size_t size) {
    return realloc(ptr, size);
}
