use sha2::{Sha256, Digest};

struct UeMeasurementResult {
    ran_node_id: u16,
    measurement_type: String,
    measurement_value: f64,
    moving_average: f64,
}

fn initialize_measurement_directory() -> Result<(), Box<dyn std::error::Error>> {
    let dir_path = env::var("MEASUREMENT_DIR").unwrap_or_else(|_| {
        fs::create_dir_all("measurements")?;
        "measurements".to_string()
    });

    let mut timestamp: u64 = 0;
    let mut window_size: usize = 30;

    // Initialize measurement directory and calculate moving average
    let mut measurements = Vec::new();
    for _ in 0..window_size {
        let ran_node_id: u16 = (rand::random::<u16>()) % 256;
        let measurement_type: String = format!("Measurement Type {}", rand::random::<u8>());
        let measurement_value: f64 = rand::random::<f64>();
        let moving_average: f64 = measurements.iter().map(|m| m.measurement_value).sum::<f64>() / (window_size as f64);

        // Calculate CRC32 and SHA-256 checksums
        let crc_checksum = Crc32Fast::new().update(&format!("{} {} {:.2}", ran_node_id, measurement_type, measurement_value)).finalize();
        let sha_checksum = Sha256::new().update(&format!("{} {} {:.2}", ran_node_id, measurement_type, measurement_value)). finalize();

        measurements.push(UeMeasurementResult {
            ran_node_id,
            measurement_type,
            measurement_value,
            moving_average,
        });
    }

    // Write records to file
    for (i, record) in measurements.iter().enumerate() {
        let mut file_path = Path::new(&dir_path).join(format!("measurement_{}.txt", timestamp));
        if !file_path.exists() {
            fs::create_dir_all(file_path.parent())?;
            File::create(file_path)?;
        }

        writeln!(File::open(file_path)?, "{}, {:.2}, {:.8}", record.ran_node_id, record.measurement_value, record.moving_average)?;
        writeln!(File::open(file_path)?, "CRC32: {:X}, SHA256: {}", crc_checksum, sha_checksum)?;

        timestamp += 1;
    }

    Ok(())
}

fn main() {
    initialize_measurement_directory();
}
