// Define the maximum size of the log buffer
#define LOG_BUFFER_SIZE 256

typedef struct {
    uint64_t session_id;
    uint64_t timestamp;
    int packet_counter;
    char *log_buffer;
    size_t log_buffer_size;
} session_t;

// Global array to store all sessions
session_t **sessions = NULL;
size_t num_sessions = 0;
pthread_mutex_t session_mutex = PTHREAD_MUTEX_INITIALIZER;

int init_network_sessions(size_t initial_num_sessions) {
    // Allocate memory for the session array
    sessions = (session_t **)malloc(initial_num_sessions * sizeof(session_t *));
    if (!sessions) {
        return -1;  // Allocation failed, handle error
    }

    // Initialize each session with default values
    for (size_t i = 0; i < initial_num_sessions; i++) {
        sessions[i] = (session_t *)malloc(sizeof(session_t));
        if (!sessions[i]) {
            // Handle allocation failure for individual sessions
            return -1;
        }
        sessions[i]->session_id = i;
        sessions[i]->timestamp = 0;
        sessions[i]->packet_counter = 0;
        sessions[i]->log_buffer_size = LOG_BUFFER_SIZE;
        sessions[i]->log_buffer = (char *)malloc(LOG_BUFFER_SIZE);
    }

    num_sessions = initial_num_sessions;
    return 0;  // Initialization successful
}

void add_session(uint64_t session_id, uint64_t timestamp) {
    pthread_mutex_lock(&session_mutex);

    // Check if the session ID already exists
    for (size_t i = 0; i < num_sessions; i++) {
        if (sessions[i]->session_id == session_id) {
            printf("Session %lu already exists!\n", session_id);
            pthread_mutex_unlock(&session_mutex);
            return;
        }
    }

    // Find the first available slot
    size_t new_session_index = num_sessions++;
    sessions = (session_t **)realloc(sessions, (num_sessions + 1) * sizeof(session_t *));
    if (!sessions) {
        // Handle memory allocation failure for new session array
        return;
    }
    sessions[new_session_index] = (session_t *)malloc(sizeof(session_t));
    if (!sessions[new_session_index]) {
        // Handle individual session allocation failure
        num_sessions--;
        return;
    }

    sessions[new_session_index]->session_id = session_id;
    sessions[new_session_index]->timestamp = timestamp;
    sessions[new_session_index]->packet_counter = 0;
    sessions[new_session_index]->log_buffer_size = LOG_BUFFER_SIZE;
    sessions[new_session_index]->log_buffer = (char *)malloc(LOG_BUFFER_SIZE);

    pthread_mutex_unlock(&session_mutex);
}

void log_packet(session_t *session, char *data) {
    pthread_mutex_lock(&session_mutex);

    // Resize the log buffer if necessary
    if (strlen(data) + session->packet_counter > session->log_buffer_size) {
        session->log_buffer = (char *)realloc(session->log_buffer, session->log_buffer_size * 2);
        session->log_buffer_size *= 2;
    }

    // Append data to the log buffer and increment packet counter
    strcpy(session->log_buffer + session->packet_counter, data);
    session->packet_counter += strlen(data);

    pthread_mutex_unlock(&session_mutex);
}

int main() {
    init_network_sessions(10);  // Initialize sessions

    add_session(1, 1643723400);  // Add new session
    log_packet(sessions[0], "Packet received!");  // Log a packet for the added session

    return 0;
}
