#define CHACHA_BLOCK_SIZE 256
#define POLY1305_TAG_SIZE 16

typedef struct {
    EVP_PKEY* key;
    ChaCha20_Poly1305_CTX ctx;
} Session;

Session* session_init(const char* password) {
    EVP_PKEY* key = EVP_PKEY_new();
    if (!key) return NULL;

    // generate a random key
    BURN burn;
    if (EVP_PKEY_generate_key(key, 256)) {
        EVP_PKEY_free(key);
        return NULL;
    }

    ChaCha20_Poly1305_CTX ctx;
    ChaCha20_Poly1305_init(&ctx);

    Session* session = malloc(sizeof(Session));
    session->key = key;
    session->ctx = ctx;

    return session;
}

int encrypt(Session* session, const char* data, size_t data_len) {
    unsigned char ciphertext[CHACHA_BLOCK_SIZE];
    ChaCha20_Poly1305_encrypt(&session->ctx, data, &ciphertext);

    return 0;
}

int decrypt(Session* session, const char* ciphertext, size_t ciphertext_len) {
    unsigned char plaintext[CHACHA_BLOCK_SIZE];
    ChaCha20_Poly1305_decrypt(&session->ctx, ciphertext, &plaintext);

    return 0;
}

void session_free(Session* session) {
    EVP_PKEY_free(session->key);
    free(session);
}

int main() {
    Session* session = session_init("password");
    const char* data = "Hello, World!";
    size_t data_len = strlen(data);

    encrypt(session, data, data_len);
    const char* ciphertext = malloc(data_len + POLY1305_TAG_SIZE);
    if (ciphertext) {
        decrypt(session, ciphertext, data_len + POLY1305_TAG_SIZE);
        free(ciphertext);
    }

    session_free(session);
}

