    scheduler = BackgroundScheduler()
    scheduler.add_job(monitor_interfaces, 'interval', seconds=GATEWAY_CHECK_INTERVAL)
    scheduler.add_job(check_gw, 'interval', seconds=10)
    scheduler.start()

    # Monitor CPU/Memory and Network I/O
    scheduler.add_job(monitor_cpu_memory, 'interval', seconds=30)
    scheduler.add_job(monitor_network_io, 'interval', seconds=2)

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        scheduler.shutdown()
        print('Shutting down...')

if __name__ == '__main__':
    main()

