class RateLimiter:
    def __init__(self, max_requests_per_hour):
        self.max_requests_per_hour = max_requests_per_hour
        self.requests_in_last_hour = 0

    def check(self):
        if self.requests_in_last_hour >= self.max_requests_per_hour:
            time.sleep(3600 - (time.time() % 3600))  # wait for the next hour
