    size_t recordSize = sizeof(record_t);
    size_t recordsSize = recordSize * numRecords;

    // Allocate memory for the keys and offsets arrays
    long* keys = malloc(recordsSize * sizeof(long));
    long* offsets = malloc(recordsSize * sizeof(long));

    if (!keys || !offsets) {
        free(keys);
        free(offsets);
        return NULL;  // Memory allocation failed
    }

    // Initialize the key and offset values using provided function
    for (int i = 0; i < numRecords; i++) {
        keys[i] = initKey(i);  // Call initialization function to populate key
        offsets[i] = rand();     // Assign random value to record offset
    }

    // Allocate memory for the records array
    record_t** records = malloc(numRecords * sizeof(record_t*));

    if (!records) {
        free(keys);
        free(offsets);
        return NULL;  // Memory allocation failed
    }

    // Initialize each record and store pointers in the records array
    for (int i = 0; i < numRecords; i++) {
        records[i] = malloc(recordSize);  // Allocate memory for record structure
        if (!records[i]) {  // Check for memory allocation failure
            free(keys);
            free(offsets);
            free(records);
            return NULL;
        }
        records[i]->key = keys[i];
        records[i]->offset = offsets[i];
    }

    // Release allocated resources
    free(keys);
    free(offsets);

    return records;
}

void releaseRecords(record_t** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    free(records);
}
