#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
} record_t;

record_t **records = NULL;
int *keys = NULL;
long *offsets = NULL;
int num_records = 0;

// Function to generate a unique random value within a specified range
long rand_long(long min, long max) {
    return (long)(rand() % ((max + 1) - min)) + min;
}

// Function to set each record to a unique random value
void init_records(int num_records) {
    for (int i = 0; i < num_records; i++) {
        records[i]->key = rand_long(0, INT_MAX);
        records[i]->offset = rand_long(0, LONG_MAX);
    }
}

// Function to handle concurrent access from multiple threads
void *thread_func(void *arg) {
    int tid = *(int *)arg;

    // Simulate some work for each thread
    for (int i = 0; i < num_records; i++) {
        records[i][tid].key++;
    }

    pthread_exit(NULL);
}

// Function to export managed data to an external system
void export_data() {
    FILE *fp = fopen("exported_data.txt", "w");

    if (fp == NULL) {
        printf("Failed to open file for writing.\n");
        return;
    }

    for (int i = 0; i < num_records; i++) {
        fprintf(fp, "%d %ld\n", records[i]->key, records[i]->offset);
    }

    fclose(fp);
}

// Function to add a new record type
void add_record_type(int key) {
    // Allocate memory for the new record type
    record_t *new_records = (record_t *)malloc(sizeof(record_t) * num_records);

    if (new_records == NULL) {
        printf("Failed to allocate memory.\n");
        return;
    }

    // Initialize the new record type with unique random values
    init_records(num_records);

    // Update the array of records and keys
    for (int i = 0; i < num_records; i++) {
        new_records[i].key = key;
        new_records[i].offset = rand_long(0, LONG_MAX);
        records[i] = &new_records[i];
        keys[i] = key;
    }

    free(new_records);
}

// Function to remove a record type
void remove_record_type(int key) {
    // Find the index of the record type to be removed
    int idx = -1;
    for (int i = 0; i < num_records; i++) {
        if (keys[i] == key) {
            idx = i;
            break;
        }
    }

    if (idx == -1) {
        printf("Record type not found.\n");
        return;
    }

    // Remove the record type from the array
    for (int i = idx; i < num_records - 1; i++) {
        records[i] = &records[i + 1];
        keys[i] = keys[i + 1];
    }

    num_records--;
}

// Function to handle memory allocation failures
void *malloc_failure_handler(void *ptr) {
    printf("Memory allocation failed.\n");
    return NULL;
}

int main() {
    srand(time(NULL));

    // Initialize the arrays of records, keys, and offsets
    records = (record_t **)malloc(sizeof(record_t *) * 10);
    keys = (int *)malloc(sizeof(int) * 10);
    offsets = (long *)malloc(sizeof(long) * 10);

    if (records == NULL || keys == NULL || offsets == NULL) {
        malloc_failure_handler(NULL);
        return 1;
    }

    // Initialize the record structures with unique random values
    init_records(10);

    // Create and join a thread to simulate concurrent access
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        int *tid = (int *)malloc(sizeof(int));
        *tid = i;
        pthread_create(&threads[i], NULL, thread_func, tid);
        pthread_join(threads[i], NULL);
    }

    // Export the managed data to an external system
    export_data();

    // Add a new record type and remove an existing one
    add_record_type(5);
    remove_record_type(0);

    return 0;
}

