} NFAPI_CRC_INDICATION_PDU_T;

void generatePEMCertificateAndNFAPIArray(OAuth_request_t* oReq, int numStructures) {
    FILE *pKeyFile = fopen(oReq->pathToPrivateKey, "rb");
    if (pKeyFile == NULL) {
        // handle error
        return;
    }

    FILE *pCertFile = fopen(oReq->pathToCertificate, "rb");
    if (pCertFile == NULL) {
        // handle error
        fclose(pKeyFile);
        return;
    }

    char* pPrivateKey = malloc(sizeof(char));
    size_t privateKeySize = 0;

    while (fread(pPrivateKey + privateKeySize, 1, 1024, pKeyFile) > 0) {
        privateKeySize += 1024;
        if ((privateKeySize * sizeof(char)) >= (1024 * sizeof(char))) {
            break;
        }
    }

    fclose(pKeyFile);

    char* pCertificate = malloc(sizeof(char));
    size_t certificateSize = 0;

    while (fread(pCertificate + certificateSize, 1, 1024, pCertFile) > 0) {
        certificateSize += 1024;
        if ((certificateSize * sizeof(char)) >= (1024 * sizeof(char))) {
            break;
        }
    }

    fclose(pCertFile);

    // concatenate private key and certificate strings
    size_t pemStringSize = privateKeySize + certificateSize;
    char* pPEMCertificate = malloc((pemStringSize + 1) * sizeof(char));
    strcpy(pPEMCertificate, "-----BEGIN CERTIFICATE-----\n");
    strcat(pPEMCertificate, pPrivateKey);
    strcat(pPEMCertificate, "\n-----END CERTIFICATE-----\n");

    // dynamically allocate memory for the structures
    NFAPI_CRC_INDICATION_PDU_T* pStructures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pStructures == NULL) {
        // handle allocation failure
        return;
    }

