    // resize and deallocate memory as needed
    while (numStructures > 10000) {
        NFAPI_CRC_INDICATION_PDU_T* oldStructures = pStructures;
        pStructures = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pStructures, numStructures / 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(oldStructures);
    }

    // periodic garbage collection
    while (numStructures > 10000) {
        NFAPI_CRC_INDICATION_PDU_T* oldStructures = pStructures;
        pStructures = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pStructures, numStructures / 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
