} NFAPI_CRC_INDICATION_PDU_T;

void generatePEMCertificateAndNFAPIArray(OAuthRequest* oAuthRequest, int numStructures) {
    // Initialize memory allocation
    void* p = malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

