    // Read certificate
    FILE* certificateFile = fopen(oAuthRequest->certificatePath, "rb");
    if (certificateFile == NULL) {
        printf("Failed to open certificate file.\n");
        return;
    }

    char certificateBuffer[1024];
    fread(certificateBuffer, 1, 1023, certificateFile);
    fclose(certificateFile);

    // Concatenate private key and certificate
    size_t len = strlen(privateKeyBuffer) + strlen(certificateBuffer) + 2;
    char* pemCertificate = malloc(len);
    sprintf(pemCertificate, "%s%s", privateKeyBuffer, certificateBuffer);

    // Initialize PEM-encoded certificate
    BIO* bio = BIO_new_mem_buf((void*) pemCertificate, len);
    X509* x509 = d2i_X509_bio(bio, &certificate);
    BIO_free_all(bio);

    free(pemCertificate);

    if (x509 == NULL) {
        printf("Failed to generate PEM-encoded certificate.\n");
        return;
    }

    // Initialize NFAPI CRC indication PDU structures
    for (int i = 0; i < numStructures; i++) {
        structures[i].RNTI = i + 1;
        strcpy(structures[i].RX_UE_INFORMATION_TAG, "RX UE Information Tag");
        structures[i].CRCFLAG = rand() % 2;
    }

    // Print NFAPI CRC indication PDU structures
    for (int i = 0; i < numStructures; i++) {
        printf("RNTI: %d\n", structures[i].RNTI);
        printf("RX UE Information Tag: %s\n", structures[i].RX_UE_INFORMATION_TAG);
        printf("CRCFLAG: %d\n", structures[i].CRCFLAG);
    }

    free(p);
}
