void init_array(long* offsets, int* keys, record* records, event* events, size_t size) {
    // Initialize memory pool for efficient allocation
    void* pool = malloc(size * 1024); // Allocate initial memory pool

    // Loop through each element and allocate memory dynamically
    for (size_t i = 0; i < size; i++) {
        long offset = (long)i;
        int key = (int)(rand() % 10000);
        record* record = (record*)malloc(sizeof(record));
        event* eventPtr = (event*)malloc(sizeof(event));

        // Initialize record and event structures
        record->value = rand() % 1000;
        strcpy(record->string, "Sample String");

        eventPtr->timestamp = time(NULL);
        eventPtr->type = (int)(rand() % 10);
        eventPtr->recordPtr = record;

        // Assign memory to arrays
        offsets[i] = offset;
        keys[i] = key;
        records[i] = *record;
        events[i] = *eventPtr;

        // Check for out-of-memory conditions and handle errors gracefully
        if (i % 1000 == 0) {
            printf("Allocated memory: %zu bytes\n", i * sizeof(long) + i * sizeof(int) + i * sizeof(record) + i * sizeof(event));
        }
    }

    // Ensure proper deallocation of allocated resources
    for (size_t i = 0; i < size; i++) {
        free((void*)events[i].recordPtr);
        free((void*)&events[i]);
    }
    free(pool);

    // Log operations for debugging purposes
    FILE* logFile = fopen("log.txt", "w");
    fprintf(logFile, "Timestamp: %ld\nThread ID: %lu\nAction: Successful memory allocation\n", time(NULL), (unsigned long)pthread_self());
    fclose(logFile);
}

int main() {
