    long* offsets = malloc(size * sizeof(long));
    int* keys = malloc(size * sizeof(int));
    record* records = malloc(size * sizeof(record));
    event* events = malloc(size * sizeof(event));

    init_array(offsets, keys, records, events, size);

    // Free allocated memory
    free(offsets);
    free(keys);
