typedef struct {
    int key;
    long offset;
} Record;

class RecordCollection {
public:
    RecordCollection(size_t initialCapacity) {
        records = (Record*)malloc(initialCapacity * sizeof(Record));
        capacity = initialCapacity;
        size = 0;
        mutex = pthread_mutex_init();
    }

    ~RecordCollection() {
        free(records);
        pthread_mutex_destroy(mutex);
    }

    void addRecord(int key, long offset) {
        pthread_mutex_lock(mutex);

        if (size >= capacity) {
            capacity *= 2;
            records = (Record*)realloc(records, capacity * sizeof(Record));
        }

        records[size].key = key;
        records[size++].offset = offset;

        pthread_cond_signal(&cond);
        pthread_mutex_unlock(mutex);
    }

    void getRecords(Record* destination, size_t length) {
        pthread_mutex_lock(mutex);

        while (size < length) {
            pthread_cond_wait(&cond, mutex);
        }

        for (size_t i = 0; i < length && i < size; i++) {
            destination[i] = records[i];
        }

        pthread_mutex_unlock(mutex);
    }

private:
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t* mutex;
    pthread_cond_t cond;
};
