struct item {
    double value;
    char buffer[256];
};

class DynamicList {
public:
    DynamicList(size_t initialCapacity, size_t growthFactor) 
        : capacity_(initialCapacity), size_(0),
          data_(new item[capacity_]), mutex_(), lock_() {}

    ~DynamicList() {
        delete[] data_;
    }

    void push_back(item const& item) {
        std::lock_guard<std::mutex> guard(lock_);
        if (size_ == capacity_) {
            // grow the array
            size_t newCapacity = capacity_ * growthFactor;
            item* newData = new item[newCapacity];
            std::copy(data_, data_ + capacity_, newData);
            delete[] data_;
            data_ = newData;
            capacity_ = newCapacity;
        }
        data_[size_++] = item;
    }

    size_t getSize() const {
        return size_;
    }

private:
    size_t capacity_;
    size_t size_;
    item* data_;
    std::mutex mutex_;
    std::lock_guard<std::mutex> lock_;
};

class LRUcache {
public:
    void set(const char* key, const char* value) {
        cache_.insert(std::pair<const char*, const char*>(key, value));
        if (cache_.size() > max_size_) {
            // evict the least recently used item
            auto it = cache_.begin();
            std::advance(it, -max_size_);
            cache_.erase(it);
        }
    }

    const char* get(const char* key) {
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            // mark the accessed item as recently used
            it->second = value;
            return it->first;
        } else {
            return nullptr;
        }
    }

private:
    size_t max_size_ = 1000;
    std::map<const char*, const char*> cache_;
};

int main() {
    DynamicList list(10, 2);
    LRUcache cache;

    // process events
