    // Acquire lock for thread-safety
    std::unique_lock<std::mutex> lock(mtx);

    // Check if the character has already entered a cooldown period
    if (totalMemoryAllocated > 0 && gettime() - records[0].engagementTimestamp >= 15) {
        // Reset combat state and release memory
        for (int i = 0; i < totalMemoryAllocated; i++) {
            delete[] records[i];
        }
        records.clear();
        totalMemoryAllocated = 0;
    }

    // Check if the character has reached the maximum number of consecutive attacks
    int consecutiveAttacks = 0;
    for (int i = 0; i < totalMemoryAllocated; i++) {
        if (records[i].lastAttackType == attackType) {
            consecutiveAttacks++;
        } else {
            break;
        }
    }

    // Handle close-range and ranged attacks based on game state and available resources
    if (consecutiveAttacks < 3 && gettime() - records[0].engagementTimestamp >= 1) {
        if (attackType == 1) { // Close-range attack
            // Allocate memory for new combat record
            CombatRecord* newRecord = new CombatRecord;
            newRecord->lastAttackType = 1;
            newRecord->isCooldown = false;
            newRecord->engagementTimestamp = gettime();
            records.push_back(newRecord);
            totalMemoryAllocated++;

            // Update character's consecutive attack count and last used attack type
            if (consecutiveAttacks < 2) {
                consecutiveAttacks++;
            }
        } else { // Ranged attack
            // Allocate memory for new combat record
