struct UeMeasurementResult {
    ran_node_id: u32,
    measurement_type: String,
    measurement_value: f64,
    moving_average: f64,
}

fn initialize_measurement_directory() -> PathBuf {
    let current_timestamp = chrono::Utc::now().to_rfc3339();
    let unique_identifier = rand::random::<u32>();
    let directory_name = format!("measurements-{}-{}", current_timestamp, unique_identifier);

    let measurement_dir_path = env::var("MEASUREMENT_DIR").ok_or_else(|| {
        fs::create_dir_all(&directory_name).expect("Failed to create directory");
        env::set_var("MEASUREMENT_DIR", &directory_name);
        PathBuf::from(&directory_name)
    })?;

    // Populate the directory with UeMeasurementResult entries
    let mut measurement_results = Vec::new();
    for _ in 0..10 {
        let ran_node_id: u32 = rand::random();
        let measurement_type = format!("measurement-{}", rand::random::<u8>());
        let measurement_value: f64 = rand::random::<f64>();
        let moving_average: f64 = (measurement_value + rand::random::<f64>()) / 2.0;

        let record = UeMeasurementResult {
            ran_node_id,
            measurement_type,
            measurement_value,
            moving_average,
        };

        // Calculate CRC32 and SHA-256 checksums
        let crc_checksum = Crc32Fast::new().update(recordmeasurement_type.as_bytes()).finalize();
        let sha256_checksum = Sha256::digest(record.measurement_type.as_bytes());

        measurement_results.push((record, crc_checksum, sha256_checksum));
    }

    // Store and retrieve historical measurement data
    let history_directory_path = PathBuf::from(&measurement_dir_path).join("history");
    fs::create_dir_all(&history_directory_path)?;

    for (i, (measurement_result, _, _)) in measurement_results.iter().enumerate() {
        let file_path = &history_directory_path.join(format!("measurement-{}.txt", i));

        // Write measurement data to file
        fs::write(file_path, format!("{:?}", measurement_result).as_bytes())?;
    }

    PathBuf::from(&measurement_dir_path)
}
