} document_index;

struct record {
    char **strings;
    int *metadata;
    struct record *next;
};

int construct_document_index(int *document_indices, int num_documents, void *tpa, int start_doc, int end_doc) {
    int i;
    int total_strings = 0;
    int total_metadata = 0;
    for (i = start_doc; i <= end_doc; i++) {
        total_strings += strlen((char *)tpa);
        total_metadata++;
    }

    document_index *index = malloc(sizeof(document_index));
    if (!index) return -1;

    index->strings = malloc((total_strings + 1) * sizeof(char *));
    if (!index->strings) {
        free(index);
        return -1;
    }

    index->metadata = malloc(total_metadata * sizeof(int));
    if (!index->metadata) {
        free(index->strings);
        free(index);
        return -1;
    }

    index->records = NULL;

    int record_count = 0;
    for (i = start_doc; i <= end_doc; i++) {
        struct record *record = malloc(sizeof(struct record));
        if (!record) {
            free(index->metadata);
            free(index->strings);
            free(index);
            return -1;
        }

        record->strings = malloc((strlen((char *)tpa)) * sizeof(char *));
        if (!record->strings) {
            free(record);
            free(index->metadata);
            free(index->strings);
            free(index);
            return -1;
        }

        record->metadata = &index->metadata[i - start_doc];
        record->next = NULL;

        index->records = record;
        record_count++;
    }

    index->next = NULL;

    int total_init_records = 0;
    struct record *current = index->records;
    while (current) {
        current->strings = malloc((strlen((char *)tpa)) * sizeof(char *));
        if (!current->strings) {
            free(current);
            return -1;
        }
        current = current->next;
        total_init_records++;
    }

    // Initialize metadata
    for (i = start_doc; i <= end_doc; i++) {
        index->metadata[i - start_doc] = 0;
    }

    return record_count;
}
