class DatabasePool {
public:
    DatabasePool(size_t initialSize, size_t maxSize) : maxConnections(maxSize), activeConnections(0) {}

    ~DatabasePool() {}

    void manageConnections(size_t currentLoad) {
        if (currentLoad > maxConnections * 2) {
            // scale up the pool
            for (int i = 0; i < (maxConnections - activeConnections); ++i) {
                connect();
            }
        } else if (activeConnections > maxConnections / 2) {
            // scale down the pool
            close();
        }
    }

private:
    void connect() {
        DatabaseConnection* conn = new DatabaseConnection();
        connections.push(conn);
        ++activeConnections;
    }

    void close() {
        while (!connections.empty()) {
            DatabaseConnection* conn = connections.front();
            delete conn;
            connections.pop();
            --activeConnections;
        }
    }

    size_t maxConnections;
    std::queue<DatabaseConnection*> connections;
    size_t activeConnections;
};

class ConnectionTracker {
public:
    void trackConnection(ConnectionState state) {
        switch (state) {
            case ConnectionState::Active:
                ++activeConnections;
                break;
            case ConnectionState::Idle:
                ++idleConnections;
                break;
            case ConnectionState::Broken:
                ++brokenConnections;
                break;
        }
    }

    void reset() {
        activeConnections = 0;
        idleConnections = 0;
        brokenConnections = 0;
    }

private:
    size_t activeConnections;
    size_t idleConnections;
    size_t brokenConnections;
};

