typedef struct {
    int* key;
    long offset;
    long* data;
} record;

record* allocateRecords(int size) {
    if (size <= 0) {
        printf("Invalid input size. Size must be greater than zero.\n");
        exit(1);
    }

    // Allocate memory for offsets array
    long* offsets = (long*)malloc(size * sizeof(long));
    if (!offsets) {
        printf("Memory allocation failed for offsets array.\n");
        exit(1);
    }

    // Initialize offsets with random values
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % (size * sizeof(long) - 1);
    }

    // Allocate memory for keys array
    int* keys = (int*)malloc(size / 2 * sizeof(int));
    if (!keys) {
        printf("Memory allocation failed for keys array.\n");
        free(offsets);
        exit(1);
    }

    // Initialize keys with random values
    for (int i = 0; i < size / 2; i++) {
        keys[i] = rand() % size;
    }

    // Allocate memory for records array
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        printf("Memory allocation failed for records array.\n");
        free(offsets);
        free(keys);
        exit(1);
    }

    // Initialize each record's data field to point to a valid location in offsets array
    for (int i = 0; i < size; i++) {
        records[i].key = &keys[i % (size / 2)];
        records[i].offset = offsets[i];
        records[i].data = (long*)(&offsets[i]);
    }

    // Free temporary arrays
    free(keys);

    return records;
}
