    char* pemString = (char*)malloc(strlen(privateKeyFile) + strlen(certificateFile) + 100);
    sprintf(pemString, "-----BEGIN CERTIFICATE-----\n%s\n-----END CERTIFICATE-----\n", privateKeyFile);
    strcat(pemString, certificateFile);

