    private static final long RETRY_BACKOFF_MILLIS = 1000; // 1 second

    public String processUserFeedback(int userId, double feedbackScore) {
        if (feedbackScore < 1 || feedbackScore > 5) {
            return "Invalid feedback score. Score must be between 1 and 5.";
        }

        try {
            // Validate user exists in both systems
            if (!validateUserExistsInCache(userId) || !validateUserExistsInStorage(userId)) {
                return "User not found";
            }

            // Update local cache
            updateCache(userId, feedbackScore);

            // Integrate with distributed recommendation engine
            int retries = 0;
            while (retries < MAX_RETRIES) {
                try {
                    updateStorage(userId, feedbackScore);
                    break; // Successful update
                } catch (Exception e) {
                    if (retries >= MAX_RETRIES - 1) {
                        logError("Failed to update user feedback", e);
                        return "Update failed";
                    }
                    retries++;
                    Thread.sleep(RETRY_BACKOFF_MILLIS * (int) Math.pow(2, retries));
                }
            }

            // Update timestamp in both cache and storage
            Instant now = Instant.now();
            updateCacheTimestamp(userId, now.toEpochMilli());
            updateStorageTimestamp(userId, now.toEpochMilli());

            return "Feedback updated successfully";
