    rand::Rng,
};

struct FileProcessor {
    cache: std::collections::HashMap<String, String>,
    allowed_extensions: Vec<&str>
}

impl FileProcessor {
    fn new(allowed_extensions: Vec<&str>) -> Self {
        Self { cache: Default::default(), allowed_extensions }
    }

    fn process_directory(&mut self, dir: &Path) -> String {
        let mut new_filename = String::new();
        for entry in std::fs::read_dir(dir).unwrap() {
            let entry = entry.unwrap();
            let path = entry.path();

            if path.is_file() && self.allowed_extensions.iter().any(|ext| &path.extension().unwrap() == ext) {
                match self.process_file(&path) {
                    Ok(ir_code) => {
                        info!("Generated LLVM IR code for {}", path.display());
                        new_filename.push_str(&ir_code);
                    },
                    Err(e) => error!("Error processing file {}: {}", path.display(), e),
                }
            } else if path.is_dir() {
                let dir_name = path.file_name().unwrap().to_string_lossy();
                let new_dir = format!("{}/{}", dir_name, rand::thread_rng().gen::<f64>().to_string());
                self.cache.insert(path.to_str().unwrap().to_string(), new_dir);
                info!("Caching directory {}", path.display());
            }
        }

        if !new_filename.is_empty() {
            let mut file = File::create("output.txt").unwrap();
            file.write_all(new_filename.as_bytes()).unwrap();
        }

        self.cache.get(&dir.to_str().unwrap().to_string()).unwrap_or_default().clone()
    }

    fn process_file(&mut self, path: &Path) -> Result<String, String> {
        let mut file = File::open(path).unwrap();
        let mut content = String::new();

        file.read_to_string(&mut content).unwrap();

        // Simulate unpredictable service behavior
        thread::sleep(std::time::Duration::from_millis(rand::thread_rng().gen_range(0..100)));

        let ir_code = llvm_ir(content.as_bytes());

        Ok(ir_code)
    }

    fn llvm_ir(data: &[u8]) -> String {
        // Generate LLVM IR code here
        // ...
    }
}
