    private long[] _verticesOffsets;
    private int[] _verticesKeys;
    private Record[] _verticesRecords;
    private int _edgeCount;
    private long[] _edgesOffsets;
    private int[] _edgesKeys;
    private EdgeRecord[] _edgesRecords;

    public GraphDatabase(int vertexArrayCapacity = DefaultVertexArrayCapacity, int edgeArrayCapacity = DefaultEdgeArrayCapacity)
    {
        _verticesOffsets = new long[vertexArrayCapacity];
        _verticesKeys = new int[vertexArrayCapacity];
        _verticesRecords = new Record[vertexArrayCapacity];

        _edgesOffsets = new long[edgeArrayCapacity];
        _edgesKeys = new int[edgeArrayCapacity];
        _edgesRecords = new EdgeRecord[edgeArrayCapacity];

        _vertexCount = 0;
        _edgeCount = 0;
    }

    public void AddVertex(int key, int value)
    {
        lock (_lock)
        {
            if (_vertexCount >= _verticesOffsets.Length)
                ResizeVertices();

            _verticesOffsets[_vertexCount] = unchecked((long)(_verticesOffsets.Sum() + (int)Math.Pow(2, 31) - 1));
            _verticesKeys[_vertexCount] = key;
            _verticesRecords[_vertexCount].Value = value;

            _vertexCount++;
        }
    }

    public void AddEdge(int source, int target)
    {
        lock (_lock)
        {
            if (_edgeCount >= _edgesOffsets.Length)
                ResizeEdges();

            _edgesOffsets[_edgeCount] = unchecked((long)(_edgesOffsets.Sum() + (int)Math.Pow(2, 31) - 1));
            _edgesKeys[_edgeCount] = source;
            _edgesRecords[_edgeCount].Source = source;
            _edgesRecords[_edgeCount].Target = target;

            _edgeCount++;
        }
    }

    public void MonitorMemoryThreshold(int thresholdKb)
