} system_component;

typedef struct {
    int value;
} record;

system_component* manage_memory_allocation(int max_offset, int key_count, int max_record_size) {
    // Calculate power of two size for offsets array
    int offset_size = (int)pow(2, ceil(log2(max_offset)));

    // Allocate memory for offsets array
    long *offsets = (long*)malloc(offset_size * sizeof(long));
    if (!offsets) return NULL;

    // Calculate prime number for keys array
    int key_prime = 97;
    while (!is_prime(key_prime)) {
        key_prime++;
    }

    // Allocate memory for keys array
    int *keys = (int*)malloc(key_prime * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Calculate total size of records in bytes
    int record_size = max_record_size + sizeof(record);

    // Allocate memory for records array
    record *records = (record*)malloc(1024 * sizeof(record));  // Assume <= 4KB constraint
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize offsets and keys with some values
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = i * 2;
    }
    for (int i = 0; i < key_prime; i++) {
        keys[i] = i % 10;
    }

    // Populate records array with random integers
    srand(time(NULL));
    for (int i = 0; i < 1024; i++) {
        record temp = {rand() % 100};
        if (i > 0 && temp.value == records[i - 1].value) {
            temp.value = rand() % 100;
        }
        records[i] = temp;
    }

    // Validate sum of offsets
    long total_offset_sum = 0;
    for (int i = 0; i < offset_size; i++) {
        total_offset_sum += offsets[i];
    }
    if (total_offset_sum > 1048576) {  // 1MB limit
        printf("Offset sum exceeds limit.\n");
        return NULL;
    }

    system_component* component = (system_component*)malloc(sizeof(system_component));
    if (!component) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }
    component->keys = keys;
    component->offsets = offsets;
    component->records = records;

    // Calculate total allocated size
    int total_allocated_size = offset_size * sizeof(long) + key_prime * sizeof(int) + 1024 * record_size;
    component->total_allocated_size = total_allocated_size;

    return component;
}

void deallocate(system_component* component) {
    free(component->keys);
    free(component->offsets);
    free(component->records);
    free(component);

    // Handle edge cases and potential memory leaks
}
