Record* create_record(int num_records, int* keys, long* offsets) {
    if (!num_records || !keys || !offsets) return NULL;

    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) return NULL;

    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
        records[i].value = 0;
        records[i].update = NULL;
        srand(time(NULL));
        records[i].value = rand() % 100 + 1; // Fill int field with random value
    }

    return records;
}

void free_records(Record* records, int num_records) {
    if (!records || !num_records) return;

    for (int i = 0; i < num_records; i++) {
        // Release allocated memory
        free(records[i].log_buffer);
    }

    free(records);
}
