#include <iostream>
#include <vector>
#include <algorithm>
#include <map>

struct Item {
    std::string type;
    std::string rarity;
    int usageCount;
    long cooldownTimestamp;

    // Constructor
    Item(std::string t, std::string r) : type(t), rarity(r), usageCount(0), cooldownTimestamp(-1) {}
};

void manageInventory(const std::vector<Item>& inventory) {
    // Track total uses for each item type
    std::map<std::string, int> totalUses;

    // Cycle through items by type, then rarity, and finally usage count
    for (const auto& item : inventory) {
        while (true) {
            if (item.cooldownTimestamp <= 0 || (item.rarity == "Legendary" && item.cooldownTimestamp + 15 < std::time(nullptr))) {
                // Print the selected item's details to the console
                std::cout << "Selected: " << item.type << " (" << item.rarity << ") with usage count " << item.usageCount << std::endl;

                // Update total uses for this item type, if applicable
                if (totalUses.find(item.type) == totalUses.end()) {
                    totalUses[item.type] = 0;
                }
                totalUses[item.type]++;

                // Reset cooldown timestamps
                item.cooldownTimestamp = -1;
                break;
            } else {
                // Skip to the next available item
                for (auto& otherItem : inventory) {
                    if (otherItem.rarity != "Legendary" || otherItem.cooldownTimestamp + 15 < std::time(nullptr)) {
                        std::swap(item, otherItem);
                        break;
                    }
                }

                // If no suitable item found, skip to the next iteration
                if (item.type == otherItem.type) continue;

                // Reset cooldown timestamps for all Legendary items
                for (auto& legendItem : inventory) {
                    if (legendItem.rarity == "Legendary" && legendItem.cooldownTimestamp > 0) legendItem.cooldownTimestamp = -1;
                }
            }
        }
    }

    // Serialize the current state of the inventory for persistence across game sessions
    std::cout << "Serialized inventory: ";
    for (const auto& item : inventory) {
        std::cout << item.type << "-" << item.rarity << ":" << item.usageCount << "," << item.cooldownTimestamp << " ";
    }
    std::cout << std::endl;
}

int main() {
    // Example inventory
    std::vector<Item> inventory = {
        {"Sword", "Common", 0, -1},
        {"Shield", "Uncommon", 1, -2},
        {"Potion", "Rare", 3, -10},
        {"Legendary Sword", "Legendary", 5, std::time(nullptr) - 30000},
    };

    manageInventory(inventory);

    return 0;
}

