#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PRODUCTS 1000
#define CACHE_SIZE 100
#define BUFFER_SIZE 1024

typedef struct product {
    int id;
    char* name;
    float price;
} Product;

Product products[MAX_PRODUCTS];
int product_count = 0;
int cache_size = 0;
char* cache_names[CACHE_SIZE];
float cache_prices[CACHE_SIZE];

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void add_product(int id, char* name, float price) {
    pthread_mutex_lock(&mutex);
    if (product_count >= MAX_PRODUCTS) {
        printf("Product list is full. Cannot add more products.\n");
    } else {
        products[product_count].id = id;
        products[product_count].name = name;
        products[product_count].price = price;
        product_count++;
    }
    pthread_mutex_unlock(&mutex);
}

void update_product(int id, char* name, float price) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < product_count; i++) {
        if (products[i].id == id) {
            products[i].name = name;
            products[i].price = price;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void remove_product(int id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < product_count; i++) {
        if (products[i].id == id) {
            memmove(&products[i], &products[i + 1], (product_count - i - 1) * sizeof(Product));
            product_count--;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

Product* find_product_by_name(char* name) {
    for (int i = 0; i < product_count; i++) {
        if (!strcmp(products[i].name, name)) {
            return &products[i];
        }
    }
    return NULL;
}

void search_products_by_name(char* query) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < product_count; i++) {
        if (!strstr(products[i].name, query)) continue;
        printf("Product ID: %d, Name: %s, Price: %.2f\n", products[i].id, products[i].name, products[i].price);
    }
    pthread_mutex_unlock(&mutex);
}

void* cache_manager(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < product_count; i++) {
            if (cache_size < CACHE_SIZE && !strcmp(products[i].name, cache_names[cache_size])) {
                strcpy(cache_names[cache_size], products[i].name);
                cache_prices[cache_size] = products[i].price;
                cache_size++;
            }
        }
        pthread_mutex_unlock(&mutex);
        usleep(100000); // Simulate network delay
    }
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, &cache_manager, NULL);

    // Example usage
    add_product(1, "Product A", 9.99f);
    add_product(2, "Product B", 19.99f);
    add_product(3, "Product C", 29.99f);

    update_product(1, "New Product A", 12.99f);

    remove_product(2);

    printf("Searching for products containing 'A':\n");
    search_products_by_name("A");

    pthread_join(thread, NULL);
    return 0;
}
