#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <json-c/json.h>

typedef enum {
    PENDING,
    IN_PROGRESS,
    COMPLETED
} TaskStatus;

typedef struct {
    int priority;
    time_t deadline;
    TaskStatus status;
} Task;

Task* tasks = NULL;
int taskCount = 0;
int capacity = 10;

// Function to resize the task array
void resizeTasks() {
    if (taskCount >= capacity) {
        capacity *= 2;
        Task* temp = realloc(tasks, sizeof(Task) * capacity);
        if (!temp) {
            printf("Memory allocation failed!\n");
            exit(1);
        }
        tasks = temp;
    }
}

// Function to add a task from JSON file
void addTaskFromJSON(json_object* json_task) {
    Task* new_task = (Task*)malloc(sizeof(Task));
    if (!new_task) {
        printf("Memory allocation failed!\n");
        exit(1);
    }

    // Parse JSON fields and assign values to the task struct
    new_task->priority = json_object_get_int(json_task, "priority");
    new_task->deadline = json_object_get_int64(json_task, "deadline");
    new_task->status = (TaskStatus)json_object_get_int(json_task, "status");

    // Insert the task into the array and increment count
    resizeTasks();
    tasks[taskCount] = *new_task;
    taskCount++;
}

// Function to read tasks from multiple JSON files
void readTasksFromJSONFiles(char** fileNames, int numFiles) {
    for (int i = 0; i < numFiles; i++) {
        json_object* json_file = json_load_file(fileNames[i], NULL);
        if (!json_file) {
            printf("Failed to load JSON file '%s'!\n", fileNames[i]);
            exit(1);
        }

        json_object_object_foreach(json_file, key, val) {
            if (strcmp(key, "tasks") == 0) {
                json_object* json_tasks = json_object.GetObject(val);
                for (int j = 0; j < json_object_get_size(json_tasks); j++) {
                    json_object* json_task = json_objectGetObjectItem(json_tasks, j);
                    addTaskFromJSON(json_task);
                }
            }
        }

        json_object_put(json_file);
    }
}

// Function to print task details
void printTasks() {
    for (int i = 0; i < taskCount; i++) {
        printf("Priority: %d, Deadline: %ld, Status: %s\n", tasks[i].priority,
               (long int)tasks[i].deadline, (i == PENDING ? "PENDING" :
              i == IN_PROGRESS ? "IN PROGRESS" : "COMPLETED"));
    }
}

int main() {
    // Read tasks from multiple JSON files
    readTasksFromJSONFiles(fileNames, numFiles);

    // Print task details
    printTasks();

    return 0;
}
