typedef struct {
    long* offsets;
    int* keys;
    struct record* records;
} SystemComponent;

typedef struct {
    int value;
} record;

SystemComponent* manageMemory(size_t offsetSize, size_t keyCount, size_t recordCapacity) {
    SystemComponent* component = (SystemComponent*)malloc(sizeof(SystemComponent));

    // Allocate memory for offsets array
    long powerOfTwo = 1 << (offsetSize > 0 && offsetSize < 17 ? offsetSize : 16);
    if (powerOfTwo > 65536) { // Ensure size is not greater than 64KB
        return NULL;
    }
    component->offsets = (long*)malloc(powerOfTwo * sizeof(long));

    // Allocate memory for keys array
    int primeKeyCount = 53; // A small prime number less than 100
    if (keyCount < primeKeyCount) {
        component->keys = (int*)malloc(primeKeyCount * sizeof(int));
    } else {
        return NULL;
    }

    // Allocate memory for records array
    record* records = (record*)malloc(recordCapacity * sizeof(record));

    // Populate the 'records' array with random integers within a given range, ensuring no two consecutive records have the same value
    srand(time(NULL));
    for (size_t i = 0; i < recordCapacity; i++) {
        record temp;
        do {
            temp.value = rand() % 100;
        } while (i > 0 && temp.value == records[i - 1].value);
        records[i] = temp;
    }

    // Validate that the sum of all offsets does not exceed a specified limit
    size_t totalOffsetSize = sizeof(long) * powerOfTwo;
    if (totalOffsetSize + sizeof(int) * primeKeyCount + recordCapacity * sizeof(record) > 1048576) { // Check against 1MB limit
        return NULL;
    }

    component->offsets = component->keys = &records[0];
    component->records = records;

    return component;
}

void deallocate(SystemComponent* component) {
    if (component == NULL)
        return;

    free(component->offsets);
    free(component->keys);
    free(component->records);

    free(component);
}
