#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Define a structure to represent a polygon
typedef struct {
    int numVertices;
    double** coordinates;
} Polygon;

// Function to create and initialize a polygon with vertices within a bounding box
Polygon* createPolygon(int width, int height) {
    Polygon* poly = (Polygon*)malloc(sizeof(Polygon));

    // Generate random number of vertices for the polygon
    poly->numVertices = rand() % 3 + 3; // Ensure at least 3 vertices

    // Allocate memory for polygon coordinates
    poly->coordinates = (double**)malloc(poly->numVertices * sizeof(double*));
    for(int i = 0; i < poly->numVertices; i++) {
        poly->coordinates[i] = (double*)malloc(2 * sizeof(double)); // x and y coordinates
    }

    // Generate random vertex coordinates within the bounding box
    for(int i = 0; i < poly->numVertices; i++) {
        poly->coordinates[i][0] = rand() % width;
        poly->coordinates[i][1] = rand() % height;
    }

    return poly;
}

// Function to check if a polygon is convex
int isConvex(Polygon* poly) {
    int numVertices = poly->numVertices;
    double x1, y1, x2, y2; // Previous and current vertices

    for(int i = 0; i < numVertices - 2; i++) {
        x1 = poly->coordinates[i][0];
        y1 = poly->coordinates[i][1];
        x2 = poly->coordinates[i+1][0];
        y2 = poly->coordinates[i+1][1];

        // Check if the polygon is not convex
        if((x1 * (y2 - y1) + x2 * (y1 - y2) > 0.0)) {
            return 0; // Not convex
        }
    }

    return 1; // Convex
}

// Function to dynamically resize the polygon array
void resizePolygon(Polygon* poly, int newSize) {
    if(newSize <= poly->numVertices) {
        for(int i = poly->numVertices; i < newSize; i++) {
            free(poly->coordinates[i]);
        }
    } else if(newSize > poly->numVertices) {
        double** tempCoords = (double**)malloc((newSize - 1) * sizeof(double*));
        int j = 0;
        for(int i = poly->numVertices; i < newSize; i++) {
            tempCoords[j] = (double*)malloc(2 * sizeof(double)); // x and y coordinates
            j++;
        }

        // Copy existing vertices to the new array
        for(int i = 0; i < poly->numVertices; i++) {
            tempCoords[i][0] = poly->coordinates[i][0];
            tempCoords[i][1] = poly->coordinates[i][1];
        }

        // Free old vertex coordinates and update polygon information
        for(int i = 0; i < poly->numVertices; i++) {
            free(poly->coordinates[i]);
        }
        free(poly->coordinates);
        poly->numVertices = newSize;
        poly->coordinates = tempCoords;
    }
}

int main() {
    // Example usage:
    Polygon* poly = createPolygon(100, 100);
    printf("Polygon vertices: %d\n", poly->numVertices);

    for(int i = 0; i < poly->numVertices; i++) {
        printf("(%f, %f)\n", poly->coordinates[i][0], poly->coordinates[i][1]);
    }

    int convexity = isConvex(poly);
    if(convexity) {
        printf("Polygon is convex.\n");
    } else {
        printf("Polygon is not convex.\n");
    }

    resizePolygon(poly, 5); // Resize polygon to 5 vertices

    return 0;
}
