typedef struct {
    int id;
    char name[256];
    int quantity;
    float price;
} Product;

typedef struct {
    Product* products;
    size_t capacity;
    size_t size;
} ProductsCollection;

ProductsCollection* products_collection_create(size_t initial_capacity) {
    ProductsCollection* collection = malloc(sizeof(ProductsCollection));
    if (!collection) return NULL;
    collection->products = malloc(initial_capacity * sizeof(Product));
    if (!collection->products) {
        free(collection);
        return NULL;
    }
    collection->capacity = initial_capacity;
    collection->size = 0;
    return collection;
}

void products_collection_destroy(ProductsCollection* collection) {
    if (collection) {
        free(collection->products);
        free(collection);
    }
}

int products_collection_add_product(ProductsCollection* collection, Product product) {
    if (!collection) return -1;
    if (collection->size >= collection->capacity) {
        // Double the capacity
        collection->products = realloc(collection->products, 2 * collection->capacity * sizeof(Product));
        if (!collection->products) return -1;
        collection->capacity *= 2;
    }
    strcpy(collection->products[collection->size].name, product.name);
    collection->products[collection->size++] = product;
    return 0;
}

int products_collection_update_product(ProductsCollection* collection, int id, Product new_product) {
    // Find the product to update
    for (size_t i = 0; i < collection->size; i++) {
        if (collection->products[i].id == id) {
            // Update the product attributes
            strcpy(collection->products[i].name, new_product.name);
            collection->products[i].quantity = new_product.quantity;
            collection->products[i].price = new_product.price;
            return 0;
        }
    }
    return -1; // Product not found
}

int products_collection_remove_product(ProductsCollection* collection, int id) {
    for (size_t i = 0; i < collection->size; i++) {
        if (collection->products[i].id == id) {
            // Shift the remaining products down
            memmove(&collection->products[i], &collection->products[i + 1], (collection->size - i - 1) * sizeof(Product));
            collection->size--;
            return 0;
        }
    }
    return -1; // Product not found
}

Product* products_collection_get_product_by_name(ProductsCollection* collection, const char* name) {
    for (size_t i = 0; i < collection->size; i++) {
        if (!strcasecmp(collection->products[i].name, name)) {
            return &collection->products[i];
        }
    }
    return NULL;
}

int main() {
    ProductsCollection* collection = products_collection_create(10);
    // Add, update, and remove products
    Product product1 = {"P001", "Apple iPhone", 5, 799.99};
    Product product2 = {"P002", "Samsung Galaxy", 3, 699.99};
    product_collection_add_product(collection, product1);
    product_collection_update_product(collection, product1.id, product2);
    product_collection_remove_product(collection, product1.id);

    // Retrieve products by name
    Product* product = product_collection_get_product_by_name(collection, "SAMSUNG GALAXY");
    if (product) {
        printf("Product found: %s\n", product->name);
    } else {
        printf("Product not found.\n");
    }

    products_collection_destroy(collection);
    return 0;
}
