// Function to derive AES-256-CBC key from password using SHA-256 hash
int derive_aes_key(const char* password, unsigned char** aes_key, size_t* aes_key_len) {
    // Initialize random salt for key derivation
    unsigned char salt[16];
    RAND_bytes(salt, 16);

    // Derive key using PBKDF2-HMAC-SHA256 with 100000 iterations
    unsigned char derived_key[32];
    int err = PKCS5_PBKDF2(password, strlen(password), salt, 16, 100000, 32, derived_key);
    if (err) {
        printf("Error deriving key: %s\n", strerror(err));
        return -1;
    }

    *aes_key = malloc(32);
    memcpy(*aes_key, derived_key, 32);
    *aes_key_len = 32;

    return 0;
}

// Function to generate initialization vector (IV) for AES-256-CBC encryption
int gen_iv(unsigned char** iv, size_t* iv_len) {
    // Initialize random IV with 16 bytes length
    RAND_bytes(*iv, 16);
    *iv_len = 16;

    return 0;
}

// Function to initialize AES-256-CBC cipher for graph database operations
int init_aes_crypt(const char* password, unsigned char** aes_key, size_t* aes_key_len, unsigned char** iv, size_t* iv_len) {
    // Derive AES key from password using SHA-256 hash
    int err = derive_aes_key(password, &aes_key, &aes_key_len);
    if (err) {
        return err;
    }

    // Generate initialization vector for each encryption operation
    err = gen_iv(&iv, &iv_len);
    if (err) {
        return err;
    }

    // Initialize AES-256-CBC cipher context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, *aes_key, *iv);

