#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure to represent products
typedef struct {
    int id;
    char name[256];
    float price;
} Product;

// Define a structure to represent the product catalog
typedef struct {
    Product* products;
    int size;
    pthread_mutex_t lock;
} Catalog;

// Initialize and return a new, empty catalog
Catalog* create_catalog() {
    Catalog* cat = (Catalog*)malloc(sizeof(Catalog));
    cat->products = NULL;
    cat->size = 0;
    pthread_mutex_init(&cat->lock, NULL);
    return cat;
}

// Add a product to the catalog and update the size
void add_product(Catalog* cat, Product* new_product) {
    pthread_mutex_lock(&cat->lock);
    // Allocate memory for the new product
    cat->products = (Product*)realloc(cat->products, (cat->size + 1) * sizeof(Product));
    cat->products[cat->size] = *new_product;
    cat->size++;
    pthread_mutex_unlock(&cat->lock);
}

// Remove a product from the catalog and update the size
void remove_product(Catalog* cat, int id) {
    pthread_mutex_lock(&cat->lock);
    for (int i = 0; i < cat->size; i++) {
        if (cat->products[i].id == id) {
            // Shift all products after this one down to fill the gap
            memmove(&cat->products[i], &cat->products[i + 1], (cat->size - i - 1) * sizeof(Product));
            cat->size--;
            break;
        }
    }
    pthread_mutex_unlock(&cat->lock);
}

// Update a product's information in the catalog
void update_product(Catalog* cat, int id, Product* new_product) {
    pthread_mutex_lock(&cat->lock);
    for (int i = 0; i < cat->size; i++) {
        if (cat->products[i].id == id) {
            // Update the product's information
            *new_product = cat->products[i];
            break;
        }
    }
    pthread_mutex_unlock(&cat->lock);
}

// Search for products in the catalog by name and return a pointer to the matching products
Product* search_products(Catalog* cat, char* query) {
    Product* results = NULL;
    pthread_mutex_lock(&cat->lock);
    for (int i = 0; i < cat->size; i++) {
        if (strstr(cat->products[i].name, query)) {
            // Add the matching product to the results
            results = (Product*)realloc(results, (results ? results->size + 1 : 1) * sizeof(Product));
            results[results->size++] = cat->products[i];
        }
    }
    pthread_mutex_unlock(&cat->lock);
    return results;
}

// List products within a specified price range
void list_products(Catalog* cat, float min_price, float max_price) {
    pthread_mutex_lock(&cat->lock);
    for (int i = 0; i < cat->size; i++) {
        if (cat->products[i].price >= min_price && cat->products[i].price <= max_price) {
            // Print the matching product's information
            printf("Product %d: %s - $%.2f\n", cat->products[i].id, cat->products[i].name, cat->products[i].price);
        }
    }
    pthread_mutex_unlock(&cat->lock);
}

// Define a caching mechanism to optimize frequent product lookups
void cache_products(Catalog* cat) {
    // Initialize the cache
    int cache_size = 10;
    Product* cache[cache_size];
    int cache_hit_count = 0;

    while (1) {
        // Perform periodic cache eviction
        if (cache_hit_count > 5 && !is_cache_full()) {
            // Evict outdated or infrequently accessed products from the cache
            for (int i = 0; i < cache_size - 1; i++) {
                cache[i] = cache[i + 1];
            }
            cache[cache_size - 1] = NULL;
        }

        // Handle user queries and manage the cache
        int query_id;
        char* query_name;
        while (1) {
            // Check for cache hits
            if (!is_cache_empty()) {
                // Retrieve the requested product from the cache
                Product* cached_product = get_cached_product(query_id, query_name);
                if (cached_product != NULL) {
                    // Return the cached product and update the hit count
                    printf("Product found in cache: %s - $%.2f\n", cached_product->name, cached_product->price);
                    cache_hit_count++;
                    break;
                }
            }

            // Handle cache misses
            Product* requested_product = get_requesting_product();
            if (requested_product != NULL) {
                // Add the product to the cache and update the hit count
                cache[cache_size - 1] = requested_product;
                cache_hit_count++;
            } else {
                // Handle edge cases like cache hits and misses efficiently under varying loads
