#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/sem.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>

// Function to initialize and manage a semaphore with a specified initial value
int init_semaphore(int initial_value) {
    key_t key = ftok("semaphore", 0);
    int sem_id = semget(key, 1, IPC_CREAT | IPC_EXCL | S_IRUSR | S_IWUSR);

    if (sem_id < 0) {
        perror("semget");
        return -1;
    }

    struct sembuf op[1] = {0};

    // Initialize the semaphore with the specified initial value
    op[0].sem_num = 0;
    op[0].sem_op = initial_value;
    op[0].sem_flg = SEM_UNDO;

    if (semop(sem_id, op, 1) < 0) {
        perror("semop");
        return -1;
    }

    return sem_id;
}

// Function to perform DNS resolution for a given hostname and return the corresponding IP address
u_char* resolve_dns(const char* hostname) {
    struct hostent* host = gethostbyname(hostname);

    if (host == NULL) {
        perror("gethostbyname");
        return NULL;
    }

    char* ip_address = inet_ntoa(*((struct in_addr*)host->h_addr));
    int len = strlen(ip_address);
    u_char* result = malloc(len + 1);
    strcpy((char*)result, ip_address);

    return result;
}

// Function to release the semaphore
void release_semaphore(int sem_id) {
    struct sembuf op[1] = {0};

    op[0].sem_num = 0;
    op[0].sem_op = 1;
    op[0].sem_flg = SEM_UNDO;

    if (semop(sem_id, op, 1) < 0) {
        perror("semop");
    }
}

// Function to destroy the semaphore
void destroy_semaphore(int sem_id) {
    if (semctl(sem_id, 0, IPC_RMID) < 0) {
        perror("semctl");
    }
}

int main() {
    int sem_id = init_semaphore(1);
    u_char* ip_address = resolve_dns("example.com");
    release_semaphore(sem_id);
    destroy_semaphore(sem_id);

    return 0;
}
