#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define BUFFER_SIZE 1024
#define RECORD_LENGTH 256
#define AVERAGE_WINDOW 3
#define LOG_FILE "processing.log"
#define CONFIG_FILE "config.txt"

typedef struct {
    char data[RECORD_LENGTH];
    double avg;
} Record;

Record* read_record(int fd) {
    Record* record = (Record*)malloc(sizeof(Record));
    read(fd, record->data, RECORD_LENGTH);
    return record;
}

void process_record(Record* record) {
    int fields[AVERAGE_WINDOW];
    char* token = strtok(record->data, ",");
    for (int i = 0; i < AVERAGE_WINDOW; i++) {
        if (!token) break;
        fields[i] = atof(token);
        token = strtok(NULL, ",");
    }
    double avg = 0.0;
    for (int i = 0; i < AVERAGE_WINDOW; i++) {
        avg += fields[i];
    }
    avg /= AVERAGE_WINDOW;
    record->avg = avg;
}

void write_record(int fd, Record* record) {
    write(fd, record->data, strlen(record->data));
    char buffer[32];
    sprintf(buffer, ",%.2f\n", record->avg);
    write(fd, buffer, strlen(buffer));
}

int main(int argc, char** argv) {
    int input_fd = open(argv[1], O_RDONLY);
    if (input_fd < 0) {
        perror("Opening input file");
        return 1;
    }

    int output_fd = open(argv[2], O_WRONLY | O_CREAT, 0644);
    if (output_fd < 0) {
        perror("Opening output file");
        close(input_fd);
        return 1;
    }

    Record* record = read_record(input_fd);
    while (record->data[AVERAGE_WINDOW * strlen(",")]) {
        process_record(record);
        write_record(output_fd, record);
        free(record);
        record = read_record(input_fd);
    }
    free(record);

    close(input_fd);
    close(output_fd);

    return 0;
}
