#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Semaphore structure
typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int value;
} semaphore_t;

// DNS cache structure
typedef struct {
    char* domain;
    char* ip;
    time_t expires;
} dns_cache_entry_t;

// DNS cache structure
typedef struct {
    size_t capacity;
    size_t size;
    dns_cache_entry_t** entries;
} dns_cache_t;

// Semaphore functions
semaphore_t* semaphore_create(int initial_value) {
    semaphore_t* sem = (semaphore_t*)malloc(sizeof(semaphore_t));
    sem->value = initial_value;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);
    return sem;
}

void semaphore_wait(semaphore_t* sem) {
    pthread_mutex_lock(&sem->mutex);
    while (sem->value == 0) {
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    --sem->value;
    pthread_mutex_unlock(&sem->mutex);
}

int semaphore_signal(semaphore_t* sem) {
    pthread_mutex_lock(&sem->mutex);
    ++sem->value;
    pthread_cond_broadcast(&sem->cond);
    pthread_mutex_unlock(&sem->mutex);
    return sem->value;
}

// DNS cache functions
dns_cache_t* dns_cache_create(size_t capacity) {
    dns_cache_t* cache = (dns_cache_t*)malloc(sizeof(dns_cache_t));
    cache->capacity = capacity;
