TransactionRecord* filter_transactions(int num_records, int max_key, int min_key, float threshold) {
    TransactionRecord* records = (TransactionRecord*)malloc(num_records * sizeof(TransactionRecord));
    if (!records) return NULL; // Handle memory allocation failure

    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        if (records[i].key > max_key) {
            strcpy(records[i].status, "Invalid key");
        } else if (records[i].key % 2 == 0) {
            strcpy(records[i].status, "Even key");
        } else {
            strcpy(records[i].status, "Odd key");
        }
    }

    int max_weighted_sum = 0;
    int max_weighted_sum_id = -1;

    for (int i = 0; i < num_records; i++) {
        float weighted_sum = records[i].key * threshold;
        if (weighted_sum > max_weighted_sum) {
            max_weighted_sum = weighted_sum;
            max_weighted_sum_id = i;
        }
    }

    free(records);

    // DNS resolution and IP address lookup
    char hostname[] = "example.com";
    struct in_addr ipaddr;
    int err = gethostbyname(hostname, &ipaddr);
    if (err) {
        return -1; // Handle error
    }

    u_char ip[4];
    inet_ntop(AF_INET, &ipaddr, ip, sizeof(ip));

    // Limit process capabilities
    setrlimit(RLIMIT_NOFILE, (struct rlimit*)NULL);

    return max_weighted_sum_id;
}
