    if (ptr != NULL) {
        free(ptr);
    }
}

// Dynamic list management functions
Item** create_list(int initial_size) {
    Item** list = (Item**)my_malloc(initial_size * sizeof(Item*));
    return list;
}

void add_item(Item** list, int size, char* name, int priority) {
    // Dynamically allocate memory for the new item
    Item* item = (Item*)my_malloc(sizeof(Item));
    if (!item) {
        printf("Out-of-memory condition occurred. Cannot add item.\n");
        return;
    }
    item->name = my_strdup(name);
    item->priority = priority;
    // Update the list with the new item
    Item** temp_list = (Item**)my_realloc(list, (size + 1) * sizeof(Item*));
    if (!temp_list) {
        printf("Out-of-memory condition occurred. Cannot update list.\n");
        return;
    }
    temp_list[size] = item;
}

void remove_item(Item** list, int size, char* name) {
    // Find the item to be removed
    for (int i = 0; i < size; i++) {
        if (strcmp(list[i]->name, name) == 0) {
            // Dynamically deallocate the item's memory
            my_free(list[i]->name);
            my_free(list[i]);
            // Shift elements to fill the removed gap and resize the list
            for (int j = i; j < size - 1; j++) {
                list[j] = list[j + 1];
            }
            return;
        }
    }
}

Item* find_item(Item** list, int size, char* name) {
    // Search for an item by its name
    for (int i = 0; i < size; i++) {
        if (strcmp(list[i]->name, name) == 0) {
            return list[i];
        }
    }
    return NULL;
}

void update_priority(Item** list, int size, char* name, int new_priority) {
    // Find and update the item's priority
    Item* item = find_item(list, size, name);
