        if key not in self.cache:
            return None
        return self.cache.pop(key)

    def set(self, key, value):
        with self.lock:
            if key in self.cache:
                del self.cache[key]
            self.cache[key] = value

    def refresh_cache(self):
        while True:
            try:
                response = requests.get(self.api_url, headers={'X-API-KEY': self.api_key})
                if response.status_code == 200:
                    config_data = response.json()
                    for key, value in config_data.items():
                        self.set(key, value)
                    break
            except Exception as e:
                print(f"Error refreshing cache: {e}")
            time.sleep(self.refresh_interval)

    def invalidate_cache(self):
        with self.lock:
            self.cache.clear()

    def evict(self):
        if len(self.cache) > 1000:  # Set the eviction threshold here
            while True:
                oldest_key = next(iter(self.cache))
                del self.cache[oldest_key]
                if len(self.cache) <= 500:  # Adjust the cache size as needed
                    break

    def update_shared_library(self, new_version):
        with self.lock:
            for key in list(self.cache.keys()):
                if not self.validate(key, new_version):  # Implement validation logic here
                    del self.cache[key]

    def async_get(self, key):
        return asyncio.create_task(self.get_async(key))

    async def get_async(self, key):
        try:
            with await self.lock.acquire():
                if key in self.cache:
                    return self.cache.pop(key)
        except Exception as e:
            print(f"Error fetching {key}: {e}")
        return None

    def parallel_get(self, keys):
        tasks = [self.async_get(key) for key in keys]
        results = await asyncio.gather(*tasks)
        return {k: v for k, v in zip(keys, results)}

    def api_request(self, url, params={}):
        try:
            response = requests.get(url, params=params, headers={'X-API-KEY': self.api_key})
            if response.status_code == 200:
                return response.json()
        except Exception as e:
            print(f"Error fetching {url}: {e}")
        return None

    def update_api_config(self):
        config_data = self.api_request(self.api_url)
        if config_data:
            for key, value in config_data.items():
                self.set(key, value)

# Example usage
cache_manager = CacheManager()
cache_manager.refresh_cache()

# Accessing cache values
config_value1 = cache_manager.get('key1')
config_value2 = cache_manager.set('key2', 'value')

# Invalidating cache
cache_manager.invalidate_cache()

# Evicting cache entries
cache_manager.evict()

# Updating shared library
cache_manager.update_shared_library('new_version')

# Asynchronous fetching
async_result = await cache_manager.async_get('key3')
print(async_result)

# Parallel fetching
keys = ['key1', 'key2', 'key3']
results = cache_manager.parallel_get(keys)
print(results)

