        } catch (Exception e) {
            // Handle API errors and network failures
            if (e instanceof IOException || e instanceof JsonProcessingException) {
                return "Error: Unable to fetch character data";
            }
            // Handle unexpected responses from API
            return "Error: Unexpected response from API";
        }
