void mergeData(vector<char>& buffer, vector<vector<char>>& dataChunks) {
    int offset = 0;
    for (auto& chunk : dataChunks) {
        // Checksum verification
        if (checksum(chunk.data(), chunk.size()) != checksum(buffer.data() + offset, chunk.size())) {
            cout << "Data integrity failed!" << endl;
            return;
        }
        // Copy and merge the chunk
        std::memcpy(buffer.data() + offset, chunk.data(), chunk.size());
        offset += chunk.size();
    }
