import java.io.*;
import java.util.*;

public class Main {
    public static void processArrayAndFile(int[] arr, String filename) {
        long start = System.nanoTime();

        // Initialize Union-Find data structure
        UnionFind uf = new UnionFind(arr.length);

        for (int i : arr) {
            uf.union(i, i); // Each element is its own set initially
        }

        int disjointPairsCount = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            if (!uf.isConnected(arr[i], arr[i + 1])) {
                disjointPairsCount++;
            }
        }

        long end = System.nanoTime();

        // Fetch metadata from external API
        try {
            Map<String, String> metadata = fetchMetadata(filename);
            filename += "." + getExtension(disjointPairsCount) + "/" + metadata.get("FileSize") + " bytes";
        } catch (IOException e) {
            filename += ".txt"; // Default to .txt if API fails
        }

        System.out.println((end - start) / 1e6 + " milliseconds");
    }

    private static class UnionFind {
        int[] parent;
        int[] size;

        public UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX != rootY) {
                if (size[rootX] < size[rootY]) {
                    parent[rootX] = rootY;
                } else {
                    parent[rootY] = rootX;
                }
            }
        }

        public boolean isConnected(int x, int y) {
            return find(x) == find(y);
        }

        private int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }
    }

    private static String getExtension(int disjointPairsCount) {
        if (disjointPairsCount % 2 == 0) return "txt";
        for (int i = 2; ; i++) {
            if (Math.sqrt(i) == (int) Math.sqrt(i)) {
                return "xml";
            }
            if (isPrime(i)) {
                return "csv";
            }
        }
    }

    private static boolean isPrime(int n) {
        if (n <= 1) return false;
        for (int i = 2, sqrt = (int) Math.sqrt(n); i <= sqrt; i++) {
            if (n % i == 0) return false;
        }
        return true;
    }

    private static Map<String, String> fetchMetadata(String filename) throws IOException {
        // Call external API to fetch metadata
        // For demonstration purposes, assume a successful call with metadata:
        Map<String, String> metadata = new HashMap<>();
        metadata.put("FileSize", "1024");
        return metadata;
    }
}
