```java
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;

import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NamedNodeMap;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

public class XmlTraverser {
    public List<Node> traverseXml(String xmlString, Predicate<Node> predicate) throws IOException, ParserConfigurationException {
        try (InputStream is = new ByteArrayInputStream(xmlString.getBytes())) {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document document = builder.parse(is);

            NodeList nodeList = document.getDocumentElement().getChildNodes();
            List<Node> result = new ArrayList<>();

            for (int i = 0; i < nodeList.getLength(); i++) {
                Node node = nodeList.item(i);
                if (predicate.test(node)) {
                    result.add(node);
                }
                else if (node instanceof Element) {
                    NodeList childNodes = ((Element) node).getChildNodes();
                    for (int j = 0; j < childNodes.getLength(); j++) {
                        Node childNode = childNodes.item(j);
                        if (predicate.test(childNode)) {
                            result.add(childNode);
                        }
                    }
                }
            }

            return result;
        }
    }
}
