use {
    tonic::{transport::Channel, RequestBuilder},
    tracing::{span_from_ctx, Spanned},
};
use futures_util::future;

async fn instrumented_grpc_client(
    channel: &mut Channel,
    tracing_span: &Spanned<tonic::service::Service>,
) -> Result<(), tonic::transport::Error> {
    // Implement retry logic using a custom policy
    let retry_policy = |f| async move {
        match f.await {
            Ok(_) => Ok(()),
            Err(e) if e.is_transient() => {
                tracing_span.info!("Transient failure, will retry");
                future::sleep(std::time::Duration::from_millis(100)).await;
                retry_policy(f).await
            }
            _ => Err(e),
        }
    };

    loop {
        let mut req = RequestBuilder::new(channel.clone()).set_timeout(std::time::Duration::from_secs(10));
        // Set tracing span context on the request
        if let Some(span) = span_from_ctx(&tracing_span) {
            req.set_extension("otel.context", &span.tracing_context());
        }
        let mut resp = channel unary(req).await?;
        match retry_policy(unary(resp)).await {
            Ok(_) => return Ok(()),
            Err(e) => {
                tracing_span.error!("Error during gRPC call: {}", e);
                // Disable retries in testing
                if std::env::var("TESTING").is_ok() {
                    tracing_span.info!("Disabling retries due to testing");
                    break;
                }
            }
        }
    }

    Err(tonic::transport::Error::new("gRPC client failed"))
}

async fn unary(req: tonic::Request<tonc::UnaryRequest>) -> Result<tonic::Response, tonic::transport::Error> {
    // Call the gRPC service
    let resp = req.get_ref().call_service();
    // Collect telemetry data (method name, latency, error status)
    let telemetry_data = collect_telemetry_data(req, resp);
    // Send telemetry data to the distributed tracing system
    send_telemetry_data(telemetry_data);

    Ok(resp)
}

fn collect_telemetry_data(req: tonic::Request<tonc::UnaryRequest>, resp: tonic::Response) {
    // Collect method name and latency
    let method_name = req.get_ref().method();
    let latency = chrono::Duration::now() - req.request_start_time();
    // Get error status (if any)
    let error_status = match resp.get_ref().status_code() {
        Some(code) => code,
        None => tonic::StatusCode::OK,
    };
    // Create telemetry data structure
    let telemetry_data = TelemetryData {
        method_name,
        latency,
        error_status,
    };
}

fn send_telemetry_data(telemetry_data: TelemetryData) {
    // Send telemetry data to the distributed tracing system
