        if response.status_code == 200:
            user_data = response.json()
            return User(user_data["username"], user_data["email"], user_data["profile_picture_url"])
        else:
            raise ConnectionError("Failed to retrieve user info")
    except Exception as e:
        logging.error(f"Error retrieving user info: {str(e)}")
        return None

class UserManager:
    def __init__(self):
        self.lock = Lock()
        self.user_cache = {}

    def get_user_info(self, username):
        with self.lock:
            if username in self.user_cache:
                return self.user_cache[username]
            user_data = retrieve_user_info(username)
            if user_data is not None:
                self.user_cache[username] = user_data
            return user_data

def main():
    logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")
    graph_db = GraphDatabase()
    manager = UserManager()

    while True:
        username = input("Enter a username (or 'quit' to exit): ")
        if username.lower() == "quit":
            break
        user_data = manager.get_user_info(username)
        if user_data is not None:
            logging.info(f"Username: {user_data.username}, Email: {user_data.email}, Profile Picture URL: {user_data.profile_picture_url}")
            graph_db.add_vertex({"type": "user", "id": username})
            for edge in ["friend", "follower"]:
                graph_db.add_edge({"type": edge, "from": username, "to": user_data.username})

if __name__ == "__main__":
    main()

```

