            return (a.isLeaf ? 0 : a.id) > (b.isLeaf ? 0 : b.id);
        }
    };

public:
    std::unique_ptr<KDTreeNode> root;

    void insert(int id, const std::vector<double>& features) {
        if (!root) {
            root = std::make_unique<KDTreeNode>();
            root->id = id;
            root->features = features;
            root->isLeaf = true;
        } else {
            KDTreeNode* current = &*root;
            while (true) {
                double pivot = current->features[0];
                if (!current->isLeaf) {
                    if (features[0] < pivot) {
                        if (current->left) {
                            current = &*current->left;
                        } else {
                            current->left = std::make_unique<KDTreeNode>();
                            current->left->id = id;
                            current->left->features = features;
                            current->left->isLeaf = true;
                            break;
                        }
