typedef struct {
    long offset;
    int key;
} BundleItem;

BundleItem* loadResourceBundle(const char* filePath, size_t* numItems) {
    FILE* file = fopen(filePath, "rb");
    if (!file) return NULL; // handle memory allocation failure

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    size_t numBundleItems = (size_t)(fileSize / sizeof(BundleItem));
    BundleItem* bundle = (BundleItem*)malloc(numBundleItems * sizeof(BundleItem));
    if (!bundle) return NULL; // handle memory allocation failure

    fread(bundle, sizeof(BundleItem), numBundleItems, file);
    fclose(file);

    *numItems = numBundleItems;
    return bundle;
}

int main() {
    size_t numItems;
    BundleItem* bundle = loadResourceBundle("path/to/bundle", &numItems);
    if (!bundle) {
        printf("Error loading resource bundle\n");
        return 1;
    }
    printf("Number of items: %zu\n", numItems);

    // Convert keys to the required type
    int* convertedKeys = (int*)malloc(numItems * sizeof(int));
    for (size_t i = 0; i < numItems; i++) {
        convertedKeys[i] = bundle[i].key;
    }
    free(bundle);
    free(convertedKeys);

    return 0;
}
