#include <ifaddrs.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <time.h>

char* resolve_host_to_ip(const char* file_path, int timeout_ms, int retry) {
    // Create a socket
    int sock = socket(AF_INET, SOCK_STREAM, 0);

    if (sock == -1) {
        return "";
    }

    // Set the socket timeout
    struct timeval tv;
    tv.tv_sec = timeout_ms / 1000;
    tv.tv_usec = (timeout_ms % 1000) * 1000;
    setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

    // Resolve the host name to IP address
    struct addrinfo hints, *res;
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = 0;
    int ret = getaddrinfo(file_path, NULL, &hints, &res);

    if (ret != 0) {
        close(sock);
        return "";
    }

    // Extract the IP address
    char* ip_address = inet_ntoa(((struct sockaddr_in*) res->ai_addr)->sin_addr);

    // Close the socket and release resources
    freeaddrinfo(res);
    close(sock);

    return ip_address;
}
