int extractImageInformation(const std::string& imagePath) {
    // Initialize error message
    char errorMessage[1024];

    // Parse TIFF image
    TIFF* tiff = TIFFOpen(imagePath.c_str(), "r");
    if (tiff != NULL) {
        int bitsPerSample;
        uint16_t samplesPerPixel;
        uint16_t extraSamples;

        // Read bits per sample, sample per pixel, and extra samples
        TIFFGetField(tiff, TIFF_FIELD_BITSPERSAMPLE, &bitsPerSample);
        TIFFGetField(tiff, TIFF_FIELD_SAMPLESPERPIXEL, &samplesPerPixel);
        TIFFGetField(tiff, TIFF_FIELD_EXTRASAMPLES, &extraSamples);

        // Print information
        std::cout << "TIFF Image Information:" << std::endl;
        std::cout << "Bits per sample: " << bitsPerSample << std::endl;
        std::cout << "Samples per pixel: " << samplesPerPixel << std::endl;
        std::cout << "Extra samples: " << extraSamples << std::endl;

        // Close TIFF file
        TIFFClose(tiff);
    } else {
        sprintf(errorMessage, "Error opening TIFF file %s", imagePath.c_str());
        std::cerr << errorMessage << std::endl;
    }

    // Parse PNG image
    png_structp pngPtr = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
    if (pngPtr != NULL) {
        png_infop pngInfo = png_create_info_struct(pngPtr);
        if (pngInfo != NULL) {
            FILE* fp = fopen(imagePath.c_str(), "rb");
            if (fp != NULL) {
                // Read PNG image
                png_init_io(pngPtr, fp, NULL);
                png_read_from_file(pngPtr, fp);

                // Get information about the PNG image
                int32_t bitDepth;
                uint16_t colorType;
                uint16_t channels;

                png_get_IHDR(pngPtr, pngInfo, &bitDepth, &colorType, &channels, NULL, NULL, NULL, NULL);
                std::cout << "PNG Image Information:" << std::endl;
                std::cout << "Bit depth: " << bitDepth << std::endl;
                std::cout << "Color type: " << colorType << std::endl;
                std::cout << "Channels: " << channels << std::endl;

                // Close PNG file
                png_destroy_read_struct(&pngPtr, &pngInfo, NULL);
            } else {
                sprintf(errorMessage, "Error opening PNG file %s", imagePath.c_str());
                std::cerr << errorMessage << std::endl;
            }
        } else {
            sprintf(errorMessage, "Error creating PNG info struct");
            std::cerr << errorMessage << std::endl;
        }
    } else {
        sprintf(errorMessage, "Error creating PNG read struct");
        std::cerr << errorMessage << std::endl;
    }

    return 0;
}
