#define MAX_TOKEN_LENGTH 512
#define MAX_EXPIRES_IN 10000
#define TOKEN_TYPE_LENGTH 7
#define JSON_KEY_MAX_LENGTH 20

int validateOAuthTokenResponse(json_object *jobj) {
    if (!jobj || json_object_get_type(jobj) != json_type_object) return 0;

    char *token_type = NULL;
    int expires_in = 0;
    char *access_token = NULL;
    char *refresh_token = NULL;

    if (json_object_object_get_ex(jobj, "access_token", &jobj)) {
        access_token = json_object_get_string(jobj);
        if (!access_token || strlen(access_token) == 0) return 0;
    } else return 0;

    if (json_object_object_get_ex(jobj, "token_type", &jobj)) {
        token_type = json_object_get_string(jobj);
        if (!strncasecmp(token_type, "Bearer", TOKEN_TYPE_LENGTH)) {
            free((void*)token_type);
            token_type = NULL;
        } else return 0;
    } else return 0;

    if (json_object_object_get_ex(jobj, "expires_in", &jobj)) {
        json_object *expires_jobj = jobj;
        expires_in = json_object_get_int(expires_jobj);
        if (expires_in <= 0 || expires_in > MAX_EXPIRES_IN) return 0;
    } else return 0;

    if (json_object_object_get_ex(jobj, "refresh_token", &jobj)) {
        refresh_token = json_object_get_string(jobj);
        if (!refresh_token || strlen(refresh_token) > MAX_TOKEN_LENGTH) return 0;
    }

    free((void*)token_type);
    free((void*)access_token);
    free((void*)refresh_token);

    return 1;
}
