namespace Base64DecoderService
{
    public class Base64DecoderService : IBase64DecoderService
    {
        private readonly ILogger<Base64DecoderService> _logger;
        private readonly IDistributedCache _cache;
        private readonly IEncryptionService _encryptionService;

        public Base64DecoderService(ILogger<Base64DecoderService> logger, IDistributedCache cache, IEncryptionService encryptionService)
        {
            _logger = logger;
            _cache = cache;
            _encryptionService = encryptionService;
        }

        public async Task<string> DecryptAsync(string base64EncodedMessage, string encryptionAlgorithm)
        {
            try
            {
                byte[] encryptedBytes = Convert.FromBase64String(base64EncodedMessage);

                if (string.IsNullOrEmpty(encryptionAlgorithm) || !new[] { "TripleDES", "AES" }.Contains(encryptionAlgorithm))
                {
                    throw new ArgumentException("Invalid encryption algorithm", nameof(encryptionAlgorithm));
                }

                using var encryptor = _encryptionService.GetEncryptor(encryptionAlgorithm);
                byte[] decryptedBytes;

                if (_cache.TryGet(base64EncodedMessage, out decryptedBytes))
                {
                    _logger.LogInformation($"Caching result for {base64EncodedMessage} ({encryptionAlgorithm})");
                }
                else
                {
                    using var ms = new MemoryStream(encryptedBytes);
                    using var cryptoStream = encryptor.CreateDecryptingStream(ms);

                    byte[] buffer = new byte[1024];
                    int read;
                    decryptedBytes = new byte[cryptoStream.Length];

                    while ((read = cryptoStream.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        Array.Copy(buffer, 0, decryptedBytes, cryptoStream.Position, read);
                        cryptoStream.Position += read;
                    }

                    _cache.Set(base64EncodedMessage, decryptedBytes);
                }

                return Encoding.UTF8.GetString(decryptedBytes);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error decrypting {base64EncodedMessage} ({encryptionAlgorithm})");
                throw;
            }
        }
    }

    public class EncryptionService
    {
        private readonly ILogger<EncryptionService> _logger;

        public EncryptionService(ILogger<EncryptionService> logger)
        {
            _logger = logger;
        }

        public ICryptoTransform GetEncryptor(string algorithm)
        {
            switch (algorithm.ToLower())
            {
                case "tripledes":
                    return new TripleDESCryptoServiceProvider();
                case "aes":
                    return new AesCryptoServiceProvider();
                default:
                    throw new ArgumentException("Invalid encryption algorithm", nameof(algorithm));
            }
        }
    }

    public interface IBase64DecoderService
    {
        Task<string> DecryptAsync(string base64EncodedMessage, string encryptionAlgorithm);
    }

    public class DistributedCache : IDistributedCache
    {
        // Implement caching logic here
    }

    public interface IDistributedCache
    {
        bool TryGet(string key, out byte[] value);
        void Set(string key, byte[] value);
    }
}
