void DynamicList::push_back(const Item& item) {
    std::unique_lock<std::mutex> lock(mtx);
    if (size >= capacity) {
        capacity *= 2; // Dynamically grow the list
        items.reserve(capacity);
    }
    items.push_back(item);
    ++size;
}

bool DynamicList::pop_front() {
    std::unique_lock<std::mutex> lock(mtx);
    if (size == 0) return false; // List is empty
    auto& item = items[0];
    items.erase(items.begin());
    --size;
    return true;
