using System;
using System.IO;
using System.Threading;
using GZipStream = System.IO.Compression.GzipStream;

public class GZipDecompressor
{
    public byte[] DecompressGZipFile(string file_path, int buffer_size = 1024 * 1024, int max_buffer_size = 512 * 1024 * 1024)
    {
        using var stream = new FileStream(file_path, FileMode.Open);
        using var gzip_stream = new GZipStream(stream, CompressionMode.Decompress);

        byte[] decompressed_data;
        int total_bytes = (int)stream.Length;

        if (!AllocateMemory(total_bytes, out decompressed_data))
            return null; // Allocation failed

        long current_offset = 0;
        int bytes_read;
        int bytes_written = 0;

        using var memory_stream = new MemoryStream();
        using var buffer_stream = new MemoryStream();

        try
        {
            while ((bytes_read = gzip_stream.Read(new byte[buffer_size], 0, buffer_size)) > 0)
            {
                memory_stream.Write(new byte[bytes_read], 0, bytes_read);
                current_offset += bytes_read;

                int bytes_written_to_buffer = Math.Min(buffer_size, total_bytes - current_offset);

                if (bytes_written_to_buffer < buffer_size)
                    break; // End of file reached

                buffer_stream.Position = 0;
                memory_stream.WriteTo(buffer_stream);
                decompressed_data.AsSpan(0, buffer_stream.Length).CopyTo(decompressed_data.AsSpan(bytes_written));
                bytes_written += buffer_stream.Length;

                if (memory_stream.Length > max_buffer_size / 2)
                    AdjustBufferSizes(gzip_stream);

                memory_stream.Position = 0;
                memory_stream.SetLength(0);
            }

            gzip_stream.Close();

            return decompressed_data;
        }
        catch (Exception ex)
        {
            HandleDecompressionError(ex);
            return null; // Decompression failed
        }
    }

    private bool AllocateMemory(int total_bytes, out byte[] buffer)
    {
        int bytes_per_allocation = 128 * 1024 * 1024;

        if (total_bytes > int.MaxValue || bytes_per_allocation > int.MaxValue / total_bytes)
            return false; // Allocation would exceed maximum size

        while (true)
        {
            try
            {
                buffer = new byte[bytes_per_allocation];
                return true;
            }
            catch
            {
                bytes_per_allocation /= 2;

                if (bytes_per_allocation < 1)
                    return false; // Allocation failed, too small
            }
        }
    }

    private void AdjustBufferSizes(GZipStream gzip_stream)
    {
        int new_buffer_size = Math.Min(gzip_stream.CanRead ? (int)gzip_stream.Length : buffer_size * 2, max_buffer_size);
        buffer_size = new_buffer_size;
    }

    private void HandleDecompressionError(Exception ex)
    {
        // Log or report the error
        Console.WriteLine("Decompression failed: " + ex.Message);
    }
}
