import java.io.*;
import java.util.Map;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class ConfigManager {

    private final ReadWriteLock readWriteLock = new ReentrantReadWriteLock();
    private Map<String, Object> configMap;
    private ObjectMapper mapper;

    public ConfigManager() {
        this.mapper = new ObjectMapper().enable(SerializationFeature.INDENT_OUTPUT);
        this.configMap = ImmutableMap.of();
    }

    public void loadConfig(String configFile) throws IOException {
        readWriteLock.writeLock().lock();

        try (InputStream inputStream = new FileInputStream(configFile)) {
            configMap = mapper.readValue(inputStream, Map.class);
        } finally {
            readWriteLock.writeLock().unlock();
        }
    }

    public void updateConfig(String key, Object value) {
        readWriteLock.readLock().lock();

        try {
            if (!configMap.containsKey(key)) {
                throw new RuntimeException("Key not found in config file");
            }
            configMap.put(key, value);
        } finally {
            readWriteLock.readLock().unlock();
        }
    }

    public void validateConfig() throws ValidationException {
        // Implement validation rules here
    }

    public Object getConfig(String key) {
        return configMap.getOrDefault(key, null);
    }

    private class ValidationException extends Exception {}

    public static void main(String[] args) {
        ConfigManager configManager = new ConfigManager();
        try {
            configManager.loadConfig("config.json");
            // Update and validate the config
        } catch (IOException | ValidationException e) {
            // Handle exceptions
        }
    }
}
