const axios = require('axios');
const { OAuth2 } = require('oauth2-server');
const { validateProfile } = require('./profile-schema-validator');
const { cacheManager } = require('./cache-manager');
const { messagingService } = require('./messaging-service');

async function fetchAndValidateUserProfile(identifier) {
  const apiEndpoint = 'https://api.identityprovider.com/user/profile';
  const clientId = 'your-client-id';
  const clientSecret = 'your-client-secret';
  const redirectUri = 'http://localhost:3000/callback';

  const oauth2 = new OAuth2({
    clientId,
    clientSecret,
    redirectUri,
  });

  try {
    const tokenResponse = await oauth2.getToken();
    const accessToken = tokenResponse.accessToken;

    const headers = { Authorization: `Bearer ${accessToken}` };
    const requestConfig = {
      method: 'GET',
      url: apiEndpoint,
      headers,
      params: { identifier },
    };

    const response = await axios(requestConfig);

    if (!response.data) {
      throw new Error('Invalid or missing response data');
    }

    const profileData = response.data;

    // Validate the profile data against the expected schema
    validateProfile(profileData);

    // Cache the user profile for a configurable TTL period
    cacheManager.set(identifier, profileData, 3600); // 1 hour TTL

    // Notify other systems of changes in user data
    messagingService.publishUpdate(identifier, profileData);

    return profileData;
  } catch (error) {
    if (error.response) {
      const responseError = error.response.data;
      console.error(`Error fetching and validating user profile: ${responseError.message}`);
    } else {
      console.error('Error fetching and validating user profile:', error);
    }
  }

  // Implement rate limiting at the function level
  setTimeout(() => {
    if (cacheManager.getHitCount(identifier) > 5) {
      cacheManager.setRateLimit(identifier, 10); // 10 requests per minute
    }
  }, 1000 * 60);

  return null;
}

// API client rate limiting implementation
axios.interceptors.push({
  onSuccess: (response) => {
    if (response.status >= 400) {
      setTimeout(() => {
        axios.get('https://api.identityprovider.com/rate-limits');
      }, 1000 * 60); // Request rate limits every minute
    }
  },
});
