from abc import ABC, abstractmethod
from typing import Any, Dict, List

class SerializationError(Exception):
    pass

class VersionedJSON(ABC):
    @abstractmethod
    def to_json(self) -> str:
        pass

    @abstractmethod
    def from_json(self, json_str: str) -> None:
        pass

class JSONEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, VersionedJSON):
            return obj.to_json()
        return super().default(obj)

class JSONDecoder(json.JSONDecoder):
    def object_pairs_hook(self, pairs):
        result = {}
        for k, v in pairs:
            if isinstance(k, str) and k.startswith('__version'):
                result['__version'] = int(v)
            else:
                result[k] = self.decode(v)
        return result

class JSONRegistry:
    _registry_lock = RLock()
    _registry = {}

    @classmethod
    def register(cls, factory: Any):
        with cls._registry_lock:
            if factory not in cls._registry.values():
                cls._registry[factory.__name__] = factory()

    @classmethod
    def get_registry(cls) -> Dict[str, Any]:
        return cls._registry

class JSONParser:
    _logger = logging.getLogger('JSONParser')

    @lru_cache(maxsize=None)
    def parse_json(self, json_str: str) -> VersionedJSON:
        try:
            obj = json.loads(json_str)
        except Exception as e:
            self._logger.error(f"Error parsing JSON: {e}")
            raise SerializationError("Invalid JSON format")

        version = None
        if isinstance(obj, dict) and '__version' in obj:
            version = int(obj.pop('__version'))
        return obj

    def parse_json_file(self, file_path: str) -> VersionedJSON:
        try:
            with open(file_path, 'r') as f:
                json_str = f.read()
        except Exception as e:
            self._logger.error(f"Error reading JSON file: {e}")
            raise SerializationError("Invalid JSON file")

        return self.parse_json(json_str)

class JSONWriter:
    _logger = logging.getLogger('JSONWriter')

    def write_json(self, obj: VersionedJSON, file_path: str) -> None:
        try:
            with open(file_path, 'w') as f:
                json.dump(obj.to_json(), f)
        except Exception as e:
            self._logger.error(f"Error writing JSON to file: {e}")
            raise SerializationError("Invalid JSON format")
