#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define AVL_MAX_HEIGHT 20
#define AVL_NODE_MAX 1000
#define AVL_TREE_DEFAULT_SIZE 100
#define LOG_LEVEL_VERBOSE 1
#define LOG_LEVEL_DEBUG 2

typedef struct {
    int key;
    double value;
} Value;

typedef struct AVLNode {
    int key;
    double value;
    int height;
    struct AVLNode* left;
    struct AVLNode* right;
    pthread_mutex_t lock;
} Node;

Node* create_node(int key, double value) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = key;
    node->value = value;
    node->height = 1;
    node->left = NULL;
    node->right = NULL;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

int is_left_child(struct AVLNode* node) {
    if (node == NULL)
        return -1; // No child
    else if (node->parent && node->parent->left == node)
        return 0; // Left child
    else if (node->parent && node->parent->right == node)
        return 1; // Right child
    else
        return -2; // Node has no parent
}

int get_height(struct AVLNode* node) {
    if (node == NULL)
        return -1;
    else
        return node->height;
}

// Insert a new node into the tree, rebalancing as needed
void insert(Node** root, int key, double value) {
    Node* newNode = create_node(key, value);
    if (*root == NULL) {
        *root = newNode;
    } else {
        Node* temp = *root;
        Node* parent;
        while (1) {
            parent = temp;
            if (key < temp->key) {
                temp = temp->left;
                if (temp == NULL) {
                    break;
                }
            } else {
                temp = temp->right;
                if (temp == NULL) {
                    break;
                }
            }
        }
        newNode->parent = parent;
        if (key < parent->key) {
            parent->left = newNode;
        } else {
            parent->right = newNode;
        }
        AVL_insert(&newNode, root);
    }
}

// Function to rebalance the tree
void AVL_insert(Node** node, Node** root) {
    int balance_factor = get_balance(*node);
    if (balance_factor > 1 || balance_factor < -1) {
        if (get_height((*node)->left) >= get_height((*node)->right)) {
            // Left-heavy, so we need to perform a right rotation
            right_rotate(root, *node);
        } else {
            // Right-heavy, so we need to perform a left rotation
            left_rotate(root, *node);
        }
    }
}

// Function for left rotation
void left_rotate(Node** root, Node* node) {
    Node* temp = node->right;
    node->right = temp->left;
    if (temp->left != NULL) {
        temp->left->parent = node;
    } else {
        temp->left = node;
    }
    temp->parent = node->parent;
    node->parent = temp;
    if (node == *root) {
        *root = temp;
    }
}

// Function for right rotation
void right_rotate(Node** root, Node* node) {
    Node* temp = node->left;
    node->left = temp->right;
    if (temp->right != NULL) {
        temp->right->parent = node;
    } else {
        temp->right = node;
    }
    temp->parent = node->parent;
    node->parent = temp;
    if (node == *root) {
        *root = temp;
    }
}

// Function to calculate balance factor
int get_balance(Node* node) {
    return get_height(node->left) - get_height(node->right);
}
