    pthread_mutex_unlock(&lock);

    return 0; // Successful addition
}

int add_edge(int from, int to) {
    pthread_mutex_lock(&lock);

    if (from >= KEY_MAX || to >= KEY_MAX)
        return -1; // Handle error

    // Edge logic here...

    pthread_mutex_unlock(&lock);

    return 0; // Successful edge addition
}

void* thread_func(void* arg) {
    int i;
    for (i = 0; i < 10; i++) { // Simulate concurrent updates
        add_vertex(i);
        add_edge(i, i + 1);
    }

    return NULL;
}

int main() {
    pthread_t threads[10];
    long i;

    init_graph_db(100, 200);

    for (i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }

    for (i = 0; i < 10; i++) {
