using System;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class Base64Decryptor
{
    private readonly ILogger _logger;

    public Base64Decryptor(ILogger logger)
    {
        _logger = logger;
    }

    public async Task<string> DecryptBase64Async(string base64EncodedMessage, string encryptionAlgorithm, int decryptionTimeoutInMilliseconds, bool invalidateExpiredTokens)
    {
        if (string.IsNullOrEmpty(base64EncodedMessage))
            throw new ArgumentNullException(nameof(base64EncodedMessage));

        var decryptedBytes = await DecryptAsync(GetEncryptionProvider(encryptionAlgorithm), base64EncodedMessage);
        return Encoding.UTF8.GetString(decryptedBytes);

        async Task<byte[]> DecryptAsync(IEncryptionProvider encryptionProvider, string base64EncodedMessage)
        {
            try
            {
                // Use asynchronous decryption
                using (var ms = new MemoryStream())
                {
                    using (var cs = new CryptoStream(ms, encryptionProvider.Decrypt(base64EncodedMessage), CryptoStreamMode.Write))
                    {
                        var buffer = new byte[4096];
                        int bytesRead;
                        while ((bytesRead = base64EncodedMessage.Read(buffer, 0, buffer.Length)) > 0)
                            await cs.WriteAsync(buffer, 0, bytesRead);
                    }
                }

                return ms.ToArray();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Decryption failed");
                throw;
            }
        }

        IEncryptionProvider GetEncryptionProvider(string encryptionAlgorithm)
        {
            switch (encryptionAlgorithm.ToLower())
            {
                case "triple des":
                    return new TripleDesEncryptionProvider();
                case "aes":
                    return new AesEncryptionProvider();
                default:
                    throw new ArgumentException("Unsupported encryption algorithm", nameof(encryptionAlgorithm));
            }
        }
    }

    public interface IEncryptionProvider
    {
        Stream Decrypt(string base64EncodedMessage);
    }

    public class TripleDesEncryptionProvider : IEncryptionProvider
    {
        private readonly ICryptoTransform _decryptor;

        public TripleDesEncryptionProvider()
        {
            using (var des = new DESCryptoServiceProvider { Key = new byte[] { 0x12, 0x34, 0x56, 0x78 }, IV = new byte[8] })
            {
                _decryptor = des.CreateDecryptor();
            }
        }

        public Stream Decrypt(string base64EncodedMessage)
        {
            var ms = new MemoryStream(Convert.FromBase64String(base64EncodedMessage));
            using (var cs = new CryptoStream(ms, _decryptor, CryptoStreamMode.Read))
            {
                return cs;
            }
        }
    }

    public class AesEncryptionProvider : IEncryptionProvider
    {
        private readonly ICryptoTransform _decryptor;

        public AesEncryptionProvider()
        {
            using (var aes = new AesCryptoServiceProvider { Key = new byte[] { 0x12, 0x34, 0x56, 0x78 }, IV = new byte[16] })
            {
                _decryptor = aes.CreateDecryptor();
            }
        }

        public Stream Decrypt(string base64EncodedMessage)
        {
            var ms = new MemoryStream(Convert.FromBase64String(base64EncodedMessage));
            using (var cs = new CryptoStream(ms, _decryptor, CryptoStreamMode.Read))
            {
                return cs;
            }
        }
    }
}
