#define RECORD_SIZE sizeof(record_t)
#define MEMORY_THRESHOLD 0.85

typedef struct {
    int key;
} record_t;

static pthread_once_t init_once = PTHREAD_ONCE_INIT;
static pthread_key_t records_key;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void *init_records(void* arg) {
    void *records = mmap(NULL, 1024, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        exit(1);
    }
    pthread_key_create(&records_key, NULL);
    return records;
}

void *record_array = NULL;

void record_init() {
    pthread_once(&init_once, init_records);
}

void* get_record_array() {
    return record_array;
}

void record_add(int key) {
    record_t *record = (record_t*)pthread_getspecific(records_key);
    if (!record) {
        record = malloc(RECORD_SIZE);
        pthread_setspecific(records_key, record);
    }
    record->key = key;
}

int memory_usage() {
    struct stat sb;
    stat("/", &sb);
    return (int)sb.st_size * MEMORY_THRESHOLD;
}

void check_memory_usage(long long offset_values_size, int keys_size) {
    if ((offset_values_size + keys_size) > memory_usage()) {
        fprintf(stderr, "Memory usage exceeded 85% threshold. Adjust your application's memory consumption.\n");
    }
}

void serialize_records(const char* filename) {
    pthread_mutex_lock(&mutex);
    record_t *record = (record_t*)pthread_getspecific(records_key);
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(record, RECORD_SIZE, 1, file);
    fclose(file);
    pthread_mutex_unlock(&mutex);
}
