Task** init_tasks(int numTasks, const char* idRange, time_t startTimeRange, time_t deadlineRange, const char* logFile, const char* notificationSystem) {
    // Calculate the length of the id range
    int idLength = strlen(idRange);

    // Initialize the task array with a pointer to NULL for each task
    Task** tasks = (Task**)malloc(numTasks * sizeof(Task*));
    for(int i = 0; i < numTasks; i++) {
        tasks[i] = NULL;
    }

    // Generate random identifiers, start times and deadlines
    char id[idLength + 1];
    time_t start_time, deadline;
    for(int i = 0; i < numTasks; i++) {
        // Generate a random identifier within the specified range
        int j = rand() % (idLength - 1) + 1;
        memcpy(id, idRange, j);
        id[j] = '\0';

        // Generate a random start time and deadline within the specified ranges
        start_time = startTimeRange + rand() % ((int)(deadlineRange - startTimeRange));
        deadline = deadlineRange - rand() % ((int)(deadlineRange - startTimeRange));

        tasks[i] = (Task*)malloc(sizeof(Task));
        tasks[i]->id = strdup(id);
        tasks[i]->start_time = start_time;
        tasks[i]->deadline = deadline;
        tasks[i]->progress = 0; // Initialize progress to 0
    }

    return tasks;
}
