        : maxThresholdMB(maxThresholdMB), eventsPerSecond(eventsPerSecond), recordsPerEvent(recordsPerEvent) {}

    void processEvents(const std::string& logFile) {
        std::ifstream file(logFile);
        if (!file.is_open()) {
            std::cerr << "Error opening log file." << std::endl;
            return;
        }

        size_t totalRecords = 0;

        while (true) {
            Event event;
            file.read(reinterpret_cast<char*>(&event), sizeof(Event));

            if (file.eof())
                break;

            for (size_t i = 0; i < recordsPerEvent; ++i) {
                double record;
                file.read(reinterpret_cast<char*>(&record), sizeof(double));
                event.records.push_back(record);
                totalRecords++;
