void init_DynamicValueGenerator(struct DynamicValueGenerator* generator, int min, int max) {
    generator->range_min = min;
    generator->range_max = max;
    generator->max_value = (generator->range_min > 0 ? generator->range_min : 1);
}

// Generate a random value within the specified range and maximum
double generate_DynamicValue(struct DynamicValueGenerator* generator, int type) {
    if(type == 0) { // Integer value
        return (double)rand() / RAND_MAX * (generator->range_max - generator->range_min + 1);
    } else { // Floating-point value
        return (double)rand() / RAND_MAX * (generator->range_max - generator->range_min);
    }
}

