// Function to initialize and resize arrays
void* resizeArray(void* arr, size_t oldSize, size_t newSize) {
    if (newSize > oldSize) {
        // Increase array size
        void* newArr = realloc(arr, newSize * sizeof(*arr));
        if (!newArr) return NULL;  // Handle memory allocation failure
    } else if (oldSize > newSize) {
        // Decrease array size
        void* newArr = realloc(arr, newSize * sizeof(*arr));
        if (!newArr) return NULL;  // Handle memory allocation failure
    }
    return newArr;
