record* initialize_data(int num_keys, int num_records) {
    // Allocate memory for key array
    long* keys = (long*)calloc(num_keys, sizeof(long));

    // Initialize keys with unique values
    for (int i = 0; i < num_keys; i++) {
        // Generate random key value
        long key = rand() % INT_MAX;

        // Check if key already exists
        int found_duplicate = 0;
        for (int j = 0; j < i; j++) {
            if (keys[j] == key) {
                found_duplicate = 1;
                break;
            }
        }

        // Log error and proceed with unique entries only
        if (found_duplicate) {
            printf("Error: Duplicate key detected\n");
            return NULL;
        } else {
            keys[i] = key;
        }
    }

    // Allocate memory for record array using variable-length arrays (VLAs)
    #ifdef _MSC_VER
    record records[num_records];
    #else
    record* records = (record*)malloc(num_records * sizeof(record));
    #endif

    // Initialize records with random values
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % INT_MAX;
    }

    return &records[0];
}

void monitor_memory_usage(int* max_threshold_kb, int* current_usage_kb) {
    // Monitor memory usage and adjust arrays as needed
    if (*current_usage_kb > *max_threshold_kb - 90) {
        int new_max_threshold_kb = *max_threshold_kb + 1;
        int num_records_to_remove = (new_max_threshold_kb - *current_usage_kb) / sizeof(record);

        // Adjust record array size and free excess memory
        #ifdef _MSC_VER
        record* temp_records = &records[0];
        records = (record*)malloc(num_records_to_remove * sizeof(record));
        #else
        record* temp_records = records;
        records = (record*)realloc(records, num_records_to_remove * sizeof(record));
        free(temp_records);
        #endif

        // Update current memory usage and max threshold
        *current_usage_kb -= num_records_to_remove * sizeof(record);
        *max_threshold_kb = new_max_threshold_kb;
    }
}

int main() {
    int num_keys = 100;
    int num_records = 500;

    record* data = initialize_data(num_keys, num_records);

    if (data == NULL) {
        return -1;
    }

    // Monitor memory usage
    int max_threshold_kb = 1024;
    int current_usage_kb = sizeof(record) * num_records + sizeof(long) * num_keys;
    monitor_memory_usage(&max_threshold_kb, &current_usage_kb);

    return 0;
}
