    char** strings = (char**)malloc(arrSize * sizeof(char*));
    metadata_t** metadatas = (metadata_t*)malloc(arrSize * sizeof(metadata_t*));
    record_t** records = (record_t*)malloc(arrSize * sizeof(record_t*));

    if (!strings || !metadatas || !records) {
        errCode = -1; // Error: insufficient memory
        goto cleanup;
    }

    // Initialize arrays with random values and populate records
    for (int i = 0; i < arrSize; i++) {
        strings[i] = (char*)malloc(256 * sizeof(char)); // Assume max string length is 255 characters
        metadatas[i] = (metadata_t*)malloc(sizeof(metadata_t));
        records[i] = (record_t*)malloc(sizeof(record_t));

        if (!strings[i] || !metadatas[i] || !records[i]) {
            errCode = -1; // Error: insufficient memory
            goto cleanup;
        }

        int randomVal = rand() % rngEnd + rngStart;
        records[i]->integerField = randomVal;
        records[i]->statusIndicator = (randomVal % 2 == 0) ? RECORD_STATUS_EVEN : RECORD_STATUS_ODD;
    }

    // Initialize document index
    docIndex = (void*)malloc(sizeof(documentIndex_t));

    if (!docIndex) {
        errCode = -1; // Error: insufficient memory
        goto cleanup;
    }

    // Populate document index with pointers to records and initialize 'next' pointer
    for (int i = startDocIndex; i <= endDocIndex; i++) {
        documentIndex_t* docIndexPtr = (documentIndex_t*)malloc(sizeof(documentIndex_t));
        if (!docIndexPtr) {
            errCode = -1; // Error: insufficient memory
            goto cleanup;
        }
        docIndexPtr->recordPtr = records[i];
        docIndexPtr->metadataPtr = metadatas[i];
        docIndexPtr->stringPtr = strings[i];
        docIndex->next = i == endDocIndex ? NULL : docIndexPtr;
    }

    // Free memory
    cleanup:
    for (int i = 0; i < arrSize; i++) {
        if (strings[i]) free(strings[i]);
        if (metadatas[i]) free(metadatas[i]);
        if (records[i]) free(records[i]);
    }
    if (docIndex) free(docIndex);
    if (errCode == -1) return NULL; // Error: insufficient memory
    else return docIndex;
}
