    pthread_mutex_lock(&lock);
    if (list_size == MAX_LIST_SIZE) {
        printf("List full\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    Object* new_list = (Object*)heap_realloc(list, (list_size + 1) * sizeof(Object));
    if (!new_list)
        printf("Memory allocation failed\n");
    list = new_list;
    list[list_size++] = obj;
    pthread_mutex_unlock(&lock);
}

void list_remove(int idx) {
    pthread_mutex_lock(&lock);
    if (idx >= list_size || idx < 0) {
        printf("Invalid index\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    Object* new_list = (Object*)heap_realloc(list, list_size * sizeof(Object));
    if (!new_list)
        printf("Memory reallocation failed\n");
    list = new_list;
    memmove(&list[idx], &list[idx + 1], (list_size - idx - 1) * sizeof(Object));
    list_size--;
    pthread_mutex_unlock(&lock);
}

void* cache_get(int id) {
    for (int i = 0; i < cache_size; i++) {
        if (object_cache[i] && ((Object*)object_cache[i])->id == id) {
