#include <thread>
#include <mutex>
#include <condition_variable>
#include <fstream>

struct item {
    double value;
    char buffer[256];
};

class DynamicList {
public:
    DynamicList(size_t initialCapacity) : capacity(initialCapacity), size(0), data(new item*[initialCapacity]) {}

    ~DynamicList() {
        for (size_t i = 0; i < capacity; ++i) {
            delete[] data[i];
        }
        delete[] data;
    }

    void add(item* item) {
        if (size >= capacity) {
            grow();
        }
        data[size++] = item;
    }

    item* get(size_t index) {
        if (index >= size || index < 0) {
            return nullptr;
        }
        return data[index];
    }

private:
    void grow() {
        size_t newCapacity = capacity * 2;
        item** newData = new item*[newCapacity];
        for (size_t i = 0; i < capacity; ++i) {
            newData[i] = data[i];
        }
        delete[] data;
        data = newData;
        capacity = newCapacity;
    }

    size_t capacity;
    size_t size;
    item** data;
};

int main() {
    DynamicList list(10);
    // Add items to the list
    for (size_t i = 0; i < 20; ++i) {
        item* item = new item();
        item->value = static_cast<double>(i);
        strcpy(item->buffer, "Item ");
        list.add(item);
    }
    // Retrieve and process items from the list
    for (size_t i = 0; i < list.size(); ++i) {
        item* item = list.get(i);
        if (item != nullptr) {
            std::cout << "Value: " << item->value << ", Buffer: " << item->buffer << std::endl;
            delete item;
        }
    }
    return 0;
}
