int allocate_memory(int config_num_vertices, int config_max_vertex_id) {
    // Calculate total memory required
    int total_bytes = sizeof(long) * config_num_vertices + sizeof(int) * config_num_vertices + sizeof(record) * config_num_vertices;

    if (total_bytes > MAX_THRESHOLD * 1024) {
        return -1; // Memory allocation failed
    }

    // Allocate memory for arrays
    long *vertex_offsets = (long *)malloc(sizeof(long) * config_num_vertices);
    int *vertex_keys = (int *)malloc(sizeof(int) * config_num_vertices);
    record **records = (record **)malloc(config_num_vertices * sizeof(record *));
    for (int i = 0; i < config_num_vertices; i++) {
        records[i] = create_records(1, config_max_vertex_id + 1);
    }

    return 0;
}

void deallocate_memory(int config_num_vertices) {
    // Free allocated memory
    free(vertex_offsets);
    free(vertex_keys);
    for (int i = 0; i < config_num_vertices; i++) {
