#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 128
#define LOAD_FACTOR 0.75
#define QUADRATIC_PROBING 2

typedef struct {
    char* key;
    long* value;
} kvpair;

typedef struct {
    int capacity;
    int size;
    float load_factor;
    pthread_mutex_t lock;
    kvpair** table;
} hashmap;

hashmap* hashmap_new(int capacity) {
    hashmap* map = (hashmap*)malloc(sizeof(hashmap));
    map->capacity = capacity;
    map->size = 0;
    map->load_factor = LOAD_FACTOR;
    map->table = (kvpair**)calloc(capacity, sizeof(kvpair*));

    pthread_mutex_init(&map->lock, NULL);
    return map;
}

void hashmap_free(hashmap* map) {
    for(int i = 0; i < map->capacity; i++) {
        if(map->table[i] != NULL) {
            free(map->table[i]->key);
            free(map->table[i]->value);
        }
    }

    free(map->table);
    pthread_mutex_destroy(&map->lock);
    free(map);
}

long int_string_to_long(char* str) {
    // Convert string to long integer
    return atol(str);
}

char* long_to_int_string(long val) {
    // Convert long integer to string
    char* str = (char*)malloc(20 * sizeof(char));
    sprintf(str, "%ld", val);
    return str;
}

int hashmap_insert(hashmap* map, char* key, long value) {
    int index = hash(key) % map->capacity;

    kvpair* pair = (kvpair*)malloc(sizeof(kvpair));
    pair->key = strdup(key);
    pair->value = &value;

    while(map->table[index] != NULL && strcmp(map->table[index]->key, key) != 0) {
        index += QUADRATIC_PROBING;
        if(index >= map->capacity) {
            // Rehashing required
            pthread_mutex_lock(&map->lock);
            if(map->size * (1 + map->load_factor) > map->capacity) {
                int new_capacity = map->capacity * 2;
                hashmap* new_map = hashmap_new(new_capacity);

                for(int i = 0; i < map->capacity; i++) {
                    kvpair* pair = map->table[i];
                    while(pair != NULL) {
                        int new_index = hash(pair->key) % new_capacity;
                        if(map->table[new_index] == NULL || strcmp(map->table[new_index]->key, pair->key) != 0) {
                            map->table[new_index] = pair;
                            break;
                        }
                        pair = pair->next;
                    }
                }

                pthread_mutex_unlock(&map->lock);
            } else {
                pthread_mutex_unlock(&map->lock);
            }
        }
    }

    if(map->table[index] == NULL) {
        map->table[index] = pair;
        map->size++;
    } else {
        // Collision, update existing key-value pair
        free(pair->key);
        free(pair->value);
        free(pair);
    }

    return 0;
}

int hashmap_remove(hashmap* map, char* key) {
    int index = hash(key) % map->capacity;

    kvpair* pair = map->table[index];
    while(pair != NULL && strcmp(pair->key, key) != 0) {
        index += QUADRATIC_PROBING;
        if(index >= map->capacity) {
            // Rehashing required
            pthread_mutex_lock(&map->lock);
            if(map->size * (1 + map->load_factor) > map->capacity) {
                int new_capacity = map->capacity * 2;
                hashmap* new_map = hashmap_new(new_capacity);

                for(int i = 0; i < map->capacity; i++) {
                    kvpair* pair = map->table[i];
                    while(pair != NULL) {
                        int new_index = hash(pair->key) % new_capacity;
                        if(map->table[new_index] == NULL || strcmp(map->table[new_index]->key, pair->key) != 0) {
                            map->table[new_index] = pair;
                            break;
                        }
                        pair = pair->next;
                    }
                }

                pthread_mutex_unlock(&map->lock);
            } else {
                pthread_mutex_unlock(&map->lock);
            }
        }
    }

    if(pair == NULL) {
        return -1; // Key not found
    }

    map->table[index] = pair->next;
    free(pair->key);
    free(pair->value);
    free(pair);

    map->size--;
    return 0;
}

long hashmap_get(hashmap* map, char* key) {
    int index = hash(key) % map->capacity;

    kvpair* pair = map->table[index];
    while(pair != NULL && strcmp(pair->key, key) != 0) {
        index += QUADRATIC_PROBING;
        if(index >= map->capacity) {
            // Rehashing required
            pthread_mutex_lock(&map->lock);
            if(map->size * (1 + map->load_factor) > map->capacity) {
                int new_capacity = map->capacity * 2;
                hashmap* new_map = hashmap_new(new_capacity);

                for(int i = 0; i < map->capacity; i++) {
                    kvpair* pair = map->table[i];
                    while(pair != NULL) {
                        int new_index = hash(pair->key) % new_capacity;
                        if(map->table[new_index] == NULL || strcmp(map->table[new_index]->key, pair->key) != 0) {
                            map->table[new_index] = pair;
                            break;
                        }
                        pair = pair->next;
                    }
                }

                pthread_mutex_unlock(&map->lock);
            } else {
                pthread_mutex_unlock(&map->lock);
            }
        }
    }

    if(pair == NULL) {
        return -1; // Key not found
    }

    return *pair->value;
}

int hash(char* key) {
    int sum = 0;
    for(int i = 0; i < strlen(key); i++) {
        sum += (int)key[i];
    }
    return sum % INITIAL_CAPACITY;
}

