    fwrite(item->buffer, sizeof(char), strlen(item->buffer)+1, file);
    return 0;
}

int deserialize_item(item* item, FILE* file) {
    fread(&item->value, sizeof(double), 1, file);
    item->buffer[0] = '\0';
    int len = 0;
    while (fread(&item->buffer[len], sizeof(char), 1, file) == 1) {
        item->buffer[++len] = '\0';
    }
    return 0;
}

