from flask import jsonify
from functools import wraps
from datetime import datetime

user_profiles = []

def cache_response(ttl=60):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            response = func(*args, **kwargs)
            return jsonify(response), 200
        return wraps(func)(wrapper)
    return decorator

@cache_response()
def get_user_profiles():
    return user_profiles

@cache_response()
def create_user_profile(username, email, password, role, status):
    if not (3 <= len(username) <= 20):
        return jsonify({'error': 'Username must be between 3 and 20 characters'}), 400
    if not re.match(r"[^@]+@[^@]+\.[^@]+", email):
        return jsonify({'error': 'Invalid email format'}), 400
    if len(password) < 8:
        return jsonify({'error': 'Password must be at least 8 characters long'}), 400
    if not re.search(r"\d+|[!@#$%^&*()_+=-{};:'<>,./?]", password):
        return jsonify({'error': 'Password must have at least one digit and one special character'}), 400
    if role not in ['admin', 'moderator', 'user']:
        return jsonify({'error': 'Invalid role'}), 400
    if status not in ['active', 'inactive', 'banned']:
        return jsonify({'error': 'Invalid status'}), 400

    new_profile = {
        'id': len(user_profiles) + 1,
        'username': username,
        'email': email,
        'password': password,
        'role': role,
        'status': status,
        'last_modified': datetime.now()
    }
    user_profiles.append(new_profile)
    return new_profile

@cache_response()
def update_user_profile(id, username=None, email=None, password=None, role=None, status=None):
    profile = next((profile for profile in user_profiles if profile['id'] == id), None)
    if not profile:
        return jsonify({'error': 'User not found'}), 404
    if username and not (3 <= len(username) <= 20):
        return jsonify({'error': 'Username must be between 3 and 20 characters'}), 400
    if email and not re.match(r"[^@]+@[^@]+\.[^@]+", email):
        return jsonify({'error': 'Invalid email format'}), 400
    if password and (len(password) < 8 or not re.search(r"\d+|[!@#$%^&*()_+=-{};:'<>,./?]", password)):
        return jsonify({'error': 'Password must be at least 8 characters long with at least one digit and one special character'}), 400
    if role and role not in ['admin', 'moderator', 'user']:
        return jsonify({'error': 'Invalid role'}), 400
    if status and status not in ['active', 'inactive', 'banned']:
        return jsonify({'error': 'Invalid status'}), 400

    profile['username'] = username or profile['username']
    profile['email'] = email or profile['email']
    profile['password'] = password or profile['password']
    profile['role'] = role or profile['role']
    profile['status'] = status or profile['status']
    profile['last_modified'] = datetime.now()
    return profile

@cache_response()
def delete_user_profile(id, sub_action):
    if sub_action != 'delete':
        return jsonify({'error': 'Invalid action'}), 400
    profile = next((profile for profile in user_profiles if profile['id'] == id), None)
    if not profile:
        return jsonify({'error': 'User not found'}), 404

    if sub_action == 'delete':
        user_profiles.remove(profile)

@cache_response()
def list_user_profiles():
    sorted_profiles = sorted(user_profiles, key=lambda x: (x['role'], x['status']), reverse=True)
    return sorted_profiles
