#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for each record
typedef struct {
    int key;
    int value;
} Record;

// Define the memory pool structure
typedef struct {
    Record* records;
    size_t capacity;
    size_t used;
    pthread_mutex_t mutex;
} MemoryPool;

// Function to initialize and populate the record collection
void init_and_populate(MemoryPool* mp, int* keys, int* values, size_t num_records) {
    // Allocate memory for the record collection
    mp->records = (Record*)malloc(num_records * sizeof(Record));
    mp->capacity = num_records;
    mp->used = 0;

    // Initialize mutex for thread-safe access
    pthread_mutex_init(&mp->mutex, NULL);

    // Populate the record collection
    for (size_t i = 0; i < num_records; i++) {
        Record* record = &mp->records[i];
        record->key = keys[i];
        record->value = values[i];

        // Validate key and value integrity
        if (record->key >= 0 && record->value > -1) {
            pthread_mutex_lock(&mp->mutex);
            mp->used++;
            pthread_mutex_unlock(&mp->mutex);
        } else {
            printf("Invalid record: key=%d, value=%d\n", record->key, record->value);
        }
    }
}

// Function to handle concurrent access to the data structure
void* access_data(void* arg) {
    MemoryPool* mp = (MemoryPool*)arg;
    pthread_mutex_lock(&mp->mutex);

    // Perform operations on the record collection concurrently
    for (size_t i = 0; i < mp->used; i++) {
        Record* record = &mp->records[i];
        printf("Concurrently accessed key=%d, value=%d\n", record->key, record->value);
    }

    pthread_mutex_unlock(&mp->mutex);

    return NULL;
}

int main() {
    // Example usage
    int keys[] = {1, 2, 3, 4};
    int values[] = {-1, 0, 1, 2};
    size_t num_records = sizeof(keys) / sizeof(int);

    MemoryPool mp;
    init_and_populate(&mp, keys, values, num_records);

    // Initialize threads for concurrent access
    pthread_t threads[4];
    for (size_t i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, access_data, &mp);
    }

    // Join the threads
    for (size_t i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
