    int value;
} dataEntry;

void init_data_entry(dataEntry** entries, int num_entries) {
    *entries = (dataEntry*)malloc(num_entries * sizeof(dataEntry));
}

int set_random_value(dataEntry* entry, int min_value, int max_value) {
    srand(time(NULL));
    return min_value + rand() % (max_value - min_value);
}

void update_entry(dataEntry* entry, char* new_data, int value) {
    free(entry->data);
    entry->data = strdup(new_data);
    entry->value = value;
}

int compare_entries(const void* a, const void* b) {
    dataEntry* entry1 = (dataEntry*)a;
    dataEntry* entry2 = (dataEntry*)b;

    if (strcmp(entry1->data, entry2->data) > 0)
        return 1;
    else if (strcmp(entry1->data, entry2->data) < 0)
        return -1;
    else
        return entry1->value - entry2->value;
}

void free_entries(dataEntry* entries, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        free(entries[i].data);
    }
    free(entries);
}
