typedef struct Record {
    int key;
    long offset;
    time_t timestamp;
} Record;

typedef struct Node {
    Record* record;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* createLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insertRecord(LinkedList* list, int key, long offset) {
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;
    record->timestamp = time(NULL);

    Node* node = (Node*)malloc(sizeof(Node));
    node->record = record;
    node->next = list->head;
    list->head = node;

    pthread_mutex_unlock(&list->lock);
}

void deleteRecord(LinkedList* list, int key) {
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL && current->record->key != key) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return; // record not found

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current->record);
    free(current);

    pthread_mutex_unlock(&list->lock);
}

void serialize(LinkedList* list, FILE* file) {
    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->record->key, sizeof(int), 1, file);
        fwrite(&current->record->offset, sizeof(long), 1, file);
        fwrite(&current->record->timestamp, sizeof(time_t), 1, file);

        current = current->next;
    }
}

void deserialize(LinkedList* list, FILE* file) {
    Record* record;
    Node* node;

    while (fread(&record->key, sizeof(int), 1, file) == 1 &&
           fread(&record->offset, sizeof(long), 1, file) == 1 &&
           fread(&record->timestamp, sizeof(time_t), 1, file) == 1) {
        node = (Node*)malloc(sizeof(Node));
        node->record = record;
        node->next = list->head;
        list->head = node;
    }
}

void compact(LinkedList* list) {
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL) {
        if (/* check for unused/obsolete records */) {
            previous = current;
            current = current->next;
        } else {
            previous = current;
            current = current->next;
        }
    }

    if (previous == list->head) return; // no records to remove

    free(previous->record);
    free(previous);

    pthread_mutex_unlock(&list->lock);
}

void* backupThread(void*) {
    int attempts = 0;
    while (/* check environment variables for automatic backups */) {
        // serialize data and write to secondary storage
        if (/* error handling */) {
            attempts++;
            if (attempts >= 3) break; // fail gracefully after three attempts
        } else {
            // log successful backup attempt
        }
    }

    return NULL;
}

int main() {
    LinkedList* list = createLinkedList();
    pthread_t thread;

    pthread_create(&thread, NULL, backupThread, NULL);

    // insert records and delete them as needed

    // compact data structure periodically or on demand

    // free dynamically allocated memory upon completion
    free(list);
    return 0;
}
