        return -1; // Error: invalid parameter values
    }

    // Initialize memory allocation limits
    const size_t MAX_MEMORY = 1024 * 1024 * 10; // 10MB

    // Allocate arrays dynamically
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(key_size * sizeof(int));
