    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return -2; // Error: memory allocation failed
    }

    // Initialize arrays
    for (int i = 0; i < size; i++) {
        offsets[i] = i * sizeof(long);
    }
    for (int i = 1; i <= max_key; i++) {
        keys[i - 1] = i;
    }
    for (int i = 0; i < record_count; i++) {
        records[i].key = rand() % max_key + 1;
        records[i].value = rand();
    }

    return 0; // Success
