int load_theme_bitmap(const char* theme_name, char** bitmap_data, int* width, int* height) {
    const char* default_dir = "/default/theme";
    const char* fallback_dir = "/fallback/theme";

    if(access(default_dir, F_OK)) {
        *bitmap_data = (char*)malloc(1024);
        // load and cache theme bitmap from default directory
        strcpy(*bitmap_data, "theme_default.png");
        *width = 256;
        *height = 128;
    } else {
        char* dir = (char*)malloc(strlen(default_dir) + strlen(fallback_dir) + 1);
        strcpy(dir, default_dir);
        strcat(dir, "/"); 
        strcat(dir, theme_name);
        // load and cache theme bitmap from specified directory
        *bitmap_data = (char*)malloc(1024);
        strcpy(*bitmap_data, "theme_" THEME_NAME ".png");
        *width = 256;
        *height = 128;
    }
}

void parse_png(const char* file_path, int** width, int** height) {
    FILE* file = fopen(file_path, "rb");
    if(file == NULL) {
        return;
    }

    png_structp png_ptr = png_create_read_struct(PNG_LIBPNG_VERSION_NEEDED, NULL, NULL, NULL);
    png_infop info = png_create_info_struct(png_ptr);

    int i = 0;
    while(!png_read_info(png_ptr, &info)) {
        i++;
    }

    *width = (int*)malloc(sizeof(int));
    *height = (int*)malloc(sizeof(int));
    (*width) = info.width;
    (*height) = info.height;

    png_destroy_read_struct(&png_ptr, &info, NULL);
    fclose(file);
}

void free_resources(record* records, char* bitmap_data) {
    if(records != NULL) {
        free(records);
    }
    if(bitmap_data != NULL) {
        free(bitmap_data);
    }
}
