    let offset_values: Vec<u64> = (0..window_size).map(|_| rng.gen::<u64>()).collect();
    let key_values: Vec<i32> = (0..window_size).map(|_| rng.gen_range(1, 100)).collect();

    let mut records: Vec<UeMeasurementResult> = Vec::new();
    for _ in 0..window_size {
        records.push(UeMeasurementResult {
            ran_node_id: rng.gen::<u64>(),
            measurement_type: "random_type".to_string(),
            measurement_value: rng.gen::<f64>(),
            moving_average: 0.0,
        });
    }

    // Initialize arrays
    let mut offset_values_array = vec![0; window_size];
    let mut key_values_array = vec![0; window_size];
    for i in 0..window_size {
        offset_values_array[i] = *offset_values.get(i).unwrap();
        key_values_array[i] = *key_values.get(i).unwrap();
    }

    // Calculate checksum
    let crc32_checksum: u32 = Crc32Fast::new().update(&records).checksum();
    let sha256_checksum: [u8; 32] = Sha256::digest(&records);

    (records, offset_values_array, key_values_array)
}
