// Enum for connection status
typedef enum {
    CONNECTED,
    DISCONNECTED,
    PENDING
} connection_status;

// Structure representing a network connection
typedef struct {
    int id;
    char host[256];
    int port;
    connection_status status;
} connection_t;

// Thread-safe array of connections
connection_t **connections;
pthread_mutex_t connections_lock = PTHREAD_MUTEX_INITIALIZER;

// Allocate memory for the specified number of connections
void *allocate_connections(int num_connections) {
    connections = (connection_t **)malloc(num_connections * sizeof(connection_t *));
    if (!connections) {
        fprintf(stderr, "Failed to allocate memory for connections.\n");
        return NULL;
    }
    for (int i = 0; i < num_connections; i++) {
        connections[i] = (connection_t *)malloc(sizeof(connection_t));
        if (!connections[i]) {
            fprintf(stderr, "Failed to allocate memory for connection %d.\n", i);
            free(connections);
            return NULL;
        }
        connections[i]->id = i;
    }
    return connections;
}

// Initialize a connection with default values
void initialize_connection(int index) {
    pthread_mutex_lock(&connections_lock);
    connections[index]->host[0] = '\0';
    connections[index]->port = 0;
    connections[index]->status = PENDING;
    pthread_mutex_unlock(&connections_lock);
}

// Free memory for the connections array and individual connections
void free_connections(int num_connections) {
    for (int i = 0; i < num_connections; i++) {
        free(connections[i]);
    }
    free(connections);
}

// Monitor connection status changes
void monitor_connection_status(int index, connection_status new_status) {
    pthread_mutex_lock(&connections_lock);
    connections[index]->status = new_status;
    pthread_mutex_unlock(&connections_lock);
}
