class FileParser {
public:
    std::vector<std::string> parseFile(const std::string& filePath) {
        std::ifstream file(filePath);
        if (!file) {
            throw std::runtime_error("Error opening file: " + filePath);
        }

        std::vector<std::string> records;
        std::string line;
        while (std::getline(file, line)) {
            records.push_back(line);
        }
        file.close();
        return records;
    }

    double calculateAverage(const std::vector<double>& numbers) {
        if (numbers.empty()) {
            throw std::runtime_error("Cannot calculate average of an empty vector");
        }
        double sum = 0.0;
        for (double num : numbers) {
            sum += num;
        }
        return sum / numbers.size();
    }

    double calculateMax(const std::vector<double>& numbers) {
        if (numbers.empty()) {
            throw std::runtime_error("Cannot find maximum of an empty vector");
        }
        double max = numbers[0];
        for (double num : numbers) {
            if (num > max) {
                max = num;
            }
        }
        return max;
    }

    std::string transformToJson(const std::vector<std::string>& fields) {
        std::stringstream jsonStream;
        jsonStream << "{\"fields\": [";
        for (int i = 0; i < fields.size(); ++i) {
            if (i > 0) {
                jsonStream << ", ";
            }
            jsonStream << "\"" << fields[i] << "\"";
        }
        jsonStream << "]}";
        return jsonStream.str();
    }
};

void insertString(std::forward_list<std::string>& list, const std::string& searchFor, const std::string& insertAfter) {
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == searchFor) {
            list.insert_after(it, insertAfter);
            return;
        }
        ++it;
    }
    list.push_back(insertAfter);
}

int main() {
    FileParser parser;

    std::forward_list<std::string> filePaths = {"file1.json", "file2.json", "file3.json"};

    for (auto& filePath : filePaths) {
        try {
            auto records = parser.parseFile(filePath);
            for (const auto& record : records) {
                // assume the JSON encoded string is stored in `record`
                std::vector<std::string> fields;
                // split the record into fields
                std::stringstream stream(record);
                std::string field;
                while (std::getline(stream, field, ',')) {
                    fields.push_back(field);
                }
                std::cout << "JSON-formatted string of all fields for this record: " << parser.transformToJson(fields) << "\n";

                // calculate average and max values
                std::vector<double> numbers;
                for (const auto& field : fields) {
                    try {
                        double value = stod(field);
                        numbers.push_back(value);
                    } catch (const std::invalid_argument&) {
                        // ignore non-numeric fields
                    }
                }

                if (!numbers.empty()) {
                    double average = parser.calculateAverage(numbers);
                    double max = parser.calculateMax(std::vector<double>(numbers.begin(), numbers.end() - 3));
                    std::cout << "Average value of the last three numerical fields: " << average << "\n";
                    std::cout << "Maximum value among the last five numerical fields: " << max << "\n";
                }
            }
        } catch (const std::exception& e) {
            std::cerr << "Error parsing file: " << e.what() << "\n";
        }
    }

    return 0;
}
