typedef struct item {
    int key;
    double value;
    struct item* next;
} item;

typedef struct node {
    item* head;
    int size;
    struct node* next;
} node;

node* add_item(node* head, int key, double value) {
    item* new_item = (item*)malloc(sizeof(item));
    new_item->key = key;
    new_item->value = value;
    new_item->next = NULL;

    if (!head || key < head->key) {
        new_item->next = head;
        return node{new_item, 1, NULL};
    }

    item* current = head;
    while (current->next && current->next->key >= key)
        current = current->next;
    new_item->next = current->next;
    current->next = new_item;

    if (!head) {
        return node{new_item, 1, NULL};
    }
    return head;
}

node* create_node() {
    return (node*)malloc(sizeof(node));
}
