void* my_malloc(size_t size) {
    static void* pool = NULL;
    static int count = 0;
    if (!pool) {
        pool = malloc(MAX_RECORDS * sizeof(Record));
        count = MAX_RECORDS;
    }
    return (void*)((char*)pool + (size_t)(count++ % MAX_RECORDS) * sizeof(Record));
}

// Custom memory pool deallocator
void my_free(void* ptr) {
    static void* pool = NULL;
    if (!pool) return;
    Record* record = (Record*)ptr;
    static int count = 0;
    if (count >= MAX_RECORDS) return;
    *record = (Record){0}; // Reset the record
    ((char*)pool + (size_t)(count++ % MAX_RECORDS) * sizeof(Record)) = ptr;
}

