    if (argc != 2) {
        printf("Usage: %s <num_records>\n", argv[0]);
        exit(1);
    }

    num_records = atoi(argv[1]);

    // Check for invalid input and prevent resource exhaustion
    if (num_records > MAX_RECORDS) {
        printf("Error: Maximum number of records exceeded.\n");
        exit(2);
    }

    Record* records = init_record_array(num_records);

    if (!records) {
        printf("Error: Memory allocation failed.\n");
        return 1;
    }

