use tokio::net::{TcpStream, TcpListener};
use tokio::sync::{mpsc, oneshot};
use tokio::time::sleep;
use bytes::BytesMut;
use tokio::stream::StreamExt;

struct Graph {
    vertices: Vec<(String, Vec<String>)>,
    edges: Vec<(String, String)>,
}

impl Graph {
    async fn new(max_memory_kb: u64) -> Self {
        let mut graph = Graph { vertices: Vec::new(), edges: Vec::new() };
        // initialize graph with max memory
        loop {
            let current_memory = self::get_current_memory();
            if current_memory <= max_memory_kb * 1024 {
                break;
            }
            // resize graph to reduce memory usage
            graph.vertices.resize(0, 16);
            graph.edges.resize(0, 32);
        }
        graph
    }

    async fn add_vertex(&mut self, vertex_id: String) -> Result<(), ()> {
        if self.vertices.iter().any(|v| v.0 == vertex_id.clone()) {
            return Err(());
        }
        self.vertices.push((vertex_id.clone(), Vec::new()));
        Ok(())
    }

    async fn add_edge(&mut self, edge: (String, String)) -> Result<(), ()> {
        let from_vertex = &self.vertices.iter().find(|v| v.0 == edge.0.clone()).unwrap();
        let to_vertex = &self.vertices.iter().find(|v| v.0 == edge.1.clone()).unwrap();

        if !from_vertex.1.is_empty() || !to_vertex.1.len() < 16 {
            return Err(());
        }

        from_vertex.1.push(edge.1.clone());
        to_vertex.1.push(edge.0.clone());

        Ok(())
    }

    async fn get_neighbors(&self, vertex_id: String) -> Vec<String> {
        self.vertices.iter().find(|v| v.0 == vertex_id).map_or(Vec::new(), |v| &v.1)
    }
}

fn main() {
    let graph = Graph::new(1024).await;
    tokio::spawn(async move {
        // add vertices and edges concurrently
        graph.add_vertex("A".to_string()).await.unwrap();
        graph.add_vertex("B".to_string()).await.unwrap();
        graph.add_edge(("A".to_string(), "B".to_string())).await.unwrap();

        // retrieve neighbors of vertex A
        let neighbors = graph.get_neighbors("A".to_string()).await;
        println!("{:?}", neighbors);

        // start HTTP client to fetch external data
        let client = reqwest::blocking::get("https://example.com/data").send();
    });
}
