struct memory_pool {
    void* start;
    size_t size;
    pthread_mutex_t lock;
};

void* my_malloc(size_t size) {
    struct memory_pool* pool = (struct memory_pool*)malloc(sizeof(struct memory_pool));
    if (!pool) return NULL;

    pool->start = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (pool->start == MAP_FAILED) {
        free(pool);
        return NULL;
    }

    pool->size = size;
    pthread_mutex_init(&pool->lock, NULL);

    return pool->start;
}

void* my_realloc(void* ptr, size_t size) {
    struct memory_pool* pool = (struct memory_pool*)mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (!pool) return NULL;

    memcpy(pool->start, ptr, size);
    munmap(ptr, size);

    return pool->start;
}

void my_free(void* ptr, struct memory_pool* pool) {
    munmap(ptr, pool->size);
    free(pool);
}

