char* generate_new_filename(const char* input_filename) {
    // List of allowed file types and extensions
    const char* valid_extensions[] = {".txt", ".jpg", ".pdf"};
    int num_valid_extensions = sizeof(valid_extensions) / sizeof(char*);

    // Check if the input filename is valid
    for (int i = 0; i < num_valid_extensions; i++) {
        if (strcmp(input_filename + strlen(input_filename) - strlen(valid_extensions[i]), valid_extensions[i]) == 0) {
            break;
        }
    }

    if (i >= num_valid_extensions) {
        // Invalid input filename, return a default filename
        return "default_filename.txt";
    }

    // Extract the primary component (extension) from the input filename
    const char* extension = input_filename + strlen(input_filename) - 1;
    while (*extension != '.') {
        extension--;
    }
    extension++;

    // Generate a new extension based on the input filename's characters
    int new_extension_length = rand() % MAX_EXTENSION_LENGTH + 1;
    char* new_extension = (char*)malloc(new_extension_length * sizeof(char));
    for (int i = 0; i < new_extension_length; i++) {
