#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

#define RECORD_POOL_SIZE 1000
#define MAX_RECORDS 10000
#define RANGE_MIN 0
#define RANGE_MAX 1000000
#define TYPE_LONG 1
#define TYPE_INT 2

typedef struct {
    int key;
    union {
        long lval;
        int ival;
    } value;
} Record;

Record *record_pool = NULL;
int record_count = 0;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocate_record() {
    Record *new_record;
    pthread_mutex_lock(&pool_mutex);
    if (record_pool == NULL || record_count >= RECORD_POOL_SIZE) {
        // Allocate a new pool
        void *temp = malloc(RECORD_POOL_SIZE * sizeof(Record));
        if (temp == NULL) {
            printf("Memory allocation failed\n");
            exit(-1);
        }
        record_pool = temp;
    }
    new_record = &record_pool[record_count++];
    pthread_mutex_unlock(&pool_mutex);
    return new_record;
}

void deallocate_record() {
    pthread_mutex_lock(&pool_mutex);
    if (record_pool != NULL) {
        // Return unused records to the pool
        for (int i = 0; i < record_count - 1; i++) {
            record_pool[i] = record_pool[i + 1];
        }
        record_count--;
        free(record_pool);
        record_pool = NULL;
    }
    pthread_mutex_unlock(&pool_mutex);
}

Record* initialize_records(int num_records, int** data_streams) {
    Record *records = malloc(num_records * sizeof(Record));
    if (records == NULL) {
        printf("Memory allocation failed\n");
        exit(-1);
    }

    for (int i = 0; i < num_records; i++) {
        Record *record = allocate_record();
        record->key = i;
        int type = rand() % 2;
        if (type == TYPE_LONG) {
            record->value.lval = ((long)(rand() % (RANGE_MAX - RANGE_MIN + 1)) + RANGE_MIN);
        } else {
            record->value.ival = ((int)(rand() % (RANGE_MAX - RANGE_MIN + 1)) + RANGE_MIN);
        }
    }

    deallocate_record();

    return records;
}

void cleanup() {
    deallocate_record();
    free(records);
}
