#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the struct record
typedef struct {
    int id;
    double value;
} Record;

// Function to generate unique identifiers
int getUniqueId() {
    static int lastId = 0;
    return ++lastId;
}

// Thread-safe data structure for records
typedef struct {
    pthread_mutex_t lock;
    Record *records;
    size_t capacity;
    size_t count;
} Records;

// Initialize records
Records* initRecords(size_t capacity) {
    Records *r = malloc(sizeof(Records));
    r->capacity = capacity;
    r->count = 0;
    r->records = malloc(capacity * sizeof(Record));
    pthread_mutex_init(&r->lock, NULL);
    return r;
}

// Free records
void freeRecords(Records *r) {
    pthread_mutex_unlock(&r->lock);
    free(r->records);
    free(r);
}

// Insert record
int insertRecord(Records *r, Record *record) {
    pthread_mutex_lock(&r->lock);
    if (r->count >= r->capacity) {
        // Resize the array when it's full
        size_t newCapacity = r->capacity * 2;
        Records *newR = initRecords(newCapacity);
        memcpy(newR->records, r->records, r->capacity * sizeof(Record));
        freeRecords(r);
        r = newR;
    }
    int idx = r->count++;
    record->id = getUniqueId();
    memmove(&r->records[idx + 1], &r->records[idx], (r->count - idx - 1) * sizeof(Record));
    memcpy(&r->records[idx], record, sizeof(Record));
    pthread_mutex_unlock(&r->lock);
    return idx;
}

// Prune outdated or unused records
void pruneRecords(Records *r, double timestampThreshold) {
    pthread_mutex_lock(&r->lock);
    size_t i = 0;
    for (size_t j = 0; j < r->count; ++j) {
        if (r->records[i].timestamp <= timestampThreshold) {
            memmove(&r->records[i], &r->records[i + 1], (r->count - i - 1) * sizeof(Record));
            --i;
        } else {
            ++i;
        }
    }
    r->count = i;
    pthread_mutex_unlock(&r->lock);
}

// Periodic prune function
void* periodicPrune(void* arg) {
    Records *r = (Records*)arg;
    while (1) {
        sleep(60); // Prune every minute
        pruneRecords(r, 0.0);
    }
    return NULL;
}

int main() {
    Records *records = initRecords(10);

    pthread_t periodicPruneThread;
    pthread_create(&periodicPruneThread, NULL, &periodicPrune, records);

    // Example usage:
    Record record;
    record.value = 3.14;
    insertRecord(records, &record);
    // ...

    // Graceful shutdown
    pthread_join(periodicPruneThread, NULL);
    freeRecords(records);
    return 0;
}
