    void* ptr = NULL;
    pthread_mutex_lock(&mutex);
    while ((ptr = malloc(size)) == NULL) {
        if (pthread_getenv("WORST_FIT") != NULL) {
            void* best_fit_ptr = NULL;
            size_t best_fit_size = SIZE_MAX;
            for (void* p = start; p <= end; p += aligned_size) {
                size_t s = *(size_t*)p - sizeof(size_t);
                if (s >= size && s < best_fit_size) {
                    best_fit_ptr = p;
                    best_fit_size = s;
                }
            }
            if (best_fit_ptr != NULL) {
                ptr = best_fit_ptr;
                break;
            } else {
                pthread_getenv("BEST_FIT");
                start += aligned_size;
                end += aligned_size;
            }
        } else {
