typedef struct LTE_NAS_Message {
    char NAS_Message_ID[MESSAGE_ID_SIZE];
    char Message[MESSAGE_SIZE];
    int Priority;
} LTE_NAS_Message;

// Mutex for thread safety
pthread_mutex_t message_collection_mutex = PTHREAD_MUTEX_INITIALIZER;

// Dynamic array to store messages
LTE_NAS_Message* messages = NULL;
int message_count = 0;

// Function prototypes
void add_message(LTE_NAS_Message* message);
LTE_NAS_Message* get_message(int index);
int serialize_messages(const char* filename);
int deserialize_messages(const char* filename);
void print_messages();

// Allocate memory for a new message
LTE_NAS_Message* allocate_message() {
    if (message_count < MAX_MESSAGES) {
        return malloc(sizeof(LTE_NAS_Message));
    } else {
        printf("Error: Message collection is full.\n");
        exit(1);
    }
}

// Add a message to the collection
void add_message(LTE_NAS_Message* message) {
    pthread_mutex_lock(&message_collection_mutex);

    if (messages == NULL || message_count >= MAX_MESSAGES) {
        // Reallocate memory if necessary
        messages = realloc(messages, sizeof(LTE_NAS_Message) * (MAX_MESSAGES + 1));
        messages[message_count].Priority = message->Priority;
        strcpy(messages[message_count].NAS_Message_ID, message->NAS_Message_ID);
        strcpy(messages[message_count].Message, message->Message);
    } else {
        // Add the new message to the existing array
        memcpy(&messages[message_count], message, sizeof(LTE_NAS_Message));
    }

    message_count++;
    pthread_mutex_unlock(&message_collection_mutex);
}

// Retrieve a message by index
LTE_NAS_Message* get_message(int index) {
    if (index >= 0 && index < message_count) {
        pthread_mutex_lock(&message_collection_mutex);
        LTE_NAS_Message* message = &messages[index];
        pthread_mutex_unlock(&message_collection_mutex);
        return message;
    } else {
        printf("Error: Invalid message index.\n");
        exit(1);
    }
}

// Serialize the message collection to a file
int serialize_messages(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error: Unable to open file for writing.\n");
        return 1;
    }

    fwrite(&message_count, sizeof(int), 1, file);
    for (int i = 0; i < message_count; i++) {
        LTE_NAS_Message* message = &messages[i];
        fwrite(message->NAS_Message_ID, MESSAGE_ID_SIZE, 1, file);
        fwrite(message->Message, MESSAGE_SIZE, 1, file);
        fwrite(&message->Priority, PRIORITIY_SIZE, 1, file);
    }

    fclose(file);
    return 0;
}

// Deserialize the message collection from a file
int deserialize_messages(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error: Unable to open file for reading.\n");
        return 1;
    }

    int message_count_temp;
    fread(&message_count_temp, sizeof(int), 1, file);
    messages = realloc(messages, sizeof(LTE_NAS_Message) * message_count_temp);

    for (int i = 0; i < message_count_temp; i++) {
        LTE_NAS_Message* message = &messages[i];
        fread(message->NAS_Message_ID, MESSAGE_ID_SIZE, 1, file);
        fread(message->Message, MESSAGE_SIZE, 1, file);
        fread(&message->Priority, PRIORITIY_SIZE, 1, file);
    }

    fclose(file);
    return 0;
}

// Print the message collection
void print_messages() {
    for (int i = 0; i < message_count; i++) {
        LTE_NAS_Message* message = &messages[i];
        printf("Message ID: %s\n", message->NAS_Message_ID);
        printf("Message: %s\n", message->Message);
        printf("Priority: %d\n", message->Priority);
    }
}

int main() {
    // Initialize the message collection
    messages = NULL;
    message_count = 0;

    // Add messages to the collection
    for (int i = 0; i < 5; i++) {
        LTE_NAS_Message* message = allocate_message();
        strcpy(message->NAS_Message_ID, "Message ID");
        strcpy(message->Message, "This is a test message");
        message->Priority = i;
        add_message(message);
    }

    // Serialize the message collection
    int result = serialize_messages("messages.bin");
    if (result != 0) {
        printf("Error: Serialization failed.\n");
        return 1;
    }

    // Deserialize the message collection
    result = deserialize_messages("messages.bin");
    if (result != 0) {
        printf("Error: Deserialization failed.\n");
        return 1;
    }

    // Print the deserialized message collection
    print_messages();

    return 0;
}
