#include <string.h>
#include <stdbool.h>

typedef struct {
    char* string;
    int value;
} node;

int compare(const void* a, const void* b) {
    node* na = (node*)a;
    node* nb = (node*)b;

    if (na->value > nb->value) return -1;
    else if (na->value < nb->value) return 1;
    else {
        int pa = (na->string[0] >= 'a' && na->string[0] <= 'z') ? tolower : toupper;
        int pb = (nb->string[0] >= 'a' && nb->string[0] <= 'z') ? tolower : toupper;

        char* sa = strchr(na->string, '\n');
        char* sb = strchr(nb->string, '\n');

        if (sa == NULL) {
            sa = na->string + strlen(na->string);
        }
        if (sb == NULL) {
            sb = nb->string + strlen(nb->string);
        }

        int result = pb(sa[0]) - pa(sb[0]);
        if (result != 0) return result;

        for (; sa[0] == sb[0]; sa++, sb++) {
            if (*sa < *sb) return -1;
            else if (*sa > *sb) return 1;
        }
    }

    return 0;
}

int main() {
    // Read data from file and initialize the structures
    FILE* file = fopen("data.txt", "r");
    if (file == NULL) {
        printf("Error opening file.\n");
        return -1;
    }

    node* nodes = malloc(sizeof(node)*10);
    int priorities[3] = {0, 1, 2};
    float weights[3] = {0.5f, 0.3f, 0.2f};

    // Read data from file and populate the structures
    for (int i = 0; i < 10; i++) {
        node* n = &nodes[i];
        fscanf(file, "%s %d", n->string, &n->value);

        int priority = priorities[rand() % 3];
        float weight = weights[rand() % 3];

        // Sort the nodes based on value and then priority
        qsort(nodes, sizeof(node), 10, compare);
    }

    fclose(file);

    // Print the sorted data
    for (int i = 0; i < 10; i++) {
        printf("%s %d\n", nodes[i].string, nodes[i].value);
    }

    // Free allocated memory and return a status indicator
    free(nodes);
    return 0;
}
