function runTests(label, f, asyncTests) {
  const tests = [];
  let passed = 0;
  let failed = 0;
  let totalExecutionTime = 0;

  for (const test of [f, ...asyncTests]) {
    const start = new Date().getTime();

    try {
      if (typeof test === 'function') {
        require('module-name'); // dynamically load module
        const result = test();
        if (!result || typeof result.then !== 'function') {
          tests.push({ label, passed: true });
          passed++;
          totalExecutionTime += new Date().getTime() - start;
        } else {
          result.then(() => {
            tests.push({ label, passed: true });
            passed++;
            totalExecutionTime += new Date().getTime() - start;
          }).catch((err) => {
            tests.push({ label, error: err, passed: false });
            failed++;
            totalExecutionTime += new Date().getTime() - start;
          });
        }
      } else {
        throw new Error('Invalid test function');
      }

      // unload module after test execution
      delete require.cache['module-name'];
    } catch (err) {
      tests.push({ label, error: err, passed: false });
      failed++;
      totalExecutionTime += new Date().getTime() - start;
    }
  }

  console.log(`Total tests executed: ${tests.length}`);
  console.log(`Passed tests: ${passed}`);
  console.log(`Failed tests: ${failed}`);
  console.log(`Average execution time per test: ${totalExecutionTime / tests.length} ms`);
}

