#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_OFFSET_SIZE 1024
#define MAX_KEY_SIZE 256
#define MIN_RANDOM_VALUE 1
#define MAX_RANDOM_VALUE 1000
#define TOTAL_MEMORY_LIMIT 4096

struct Record {
    int key;
    long offset;
    int value;
};

void* manage_memory(int num_keys, int* offsets, int* keys) {
    struct Record* records = NULL;

    // Allocate and initialize array of long integers representing offsets
    if ((offsets = (int*)malloc(MAX_OFFSET_SIZE * sizeof(long))) == NULL) {
        fprintf(stderr, "Error: Unable to allocate memory for offsets.\n");
        return NULL;
    }
    for (int i = 0; i < num_keys; ++i) {
        offsets[i] = rand() % MAX_RANDOM_VALUE;
    }

    // Allocate and initialize array of int integers representing keys
    if ((keys = (int*)malloc(MAX_KEY_SIZE * sizeof(int))) == NULL) {
        fprintf(stderr, "Error: Unable to allocate memory for keys.\n");
        free(offsets);
        return NULL;
    }
    for (int i = 0; i < num_keys; ++i) {
        keys[i] = rand() % MAX_RANDOM_VALUE;
    }

    // Allocate and initialize array of struct Record
    if ((records = (struct Record*)malloc(num_keys * sizeof(struct Record))) == NULL) {
        fprintf(stderr, "Error: Unable to allocate memory for records.\n");
        free(offsets);
        free(keys);
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < num_keys; ++i) {
        records[i].key = rand() % MAX_RANDOM_VALUE;
        records[i].offset = offsets[i];
        records[i].value = rand() % MAX_RANDOM_VALUE;
    }

    // Check if total memory allocated does not exceed the limit
    if (num_keys * sizeof(long) + num_keys * sizeof(int) + num_keys * sizeof(struct Record) > TOTAL_MEMORY_LIMIT) {
        fprintf(stderr, "Error: Total memory allocation exceeds the limit.\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Check if all allocations succeed
    if (offsets == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    return records;
}
