record* read_and_parse_data(const char* filename, int* num_records) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL; // handle error

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    rewind(file);

    *num_records = (int)(size / sizeof(record));

    record* data = (record*)malloc(*num_records * sizeof(record));
    if (!data) {
        fclose(file);
        return NULL; // handle error
    }

    fread(data, sizeof(record), *num_records, file);
    fclose(file);

    return data;
}

