    int sum = 0;
    for (int i = num_records - 3; i < num_records; i++) {
        sum += data[i].value;
    }
    float avg = (float)sum / 3.0f;
    printf("Average: %f\n", avg);

    // compute and print maximum value among the last five numerical fields
    int max = data[num_records - 5].value;
    for (int i = num_records - 4; i < num_records; i++) {
        if (data[i].value > max) max = data[i].value;
    }
    printf("Max: %d\n", max);
}

