        offsets[i] = i * 2;
    }

    for (size_t i = 0; i < MAX_KEY_SIZE; i++) {
        keys[i] = i % 256;
    }

    srand(time(NULL)); // Initialize random number generator
    for (size_t i = 0; i < MAX_KEY_SIZE; i++) {
        records[i].value = rand() % (MAX_RANDOM_VALUE - MIN_RANDOM_VALUE + 1) + MIN_RANDOM_VALUE;
    }

    // Check if total memory usage exceeds the limit
    size_t total_size = offset_size + key_size + record_size * MAX_KEY_SIZE;
    if (total_size > TOTAL_MEMORY_LIMIT) {
        // Handle memory allocation failure
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Return pointer to the first element of records array
    return records;
}
