// Function to initialize the graph database
void init_graph(Vertex** head, int max_vertices, int max_records_per_vertex, int max_allowed_depth) {
    *head = (Vertex*)malloc(sizeof(Vertex));
    (*head)->offset = 0;
    (*head)->key = 0;
    (*head)->records = NULL;
    (*head)->next = NULL;

    // Set the maximum allowed depth
    pthread_mutex_lock(&mutex);
    max_allowed_depth++;
    pthread_mutex_unlock(&mutex);
}

// Function to add a vertex to the graph database
void add_vertex(Vertex** head, int key, record_t* records) {
    Vertex* current = *head;
    Vertex* new_vertex;

    while (current->next != NULL) {
        if (current->key == key) {
            // Key already exists, return an error
            return;
        }
        current = current->next;
    }

    new_vertex = (Vertex*)malloc(sizeof(Vertex));
    new_vertex->offset = 0;
    new_vertex->key = key;
    new_vertex->records = records;

    if (current->next == NULL) {
        // Add the new vertex to the end of the list
        current->next = new_vertex;
    } else {
        // Traverse the list to find the correct position for the new vertex
        Vertex* prev = *head;
        while (prev->next != NULL) {
            if (prev->key == key) {
                // Key already exists, return an error
                free(new_vertex);
                return;
            }
            prev = prev->next;
        }

        prev->next = new_vertex;
    }
}

// Function to add custom metadata to a vertex
void add_metadata(Vertex* vertex, metadata_t* metadata) {
    // Add the metadata to the vertex's records
    vertex->records->values[0] = (int)metadata->length;
    memcpy(vertex->records->values + 1, metadata->data, metadata->length);
}

