#define GRAPH_MAX_SIZE 1000000 // Max size for graph database
#define RECORD_MAX_SIZE 128     // Max size for record structure
#define KEY_TYPE int            // Key type used in the graph database

// Custom memory pool implementation
typedef struct {
    void* ptr;
    size_t size;
} memory_block;

memory_block* memory_pool = NULL;
int num_blocks = 0;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void* custom_malloc(size_t size) {
    void* ptr = NULL;
    pthread_mutex_lock(&pool_mutex);
    for (int i = 0; i < num_blocks; i++) {
        if (memory_pool[i].size >= size) {
            ptr = memory_pool[i].ptr;
            memory_pool[i].size -= size;
            break;
        }
    }
    pthread_mutex_unlock(&pool_mutex);

    // If no block found, allocate new memory
    if (!ptr) {
        ptr = malloc(size);
        memory_block* new_block = (memory_block*)malloc(sizeof(memory_block));
        new_block->ptr = ptr;
        new_block->size = size;
        pthread_mutex_lock(&pool_mutex);
        memory_pool = (memory_block*)realloc(memory_pool, (num_blocks + 1) * sizeof(memory_block));
        memory_pool[num_blocks++] = *new_block;
        pthread_mutex_unlock(&pool_mutex);
    }

    return ptr;
}

void custom_free(void* ptr) {
    pthread_mutex_lock(&pool_mutex);
    for (int i = 0; i < num_blocks; i++) {
        if (memory_pool[i].ptr == ptr) {
            memory_pool[i].size += strlen(ptr);
            break;
        }
    }
    pthread_mutex_unlock(&pool_mutex);
}

