// Vertex and edge data structures
typedef struct {
    long offset;
    int key;
    record_t *records;
} vertex_t, edge_t;

// Graph data structure
typedef struct {
    vertex_t *vertices;
    edge_t *edges;
} graph_t;

// Function to initialize and manage the graph database
int init_graph(graph_t **graph_p, char *log_file) {
    // Initialize the graph
    *graph_p = (graph_t *)malloc(sizeof(graph_t));
    if (*graph_p == NULL)
        return -1; // Allocation failed

    // Initialize the vertices and edges arrays
    (*graph_p)->vertices = (vertex_t *)malloc(max_vertices * sizeof(vertex_t));
    (*graph_p)->edges = (edge_t *)malloc(max_edges * sizeof(edge_t));

    // Initialize the log file
    if (log_file) {
        FILE *log_fd = fopen(log_file, "a");
        if (log_fd == NULL)
            return -1; // Log file initialization failed

        (*graph_p)->log_fd = log_fd;
    } else {
        (*graph_p)->log_fd = NULL;
    }

    return 0; // Initialization successful
}

// Function to add vertices and edges to the graph database
int add_vertices_and_edges(graph_t *graph, int num_vertices, int num_edges) {
    // Allocate memory for new vertices and edges
    vertex_t *new_vertices = (vertex_t *)malloc(num_vertices * sizeof(vertex_t));
    edge_t *new_edges = (edge_t *)malloc(num_edges * sizeof(edge_t));

    // Initialize the new vertices and edges
    for (int i = 0; i < num_vertices; i++) {
        new_vertices[i].offset = rand() % max_graph_size;
        new_vertices[i].key = rand() % 100;
        new_vertices[i].records = (record_t *)malloc(sizeof(record_t));
        // Set record value to a random value within the given range
        new_vertices[i].records->value = rand() % 256;

        // Add vertex to graph and log operation
        fwrite("Vertex added: ", sizeof(char), 14, graph->log_fd);
        fprintf(graph->log_fd, "%d\n", i);

        // Add edge to graph and log operation
        for (int j = 0; j < num_edges; j++) {
            new_edges[j].offset = rand() % max_graph_size;
            new_edges[j].key = rand() % 100;
            new_edges[j].records = (record_t *)malloc(sizeof(record_t));
            // Set record value to a random value within the given range
            new_edges[j].records->value = rand() % 256;

            // Add edge to graph and log operation
            fwrite("Edge added: ", sizeof(char), 10, graph->log_fd);
            fprintf(graph->log_fd, "%d - %d\n", i, j);

            // Update the vertices array
            for (int k = 0; k < num_vertices; k++) {
                if (new_edges[j].key == new_vertices[k].key) {
                    new_vertices[k].records = new_edges[j].records;
                    break;
                }
            }
        }
    }

    return 0; // Operation successful
}

