        try {
            Map<String, Object> config = mapper.readValue(new File(file), mapper.getTypeFactory().constructMapType(Map.class));
            for (String key : config.keySet()) {
                Object value = config.get(key);
                if (value instanceof Map) {
                    cache.put(key, new DynamicConfig(value.toString()));
                } else {
                    configMap.put(key, value);
                }
            }
        } catch (IOException e) {
            // handle loading error
        }
