        try {
            Map<String, Object> config = new HashMap<>();
            for (String key : configMap.keySet()) {
                Object value = configMap.get(key);
                if (value instanceof DynamicConfig) {
                    config.put(key, ((DynamicConfig)value).getConfig());
                } else {
                    config.put(key, value);
