        }

        private void cacheEntry(String key, Object value) {
            queue.add(new CacheEntry(key, value));
            if (queue.size() > 1000) { // adjust size based on memory usage and access patterns
                evict();
            }
        }

        public Object get(String key) {
            for (CacheEntry entry : queue) {
                if (entry.getKey().equals(key)) {
                    return entry.getValue();
                }
            }
            return null;
        }

        private void evict() {
            // implement adaptive LRU eviction policy
        }
    }

