    pthread_mutex_t lock;
    int num_vertices;
    Vertex** vertices;
    int num_edges;
    Edge** edges;
    char* storage_path;
    // Other necessary variables and data structures...
} GraphDB;

// Function to efficiently manage addition and modification of vertices and edges
void graphdb_manage(GraphDB* db, int action) {
    pthread_mutex_lock(&db->lock);

    if (action == GRAPH_DB_ADD_VERTEX) {
        Vertex* vertex = malloc(sizeof(Vertex));
        // Initialize vertex data...
        db->num_vertices++;
        db->vertices = realloc(db->vertices, sizeof(Vertex*) * (db->num_vertices + 1));
        db->vertices[db->num_vertices - 1] = vertex;
    } else if (action == GRAPH_DB_REMOVE_VERTEX) {
        int idx = find_vertex_by_id(db->vertices, db->num_vertices);
        if (idx != -1) {
            free(db->vertices[idx]);
            memmove(&db->vertices[idx], &db->vertices[idx + 1], sizeof(Vertex*) * (db->num_vertices - idx - 1));
            db->num_vertices--;
            db->vertices = realloc(db->vertices, sizeof(Vertex*) * (db->num_vertices + 1));
        }
    } else if (action == GRAPH_DB_ADD_EDGE) {
        Edge* edge = malloc(sizeof(Edge));
        // Initialize edge data...
        db->num_edges++;
        db->edges = realloc(db->edges, sizeof(Edge*) * (db->num_edges + 1));
        db->edges[db->num_edges - 1] = edge;
    } else if (action == GRAPH_DB_REMOVE_EDGE) {
        int idx = find_edge_by_id(db->edges, db->num_edges);
        if (idx != -1) {
            free(db->edges[idx]);
            memmove(&db->edges[idx], &db->edges[idx + 1], sizeof(Edge*) * (db->num_edges - idx - 1));
            db->num_edges--;
            db->edges = realloc(db->edges, sizeof(Edge*) * (db->num_edges + 1));
        }
    }

    pthread_mutex_unlock(&db->lock);
}

