    int data_size = 100;

    SensorData* sensor_data = initialize_sensor_data(data_size);

    for(int i = 0; i < data_size; i++) {
        sensor_data[i].timestamp = i * 60; // simulate timestamp in seconds
        strcpy(sensor_data[i].sensor_id, "Sensor_");
        sensor_data[i].temperature = (float)(rand() % 100) / 10.0f;
    }

    for(int i = 0; i < T; i++) {
