void init_cipher(int seed, unsigned char **key, unsigned char **iv) {
    EVP_PKEY *pkey = EVP_pkey_new();
    if (!pkey) {
        return;
    }

    // Generate a secure hash function for the key
    const EVP_MD *md = EVP_md_sha256();
    unsigned char *hash_key = (unsigned char *)malloc(EVP_MAX_MD_SIZE);
    unsigned int hash_len = 0;
    EVP_PKEY_hash(pkey, hash_key, &hash_len);

    *key = (unsigned char *)malloc(hash_len);
    memcpy(*key, hash_key, hash_len);
    free(hash_key);

    // Generate an initialization vector of a variable length
    int iv_len = rand() % 16 + 7; // Random IV length between 7 and 23 bytes
    *iv = (unsigned char *)malloc(iv_len);
    for (int i = 0; i < iv_len; i++) {
        (*iv)[i] = (char)(rand() & 0xFF);
    }

    EVP_PKEY_free(pkey);
}

void cleanup_cipher(unsigned char *key, unsigned char *iv) {
    if (key) free(key);
    if (iv) free(iv);
}
