class Event {
public:
    std::string identifier;
    int timestamp;
    // Polymorphic payload (nested object)
};

class Node {
public:
    Event event;
    Node* prev, *next;

    Node(Event e) : event(e), prev(nullptr), next(nullptr) {}
};

class DoublyLinkedList {
private:
    Node* head, *tail;

public:
    DoublyLinkedList() : head(nullptr), tail(nullptr) {}

    void push_back(Event e) {
        Node* node = new Node(e);
        if (!head) {
            head = node;
            tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
    }

    void remove(Node* node) {
        if (node == head) {
            head = node->next;
        }
        if (node == tail) {
            tail = node->prev;
        }
        if (node->prev) {
            node->prev->next = node->next;
        }
        if (node->next) {
            node->next->prev = node->prev;
        }
        delete node;
    }

    void clear() {
        while (head) {
            Node* temp = head;
            head = head->next;
            delete temp;
        }
        tail = nullptr;
    }
};

class Configuration {
public:
    int event_queue_size;
    int max_payload_depth;

    Configuration(int size, int depth) : event_queue_size(size), max_payload_depth(depth) {}
};

class MemoryAllocator {
private:
    std::mutex mtx;
    std::condition_variable cv;
    int allocation_count = 0;
    int total_allocation_size = 0;

public:
    void* allocate(size_t size) {
        std::unique_lock<std::mutex> lock(mtx);
        while (true) {
            if (cv.wait_for(lock, std::chrono::milliseconds(100)) == std::cv_status::timeout) {
                // Handle allocation failure
                if (total_allocation_size > 0) {
                    void* ptr = (void*)std::malloc(total_allocation_size);
                    total_allocation_size -= size;
                    return ptr;
                } else {
                    return nullptr; // Out of memory
                }
            }
        }
    }

    void deallocate(void* ptr, size_t size) {
        std::unique_lock<std::mutex> lock(mtx);
        total_allocation_size += size;
        cv.notify_all();
    }
};

