#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 1024 // in kilobytes
#define INITIAL_VERTEX_SIZE 16
#define NUM_FIELDS 5

typedef struct {
    int num[NUM_FIELDS];
} Vertex;

typedef struct {
    Vertex* vertices;
    int size;
    pthread_mutex_t lock;
} Graph;

Graph* create_graph() {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->vertices = (Vertex*)calloc(INITIAL_VERTEX_SIZE, sizeof(Vertex));
    graph->size = INITIAL_VERTEX_SIZE;
    pthread_mutex_init(&graph->lock, NULL);
    return graph;
}

void insert_vertex(Graph* graph) {
    Vertex* new_vertices = (Vertex*)realloc(graph->vertices, (graph->size + 1) * sizeof(Vertex));
    if (!new_vertices) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    graph->vertices = new_vertices;
    graph->size++;
}

void delete_vertex(Graph* graph, int index) {
    Vertex* new_vertices = (Vertex*)calloc(graph->size - 1, sizeof(Vertex));
    memcpy(new_vertices, graph->vertices, (index) * sizeof(Vertex));
    memcpy(&new_vertices[index], &graph->vertices[index + 1], (graph->size - index - 1) * sizeof(Vertex));
    free(graph->vertices);
    graph->vertices = new_vertices;
    graph->size--;
}

void print_graph(Graph* graph) {
    for (int i = 0; i < graph->size; i++) {
        printf("Vertex %d: ", i);
        for (int j = 0; j < NUM_FIELDS; j++) {
            printf("%d, ", graph->vertices[i].num[j]);
        }
        printf("\n");
    }
}

void* thread_func(void* arg) {
    Graph* graph = (Graph*)arg;
    // perform operations on the graph
    return NULL;
}

int main(int argc, char** argv) {
    int max_memory_usage = atoi(argv[1]);
    int initial_vertex_size = atoi(argv[2]);

    Graph* graph = create_graph();

    // allocate memory for records from binary log file
    FILE* file = fopen("log_file", "rb");
    if (!file) {
        printf("Failed to open file\n");
        exit(1);
    }
    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    rewind(file);

    char* buffer = (char*)malloc(size);
    fread(buffer, 1, size, file);
    fclose(file);

    // process records
    Vertex* vertex;
    for (int i = 0; i < size / sizeof(Vertex); i++) {
        vertex = (Vertex*)malloc(sizeof(Vertex));
        memcpy(vertex, buffer + i * sizeof(Vertex), sizeof(Vertex));
        insert_vertex(graph);
    }

    free(buffer);

    // print results
    printf("Comma-separated format of all fields: ");
    for (int i = 0; i < graph->size; i++) {
        for (int j = 0; j < NUM_FIELDS; j++) {
            printf("%d, ", graph->vertices[i].num[j]);
        }
        printf("\n");
    }

    int last_three_sum = 0;
    for (int i = graph->size - 3; i >= 0; i--) {
        last_three_sum += graph->vertices[i].num[0];
    }
    printf("Average value of the last three numerical fields: %d\n", last_three_sum / 3);

    int max_last_five = INT_MIN;
    for (int i = graph->size - 5; i >= 0; i--) {
        if (graph->vertices[i].num[0] > max_last_five) {
            max_last_five = graph->vertices[i].num[0];
        }
    }
    printf("Maximum value among the last five numerical fields: %d\n", max_last_five);

    return 0;
}
