log_entry** init_log_entries(int num_entries, int max_size) {
    log_entry** entries = (log_entry**)malloc(num_entries * sizeof(log_entry*));
    for (int i = 0; i < num_entries; i++) {
        entries[i] = (log_entry*)malloc(sizeof(log_entry));
        entries[i]->record = (record*)malloc(sizeof(record));
    }
    return entries;
}

void free_log_entries(log_entry** entries, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        free(entries[i]->record);
        free(entries[i]);
    }
    free(entries);
}

record* generate_record(int status, float value) {
    record* rec = (record*)malloc(sizeof(record));
    rec->status = status;
    rec->value = value;
    return rec;
}

log_entry* generate_log_entry(float system_load, int status, float value) {
    log_entry* entry = (log_entry*)malloc(sizeof(log_entry));
    entry->value = calculate_value(system_load, status);
    entry->record = generate_record(status, value);
    return entry;
}

float calculate_value(int system_load, int status) {
    // formula based on system metrics and status indicator
    float value = system_load * 0.1 + (status > 0 ? 5 : -2);
    return value;
}

int main() {
    int num_entries = 100;
    int max_size = 1024;
    log_entry** entries = init_log_entries(num_entries, max_size);

    // use and free the log entries

    free_log_entries(entries, num_entries);
    return 0;
}
