namespace beast = boost::beast;
namespace asio = boost::asio;

class SandeshClient {
public:
    SandeshClient(asio::io_context& ioc, size_t maxConcurrentRequests) 
        : ioc_(ioc), maxConcurrentRequests_(maxConcurrentRequests),
          threadPool_(maxConcurrentRequests_ / 4 + 1),
          workerThreads_(maxConcurrentRequests_ / 4 + 1) {
        for (int i = 0; i < maxConcurrentRequests_; i++) {
            threads_.emplace_back([this]() { run(); });
        }
    }

    void start() {
        for (auto& th : threads_) {
            th.join();
        }
    }

private:
    asio::io_context& ioc_;
    size_t maxConcurrentRequests_;
    std::vector<std::thread> threads_;
    std::mutex threadMutex_;
    std::condition_variable threadCondition_;
    std::atomic<int> currentThreadCount_(0);
    std::atomic<int> maxThreadPoolSize_(maxConcurrentRequests_ / 4 + 1);

    void run() {
        while (true) {
            // Handle GET requests
            beast::http::request<beast::http::string_body> req;
            req.method(beast::http::verb::get);
            req.version(11);
            req.target("/");

            auto ep = ioc_.io_service().accept([this](boost::asio::yield_context yield, asio::ip::tcp::socket sock) {
                // Handle connection
                beast::flat_buffer buffer;
                beast::http::request<beast::http::string_body> request;
                beast::http::response<beast::http::string_body> response;

                try {
                    beast::http::read(sock, buffer, request);
                    beast::http::write(sock, response);
                } catch (const std::exception& e) {
                    // Handle errors
                }
            });

            // Update thread pool size based on current load
            if (currentThreadCount_.load() < maxThreadPoolSize_ - 1) {
                ioc_.io_service().execute([this]() {
                    for (int i = 0; i < 2; i++) {
                        threads_.emplace_back([this]() { run(); });
                    }
                });
            } else if (currentThreadCount_.load() > maxThreadPoolSize_ + 1) {
                std::unique_lock<std::mutex> lock(threadMutex_);
                while (maxThreadPoolSize_ < currentThreadCount_.load()) {
                    threadCondition_.wait_for(lock, std::chrono::milliseconds(500));
                    ioc_.io_service().execute([this]() {
                        for (int i = 0; i < 2; i++) {
                            threads_.emplace_back([this]() { run(); });
                        }
                    });
                }
            }

            // Release the thread
            currentThreadCount_.fetch_sub(1);
        }
    }
};

int main() {
    asio::io_context ioc;
    SandeshClient client(ioc, 5000);

    client.start();
}
