// Define the product structure
typedef struct {
    int id;
    char *name;
    int quantity;
    float price;
} Product;

// Function to create a new product
Product *create_product(int id, char *name, int quantity, float price) {
    Product *new_product = (Product *)malloc(sizeof(Product));
    new_product->id = id;
    new_product->name = (char *)malloc((strlen(name) + 1) * sizeof(char));
    strcpy(new_product->name, name);
    new_product->quantity = quantity;
    new_product->price = price;
    return new_product;
}

// Function to add a product
void add_product(Product **products, int *size, Product *new_product) {
    if (*size == 0) {
        *products = (Product **)malloc(sizeof(Product *));
        (*products)[0] = new_product;
        *size = 1;
    } else {
        Product **temp_products = (Product **)realloc(*products, (*size + 1) * sizeof(Product *));
        temp_products[*size] = new_product;
        *products = temp_products;
        *size += 1;
    }
}

// Function to update a product
void update_product(Product **products, int *size, Product *new_product) {
    for (int i = 0; i < *size; i++) {
        if (products[i]->id == new_product->id) {
            products[i]->name = (char *)malloc((strlen(new_product->name) + 1) * sizeof(char));
            strcpy(products[i]->name, new_product->name);
            products[i]->quantity = new_product->quantity;
            products[i]->price = new_product->price;
        }
    }
}

// Function to remove a product
void remove_product(Product **products, int *size, int id) {
    for (int i = 0; i < *size; i++) {
        if (products[i]->id == id) {
            for (int j = i + 1; j < *size; j++) {
                products[i] = products[j];
                i++;
            }
            free(products[(*size) - 1]);
            *size -= 1;
            return;
        }
    }
}

// Function to search for a product by name
Product *search_product_by_name(Product **products, int size, char *name) {
    for (int i = 0; i < size; i++) {
        if (strncasecmp(products[i]->name, name, strlen(name)) == 0) {
            return products[i];
        }
    }
    return NULL;
}

// Function to list all products sorted by price
void list_products(Product **products, int size) {
    Product *temp = products[0];
    for (int i = 1; i < size; i++) {
        if (temp->price < products[i]->price) {
            temp = products[i];
        }
    }
    printf("ID\tName\tQuantity\tPrice\n");
    for (int i = 0; i < size; i++) {
        printf("%d\t%s\t%d\t%f\n", products[i]->id, products[i]->name, products[i]->quantity, products[i]->price);
    }
}

// Function to track total quantity
void track_total_quantity(Product **products, int size) {
    int total_quantity = 0;
    for (int i = 0; i < size; i++) {
        total_quantity += products[i]->quantity;
    }
    printf("Total Quantity: %d\n", total_quantity);
}

// Function to handle API failures
void handle_api_failure() {
    // TO DO: implement strategy to buffer changes locally when the API is unavailable
}

int main() {
    Product *products = NULL;
    int size = 0;

    // Create products and add them to the collection
    Product *product1 = create_product(1, "Product A", 100, 10.99);
    Product *product2 = create_product(2, "Product B", 200, 19.99);
    add_product(&products, &size, product1);
    add_product(&products, &size, product2);

    // Update a product
    Product *updated_product = create_product(1, "New Product A", 150, 12.99);
    update_product(&products, &size, updated_product);
    free(updated_product->name);

    // Remove a product
    remove_product(&products, &size, 2);

    // Search for a product by name
    Product *found_product = search_product_by_name(products, size, "Product A");
    if (found_product) {
        printf("Found product: %s\n", found_product->name);
    } else {
        printf("Product not found.\n");
    }

    // List all products sorted by price
    list_products(products, size);

    // Track total quantity
    track_total_quantity(products, size);

    return 0;
}
