public class TransactionProcessor
{
    private readonly List<IDatabaseConnection> _connections = new();
    private readonly Dictionary<string, SemaphoreSlim> _semaphores = new();

    public async Task ProcessTransactions(List<Transaction> transactions)
    {
        foreach (var transaction in transactions)
        {
            await ProcessTransaction(transaction);
        }
    }

    private async Task ProcessTransaction(Transaction transaction)
    {
        string connectionString = GetConnectionString(transaction.AccountId);
        IDatabaseConnection connection = _connections.Find(c => c.ConnectionString == connectionString);

        if (connection == null)
        {
            connection = CreateDatabaseConnection(connectionString);
            _connections.Add(connection);
        }

        SemaphoreSlim semaphore = _semaphores.GetValueOrDefault(connectionString, new SemaphoreSlim(1));
        await semaphore.WaitAsync();

        try
        {
            using (var command = new SqlCommand(transaction.SqlCommand, connection))
            {
                var result = await ExecuteCommand(command);

                if (result)
                {
                    transaction.Status = TransactionStatus.Success;
                }
                else
                {
                    transaction.Status = TransactionStatus.Failure;
                    transaction.ErrorMessage = "Error executing SQL command";
                }
            }
        }
        catch (Exception ex)
        {
            transaction.Status = TransactionStatus.Failure;
            transaction.ErrorMessage = $"Error processing transaction: {ex.Message}";
        }
        finally
        {
            semaphore.Release();
        }
    }

    private string GetConnectionString(string accountID)
