    entry->timestamp = time(NULL);
    for (int i = 0; i < ENTRY_MAX_LENGTH; i++) {
        entry->buffer[i] = 'A' + rand() % 26;
    }
    return NULL;
}

void remove_entry(int index) {
    if (index >= num_entries || index < 0) return;
    pthread_mutex_lock(&mutex);
    for (int i = index; i < num_entries - 1; i++) {
        entries[i] = entries[i + 1];
    }
    num_entries--;
    pthread_mutex_unlock(&mutex);
}

void compress_entry(entry_t* entry, int threshold) {
    // Compress buffer if it exceeds the threshold
    for (int i = 0; i < ENTRY_MAX_LENGTH; i++) {
        if (entry->buffer[i] > threshold) {
            // Use a compression algorithm here
        }
    }
}

