void* handle_update(void* arg) {
    size_t new_max_entries = 0;
    while (1) {
        pthread_mutex_lock(&mutex);
        if (num_entries >= max_entries) {
            new_max_entries = num_entries * 2 + 1;
            max_entries = new_max_entries;
            size_t total_memory_required = (new_max_entries * sizeof(entry_t)) + TIMESTAMP_SIZE + META_DATA_SIZE;
            if (total_memory_required / 1024 > total_memory_limit_kb) {
                pthread_mutex_unlock(&mutex);
                return NULL; // Update failed, clean up
            }
        }
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&mutex);
    }
}

void* handle_insert(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        if (num_entries >= max_entries) {
            // Handle update required, trigger a new thread to handle the update
            pthread_t thread;
            pthread_create(&thread, NULL, &handle_update, NULL);
            pthread_cond_wait(&cond, &mutex);
        }
        entry_t* new_entry = malloc(sizeof(entry_t));
        if (!new_entry) {
            // Handle memory allocation failure
        }
        insert_entry(new_entry);
        entries[num_entries++] = *new_entry;
        pthread_mutex_unlock(&mutex);
    }
}

void* handle_delete(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        int key;
        // Get the key to delete
        if (num_entries > 0) {
            remove_entry(0); // Delete from the front
        }
        pthread_mutex_unlock(&mutex);
    }
}

void run_concurrent_inserts(int num_threads, int num_operations_per_thread) {
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, &handle_insert, NULL);
