    void* ptr = malloc(size);
    if (!ptr && !name) {
        perror(name);
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int main() {
    const int max_memory_kb = 1024; // adjust this value as needed
    const int seed = 42;

    srand(seed);

    size_t n_offsets = 1000, n_records = 5000;
    long* offsets = allocate_and_init(n_offsets * sizeof(long), "Offsets");
    if (!offsets) {
        return EXIT_FAILURE;
    }

    int* keys = allocate_and_init(n_offsets * sizeof(int), "Keys");
    if (!keys) {
        free(offsets);
        return EXIT_FAILURE;
    }

    int max_allowed_memory_kb = max_memory_kb - (n_offsets * sizeof(long) + n_offsets * sizeof(int));
    size_t required_bytes = 0;

    for (size_t i = 0; i < n_records && required_bytes <= max_allowed_memory_kb * 1024; ++i) {
        Record* record = allocate_and_init(sizeof(Record), "Records");
        if (!record) {
            free(offsets);
            free(keys);
            return EXIT_FAILURE;
        }

        record->value = rand() % 101;

        required_bytes += sizeof(Record);

        // Reuse the allocated memory if the constraint is exceeded
        if (required_bytes > max_allowed_memory_kb * 1024) {
            --i; // Decrement i to compensate for the reuse of previous allocation
            break;
        }
    }

    free(offsets);
    free(keys);

    return EXIT_SUCCESS;
}
