#include <stdio.h>
#include <stdlib.h>
#include <inttypes.h>
#include <time.h>

#define MAX_MEMORY_KB 1024
#define ALIGNMENT 8

typedef struct {
    long offset;
} Offset;

typedef struct {
    int key;
} Key;

typedef struct {
    int value;
} Record;

void manage_data_structures(int n_offsets, int n_keys, int n_records, int max_memory_kb, uint32_t seed) {
    // Calculate the total memory required
    size_t total_memory = (sizeof(Offset) * n_offsets + sizeof(Key) * n_keys + sizeof(Record) * n_records);

    if (total_memory > max_memory_kb * 1024) {
        // Reduce the size of the arrays to fit within the constraint
        int reduction_amount = (int)((total_memory - max_memory_kb * 1024) / (sizeof(Offset) + sizeof(Key) + sizeof(Record)));
        n_offsets -= reduction_amount;
        n_keys -= reduction_amount;
        n_records -= reduction_amount;

        total_memory = (sizeof(Offset) * n_offsets + sizeof(Key) * n_keys + sizeof(Record) * n_records);
    }

    // Allocate and initialize the arrays
    Offset* offsets = aligned_alloc(sizeof(Offset), n_offsets);
    if (!offsets) {
        fprintf(stderr, "Error allocating memory for offsets.\n");
        return;
    }
    for (int i = 0; i < n_offsets; i++) {
        offsets[i].offset = i * ALIGNMENT;
    }

    Key* keys = aligned_alloc(sizeof(Key), n_keys);
    if (!keys) {
        fprintf(stderr, "Error allocating memory for keys.\n");
        free(offsets);
        return;
    }
    for (int i = 0; i < n_keys; i++) {
        keys[i].key = i % MAX_MEMORY_KB;
    }

    Record* records = aligned_alloc(sizeof(Record), n_records);
    if (!records) {
        fprintf(stderr, "Error allocating memory for records.\n");
        free(offsets);
        free(keys);
        return;
    }
    srand(seed);
    for (int i = 0; i < n_records; i++) {
        records[i].value = rand() % 101;
    }

    // Free the allocated memory
    free(records);
    free(keys);
    free(offsets);
}

void* aligned_alloc(size_t size, size_t count) {
    void* ptr = malloc(size * count);
    if (!ptr) {
        return NULL;
    }
    size_t alignment_offset = (size_t)ptr % ALIGNMENT;
    if (alignment_offset != 0) {
        ptr = (void*)((uintptr_t)ptr + ALIGNMENT - alignment_offset);
    }
    return ptr;
}
