typedef struct {
    record_t* records;
    int capacity;
} hash_table_t;

hash_table_t* hash_table_create(int initial_capacity) {
    hash_table_t* table = malloc(sizeof(hash_table_t));
    table->records = malloc(initial_capacity * sizeof(record_t));
    table->capacity = initial_capacity;
    return table;
}

void hash_table_free(hash_table_t* table) {
    free(table->records);
    free(table);
}

int hash_function(int key, int capacity) {
    return key % capacity;
}

int linear_probe(int key, record_t** records, int capacity) {
    int i = 0;
    while (records[hash_function(key, capacity)] != NULL) {
        i++;
        key = (key + i) % capacity;
    }
    return key;
}

record_t* hash_table_get(hash_table_t* table, int key) {
    record_t** records = table->records;
    int capacity = table->capacity;

    int index = linear_probe(key, records, capacity);

    if (records[index] == NULL) {
        return NULL; // Key not found
    }

    return &records[index]->value;
}

