const express = require('express');
const app = express();
const profilesService = require('./profiles-service');
const validatorService = require('./validator-service');

app.use(express.json());

// API endpoint for updating an existing profile via HTTP PUT method
app.put('/profiles/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const profileData = req.body;

    // Validate profile data using the third-party service
    const validationResult = await validatorService.validateProfile(profileData);

    if (!validationResult.valid) {
      return res.status(400).send({ message: 'Invalid profile data' });
    }

    // Update the profile in the database, handling concurrent updates gracefully
    profilesService.updateProfile(id, profileData)
      .then(() => res.send(`Profile updated successfully`))
      .catch((error) => res.status(500).send({ message: 'Error updating profile', error }));
  } catch (error) {
    res.status(500).send({ message: 'Error processing request', error });
  }
});

// API endpoint for archiving a profile via HTTP PATCH method
app.patch('/profiles/:id/archive', async (req, res) => {
  try {
    const { id } = req.params;

    // Mark the profile as inactive in the database
    profilesService.archiveProfile(id)
      .then(() => res.send(`Profile archived successfully`))
      .catch((error) => res.status(500).send({ message: 'Error archiving profile', error }));
  } catch (error) {
    res.status(500).send({ message: 'Error processing request', error });
  }
});

// Error handling middleware
app.use((error, req, res, next) => {
  if (req.originalUrl.includes('/profiles')) {
    // Handle errors for profile-related operations
    res.status(500).send({ message: 'Error processing request' });
  } else {
    // Propagate the error to the next middleware or the HTTP server
    next(error);
  }
});

// Start the API server
const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`API server started on port ${port}`));
