typedef struct node {
    char* str;
    int val;
} Node;

typedef struct {
    Node* nodes;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NodeList;

void nodeList_init(NodeList* list, size_t capacity) {
    list->nodes = (Node*)calloc(capacity, sizeof(Node));
    list->capacity = capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void nodeList_add(NodeList* list, char* str, int val) {
    Node* node = &list->nodes[list->size++];

    if (list->size >= list->capacity) {
        list->capacity *= 2;
        Node* temp = (Node*)realloc(list->nodes, sizeof(Node) * list->capacity);
        list->nodes = temp;
    }

    node->str = strdup(str);
    node->val = val;

    pthread_mutex_unlock(&list->mutex);
}

void* nodeList_search(NodeList* list, int val) {
    Node* node;
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; i++) {
        node = &list->nodes[i];

        if (node->val == val) {
            pthread_mutex_unlock(&list->mutex);
            return (void*)node;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void nodeList_remove(NodeList* list, size_t index) {
    if (index >= list->size)
        return;

    Node* node = &list->nodes[index];

    free(node->str);

    for (size_t i = index; i < list->size - 1; i++) {
        list->nodes[i] = list->nodes[i + 1];
    }

    list->size--;

    if (list->size <= list->capacity / 4) {
        list->capacity /= 2;
        Node* temp = (Node*)realloc(list->nodes, sizeof(Node) * list->capacity);
        list->nodes = temp;
    }
}

void nodeList_free(NodeList* list) {
    for (size_t i = 0; i < list->size; i++) {
        free(list->nodes[i].str);
    }

    free(list->nodes);

    pthread_mutex_destroy(&list->mutex);
}
