    list->capacity = 4;
    list->size = 0;
    list->nodes = (Node**)calloc(list->capacity, sizeof(Node*));
    return list;
}

void list_free(NodeList* list) {
    for(size_t i = 0; i < list->size; i++) {
        free(list->nodes[i]->str);
        free(list->nodes[i]);
    }
    free(list->nodes);
    free(list);
}

Node* node_create(const char* str, int val) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->str = strdup(str);
    node->val = val;
    return node;
}

void list_add(NodeList* list, const char* str, int val) {
    if(list->size >= list->capacity) {
        list->nodes = (Node**)realloc(list->nodes, sizeof(Node*) * (list->capacity *= 2));
    }
    Node* node = node_create(str, val);
    list->nodes[list->size++] = node;
}

bool list_search(NodeList* list, int val) {
    for(size_t i = 0; i < list->size; i++) {
        if(list->nodes[i]->val == val) return true;
    }
    return false;
}

void list_remove(NodeList* list, size_t index) {
    Node** nodes = (Node**)realloc(list->nodes, sizeof(Node*) * --list->capacity);
    memmove(&nodes[index], &nodes[index+1], (list->size - index - 1) * sizeof(Node*));
    free(nodes[index]->str);
    free(nodes[index]);
}

void list_update(NodeList* list, size_t index, const char* str) {
    if(index < list->size) {
        Node* node = list->nodes[index];
        free(node->str);
        node->str = strdup(str);
    }
}
