#include <pthread.h>

// Define a node structure for storing string and integer values
typedef struct {
    char* str;
    int value;
} Node;

// Define the linked list structure with thread safety support
typedef struct {
    Node* nodes;
    int size;
    int capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} LinkedList;

// Function to create a new linked list instance
LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->nodes = NULL;
    list->size = 0;
    list->capacity = 10;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    return list;
}

// Function to add a new node to the linked list
void add_node(LinkedList* list, Node* node) {
    pthread_mutex_lock(&list->mutex);

    // Reallocate memory if the list is full
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->nodes = (Node*)realloc(list->nodes, sizeof(Node) * list->capacity);
    }

    // Add the new node to the end of the list
    list->nodes[list->size] = *node;
    list->size++;

    pthread_mutex_unlock(&list->mutex);
}

// Function to search for a node by its integer value in the linked list
Node* search_node(LinkedList* list, int value) {
    pthread_mutex_lock(&list->mutex);

    // Iterate through the nodes and find the one matching the given value
    for (int i = 0; i < list->size; i++) {
        if (list->nodes[i].value == value) {
            Node* node = &list->nodes[i];
            pthread_mutex_unlock(&list->mutex);
            return node;
        }
    }

    // If no matching node is found, return NULL
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Function to remove a node by its index in the linked list
void remove_node(LinkedList* list, int index) {
    pthread_mutex_lock(&list->mutex);

    // Check if the given index is within the valid range
    if (index < 0 || index >= list->size) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Shift all nodes to the left of the removed node one position forward
    for (int i = index; i < list->size - 1; i++) {
        list->nodes[i] = list->nodes[i + 1];
    }

    // Deallocate memory and update the size and capacity accordingly
    free(list->nodes[list->size]);
    list->size--;
    if (list->size <= list->capacity / 2) {
        list->capacity /= 2;
        list->nodes = (Node*)realloc(list->nodes, sizeof(Node) * list->capacity);
    }

    pthread_mutex_unlock(&list->mutex);
}

// Function to serialize the linked list to a file
void serialize_list(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");

    // Write the size and capacity of the linked list to the file
    fwrite(&list->size, sizeof(int), 1, file);
    fwrite(&list->capacity, sizeof(int), 1, file);

    // Serialize each node in the linked list
    for (int i = 0; i < list->size; i++) {
        Node* node = &list->nodes[i];
        fwrite(&node->value, sizeof(int), 1, file);
        fwrite(node->str, strlen(node->str) + 1, 1, file);
    }

    fclose(file);
}

// Function to deserialize the linked list from a file
LinkedList* deserialize_list(const char* filename) {
    FILE* file = fopen(filename, "rb");

    // Read the size and capacity of the linked list from the file
    int size;
    int capacity;
    fread(&size, sizeof(int), 1, file);
    fread(&capacity, sizeof(int), 1, file);

    LinkedList* list = create_list();
    list->size = size;

    // Deserialize each node in the linked list
    for (int i = 0; i < size; i++) {
        Node* node = &list->nodes[i];
        fread(&node->value, sizeof(int), 1, file);
        char* str = malloc(strlen(node->str) + 2);
        fread(str, strlen(node->str) + 1, 1, file);
        node->str = str;
    }

    fclose(file);
    return list;
}

// Function to integrate the linked list with an external database for persistent storage
void db_integration(LinkedList* list) {
    // TO DO: Implement database integration using a suitable library or API
}

int main() {
    LinkedList* list = create_list();

    // Example usage:
    Node node1 = {"Node 1", 1};
    add_node(list, &node1);

    Node node2 = {"Node 2", 2};
    add_node(list, &node2);

    Node* found_node = search_node(list, 2);
    printf("Found node: %s (%d)\n", found_node->str, found_node->value);

    remove_node(list, 0);

    serialize_list(list, "list.dat");

    LinkedList* deserialized_list = deserialize_list("list.dat");
    // TO DO: Verify the integrity and correctness of the deserialized list

    return 0;
}
