import java.util.*;
import java.io.*;

public class BackgroundTaskManager {
    private Map<String, Task> tasks;
    private int reportQuota;
    private int maxRetries;
    private int reportIntervalMinutes;
    private int taskIntervalMinutes;

    public BackgroundTaskManager(int reportQuota, int maxRetries, int reportIntervalMinutes, int taskIntervalMinutes) {
        this.tasks = new HashMap<>();
        this.reportQuota = reportQuota;
        this.maxRetries = maxRetries;
        this.reportIntervalMinutes = reportIntervalMinutes;
        this.taskIntervalMinutes = taskIntervalMinutes;

        (new Thread(() -> {
            try {
                while (true) {
                    sendReport();
                    Thread.sleep(reportIntervalMinutes * 60 * 1000);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        })).start();

        (new Thread(() -> {
            try {
                while (true) {
                    startTasks();
                    Thread.sleep(taskIntervalMinutes * 60 * 1000);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        })).start();
    }

    public void addTask(String name, int delayMinutes) {
        tasks.put(name, new Task(name, delayMinutes));
    }

    public void startTasks() {
        for (Task task : tasks.values()) {
            if (!task.isRunning()) {
                startTask(task);
            }
        }
    }

    private void startTask(Task task) {
        int retries = 0;
        while (retries <= maxRetries) {
            try {
                task.start();
                return;
            } catch (Exception e) {
                retries++;
                if (retries >= maxRetries) {
                    throw new RuntimeException("Failed to start task: " + task.getName(), e);
                }
                Thread.sleep(1000); // wait before retrying
            }
        }
    }

    private void sendReport() {
        // implement report sending logic here
    }

    public static class Task {
        private String name;
        private int delayMinutes;
        private boolean isRunning;

        public Task(String name, int delayMinutes) {
            this.name = name;
            this.delayMinutes = delayMinutes;
            this.isRunning = false;
        }

        public void start() throws Exception {
            Thread.sleep(delayMinutes * 60 * 1000);
            // implement task logic here
        }

        public boolean isRunning() {
            return isRunning;
        }
    }
}
