// Define structures for various object types
typedef struct {
    float x;
    float y;
} Point;

typedef struct {
    int width;
    int height;
} Rectangle;

typedef struct {
    int nSides;
    Point points[1024];
} Polygon;

// Custom memory pool management functions
void* my_malloc(size_t size);
void my_free(void* ptr, size_t size);

int main() {
    // Initialize the custom memory pool
    if (!my_init_pool(1024 * 1024)) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    // Initialize objects from multiple data streams
    double* doubles = my_malloc(sizeof(double) * 100);
    char* chars = my_malloc(sizeof(char) * 100);
    Point* points = my_malloc(sizeof(Point) * 100);
    Rectangle* rectangles = my_malloc(sizeof(Rectangle) * 100);
    Polygon* polygons = my_malloc(sizeof(Polygon) * 10);

    // Initialize object values randomly within given ranges
    srand(time(NULL));
    for (int i = 0; i < 100; i++) {
        switch ((i % 4)) {
            case 0:
                doubles[i] = (double)(rand() % 100);
                break;
            case 1:
                chars[i] = (char)(rand() % 256);
                break;
            case 2:
                points[i].x = (float)(rand() % 100.0f);
                points[i].y = (float)(rand() % 100.0f);
                break;
            case 3:
                rectangles[i].width = rand() % 100;
                rectangles[i].height = rand() % 100;
                break;
        }
    }

    // Dynamically resize the polygon array
    for (int i = 0; i < 10; i++) {
        polygons[i].nSides = rand() % 1024;
        for (int j = 0; j < polygons[i].nSides; j++) {
            points[j].x = (float)(rand() % 100.0f);
            points[j].y = (float)(rand() % 100.0f);
            memcpy(&polygons[i].points[j], &points[j], sizeof(Point));
        }
    }

    // Clean up allocated memory
    my_free(doubles, sizeof(double) * 100);
    my_free(chars, sizeof(char) * 100);
    my_free(points, sizeof(Point) * 100);
    my_free(rectangles, sizeof(Rectangle) * 100);
    my_free(polygons, sizeof(Polygon) * 10);

    // Deinit the custom memory pool
    my_deinit_pool();

    return 0;
}

// Custom memory allocation function (simulating manual memory management)
void* my_malloc(size_t size) {
    if (!my_pool) {
        printf("Memory pool not initialized.\n");
        return NULL;
    }

    void* ptr = my_pool->ptr + my_pool->free;
    if (size > my_pool->available) {
        printf("Insufficient memory in the pool.\n");
        return NULL;
    }

    my_pool->free += size;
    my_pool->available -= size;

    return ptr;
}

// Custom memory deallocation function
void my_free(void* ptr, size_t size) {
    if (!my_pool || !ptr) {
        printf("Invalid pointer or memory pool.\n");
        return;
    }

    my_pool->free = (char*)ptr - my_pool->ptr + size;
    my_pool->available += size;

    // Track memory usage
    printf("Freed %zu bytes, available: %zu\n", size, my_pool->available);
}

// Initialize the custom memory pool
int my_init_pool(size_t size) {
    if (size <= 0) {
        printf("Invalid pool size.\n");
        return -1;
    }

    // Allocate and initialize the memory pool structure
    my_pool = malloc(sizeof(struct {
        void* ptr;
        size_t free;
        size_t available;
    }));

    if (!my_pool) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    my_pool->ptr = malloc(size);
    if (!my_pool->ptr) {
        printf("Memory allocation failed.\n");
        free(my_pool);
        my_pool = NULL;
        return -1;
    }

    my_pool->free = size;
    my_pool->available = size;

    // Track memory usage
    printf("Initialized pool of %zu bytes, available: %zu\n", size, my_pool->available);

    return 0;
}

// Deinit the custom memory pool
void my_deinit_pool() {
    if (!my_pool) {
        printf("Memory pool not initialized.\n");
        return;
    }

    // Release all allocated resources
    free(my_pool->ptr);
    free(my_pool);

    my_pool = NULL;

    // Track memory usage
    printf("Deinitialized the memory pool.\n");
}
