    num_items = num_items;

    items = (Item**)malloc(num_items * sizeof(Item*));
    for (int i = 0; i < num_items; i++) {
        items[i] = (Item*)malloc(sizeof(Item));
        items[i]->name = (char*)malloc(20);
    }

    records = (Record**)malloc(num_records * sizeof(Record*));
    for (int i = 0; i < num_records; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
    }
}

void free_memory() {
    for (int i = 0; i < num_items; i++) {
        free(items[i]->name);
        free(items[i]);
    }

    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }

    free(items);
    free(records);
}

void* alloc_record(int key, long offset) {
    Record* record = malloc(sizeof(Record));
    if (record == NULL) return NULL;
    record->key = key;
    record->offset = offset;
    return record;
