typedef struct {
    char* string;
    int weight;
} Node;

// Define the dynamic list of nodes
typedef struct {
    Node** nodes;
    int size;
    pthread_mutex_t lock;
} NodeList;

// Initialize the dynamic list of nodes
NodeList* create_node_list() {
    NodeList* node_list = (NodeList*)malloc(sizeof(NodeList));
    node_list->size = 0;
    node_list->nodes = NULL;
    pthread_mutex_init(&node_list->lock, NULL);
    return node_list;
}

// Add a new node to the list
void add_node(NodeList* node_list, Node* node) {
    pthread_mutex_lock(&node_list->lock);

    // Check if the added string is a unique substring of the input string
    char* input_str = "input_string"; // Replace with actual input string
    for (int i = 0; i < node_list->size; i++) {
        if (strstr(node_list->nodes[i]->string, node->string) != NULL) {
            pthread_mutex_unlock(&node_list->lock);
            return;
        }
    }

    // Allocate memory for the new node and add it to the list
    Node** temp_nodes = (Node**)realloc(node_list->nodes, (node_list->size + 1) * sizeof(Node*));
    temp_nodes[node_list->size] = node;
    node_list->nodes = temp_nodes;
    node_list->size++;

    pthread_mutex_unlock(&node_list->lock);
}

// Retrieve a node by its weight
Node* get_node_by_weight(NodeList* node_list, int weight) {
    pthread_mutex_lock(&node_list->lock);

    for (int i = 0; i < node_list->size; i++) {
        if (node_list->nodes[i]->weight == weight) {
            Node* node = node_list->nodes[i];
            pthread_mutex_unlock(&node_list->lock);
            return node;
        }
    }

    pthread_mutex_unlock(&node_list->lock);
    return NULL;
}

// Refresh the input string from an external data source
void refresh_input_string(NodeList* node_list) {
    char* new_input_str = "new_input_string"; // Replace with actual updated input string

    // Update the nodes' strings to be unique substrings of the new input string
    for (int i = 0; i < node_list->size; i++) {
        Node* node = node_list->nodes[i];
        char* temp_str = strstr(new_input_str, node->string);
        if (temp_str != NULL) {
            // Reassign the new substring to the node
            free(node->string);
            node->string = strndup(temp_str, strlen(temp_str));
        }
    }
}

// Free the dynamic list of nodes
void free_node_list(NodeList* node_list) {
    pthread_mutex_lock(&node_list->lock);

    for (int i = 0; i < node_list->size; i++) {
        free(node_list->nodes[i]->string);
        free(node_list->nodes[i]);
    }

    free(node_list->nodes);
    free(node_list);

    pthread_mutex_unlock(&node_list->lock);
}
