    void initializeGraphMemory(int numRecords, int maxThresholdKB) {
        // Initialize configuration parameters
        int offsetSize = 100; // adjust this based on actual requirements
        int keySize = 10; // adjust this based on actual requirements

        // Calculate memory allocation size
        int totalMemoryNeeded = (offsetSize + keySize + sizeof(record)) * numRecords;

        if (totalMemoryNeeded > maxThresholdKB * 1024) {
            std::cerr << "Error: Total memory needed exceeds maximum threshold." << std::endl;
            return;
        }

        // Initialize memory allocation
        offsetValues = new long[offsetSize];
        keys = new int[keySize];
        records = new record[numRecords];

        // Randomize record values
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(1, 100); // adjust this based on actual requirements

        for (int i = 0; i < numRecords; ++i) {
            records[i].value = dis(gen);
        }
    }

    std::string generateRandomString(int length) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(1, 100); // adjust this based on actual requirements

        std::string randomString;

        for (int i = 0; i < length; ++i) {
            char c = static_cast<char>(dis(gen));
            randomString += c;
        }

        return randomString;
    }

private:
    struct record {
        int value;
    };

    long* offsetValues;
    int* keys;
    record* records;
};

