    srand(time(NULL));
    for (size_t i = 0; i < m; i++) {
        records[i].value = rand() % (max - min + 1) + min;
    }
    return records;
}

void handle_memory_allocation_failure(void* ptr, size_t bytes_allocated, int error_code) {
