event_log** manage_event_logs(int num_events) {
    int i, size = 10000; // initial array size
    event_log** logs = (event_log**)malloc(size * sizeof(event_log*));

    if (!logs) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (i = 0; i < size; i++) {
        logs[i] = (event_log*)malloc(sizeof(event_log));

        if (!logs[i]) {
            free(logs);
            printf("Memory allocation failed.\n");
            return NULL;
        }
    }

    // resize the array as needed
    int* current_size = &size;
    event_log*** logs_ptr = &logs;

    while (1) {
        if (*current_size <= num_events) break;

        *current_size *= 2; // double the size
        event_log** new_logs = (event_log**)realloc(*logs_ptr, *current_size * sizeof(event_log*));

        if (!new_logs) {
            free(*logs_ptr);
            printf("Memory allocation failed.\n");
            return NULL;
        }

        *logs_ptr = new_logs;
    }

    // free all allocated memory when done
    for (i = 0; i < *current_size; i++) {
        free(logs[i]->details);
        free(logs[i]);
    }

    free(*logs_ptr);
    return NULL;
}
