#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Define the maximum allowed transaction ID length
#define MAX_ID_LENGTH 32

// Structure for a transaction record
typedef struct {
    char* id;
    int amount;
    time_t timestamp;
} Transaction;

// Function to create a new transaction record
Transaction* create_transaction(char* id, int amount) {
    Transaction* trans = (Transaction*)malloc(sizeof(Transaction));
    trans->id = strdup(id);
    trans->amount = amount;
    trans->timestamp = time(NULL);
    return trans;
}

// Function to insert a new transaction at the head of the list
void insert_at_head(Transaction** head, char* id, int amount) {
    Transaction* new_trans = create_transaction(id, amount);
    if (*head == NULL || strcmp((*head)->id, id) > 0) {
        new_trans->next = *head;
        *head = new_trans;
    } else {
        Transaction* curr = *head;
        while (curr->next != NULL && strcmp(curr->next->id, id) < 0) {
            curr = curr->next;
        }
        new_trans->next = curr->next;
        curr->next = new_trans;
    }
}

// Function to insert a new transaction at the tail of the list
void insert_at_tail(Transaction** head, char* id, int amount) {
    Transaction* new_trans = create_transaction(id, amount);
    if (*head == NULL) {
        *head = new_trans;
    } else {
        Transaction* curr = *head;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_trans;
    }
}

// Function to print the details of each transaction in the list
void print_transactions(Transaction* head) {
    Transaction* curr = head;
    while (curr != NULL) {
        printf("ID: %s, Amount: %d, Timestamp: %ld\n", curr->id, curr->amount, curr->timestamp);
        curr = curr->next;
    }
}

// Function to delete a transaction record
void delete_transaction(Transaction** head, char* id) {
    if (*head == NULL) return;

    if (strcmp((*head)->id, id) == 0) {
        Transaction* temp = *head;
        *head = (*head)->next;
        free(temp->id);
        free(temp);
    } else {
        Transaction* curr = *head;
        while (curr->next != NULL && strcmp(curr->next->id, id) < 0) {
            curr = curr->next;
        }
        if (curr->next != NULL && strcmp(curr->next->id, id) == 0) {
            Transaction* temp = curr->next;
            curr->next = curr->next->next;
            free(temp->id);
            free(temp);
        }
    }
}

// Function to free all allocated memory
void free_transactions(Transaction** head) {
    while (*head != NULL) {
        Transaction* temp = *head;
        *head = (*head)->next;
        free(temp->id);
        free(temp);
    }
}
