struct record {
    int value;
};

void* xmalloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: unable to allocate memory.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void* xcalloc(size_t nmemb, size_t size) {
    void* ptr = calloc(nmemb, size);
    if (!ptr) {
        fprintf(stderr, "Error: unable to allocate memory.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void xfree(void* ptr) {
    free(ptr);
}

int allocateInitializeRecordsAndGenerateCertificate(struct record** records, int num_records, FILE* private_key_file, FILE* certificate_file, char* path) {
    *records = xcalloc(num_records, sizeof(struct record));

    for (int i = 0; i < num_records; i++) {
        (*records)[i].value = rand() % 100;
    }

    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    SSL* ssl = SSL_new(ctx);

    EVP_PKEY* pkey = EVP_pkey_new();
    FILE* pfile = fopen(path, "rb");
    if (pfile) {
        PEM_read_PrivateKey(pfile, &pkey, NULL, NULL);
        fclose(pfile);
    }

    X509* cert = d2i_X509_file(certificate_file, NULL);

    char* private_key = EVP_PKEY_print_pkey_string(pkey, 0, 0);
    char* certificate = X509_export(cert, &cert->header.length);
    free(cert);
    free(private_key);

    // Concatenate the private key and certificate strings
    size_t len = strlen(private_key) + strlen(certificate) + 1;
    char* pem_string = xmalloc(len);
    strcpy(pem_string, "-----BEGIN CERTIFICATE-----\n");
    strcat(pem_string, certificate);
    strcat(pem_string, "\n-----END CERTIFICATE-----");

    // Free allocated memory
    SSL_CTX_free(ctx);
    SSL_free(ssl);
    EVP_PKEY_free(pkey);
    free(private_key);
    free(certificate);

    return 0;
}
