#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000000 //10 million records
#define RECORD_VALUE_RANGE 1000 //range of int values in each record

typedef struct {
    int value;
} Record;

Record* records = NULL; 
int numRecords = 0; 

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; //mutex for thread safety

void initSystem(int maxNumRecords, int maxValueRange) {
    if (maxValueRange > RECORD_VALUE_RANGE || maxNumRecords > MAX_RECORDS) {
        printf("Invalid input parameters. Maximum record count is %d and value range is %d.\n", 
                MAX_RECORDS, RECORD_VALUE_RANGE);
        return;
    }

    records = (Record*)malloc(maxNumRecords * sizeof(Record));
    if (!records) {
        printf("Failed to allocate memory for the system.\n");
        return;
    }

    numRecords = maxNumRecords;
}

void addRecord(int value) {
    pthread_mutex_lock(&lock);

    if (numRecords >= MAX_RECORDS) {
        printf("Maximum record count exceeded. Cannot add more records.\n");
    } else {
        // caching mechanism to optimize memory allocations and deallocations
        if (!records[numRecords].value) {
            records[numRecords] = (Record){value};
            numRecords++;
        }
    }

    pthread_mutex_unlock(&lock);
}

void persistRecords() {
    pthread_mutex_lock(&lock);

    FILE* file = fopen("record_state.txt", "w");
    if (!file) {
        printf("Failed to open the file for writing.\n");
        return;
    }

    fwrite(records, sizeof(Record), numRecords, file);
    fclose(file);

    pthread_mutex_unlock(&lock);
}

void* threadFunc(void* arg) {
    // handle peak loads by optimizing resource consumption
    while (1) {
        addRecord(rand() % RECORD_VALUE_RANGE); // simulate record addition

        if (numRecords % 1000 == 0) { // persist records periodically
            persistRecords();
        }
    }

    return NULL;
}

int main() {
    int maxNumRecords = 10; 
    int maxValueRange = 500;

    initSystem(maxNumRecords, maxValueRange);

    pthread_t threads[MAX_RECORDS / 10]; // create multiple threads to simulate peak loads

    for (int i = 0; i < MAX_RECORDS / 10; i++) {
        pthread_create(&threads[i], NULL, threadFunc, NULL);
    }

    for (int i = 0; i < MAX_RECORDS / 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

