#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

#define MAX_TASKS 1000
#define MIN_PRIORITY 1
#define MAX_PRIORITY 5

typedef struct {
    char* name;
    int priority;
} Task;

Task* tasks[MAX_TASKS];
int task_count = 0;

void add_task(char* name, int priority) {
    if (task_count >= MAX_TASKS) {
        printf("Error: Maximum number of tasks reached.\n");
        return;
    }

    Task* new_task = (Task*)malloc(sizeof(Task));
    new_task->name = (char*)malloc(strlen(name) + 1);
    strcpy(new_task->name, name);
    new_task->priority = priority;

    if (new_task->priority < MIN_PRIORITY || new_task->priority > MAX_PRIORITY) {
        printf("Error: Invalid priority level.\n");
        free(new_task->name);
        free(new_task);
        return;
    }

    tasks[task_count] = new_task;
    task_count++;
}

void update_task(int index, char* name, int priority) {
    if (index >= task_count) {
        printf("Error: Task not found.\n");
        return;
    }

    if (!name) {
        free(tasks[index]->name);
        tasks[index]->name = NULL;
    } else {
        free(tasks[index]->name);
        tasks[index]->name = (char*)malloc(strlen(name) + 1);
        strcpy(tasks[index]->name, name);
    }

    tasks[index]->priority = priority;

    if (tasks[index]->priority < MIN_PRIORITY || tasks[index]->priority > MAX_PRIORITY) {
        printf("Error: Invalid priority level.\n");
    }
}

void delete_task(int index) {
    if (index >= task_count) {
        printf("Error: Task not found.\n");
        return;
    }

    free(tasks[index]->name);
    free(tasks[index]);
    tasks[index] = NULL;

    for (int i = index; i < task_count - 1; i++) {
        tasks[i] = tasks[i + 1];
    }
    task_count--;
}

void list_tasks() {
    if (!task_count) {
        printf("No tasks available.\n");
        return;
    }

    for (int i = 0; i < task_count; i++) {
        Task* current_task = tasks[i];
        printf("Task %d: Name - %s, Priority - %d\n", i + 1, current_task->name, current_task->priority);
    }
}

void log_tasks() {
    // Call external API to log the tasks
    for (int i = 0; i < task_count; i++) {
        Task* current_task = tasks[i];
        // Log the task details here
        printf("Task logged: Name - %s, Priority - %d\n", current_task->name, current_task->priority);
    }
}

int main() {
    add_task("Task 1", 3);
    add_task("Task 2", 4);
    add_task("Task 3", 5);

    update_task(0, "New Task Name 1", 2);

    delete_task(2);

    list_tasks();

    log_tasks();

    return 0;
}
