const W: usize = 5; // window size

fn initialize_measurement_directory() {
    let measurement_dir = get_measurement_dir();
    fs::create_dir_all(&measurement_dir).unwrap();

    let mut records = vec![];
    for _ in 0..100 { // generate random data
        let mut record = Record {
            key: rand::random::<i32>() % 100,
            value: (rand::random::<u32>() as f64 / 100.0).round() as u32,
        };
        records.push(record);
    }

    save_records(&measurement_dir, &records);
}

fn get_measurement_dir() -> PathBuf {
    let measurement_dir = match std::env::var("MEASUREMENT_DIR") {
        Ok(dir) => PathBuf::from(dir),
        Err(_) => generate_timestamped_directory(),
    };
    measurement_dir
}

fn generate_timestamped_directory() -> PathBuf {
    let timestamp = DateTime::<Utc, Utc>::now().to_rfc3339();
    let dir_name = format!("measurements-{}", timestamp);
    let path = Path::new(&dir_name);
    path.to_path_buf()
}

struct Record {
    key: i32,
    value: u32,
}

fn save_records(dir: &PathBuf, records: &[Record]) {
    for (i, record) in records.iter().enumerate() {
        let record_path = dir.join(format!("record-{}.txt", i));
        let mut file = fs::File::create(record_path).unwrap();
        writeln!(file, "Key: {}\nValue: {}", record.key, record.value).unwrap();

        // calculate checksum
        let crc = Crc32Fast::new().update(&record_path.to_string_lossy()).finalize();
        let sha256 = Sha256::new().update(&record_path.to_string_lossy()).finalize();
        writeln!(file, "CRC32: {}\nSHA-256: {}", crc, sha256).unwrap();
    }
}
