typedef struct {
    long timestamp;
    int type;
    char* details;
} event_log;

event_log** manage_logs(int num_logs) {
    event_log** logs = (event_log**)malloc(num_logs * sizeof(event_log*));
    if (!logs) return NULL;  // handle memory allocation failure

    for (int i = 0; i < num_logs; i++) {
        char* buffer = (char*)calloc(1024, sizeof(char)); // pre-allocate buffer size
        event_log* log = (event_log*)malloc(sizeof(event_log));
        if (!log || !buffer) return NULL;  // handle memory allocation failure

        log->timestamp = time(NULL);
        log->type = i;
        log->details = buffer;

        logs[i] = log;
    }

    return logs;
}

int main() {
    int num_logs = 10000;
    event_log** logs = manage_logs(num_logs);

    if (!logs) {
        printf("Failed to allocate memory!\n");
        return -1;
    }

    // use the managed log array

    for (int i = 0; i < num_logs; i++) {
        free(logs[i]->details);
        free(logs[i]);
    }
    free(logs);

    return 0;
}

