    new_record.value = value;

    if (vertex_array == NULL || vertex_array->value > 0) {
        // Allocate and initialize memory for the first vertex
        vertex_array = (record*)malloc(RECORD_SIZE);
        vertex_array->value = 0;
    }

    int i;
    for (i = 0; i < MAX_VERTEX && vertex_array[i].value == 0; i++) {}

    if (i >= MAX_VERTEX) {
        // Handle memory allocation failure
        printf("Memory allocation failure.\n");
        return;
    }

    memcpy(&vertex_array[i], &new_record, RECORD_SIZE);
