void add_edge(int from_key, int to_key) {
    int from_index = -1;
    int to_index = -1;

    if (from_key < 0 || to_key < 0 || from_key >= MAX_VERTEX || to_key >= MAX_VERTEX) {
        // Handle invalid vertex keys
        return;
    }

    for (int i = 0; i < MAX_VERTEX; i++) {
        if (vertex_array[i].value == from_key) {
            from_index = i;
        } else if (vertex_array[i].value == to_key) {
            to_index = i;
        }
