    if (from_index < 0 || to_index < 0) {
        // Handle missing vertex
        return;
    }

    long* current_offset = &edge_offsets[from_index];
    while (*current_offset <= to_index);
    *current_offset = to_index + 1;

    int edge_count = (to_index - from_index) + 1;
    for (int i = 0; i < edge_count; i++) {
        if (key_indices[from_index + i] == -1) {
            key_indices[from_index + i] = to_key;
        }
    }
