        // Initialize entry metadata
        entries[i].url = malloc(strlen(config.urls[i]) + 1);
        strcpy(entries[i].url, config.urls[i]);
        entries[i].lastAccessedTimestamp = time(NULL) - rand() % (int)config.refreshInterval;
        entries[i].freshnessStatus = (entries[i].lastAccessedTimestamp % 2 == 0);

        // Update cache index
        (*cacheIndex)[i] = i;

        initializedEntries++;
    }

    return initializedEntries;
}

void cleanupCache(int** cacheIndex, int numEntries) {
    for (int i = 0; i < numEntries; i++) {
        free(entries[i].url);
    }
    free(*cacheIndex);
    free(entries);
}
