#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int value;
} Record;

Record** initialize_records(int numRecords, long offsetRange[2], int intValueRange[2]) {
    // Initialize records array with NULL values
    Record** records = (Record**)malloc((numRecords + 1) * sizeof(Record*));
    for (int i = 0; i <= numRecords; i++) {
        records[i] = NULL;
    }

    // Partition records into chunks and process in parallel
    int chunkSize = 10000; // adjust this value based on your system's memory constraints
    pthread_t threads[numRecords / chunkSize];
    for (int i = 0; i < numRecords / chunkSize; i++) {
        int start = i * chunkSize;
        int end = (i + 1) * chunkSize > numRecords ? numRecords : (i + 1) * chunkSize;
        pthread_create(&threads[i], NULL, process_chunk, (void*)start);
    }

    // Wait for all threads to finish
    for (int i = 0; i < numRecords / chunkSize; i++) {
        pthread_join(threads[i], NULL);
    }

    return records;
}

void* process_chunk(void* arg) {
    int start = *(int*)arg;
    int end = start + 10000; // adjust this value based on your system's memory constraints

    for (int i = start; i < end; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        record->offset = (long)rand() % (offsetRange[1] - offsetRange[0]) + offsetRange[0];
        record->value = rand() % (intValueRange[1] - intValueRange[0]) + intValueRange[0];

        // Initialize log
        FILE* logFile = fopen("record_init_log.txt", "a+");
        fprintf(logFile, "[%d] Offset: %ld, Value: %d\n", i, record->offset, record->value);
        fclose(logFile);

        // Store records in the main array
        for (int j = start; j < end; j++) {
            if (!records[j]) {
                records[j] = record;
                break;
            }
        }
    }

    free(arg);
    return NULL;
}
