#include <string.h>
#include <openssl/sha.h>

#define MAX_FILENAME_LENGTH 256
#define MAX_DIRECTORY_PATH_LENGTH 256
#define MAX_NEW_FILENAME_LENGTH 512

char* generateDynamicFilename(char* originalFilename) {
    if (strlen(originalFilename) > MAX_FILENAME_LENGTH || strlen(originalFilename) == 0) {
        return NULL; // Handle error: invalid filename length
    }

    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256_ctx;
    SHA256_Init(&sha256_ctx);
    SHA256_Update(&sha256_ctx, originalFilename, strlen(originalFilename));
    SHA256_Final(hash, &sha256_ctx);

    char* hexHash = malloc((SHA256_DIGEST_LENGTH * 2) + 1);
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        sprintf(hexHash + i * 2, "%02x", hash[i]);
    }
    hexHash[SHA256_DIGEST_LENGTH * 2] = '\0';

    char* filenameParts[] = {"", "", ""};
    int partIndex = 0;

    for (int i = 0; i < strlen(originalFilename) && i < 100; i++) {
        int cValue = originalFilename[i];
        sprintf(filenameParts[partIndex++], "%d", cValue);
    }

    char* newFilename = malloc(MAX_NEW_FILENAME_LENGTH + 1);
    sprintf(newFilename, "%s_enhanced.txt", strcat(filenameParts[0], hexHash));

    free(hexHash);

    return newFilename;
}
