#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct record {
    int key;
    long offset;
    float weight;
    char status;
} Record;

typedef struct linked_list_node {
    Record* data;
    struct linked_list_node* next;
} LinkedListNode;

typedef struct linked_list {
    LinkedListNode* head;
    sem_t semaphore;
    int max_concurrent_operations;
} LinkedList;

LinkedList* linked_list_init(int max_concurrent_operations) {
    LinkedList* list = malloc(sizeof(LinkedList));
    list->head = NULL;
    sem_init(&list->semaphore, 0, 1);
    list->max_concurrent_operations = max_concurrent_operations;
    return list;
}

int linked_list_insert(LinkedList* list, Record* record) {
    if (pthread_mutex_lock(&list->semaphore)) {
        return -1; // Error allocating memory
    }

    LinkedListNode* new_node = malloc(sizeof(LinkedListNode));
    new_node->data = record;
    new_node->next = list->head;
    list->head = new_node;
    sem_post(&list->semaphore);

    return 0;
}

int linked_list_remove(LinkedList* list, int key) {
    if (pthread_mutex_lock(&list->semaphore)) {
        return -1; // Error allocating memory
    }

    LinkedListNode* current = list->head;
    LinkedListNode* previous = NULL;
    while (current != NULL && current->data->key != key) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        sem_post(&list->semaphore);
        return -1; // Record not found
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    sem_post(&list->semaphore);

    return 0;
}

int linked_list_query(LinkedList* list) {
    int active_records = 0;
    long sum_offsets = 0;
    float sum_weights = 0.0f;
    int highest_offset = 0;

    LinkedListNode* current = list->head;
    while (current != NULL) {
        if (current->data->status) {
            active_records++;
            sum_offsets += current->data->offset;
            sum_weights += current->data->weight;
            if (highest_offset < current->data->offset) {
                highest_offset = current->data->offset;
            }
        }
        current = current->next;
    }

    printf("Active records: %d\n", active_records);
    printf("Average weight: %.2f\n", sum_weights / active_records);
    printf("Highest offset: %ld\n", highest_offset);

    return 0;
}

void linked_list_log_operation(LinkedList* list, char* operation) {
    // External logging dependency
    log_operation(operation);
}

int main() {
    LinkedList* list = linked_list_init(5); // Initialize with a maximum of 5 concurrent operations

    Record record1 = {1, 1000, 2.5f, 'A'};
    Record record2 = {2, 2000, 3.8f, 'B'};
    Record record3 = {3, 3000, 1.9f, 'C'};

    linked_list_insert(list, &record1);
    linked_list_insert(list, &record2);
    linked_list_insert(list, &record3);

    linked_list_query(list); // Query the current state

    // Simulate concurrent modifications
    pthread_t thread1;
    pthread_create(&thread1, NULL, modify_record, (void*) &record1);
    pthread_t thread2;
    pthread_create(&thread2, NULL, modify_record, (void*) &record2);

    linked_list_query(list); // Query the current state again

    return 0;
}

void* modify_record(void* data) {
    Record* record = (Record*) data;
    // Simulate concurrent modification
    record->status = 'N'; // Mark as inactive
    linked_list_log_operation(list, "Modify");
    pthread_exit(NULL);
}
