#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
    long offset;
    struct node* next;
} Record;

Record* head = NULL;
int cacheSize = 1000; // adjust this to suit your memory constraints
Record** cache = NULL;

void initCache() {
    if (cache != NULL) return;
    cache = (Record**)malloc(cacheSize * sizeof(Record*));
    for (int i = 0; i < cacheSize; i++) cache[i] = NULL;
}

void addRecord(int key, long offset) {
    Record* newRecord = (Record*)malloc(sizeof(Record));
    newRecord->key = key;
    newRecord->offset = offset;
    newRecord->next = head;
    head = newRecord;

    int bucket = key % cacheSize;
    if (cache[bucket] == NULL) {
        cache[bucket] = newRecord;
    } else {
        Record* current = cache[bucket];
        while (current->next != NULL) current = current->next;
        current->next = newRecord;
    }
}

void removeRecord(int key) {
    if (head == NULL) return;

    // Search for the record in the cache
    int bucket = key % cacheSize;
    Record* current = cache[bucket];
    while (current != NULL && current->key != key) current = current->next;
    if (current == NULL || current->key != key) return; // not found

    // Remove from the linked list and update the cache
    Record* prev = head;
    if (head == current) {
        head = current->next;
    } else {
        while (prev->next != current) prev = prev->next;
    }
    prev->next = current->next;

    // Rebalance the cache
    int nextBucket = (bucket + 1) % cacheSize;
    if (cache[nextBucket] == NULL) {
        while (current->next != NULL) current = current->next;
        cache[bucket] = current->next;
        current->next = NULL;
    }
}

long getOffset(int key) {
    int bucket = key % cacheSize;
    Record* current = cache[bucket];
    while (current != NULL && current->key != key) current = current->next;
    if (current == NULL || current->key != key) return -1; // not found
    return current->offset;
}

void freeRecords() {
    Record* current = head;
    while (current != NULL) {
        Record* next = current->next;
        free(current);
        current = next;
    }
    for (int i = 0; i < cacheSize; i++) free(cache[i]);
    free(cache);
}
