#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
    size_t offset;
    size_t key;
} Record;

// Thread-safe dynamic in-memory data store structure
typedef struct {
    Record *records;
    size_t capacity;
    size_t allocated_size;
    size_t current_size;
    pthread_mutex_t mutex;
} DataStore;

DataStore *data_store_init(size_t initial_capacity, size_t max_allocated_size) {
    DataStore *ds = malloc(sizeof(DataStore));
    ds->capacity = initial_capacity;
    ds->allocated_size = initial_capacity * sizeof(Record);
    ds->records = malloc(ds->allocated_size);
    pthread_mutex_init(&ds->mutex, NULL);
    return ds;
}

void data_store_free(DataStore *ds) {
    free(ds->records);
    pthread_mutex_destroy(&ds->mutex);
    free(ds);
}

// Insert a new record into the data store
int data_store_insert(DataStore *ds, Record *record) {
    if (ds->current_size >= ds->capacity) {
        // Resize the data store if it's full
        ds->capacity *= 2;
        ds->allocated_size = ds->capacity * sizeof(Record);
        ds->records = realloc(ds->records, ds->allocated_size);
    }
    memcpy(&ds->records[ds->current_size], record, sizeof(Record));
    ds->current_size++;
    return 0;
}

// Delete a record from the data store
int data_store_delete(DataStore *ds, size_t key) {
    pthread_mutex_lock(&ds->mutex);
    for (size_t i = 0; i < ds->current_size; i++) {
        if (ds->records[i].key == key) {
            // Shift records to fill the gap
            memmove(&ds->records[i], &ds->records[i + 1], (ds->current_size - i - 1) * sizeof(Record));
            ds->current_size--;
            break;
        }
    }
    pthread_mutex_unlock(&ds->mutex);
    return 0;
}

// Update a record in the data store
int data_store_update(DataStore *ds, size_t key, Record *record) {
    pthread_mutex_lock(&ds->mutex);
    for (size_t i = 0; i < ds->current_size; i++) {
        if (ds->records[i].key == key) {
            memcpy(&ds->records[i], record, sizeof(Record));
            break;
        }
    }
    pthread_mutex_unlock(&ds->mutex);
    return 0;
}

// Persist the data store to an external database
