    fprintf(file, "value,offset,key\n");
    for (size_t i = 0; i < ds->current_size; i++) {
        Record record = ds->records[i];
        fprintf(file, "%d,%zu,%zu\n", record.value, record.offset, record.key);
    }
}

int main() {
    // Example usage:
    DataStore *ds = data_store_init(10, 1024);
    Record records[] = {
        {1, 0, 0},
        {2, 1, 1},
        {3, 2, 2}
    };
    for (size_t i = 0; i < sizeof(records) / sizeof(Record); i++) {
