    r->key = malloc(strlen(key) + 1);
    if (!r->key) {
        free(r);
        return NULL;
    }
    strcpy(r->key, key);

    return r;
}

void cleanup() {
    // Free all allocated memory
}

int main() {
    // Initialize random seed
    srand(time(NULL));

    size_t totalSize = 0;

    record* records[MAX_RECORDS];
    for (int i = 0; i < MAX_RECORDS; i++) {
        int value = rand();
        char key[11]; // Assuming 10 character key + '\0'
        sprintf(key, "%d=VALUE", value);

        record* r = createRecord(value, key);
        if (!r) {
            break;
        }

        records[i] = r;
        totalSize += sizeof(record) + strlen(key) + 1; // Calculate total size

        if (totalSize > MAX_STRING_SIZE * MAX_RECORDS) {
            printf("Memory limit exceeded.\n");
            break;
        }
    }

    return 0;
}
