#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char id;
    double value;
    char* str;
} item;

typedef struct {
    pthread_mutex_t lock;
    int size;
    item** items;
} collection;

void init_collection(collection* col, int max_size) {
    col->size = 0;
    col->items = (item**)malloc(max_size * sizeof(item*));
}

void free_collection(collection* col) {
    for(int i = 0; i < col->size; i++) {
        if(col->items[i] != NULL)
            free(col->items[i]->str);
        free(col->items[i]);
    }
    free(col->items);
}

item* add_item(collection* col, char id, double value) {
    pthread_mutex_lock(&col->lock);

    item* new_item = (item*)malloc(sizeof(item));
    new_item->id = id;
    new_item->value = value;

    // Randomly generate string
    int len = rand() % 10 + 1; // Between 1 and 10 characters
    char* str = (char*)malloc(len * sizeof(char));
    for(int i = 0; i < len; i++)
        str[i] = 'a' + rand() % 26;
    str[len] = '\0';
    new_item->str = str;

    if(col->size == col->items) {
        // Double the size of the array
        item** new_items = (item**)realloc(col->items, (col->size * 2 + 1) * sizeof(item*));
        col->items = new_items;
    }

    col->items[col->size] = new_item;
    col->size++;

    pthread_mutex_unlock(&col->lock);

    return new_item;
}

void remove_item(collection* col, char id) {
    pthread_mutex_lock(&col->lock);

    for(int i = 0; i < col->size; i++) {
        if(col->items[i]->id == id) {
            // Free the item's string and the item itself
            free(col->items[i]->str);
            free(col->items[i]);
            memmove(&col->items[i], &col->items[i+1], (col->size - i - 1) * sizeof(item*));
            col->size--;
            break;
        }
    }

    pthread_mutex_unlock(&col->lock);
}

item* get_item(collection* col, char id) {
    pthread_mutex_lock(&col->lock);

    for(int i = 0; i < col->size; i++) {
        if(col->items[i]->id == id)
            return col->items[i];
    }

    pthread_mutex_unlock(&col->lock);
    return NULL;
}
