    record_t* record;
    struct node* next;
} node_t;

node_t* list_new() {
    node_t* head = NULL;
    return head;
}

void list_free(node_t* head) {
    while (head) {
        node_t* current = head;
        head = head->next;
        free(current);
    }
}

