    .key_range_min = 1,
    .key_range_max = 1000000,
    .buffer_size_range_min = 5,
    .buffer_size_range_max = 20
};

node_t* generate_records(int num_records) {
    node_t* head = list_new();
    for (int i = 0; i < num_records; i++) {
        record_t* record = record_new();
        if (!record) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
        node_t* new_node = (node_t*)malloc(sizeof(node_t));
        new_node->record = record;
        new_node->next = head->next;
        head->next = new_node;
    }
    return head;
}

void free_records(node_t* head) {
    while (head) {
        node_t* current = head;
        head = head->next;
        record_free(current->record);
        free(current);
    }
}

int main() {
    srand(time(NULL));
    int num_records = 10000;
    node_t* head = generate_records(num_records);
    if (!head) {
        printf("Failed to generate records.\n");
        return -1;
    }
    // Use the generated records...
    free_records(head);
    return 0;
