typedef struct node {
    int id;
    char* name;
    double weight;
    struct node* next;
} Node;

void update_graph(Node** head, int new_id, char* new_name, double new_weight) {
    // implement optimistic locking and data integrity constraints
    if (new_id == 0 || strcmp(new_name, "") == 0) {
        printf("Error: Invalid input\n");
        return;
    }

    Node* node = *head;
    while (node != NULL) {
        if (node->id == new_id && strcmp(node->name, new_name) == 0) {
            // update existing node
            node->weight = new_weight;
            printf("Updated edge %d with weight %.2f\n", new_id, new_weight);
            return;
        }
        node = node->next;
    }

    // create a new node if it doesn't exist
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->id = new_id;
    new_node->name = strdup(new_name);
    new_node->weight = new_weight;
    new_node->next = *head;
    *head = new_node;

    printf("Added edge %d with weight %.2f\n", new_id, new_weight);

}

void delete_edge(Node** head, int id) {
    // implement data integrity constraints
    if (*head == NULL || id == 0) {
        printf("Error: Edge not found\n");
        return;
    }

    Node* node = *head;
    Node* prev = NULL;
    while (node != NULL && node->id != id) {
        prev = node;
        node = node->next;
    }

    if (node == NULL) {
        printf("Error: Edge not found\n");
        return;
    }

    if (prev == NULL) {
        *head = node->next;
    } else {
        prev->next = node->next;
    }

    free(node);

    printf("Deleted edge %d\n", id);
}

void serialize_graph(Node* head, char** buffer, int* buffer_size) {
    // implement custom serialization format
    char* current = *buffer;
    while (head != NULL) {
        int len = strlen(head->name) + 1;
        memcpy(current, &len, sizeof(int));
        current += sizeof(int);
        strcpy(current, head->name);
        current += len;
        *(current++) = head->weight;
        head = head->next;
    }
    *buffer_size = current - *buffer;
}

int deserialize_graph(Node** head, char* buffer, int size) {
    // implement custom deserialization format
    Node* new_node = (Node*)malloc(sizeof(Node));
    int len = 0;
    memcpy(&len, buffer, sizeof(int));
    buffer += sizeof(int);
    new_node->name = malloc(len);
    strcpy(new_node->name, buffer);
    buffer += len;
    new_node->weight = *(buffer++);
    new_node->next = *head;
    *head = new_node;

    return 0;
}

int main() {
    Node* head = NULL;
    int id = 1;
    char name[] = "A";
    double weight = 0.5;

    update_graph(&head, id, name, weight);
    serialize_graph(head, &name, &weight);

    // simulate deserialization
    deserialize_graph(&head, name, strlen(name) + sizeof(int) + sizeof(double));

    return 0;
}
