// Define a struct for job objects
typedef struct Job {
    int id;
    int priority;
    char status[10];
    void* data;
    struct Job* next;
} Job;

// Function to initialize the linked list and return the head node
Job* init_job_list() {
    Job* head = NULL;
    return head;
}

// Function to add a new job to the end of the linked list
void add_job(Job** head, int id, int priority, const char status[], void* data) {
    Job* new_job = (Job*)malloc(sizeof(Job));
    if(new_job == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    new_job->id = id;
    new_job->priority = priority;
    strcpy(new_job->status, status);
    new_job->data = data;
    new_job->next = (*head);

    if(*head == NULL) {
        *head = new_job;
    } else {
        Job* current = *head;
        while(current->next != NULL) {
            current = current->next;
        }
        current->next = new_job;
    }
}

// Function to remove a job from the linked list by ID
void remove_job(Job** head, int id) {
    if(*head == NULL) {
        printf("Job not found\n");
        return;
    }

    Job* current = *head;
    Job* prev = NULL;

    while(current != NULL && current->id != id) {
        prev = current;
        current = current->next;
    }

    if(current == NULL) {
        printf("Job not found\n");
        return;
    }

    if(prev == NULL) {
        *head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
}

// Function to print the linked list
void print_job_list(Job* head) {
    Job* current = head;
    while(current != NULL) {
        printf("ID: %d, Priority: %d, Status: %s, Data: %p\n", current->id, current->priority, current->status, current->data);
        current = current->next;
    }
}

// Function to free the linked list and its memory
void free_job_list(Job** head) {
    Job* current = *head;
    Job* next = NULL;

    while(current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    // Initialize the linked list
    Job* head = init_job_list();

    // Add jobs to the linked list
    add_job(&head, 1, 5, "Ready", (void*)"Job 1 data");
    add_job(&head, 2, 3, "Waiting", (void*)"Job 2 data");
    add_job(&head, 3, 4, "Running", (void*)"Job 3 data");

    // Print the linked list
    print_job_list(head);

    // Remove a job from the linked list
    remove_job(&head, 2);

    // Print the updated linked list
    print_job_list(head);

    // Free the linked list and its memory
    free_job_list(&head);

    return 0;
}
