void insertRecord(double value, unsigned long id, const char* string) {
    Record* newRecord = (Record*)malloc(sizeof(Record));
    if (!newRecord) {
        printf("Memory allocation failed.\n");
        return;
    }

    newRecord->value = value;
    newRecord->id = id;
    newRecord->string = (char*)malloc(strlen(string) + 1);
