    if (!newNode) {
        printf("Memory allocation failed.\n");
        free(newRecord->string);
        free(newRecord);
        return;
    }

    newNode->record = *newRecord;

    if (head == NULL || head->record.value > value) {
        newNode->next = head;
        head = newNode;
    } else {
        Node* temp = head;
        while (temp->next && temp->next->record.value >= value)
            temp = temp->next;
        newNode->next = temp->next;
        temp->next = newNode;
    }

    recordCount++;
}

void printRecords() {
    Node* current = head;
    while (current) {
        printf("Value: %.2f, ID: %lu, String: %s\n", current->record.value, current->record.id, current->record.string);
        current = current->next;
    }
}
