        // Fill record structure with random key and metadata
        records[i].offset = rand();
        do {
            records[i].key = rand();
        } while (keys[i] == records[i].key); // Ensure no duplicates
        records[i].metadata = (double)rand() / RAND_MAX;
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}
