        events[i].numeric_value = (double)rand() / RAND_MAX;
        sprintf(tags + i, "Tag_%d", i);
        ids[i] = i;
    }
}

event* get_event(short id) {
    for (int i = 0; i < num_events; i++) {
        if (ids[i] == id) {
            return &events[i];
        }
    }
    return NULL;
}

void update_event(event* e, double value) {
    e->numeric_value = value;
}

void delete_event(short id) {
    for (int i = 0; i < num_events; i++) {
        if (ids[i] == id) {
            free(&events[i]);
            ids[i] = -1; // mark as deleted
            break;
        }
    }
}

void free_events() {
    for (int i = 0; i < num_events; i++) {
        if (ids[i] != -1) {
            free(&events[i]);
        }
    }
    free(ids);
    free(tags);
    free(values);
}
