    // Calculate the total number of bytes required for all arrays
    int totalBytes = sizeof(long) * (*numEvents) + sizeof(int) * (*numEvents) + sizeof(Event) * (*numEvents);

    // Dynamically allocate memory for arrays
    *timestamps = (long*)malloc(sizeof(long) * (*numEvents));
    *identifiers = (int*)malloc(sizeof(int) * (*numEvents));
    *events = (Event*)malloc(totalBytes);

    if (*timestamps == NULL || *identifiers == NULL || *events == NULL) {
        // Handle memory allocation error
        printf("Memory allocation failed.\n");
        free(*timestamps);
        free(*identifiers);
        free(*events);
        *numEvents = 0;
    } else {
        // Initialize event records and set description field
        for (int i = 0; i < *numEvents; i++) {
            (*events)[i].timestamp = timestamps[i];
            (*events)[i].identifier = identifiers[i];
            char summary[256];
            sprintf(summary, "Event %d occurred at timestamp %ld.", identifiers[i], timestamps[i]);
            strcpy((*events)[i].description, summary);
        }
    }

    // Free allocated memory
    free(*timestamps);
    free(*identifiers);
    free(*events);
}
