    while (template[i] != '\0') {
        description[i % 128] = template[i];
        i++;
    }
}

// Initialize the collection of entries
Entry* initializeEntries(int count) {
    Entry* entries = (Entry*)malloc(count * sizeof(Entry));
    if (!entries) {
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        entries[i].offset = i;
        entries[i].priority = i;

        // Generate a random description
        char template[] = "This is an item with metric ";
        char description[129];
        generateDescription(template, description);

        // Assign a unique metric value to each entry
        double metric = (double)i / 1000.0;
        entries[i].item.metric = metric;

        strcpy(entries[i].item.description, description);
    }

    return entries;
}

// Verify the integrity of the data after initialization
void verifyEntries(Entry* entries, int count) {
    for (int i = 0; i < count; i++) {
        printf("Offset: %ld, Priority: %d, Description: %s, Metric: %.2f\n",
            entries[i].offset, entries[i].priority,
            entries[i].item.description, entries[i].item.metric);
