record** initialize_records(int num_records, int min_value, int max_value, unsigned seed) {
    // Load configuration settings from file
    FILE* config_file = fopen("config.txt", "r");
    if (!config_file) {
        printf("Failed to load configuration file.\n");
        return NULL;
    }

    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    char** labels = (char**)malloc(num_records * sizeof(char*));

    srand(seed);
    for (int i = 0; i < num_records; i++) {
        offsets[i] = i;
        keys[i] = rand() % (max_value - min_value) + min_value;
        int label_length = rand() % 100 + 1;
        labels[i] = (char*)malloc(label_length * sizeof(char));
        for (int j = 0; j < label_length; j++) {
            labels[i][j] = 'a' + (rand() % 26);
        }
        labels[i][label_length] = '\0';

        int log_message_length = rand() % 1000 + 1;
        char* log_message = (char*)malloc(log_message_length * sizeof(char));
        for (int j = 0; j < log_message_length; j++) {
            log_message[j] = 'a' + (rand() % 26);
        }
        log_message[log_message_length] = '\0';
    }

    // Initialize records
    record** records = (record**)malloc(num_records * sizeof(record*));
    for (int i = 0; i < num_records; i++) {
        records[i] = (record*)malloc(sizeof(record));
        records[i]->large_value = keys[i];
        records[i]->unique_id = offsets[i];
        records[i]->label = labels[i];
        records[i]->log_message = log_message;
    }

    // Verify data integrity
    for (int i = 0; i < num_records; i++) {
        if (records[i]->large_value < min_value || records[i]->large_value > max_value) {
            printf("Invalid value in record %d.\n", i);
            return NULL;
        }
        if (strlen(records[i]->label) < 1 || strlen(records[i]->log_message) < 1) {
            printf("Invalid label or log message in record %d.\n", i);
            return NULL;
        }
    }

    free(config_file);
    fclose(config_file);

    return records;
}
