#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int* value;
} Record;

int manageMemory(size_t size, int maxKey) {
    long* offsets = (long*)malloc(sizeof(long) * size);
    if (!offsets) return -1; // Memory allocation failure

    int* keys = (int*)malloc(sizeof(int) * size);
    if (!keys) {
        free(offsets);
        return -2; // Memory allocation failure
    }

    Record* records = (Record*)malloc(sizeof(Record) * size);
    for (size_t i = 0; i < size; i++) {
        records[i].value = (int*)malloc(sizeof(int));
        if (!records[i].value) {
            free(offsets);
            free(keys);
            for (size_t j = 0; j < i; j++)
                free((void*)records[j].value);
            return -3; // Memory allocation failure
        }
    }

    // Initialize arrays with predefined sizes
    srand(time(NULL));
    for (size_t i = 0; i < size; i++) {
        offsets[i] = i;
        keys[i] = rand() % maxKey;

        int uniqueValue = rand() % 100 + 1;
        while (findDuplicate(keys, i)) {
            uniqueValue = rand() % 100 + 1;
        }
        records[i].value[0] = uniqueValue; // Initialize record values
    }

    FILE* file = fopen("recordData.txt", "wb");
    if (!file) {
        free(offsets);
        free(keys);
        for (size_t i = 0; i < size; i++) {
            free((void*)records[i].value);
        }
        return -4; // File open failure
    }

    fwrite(&offsets, sizeof(long), size, file);
    fwrite(&keys, sizeof(int), size, file);
    for (size_t i = 0; i < size; i++) {
        fwrite(records[i].value, sizeof(int), 1, file);
    }
    fclose(file);

    free(offsets);
    free(keys);
    for (size_t i = 0; i < size; i++) {
        free((void*)records[i].value);
    }

    return 0;
}

int findDuplicate(int* keys, size_t index) {
    for (size_t i = 0; i < index; i++) {
        if (keys[i] == keys[index]) return 1;
    }
    return 0;
}
