#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CAPACITY 1000
#define HASH_SIZE 256

typedef struct {
    char* key;
    int value;
    time_t timestamp;
} Node;

typedef struct {
    Node** nodes;
    int capacity;
    int size;
} DynamicLinkedList;

DynamicLinkedList* init_list(int max_capacity) {
    DynamicLinkedList* list = (DynamicLinkedList*)malloc(sizeof(DynamicLinkedList));
    if (!list) return NULL;

    list->nodes = (Node**)calloc(HASH_SIZE, sizeof(Node*));
    if (!list->nodes) {
        free(list);
        return NULL;
    }

    list->capacity = max_capacity;
    list->size = 0;
    return list;
}

void destroy_list(DynamicLinkedList* list) {
    for (int i = 0; i < HASH_SIZE; i++) {
        Node* node = list->nodes[i];
        while (node) {
            Node* next = node->next;
            free(node);
            node = next;
        }
    }
    free(list->nodes);
    free(list);
}

void resize_list(DynamicLinkedList* list, int new_capacity) {
    DynamicLinkedList* new_list = init_list(new_capacity);
    for (int i = 0; i < HASH_SIZE; i++) {
        Node* node = list->nodes[i];
        while (node) {
            Node* next = node->next;
            add_node(new_list, node->key, node->value, node->timestamp);
            free(node);
            node = next;
        }
    }
    destroy_list(list);
    *list = *new_list;
}

int hash_function(char* key) {
    int result = 0;
    for (char c : key) {
        result += (int)c;
    }
    return result % HASH_SIZE;
}

void add_node(DynamicLinkedList* list, char* key, int value, time_t timestamp) {
    int index = hash_function(key);
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return;

    node->key = strdup(key);
    node->value = value;
    node->timestamp = timestamp;
    node->next = list->nodes[index];
    list->nodes[index] = node;
    list->size++;
}

void remove_node(DynamicLinkedList* list, char* key) {
    int index = hash_function(key);
    Node* node = list->nodes[index];
    while (node) {
        if (!strcmp(node->key, key)) {
            Node* next = node->next;
            free(node->key);
            free(node);
            list->nodes[index] = next;
            list->size--;
            return;
        }
        node = node->next;
    }
}

int main() {
    // Initialize the dynamic linked list
    DynamicLinkedList* list = init_list(MAX_CAPACITY);

    // Add nodes to the list
    add_node(list, "key1", 10, time(NULL));
    add_node(list, "key2", 20, time(NULL));
    add_node(list, "key3", 30, time(NULL));

    // Remove a node from the list
    remove_node(list, "key2");

