// Define the item structure
struct Item {
    double value;
    char buffer[256];
};

// Define the LRU caching mechanism
class LRUCache {
public:
    LRUCache(int capacity) : capacity(capacity), cacheSize(0) {}

    void set(const std::string& key, const std::string& value) {
        if (cacheSize >= capacity) {
            // Evict the least recently used item when cache is full
            evict();
        }

        cache[key] = value;
        recentKeys.push(key);
    }

    std::string get(const std::string& key) {
        if (cache.find(key) != cache.end()) {
            // Update the item's access time
            recentKeys.erase(recentKeys.find(key));
            recentKeys.push(key);
            return cache[key];
        } else {
            return "";
        }
    }

private:
    int capacity;
    size_t cacheSize;
    std::list<std::string> recentKeys;
    std::unordered_map<std::string, std::string> cache;

    void evict() {
        // Evict the least recently used item
        auto it = recentKeys.begin();
        while (it != recentKeys.end()) {
            if (cache.erase(it->data())) {
                break;
            }
            ++it;
        }
        cacheSize--;
    }
};

