#include <boost/asio.hpp>
#include <boost/thread.hpp>
#include <boost/bind.hpp>

namespace asio = boost::asio;
namespace thread = boost::thread;

class SandeshClient {
public:
    SandeshClient(asio::io_service& io) : io_(io), thread_pool_(io_) {}

    void start() {
        thread_pool_.async_start();
    }

    void stop() {
        thread_pool_.async_stop();
    }

private:
    asio::io_service& io_;
    ThreadPool thread_pool_;

    class ThreadPool {
    public:
        ThreadPool(asio::io_service& io) : io_(io) {}

        void async_start() {
            for (int i = 0; i < 10; ++i) {
                io_.async_accept([this](boost::system::error_code ec) {
                    if (!ec) {
                        handle_request();
                    }
                });
            }
        }

        void async_stop() {
            for (int i = 0; i < 10; ++i) {
                io_.async_cancel(i);
            }
        }

    private:
        asio::io_service& io_;
        int current_concurrent_requests_ = 0;
        int max_concurrent_requests_ = 10000;

        void handle_request() {
            if (current_concurrent_requests_ < max_concurrent_requests_) {
                ++current_concurrent_requests_;
                io_.async_accept([this](boost::system::error_code ec) {
                    handle_request();
                });
            }
        }
    };

