// Function to generate PEM-encoded certificate
void generatePEMCertificateAndNFAPIArray(OAuthRequest* oReq) {
    // Read private key and certificate files
    FILE* keyFile = fopen(oReq->pathToPrivateKey, "rb");
    if (keyFile == NULL) {
        // Error handling for private key file read error
        printf("Error reading private key file.\n");
        return;
    }
    FILE* certFile = fopen(oReq->pathToCertificate, "rb");
    if (certFile == NULL) {
        // Error handling for certificate file read error
        printf("Error reading certificate file.\n");
        fclose(keyFile);
        return;
    }

    // Read private key and certificate strings
    char* privateKeyStr = (char*)malloc(oReq->keyBufferSize + 1);
    fread(privateKeyStr, 1, oReq->keyBufferSize, keyFile);
    privateKeyStr[oReq->keyBufferSize] = '\0';
    fseek(keyFile, 0, SEEK_SET);

    char* certificateStr = (char*)malloc(oReq->certBufferSize + 1);
    fseek(certFile, 0, SEEK_SET);
    fread(certificateStr, 1, oReq->certBufferSize, certFile);
    certificateStr[oReq->certBufferSize] = '\0';
    fclose(keyFile);
    fclose(certFile);

    // Concatenate private key and certificate strings
    char* pemEncodedCert = (char*)malloc(strlen(privateKeyStr) + strlen(certificateStr) + 2);
    sprintf(pemEncodedCert, "%s\n%s", privateKeyStr, certificateStr);
    free(privateKeyStr);
    free(certificateStr);

    // Populate NFAPI_CRC_INDICATION_PDU_T structures
    int numPdus = oReq->numPdus;
    NFAPI_CRC_INDICATION_PDU_T** pdus = (NFAPI_CRC_INDICATION_PDU_T**)malloc(numPdus * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for (int i = 0; i < numPdus; i++) {
        pdus[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdus[i]->rnti = getUniqueRNTI();
        pdus[i]->rx_ue_information_tag = oReq->rx_ue_info_tag;
        pdus[i]->crcflag = rand() % 2;

        // Allocate memory for CRC indication pdu
        pdus[i]->pdu_data = (char*)malloc(oReq->maxPDUDataSize + 1);
        strcpy(pdus[i]->pdu_data, oReq->defaultPDUData);

        // Add to custom hash table
        RNTI_MAP_ENTRY entry;
        entry.rnti = getUniqueRNTI();
        entry.pdu = pdus[i];
        custom_hash_table.entries[custom_hash_table.size++] = &entry;
    }

    // Free allocated memory
    for (int i = 0; i < numPdus; i++) {
        free(pdus[i]->pdu_data);
        free(pdus[i]);
    }
    free(pemsEncodedCert);
    free(pdus);

    // Periodic garbage collection to free unused memory
    periodicGarbageCollection();
}

void periodicGarbageCollection() {
    // Implementation for periodic garbage collection
}

