class EventList {
public:
    EventList(size_t initialCapacity, size_t maxCapacity)
        : events_(new std::deque<Event*>(initialCapacity)), capacity_(initialCapacity), maxCapacity_(maxCapacity) {}

    ~EventList() {
        clear();
    }

    void addEvent(Event* event) {
        if (events_->size() >= capacity_) {
            resize();
        }
        events_->emplace_back(event);
    }

    void removeEvent(size_t index) {
        if (index >= 0 && index < events_->size()) {
            Event* event = (*events_)[index];
            delete event;
            events_->erase(events_->begin() + index);
        }
    }

    size_t size() const {
        return events_->size();
    }

    void clear() {
        for (Event* event : *events_) {
            delete event;
        }
        delete events_;
        events_ = new std::deque<Event*>(capacity_);
    }

private:
    void resize() {
        capacity_ *= 2;
        std::unique_ptr<std::deque<Event*> > newEvents(new std::deque<Event*>(capacity_));
        for (Event* event : *events_) {
            newEvents->emplace_back(event);
        }
        delete events_;
        events_ = std::move(newEvents);
    }

    size_t capacity_;
    size_t maxCapacity_;
    std::unique_ptr<std::deque<Event*> > events_;
};

