class EventStorage {
private:
    std::mutex mtx;
    size_t capacity = 1024;
    std::list<Event> events;

public:
    void addEvent(Event event) {
        std::unique_lock<std::mutex> lock(mtx);
        if (events.size() >= capacity) {
            resize();
        }
        events.emplace_back(event);
    }

    Event getEvent(time_t timestamp) {
        std::unique_lock<std::mutex> lock(mtx);
        for (auto it = events.begin(); it != events.end(); ++it) {
            if (it->timestamp == timestamp) {
                return *it;
            }
        }
        throw std::runtime_error("Event not found");
    }

private:
    void resize() {
        capacity *= 2;
        std::list<Event> newEvents(events);
        events.clear();
        for (auto& event : newEvents) {
            addEvent(event);
        }
    }
};

class LRUCache {
private:
    size_t capacity = 1024;
    std::list<std::pair<Event, time_t>> cache;

public:
    void put(Event event, time_t timestamp) {
        auto it = cache.begin();
        while (it != cache.end()) {
            if (it->first == event) {
                it->second = timestamp;
                return;
            }
            ++it;
        }
        if (cache.size() >= capacity) {
            cache.pop_front();
        }
        cache.emplace_back(event, timestamp);
    }

    Event getEvent(time_t timestamp) {
        for (auto& pair : cache) {
            if (pair.second == timestamp) {
                return pair.first;
            }
        }
        throw std::runtime_error("Event not found");
    }
};

class PredictiveAnalytics {
private:
    std::map<time_t, size_t> eventVolumes;

public:
    void train(std::vector<Event> events) {
        for (auto& event : events) {
            auto it = eventVolumes.find(event.timestamp);
            if (it == eventVolumes.end()) {
                it = eventVolumes.insert({event.timestamp, 1});
            } else {
                it->second++;
            }
        }
    }

    size_t forecast(time_t timestamp) {
        auto it = eventVolumes.find(timestamp);
        return it != eventVolumes.end() ? it->second : 0;
    }
};

