#define POOL_GROWTH 2048
#define LOGGING_LEVEL 1 // 0: off, 1: basic, 2: detailed

typedef struct {
    int value;
} record_t;

void* my_malloc(size_t size) {
    static char pool[INITIAL_POOL_SIZE];
    void* ptr = pool;

    if (size > INITIAL_POOL_SIZE) {
        // Reallocate with a new block
        ptr = realloc(pool, POOL_GROWTH);
        if (!ptr) {
            printf("Memory allocation failed!\n");
            return NULL;
        }

        pool = ptr;
        INIT_POOL(pool, POOL_GROWTH);
    }

    if (size <= INITIAL_POOL_SIZE) {
        // Reuse the existing block
        ptr += size;
    } else {
        // Allocate a new block and link to previous
        record_t* prev_ptr = (record_t*)pool;
        pool = realloc(pool, POOL_GROWTH);
        *prev_ptr++ = *(record_t*)ptr;

        ptr = prev_ptr;
    }

    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

int main() {
    int* keys = (int*)my_malloc(sizeof(int) * MAX_RECORDS);
    long* offsets = (long*)my_malloc(sizeof(long) * MAX_RECORDS);
