#define MAX_RECORDS 1000
#define BLOOM_FILTER_SIZE 1024
#define HASH_TABLE_SIZE 2048

typedef struct {
    int offset;
} long_offset;

typedef struct {
    int key;
    int value;
} record;

record *records = NULL;
int num_records = 0;
int bloom_filter[BLOOM_FILTER_SIZE / 8];

void initialize_bloom_filter() {
    for (int i = 0; i < BLOOM_FILTER_SIZE / 8; i++) {
        bloom_filter[i] = 0;
    }
}

int is_key_in_bloom_filter(int key) {
    int hash = key % (BLOOM_FILTER_SIZE / 8);
    return (bloom_filter[hash / 8] & (1 << (hash % 8))) != 0;
}

void add_key_to_bloom_filter(int key) {
    int hash = key % (BLOOM_FILTER_SIZE / 8);
    bloom_filter[hash / 8] |= 1 << (hash % 8);
}

record *create_record(int key, long offset) {
    record *new_record = (record *)malloc(sizeof(record));
    new_record->key = key;
    new_record->value = offset;
    return new_record;
}

int hash_function(int key) {
    return key % HASH_TABLE_SIZE;
}

void add_to_hash_table(int key, record *record_ptr) {
    int index = hash_function(key);
    record **bucket = (record **)malloc(sizeof(record *) * 2);
    bucket[0] = NULL;
    bucket[1] = NULL;

    if (bucket[index % 2] != NULL) {
        while (bucket[index % 2]->key != key) {
            record *temp = bucket[index % 2];
            bucket[index % 2] = temp->next;
            free(temp);
        }
    }

    record_ptr->next = bucket[index % 2];
    bucket[index % 2] = record_ptr;

    if (num_records < MAX_RECORDS) {
        records[num_records++] = record_ptr;
    } else {
        printf("Memory allocation failed.\n");
        exit(1);
    }
}

void handle_collision(int key, record *record_ptr) {
    int retries = 0;
    while (is_key_in_bloom_filter(key)) {
        key++;
        if (key % 2 == 0) {
            key++;
        }
        add_key_to_bloom_filter(key);
    }
}

void free_records() {
    for (int i = 0; i < num_records; i++) {
        record *current = records[i];
        while (current != NULL) {
            record *next = current->next;
            free(current);
            current = next;
        }
    }
    free(records);
}

void print_performance_metrics() {
    printf("Number of retries due to duplicate keys: %d\n", num_records);
    printf("Overall performance metrics:\n");
    // Add more performance metrics as needed
}

int main(int argc, char *argv[]) {
    initialize_bloom_filter();
    for (int i = 0; i < MAX_RECORDS; i++) {
        int key = rand() % (1 << 31);
        long offset = (long)rand();
        record *new_record = create_record(key, offset);
        add_key_to_bloom_filter(key);

        if (is_key_in_bloom_filter(key)) {
            handle_collision(key, new_record);
        } else {
            add_to_hash_table(key, new_record);
        }
    }

    print_performance_metrics();

    free_records();

    return 0;
}
