#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_ID_SIZE 128
#define MAX_ITEMS 1024
#define LIST_NODE_SIZE sizeof(struct item_node)

typedef struct {
    double value;
    char *id;
} item;

typedef struct {
    item data;
    struct list_node *prev, *next;
} list_node;

list_node *create_list_node(item data) {
    list_node *node = malloc(LIST_NODE_SIZE);
    node->data = data;
    node->prev = node->next = NULL;
    return node;
}

int init_data_structure(size_t max_id_count) {
    pthread_mutex_init(&id_mutex, NULL);

    item *items = malloc(sizeof(item) * max_id_count);
    char **ids = malloc(sizeof(char *) * max_id_count);

    for (size_t i = 0; i < max_id_count; i++) {
        items[i].value = NAN;
        ids[i] = malloc(MAX_ID_SIZE + 1);
        strcpy(ids[i], "");
    }

    list_node *head = create_list_node({.data.value = NAN, .id = NULL});
    list_node *tail = head;

    return 0;
}

void free_data_structure() {
    pthread_mutex_lock(&id_mutex);

    // Free items
    for (size_t i = 0; i < MAX_ITEMS; i++) {
        if (items[i].value != NAN) {
            free(items[i].id);
        }
    }

    free(items);
    free(ids);

    // Free list nodes
    list_node *curr = head;
    while (curr) {
        list_node *next = curr->next;
        free(curr);
        curr = next;
    }

    pthread_mutex_unlock(&id_mutex);
}

void add_item(double value, const char *id) {
    pthread_mutex_lock(&id_mutex);

    item new_item = {.value = value, .id = strdup(id)};
    list_node *new_node = create_list_node(new_item);

    if (head->next) {
        head->next->prev = new_node;
        new_node->next = head->next;
        head->next = new_node;
    } else {
        head->next = new_node;
        tail = new_node;
    }

    pthread_mutex_unlock(&id_mutex);
}

void remove_item(char *id) {
    pthread_mutex_lock(&id_mutex);

    // Find the item
    list_node *curr = head;
    while (curr && curr->data.id != id) {
        curr = curr->next;
    }
    if (!curr) {
        pthread_mutex_unlock(&id_mutex);
        return; // Item not found
    }

    // Remove from list and free resources
    if (curr == head) {
        head = curr->next;
    } else if (curr == tail) {
        tail = curr->prev;
    }
    curr->prev->next = curr->next;
    if (curr->next) {
        curr->next->prev = curr->prev;
    }
    free(curr->data.id);
    free(curr);

    pthread_mutex_unlock(&id_mutex);
}

void update_item(char *id, double new_value) {
    pthread_mutex_lock(&id_mutex);

    // Find the item
    list_node *curr = head;
    while (curr && curr->data.id != id) {
        curr = curr->next;
    }
    if (!curr) {
        pthread_mutex_unlock(&id_mutex);
        return; // Item not found
    }

    // Update the value
    curr->data.value = new_value;

    pthread_mutex_unlock(&id_mutex);
}
