char* generate_filename(const char* original_filename, FileType file_type) {
    MD5_CTX md5_ctx;
    unsigned char md5_digest[MD5_DIGEST_SIZE];
    FILE* f = fopen(original_filename, "rb");
    if (f == NULL) {
        return NULL; // Handle error
    }
    MD5_Init(&md5_ctx);
    while (1) {
        size_t buffer_size = 1024;
        char buffer[buffer_size];
        size_t bytes_read = fread(buffer, 1, buffer_size, f);
        if (bytes_read == 0) break; // End of file
        MD5_Update(&md5_ctx, buffer, bytes_read);
    }
    MD5_Final(md5_digest, &md5_ctx);
    fclose(f);

    char* new_filename = malloc(MAX_FILENAME_LENGTH + 1);
    sprintf(new_filename, "%s_%x_", original_filename, md5_ctx.igndlen);
    if (file_type == FILE_TYPE_TXT) {
        strcat(new_filename, "txt");
    } else if (file_type == FILE_TYPE_BIN) {
        strcat(new_filename, "bin");
    }
    free(original_filename);

    // Validate filename length
    if (strlen(new_filename) > MAX_FILENAME_LENGTH) {
        char* new_new_filename = malloc(MAX_FILENAME_LENGTH + 1);
        sprintf(new_new_filename, "%s_%x_%.4d.txt", original_filename, md5_ctx.igndlen, rand());
        free(new_filename);
        return new_new_filename;
    }
    return new_filename;
}

