#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/pem.h>
#include <pthread.h>

#define MAX_CERTIFICATES 1000
#define RNTI_RANGE 65535
#define CRCFLAG_RANGE 1

typedef struct {
    int RNTI;
    int RX_UE_INFORMATION_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* generatePEMCertificateAndNFAPIArray(OAuthRequest* request) {
    // Initialize memory statistics and periodic garbage collection
    static unsigned long long total_memory = 0;
    static pthread_mutex_t stats_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_setspecific(&total_memory, NULL);

    int num_certificates = request->num_certificates;
    NFAPI_CRC_INDICATION_PDU_T* certificates = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_certificates * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!certificates) {
        // Allocation failed
        perror("Memory allocation");
        return NULL;
    }

    pthread_mutex_lock(&stats_mutex);
    total_memory += num_certificates * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_unlock(&stats_mutex);

    // Generate unique RNTI values
    for (int i = 0; i < num_certificates; i++) {
        certificates[i].RNTI = rand() % RNTI_RANGE;
        certificates[i].RX_UE_INFORMATION_TAG = rand();
        certificates[i].CRCFLAG = rand() % CRCFLAG_RANGE;
    }

    // Read private key and certificate files
    FILE* key_file = fopen(request->private_key_path, "r");
    if (!key_file) {
        // File not found
        perror("Private key file");
        return NULL;
    }

    fseek(key_file, 0L, SEEK_END);
    size_t key_size = ftell(key_file);
    rewind(key_file);

    char* key_buffer = (char*)malloc(key_size + 1);
    if (!key_buffer) {
        // Allocation failed
        perror("Private key buffer");
        return NULL;
    }

    fread(key_buffer, 1, key_size, key_file);
    fclose(key_file);

    key_buffer[key_size] = '\0';

    FILE* cert_file = fopen(request->certificate_path, "r");
    if (!cert_file) {
        // File not found
        perror("Certificate file");
        return NULL;
    }

    fseek(cert_file, 0L, SEEK_END);
    size_t cert_size = ftell(cert_file);
    rewind(cert_file);

    char* cert_buffer = (char*)malloc(cert_size + 1);
    if (!cert_buffer) {
        // Allocation failed
        perror("Certificate buffer");
        return NULL;
    }

    fread(cert_buffer, 1, cert_size, cert_file);
    fclose(cert_file);

    cert_buffer[cert_size] = '\0';

    // Concatenate private key and certificate strings into a single PEM-formatted string
    char* pem_string = (char*)malloc(key_size + cert_size + 2 * 1024);
    if (!pem_string) {
        // Allocation failed
        perror("PEM string buffer");
        return NULL;
    }

    sprintf(pem_string, "-----BEGIN CERTIFICATE-----\n%s\n-----END CERTIFICATE-----\n-----BEGIN PRIVATE KEY-----\n%s\n-----END PRIVATE KEY-----\n", cert_buffer, key_buffer);

    free(cert_buffer);
    free(key_buffer);

    // Generate PEM-encoded certificate
    EVP_PKEY* pkey = d2i_PrivateKey_bio(NULL, pem_string);
    if (!pkey) {
        // Certificate generation failed
        perror("Certificate generation");
        return NULL;
    }

    free(pem_string);

    return certificates;
}
