            free(data);
            fclose(file);
            return NULL; // Error: memory allocation failed
        }
        data = new_data;
        allocated++;

        size_t read_bytes = fread(&data[allocated - 1], sizeof(sensor_data), 1, file);
        if (read_bytes != 1) {
            break; // End of file reached or error during reading
        }
    }

    *count = allocated;
    fclose(file);

    return data;
}

