Record** create_records(int num_records, long min_offset, long max_offset, int min_key, int max_key) {
    Record** records = (Record**)malloc(num_records * sizeof(Record*));
    for (int i = 0; i < num_records; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        int offset = (rand() % (max_offset - min_offset)) + min_offset;
        int key = (rand() % (max_key - min_key)) + min_key;
        time_t timestamp = time(NULL);
        char str[20];
        srand(time(NULL));
        for (int j = 0; j < 20; j++) {
            str[j] = (char)(rand() % ('z' - 'a' + 1) + 'a');
        }
        str[19] = '\0';
        int buffer_size = strlen(str);
        record->value = offset;
        record->buffer = (char*)malloc(buffer_size + sizeof(char));
        sprintf(record->buffer, "%ld-%d-%s", offset, key, str);
        record->timestamp = timestamp;
        records[i] = record;
    }
    return records;
}

void free_records(Record** records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        Record* record = records[i];
        if (record != NULL) {
            if (record->buffer != NULL) {
                free(record->buffer);
            }
            free(record);
        }
    }
    free(records);
}

void print_records(Record** records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        Record* record = records[i];
        printf("Value: %d, Buffer: %s, Timestamp: %lu\n", record->value, record->buffer, record->timestamp);
    }
}

int main() {
    int num_records = 10;
    long min_offset = 0;
    long max_offset = 10000;
    int min_key = 1;
    int max_key = 100;

    Record** records = create_records(num_records, min_offset, max_offset, min_key, max_key);
    print_records(records, num_records);

    free_records(records, num_records);

    return 0;
}
