        fprintf(stderr, "Array size too large.\n");
        return -1;
    }
    node_array = (Node **)malloc(size * sizeof(Node *));
    if (!node_array) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < size; i++) {
        node_array[i] = node_alloc();
        // Set random priorities
        srand(time(NULL));
        node_array[i]->priority = rand() % 100;
    }
    return 0;
}

void update_node_array(int index, Node *n) {
    pthread_mutex_lock(&lock);
    if (index < MAX_NODES) {
        node_free(node_array[index]);
        node_array[index] = n;
    }
    pthread_mutex_unlock(&lock);
}

Node *get_node_array(int index) {
    pthread_mutex_lock(&lock);
    if (index < MAX_NODES) {
        return node_array[index];
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}
