#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>

typedef struct {
    int size;
    time_t timestamp;
} FileMetadata;

typedef struct {
    FileMetadata metadata;
    void* file_data;
} CacheEntry;

typedef struct {
    int entries;
    int capacity;
    void** entry_pointers;
    time_t modification_timestamps[];
} DynamicCache;

DynamicCache* create_cache(int entries, size_t capacity) {
    // Initialize cache structure
    DynamicCache* cache = (DynamicCache*)malloc(sizeof(DynamicCache));
    cache->entries = 0;
    cache->capacity = capacity;

    // Allocate memory for entry pointers and modification timestamps
    cache->entry_pointers = (void**)calloc(capacity, sizeof(void*));

    return cache;
}

int add_entry_to_cache(DynamicCache* cache, void* file_data) {
    if (cache->entries >= cache->capacity) {
        return -1; // Cache full, cannot add more entries
    }

    CacheEntry* entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    entry->metadata.size = sizeof(void*);
    entry->metadata.timestamp = time(NULL);
    entry->file_data = file_data;

    cache->entry_pointers[cache->entries] = entry;
    cache->modification_timestamps[cache->entries] = entry->metadata.timestamp;
    cache->entries++;

    return 0; // Entry added successfully
}

void* get_file_from_cache(DynamicCache* cache, int index) {
    if (index >= cache->entries || !cache->entry_pointers[index]) {
        return NULL; // Entry not found or invalid
    }

    return ((CacheEntry*)cache->entry_pointers[index])->file_data;
}

void release_entry_in_cache(DynamicCache* cache, int index) {
    if (index >= cache->entries || !cache->entry_pointers[index]) {
        return; // Entry not found or invalid
    }

    free(((CacheEntry*)cache->entry_pointers[index])->file_data);
    free(cache->entry_pointers[index]);
    cache->entry_pointers[index] = NULL;
}

void update_cache_config(DynamicCache* cache, int new_capacity) {
    if (new_capacity < cache->entries) {
        // Cannot reduce capacity below current entries
        return;
    }

    cache->capacity = new_capacity;

    // Shrink or grow memory for entry pointers and modification timestamps
    void** old_entry_pointers = cache->entry_pointers;
    time_t* old_timestamps = cache->modification_timestamps;

    cache->entry_pointers = (void**)realloc(cache->entry_pointers, new_capacity * sizeof(void*));
    cache->modification_timestamps = (time_t*)realloc(cache->modification_timestamps, new_capacity * sizeof(time_t));

    if (!cache->entry_pointers || !cache->modification_timestamps) {
        // Memory allocation failed, restore previous state
        cache->capacity = old_entry_pointers;
        free(old_entry_pointers);
        free(old_timestamps);

        return;
    }

    // Update entry pointers and timestamps
    for (int i = 0; i < new_capacity; i++) {
        if (i < cache->entries) {
            cache->entry_pointers[i] = old_entry_pointers[i];
            cache->modification_timestamps[i] = old_timestamps[i];
        }
    }

    free(old_entry_pointers);
    free(old_timestamps);
}

void destroy_cache(DynamicCache* cache) {
    for (int i = 0; i < cache->entries; i++) {
        release_entry_in_cache(cache, i);
    }

    free(cache->entry_pointers);
    free(cache);

    return;
}
