typedef struct {
    char* name;
    double price;
    int stock_quantity;
} product;

void load_products_from_csv(const char* filename, product** products, int* num_products) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening the file");
        return;
    }

    *num_products = 0;
    product* current_products = NULL;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        product* new_product = malloc(sizeof(product));
        if (!new_product) {
            perror("Error allocating memory for a product");
            fclose(file);
            return;
        }

        int i = 0;
        char* token = strtok(line, ",");
        new_product->name = strdup(token);
        while (token && i < 3) {
            switch (i++) {
                case 0:
                    break;
                case 1:
                    if (strtol(token, NULL, 10) <= 0.0 || !token[0]) {
                        free(new_product->name);
                        free(new_product);
                        fclose(file);
                        return;
                    }
                    new_product->price = atof(token);
                    break;
                case 2:
                    if (!isdigit(token[0])) {
                        free(new_product->name);
                        free(new_product);
                        fclose(file);
                        return;
                    }
                    new_product->stock_quantity = strtol(token, NULL, 10);
                    break;
            }
            token = strtok(NULL, ",");
        }

        if (*num_products == 0) {
            *num_products = 1;
            current_products = new_product;
        } else {
            product* prev_product = *products;
            *products = realloc(*products, sizeof(product) * (*num_products + 1));
            memcpy(&((*products)[*num_products - 1]), &prev_product, sizeof(product));
            free(prev_product);
            (*products)[*num_products - 1] = new_product;
        }
    }

    fclose(file);

    if (current_products) {
        product* prev_product = *products;
        while (prev_product) {
            product* next_product = prev_product->name ? prev_product + 1 : NULL;
            free(prev_product->name);
            free(prev_product);
            prev_product = next_product;
        }
    }
}

int main() {
    product* products = NULL;
    int num_products = 0;

    load_products_from_csv("products.csv", &products, &num_products);

    // Use the loaded products...
    for (int i = 0; i < num_products; i++) {
        printf("Product %s has a price of $%.2f and a stock quantity of %d.\n",
               products[i].name, products[i].price, products[i].stock_quantity);
    }

    // Clean up...
    for (int i = 0; i < num_products; i++) {
        free(products[i].name);
        free(products[i]);
    }
    free(products);

    return 0;
}
