#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a struct for storing record data
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Allocate memory for dynamic records
Record* create_record(int size) {
    return (Record*)malloc(size * sizeof(Record));
}

// Insert new record into existing array
void insert_record(Record** arr, int* capacity, int num_records, int size) {
    if (*capacity <= num_records) {
        *capacity = num_records + 1;
        *arr = (Record*)realloc(*arr, *capacity * sizeof(Record));
    }
}

// Serialize records to file
void serialize_records(const char* filename, Record** arr, int num_records) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        return;
    }

    for (int i = 0; i < num_records; i++) {
        fwrite(&arr[i]->offset, sizeof(long), 1, file);
        fwrite(&arr[i]->key, sizeof(int), 1, file);
        fwrite(&arr[i]->value, sizeof(double), 1, file);
    }

    fclose(file);
}

// Deserialize records from file
void deserialize_records(const char* filename, Record** arr, int* num_records) {
    FILE* file = fopen(filename, "rb");
    if (!file || !fseek(file, 0, SEEK_END)) {
        *num_records = 0;
        return;
    }

    long size = ftell(file);
    fseek(file, 0, SEEK_SET);

    *num_records = size / (sizeof(long) + sizeof(int) + sizeof(double));

    for (int i = 0; i < *num_records; i++) {
        fread(&arr[i]->offset, sizeof(long), 1, file);
        fread(&arr[i]->key, sizeof(int), 1, file);
        fread(&arr[i]->value, sizeof(double), 1, file);
    }

    fclose(file);
}

// Free allocated memory
void free_records(Record** arr, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(arr[i]);
    }
    free(arr);
}
