#include <stdio.h>
#include <pthread.h>

#define MAX_KEY 1000
#define MAX_VERTEX 10000
#define MAX_EDGE 500000
#define MEM_THRESHOLD 1024 * 16 // 16KB

typedef struct {
    int value;
} record_t;

record_t* records = NULL;
long* vertex_offsets = NULL;
int* key_to_id = NULL;
int num_records = 0, num_vertices = 0, num_edges = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* add_vertex(int key) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    if (num_vertices >= MAX_VERTEX) {
        return (void*) -1; // Out of memory
    }

    record_t* new_record = (record_t*) realloc(records, (num_records + 1) * sizeof(record_t));
    if (!new_record) {
        pthread_mutex_unlock(&mutex);
        return (void*) -2; // Memory allocation failed
    }
    records = new_record;
    record_t* new_vertex = &records[num_records++];

    vertex_offsets = (long*) realloc(vertex_offsets, (num_vertices + 1) * sizeof(long));
    if (!vertex_offsets) {
        pthread_mutex_unlock(&mutex);
        return (void*) -2; // Memory allocation failed
    }
    vertex_offsets[num_vertices] = (long) new_vertex;

    key_to_id = (int*) realloc(key_to_id, (num_records + 1) * sizeof(int));
    if (!key_to_id) {
        pthread_mutex_unlock(&mutex);
        return (void*) -2; // Memory allocation failed
    }
    key_to_id[num_records] = key;

    num_vertices++;
    pthread_mutex_unlock(&mutex);
    return (void*) key;
}

int get_vertex_id(int key) {
    for (int i = 0; i < num_records; i++) {
        if (key_to_id[i] == key) {
            return i;
        }
    }
    return -1; // Key not found
}

void add_edge(int vertex1, int vertex2) {
    pthread_mutex_lock(&mutex);

    if (vertex1 >= num_vertices || vertex2 >= num_vertices) {
        pthread_mutex_unlock(&mutex);
        return; // Vertex out of range
    }

    if (!vertex_offsets) {
        vertex_offsets = (long*) malloc(sizeof(long));
        num_edges++;
    } else {
        vertex_offsets = (long*) realloc(vertex_offsets, (num_edges + 1) * sizeof(long));
        num_edges++;
    }
    vertex_offsets[num_edges - 1] = (long) vertex2;

    pthread_mutex_unlock(&mutex);
}

void convert_key_to_id(int key, int* converted_key) {
    for (int i = 0; i < num_records; i++) {
        if (key_to_id[i] == key) {
            *converted_key = i;
            return;
        }
    }
    *converted_key = -1; // Key not found
}

void print_graph_stats() {
    printf("Number of vertices: %d\n", num_vertices);
    printf("Number of edges: %d\n", num_edges);
}
