// Define the record structure type
typedef struct {
    int key;
    int value;
} record_t;

// Custom hash table for key tracking and collision resolution
int *hash_table;
int hash_table_size = 0;
int hash_table_capacity = 1000; // Default capacity

// Function to initialize and manage memory for arrays
void* initArrays(size_t max_size) {
    // Allocate memory for offset values (long)
    long *offsets = malloc(sizeof(long) * max_size);

    // Allocate memory for keys (int)
    int *keys = malloc(sizeof(int) * max_size);

    // Allocate memory for record structures
    record_t *records = malloc(sizeof(record_t) * max_size);

    return (void*) records;
}

// Initialize and populate arrays with random values within specified range
void initArraysWithData(void* data, size_t count, int min_value, int max_value) {
    record_t *records = (record_t*) data;
    srand(time(NULL));

    for (size_t i = 0; i < count; i++) {
        // Initialize random key and value within specified range
        int key = rand() % (max_value - min_value + 1) + min_value;
        int value = rand() % (max_value - min_value + 1) + min_value;

        records[i].key = key;
        records[i].value = value;

        // Update hash table
        int idx = key % hash_table_capacity;
        if (!hash_table[idx]) {
            hash_table[idx] = 1; // Set presence flag
        } else {
            printf("Collision detected! Key: %d\n", key);
        }
    }
}

// Function to release allocated memory and reset the hash table
void cleanUp(void* data) {
    record_t *records = (record_t*) data;
    free(records);

    // Reset hash table
    for (int i = 0; i < hash_table_capacity; i++) {
        if (hash_table[i]) {
            hash_table[i] = 0; // Clear presence flag
        }
    }
}

// Function to log initialization operation with timestamp and metadata
void logInit(void* data) {
    record_t *records = (record_t*) data;

    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);

    printf("[INFO] Initialization completed at %02d:%02d:%02d | Total records: %zu\n", now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, sizeof(records));
}
