// Define the record structure
struct Record {
    int key;
    long offset;
};

// Define the function to manage the dynamic collection of records
std::unique_ptr<std::map<int, long>> manageRecords(size_t initialCapacity) {
    // Initialize the map with smart pointers for proper deallocation
    std::unique_ptr<std::map<int, long>> recordMap = std::make_unique<std::map<int, long>>(initialCapacity);

    return recordMap;
}

// Define a function to add records to the collection (thread-safe)
void addRecord(std::unique_ptr<std::map<int, long>>& recordMap, int key, long offset) {
    // Acquire the lock for thread safety
    std::lock_guard<std::mutex> lock(recordMap->mutex);

    // Add the record to the map
    recordMap->insert({key, offset});
}

// Define a function to remove records from the collection (thread-safe)
void removeRecord(std::unique_ptr<std::map<int, long>>& recordMap, int key) {
    // Acquire the lock for thread safety
    std::lock_guard<std::mutex> lock(recordMap->mutex);

    // Remove the record from the map (if it exists)
    if (recordMap->erase(key) == 1) {
        // If the record was removed, update the map's capacity
        recordMap->shrink_to_fit();
    }
}

// Define a function to get the offset for a given key (thread-safe)
long getOffset(std::unique_ptr<std::map<int, long>>& recordMap, int key) {
    // Acquire the lock for thread safety
    std::lock_guard<std::mutex> lock(recordMap->mutex);

    // Retrieve the offset for the given key (if it exists)
    auto it = recordMap->find(key);
    if (it != recordMap->end()) {
        return it->second;
    }

    // If the key is not found, return a default or error value
    return -1;
}

// Define a function to print the contents of the collection (thread-safe)
void printRecords(std::unique_ptr<std::map<int, long>>& recordMap) {
    // Acquire the lock for thread safety
    std::lock_guard<std::mutex> lock(recordMap->mutex);

    // Iterate over the records and print their keys and offsets
    for (const auto& pair : *recordMap) {
        std::cout << "Key: " << pair.first << ", Offset: " << pair.second << std::endl;
    }
}

int main() {
    // Initialize the record map with an initial capacity of 10
    auto recordMap = manageRecords(10);

    // Add some records to the collection
    addRecord(recordMap, 1, 0x10000000);
    addRecord(recordMap, 2, 0x20000000);
    addRecord(recordMap, 3, 0x30000000);

    // Print the contents of the collection
    printRecords(recordMap);

    return 0;
}

