typedef struct Node {
    int id;
    struct Event **events;
    char **logs;
} Node;

// Define the event structure
typedef struct Event {
    time_t timestamp;
    enum EventType type;
    char *log;
} Event;

// Define the system manager function
void* SystemManager(int maxMemoryMB, int numNodes) {
    // Calculate the total memory required for the system
    size_t totalMemory = sizeof(Node) * numNodes + sizeof(Event) * 1000 + strlen("some log message");

    // Check if the total memory exceeds the maximum threshold
    if (totalMemory > maxMemoryMB * 1024 * 1024) {
        printf("Error: Total memory exceeded the maximum threshold.\n");
        return NULL;
    }

    // Allocate memory for the node array
    Node* nodes = (Node*)malloc(sizeof(Node) * numNodes);

    // Check if the allocation was successful
    if (nodes == NULL) {
        printf("Error: Unable to allocate memory for nodes.\n");
        free(nodes);
        return NULL;
    }

