void* setup_network_service(int port, int max_concurrent_connections) {
    // Allocate memory for the server socket
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);

    // Initialize the server socket and set it to listen on the specified port
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(port);
    inet_pton(AF_INET, "127.0.0.1", &server_address.sin_addr);
    bind(server_socket, (struct sockaddr*)&server_address, sizeof(server_address));
    listen(server_socket, MAX_CONCURRENT_CONNECTIONS);

    // Allocate memory for the client connection pool
    int* connections = malloc(MAX_CONCURRENT_CONNECTIONS * sizeof(int));

    // Initialize the thread pool with a configurable number of threads
    pthread_t* threads = malloc(max_concurrent_connections * sizeof(pthread_t));
    pthread_create(threads, NULL, handle_client_connection, NULL);

    // Initialize the message processing queue with a configurable capacity
    int* message_queue = malloc(MESSAGE_QUEUE_CAPACITY * sizeof(int));

    return server_socket;
}

void shutdown_network_service(void* network_service) {
    // Free dynamically allocated memory for the server socket and client connection pool
    free(((int*)network_service));
