Record* createRecords(int numRecords, long* offsets, int* keys) {
    if (numRecords <= 0) {
        return NULL; // Return null for invalid input
    }

    Record* records = malloc(numRecords * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        return NULL;
    }

    int maxKey = 10000; // Default maximum key value
    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < numRecords; i++) {
        Record record;
        int key;

        do {
            int offsetIndex = rand() % numRecords;
            int offset = offsets[offsetIndex];
            key = keys[offsetIndex] + offset;
        } while (key > maxKey || findDuplicate(records, i, key));

        record.key = key;
        records[i] = record;
    }

    return records;
}

int findDuplicate(Record* records, int index, int key) {
    for (int i = 0; i < index; i++) {
        if (records[i].key == key) {
            return 1; // Duplicate found
        }
    }
    return 0; // No duplicate found
