record_t* generate_records(int size, long* offsets, int* keys) {
    // Calculate total number of records
    int num_records = size * 2;

    // Initialize arrays
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int max_key = 0;

    for (int i = 0; i < num_records; i++) {
        int key, offset;
        do {
            // Generate random offset
            long random_offset = rand() % ((long)offsets[1] - (long)offsets[0]) + (long)offsets[0];
            // Generate random key
            int random_key = rand() % ((int)(keys[1] - keys[0])) + (int)keys[0];

            // Calculate unique key based on offset and random key
            key = (random_offset * 10000) + random_key;

            pthread_mutex_lock(&mutex);
            bool duplicate_key = false;
            for (int j = 0; j < i; j++) {
                if (records[j].key == key) {
                    duplicate_key = true;
                    break;
                }
            }
            pthread_mutex_unlock(&mutex);

            if (duplicate_key) {
                continue;
            }

            records[i].key = key;
            max_key = key > max_key ? key : max_key;
        } while (false);
    }

    free(offsets);
    free(keys);
    return records;
}

int main() {
    int size = 10; // Size of arrays
    long* offsets = (long*)malloc((size + 1) * sizeof(long));
    int* keys = (int*)malloc((size + 1) * sizeof(int));

    for (int i = 0; i < size; i++) {
        offsets[i] = i;
        keys[i] = i;
    }

    record_t* records = generate_records(size, offsets, keys);
    // Use the generated records
