    int* p = (int*)malloc(count * sizeof(int));
    for (int i = 0; i < count; i++) {
        p[i] = pdu[i].RNTI;
    }
    free(p);

    // Free allocated memory
    destroy_nfa_pdu(pdu, count);
    free(pem_string);

    return 1;
}

// Define the main function to handle command line arguments and parse input file
int main(int argc, char** argv) {
    // Parse command line arguments
    if (argc < 2 || strcmp(argv[1], "--manpage") == 0) {
        printf("Usage: %s [-cs] [-o output_file]\n", argv[0]);
        return 1;
    }

    // Read the input file line by line and process each line within a fixed time constraint
    FILE* file = fopen(argv[2], "r");
    if (file == NULL) {
        printf("Error opening input file\n");
        return 1;
    }

    int lines = 0;
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Process the line within a fixed time constraint
        sleep(1);  // Simulate processing time
        printf("Processed %d lines\n", ++lines);
    }
    fclose(file);

    return generatePEMCertificateAndNFAPIArray(request);
}
