import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class DeserializationService {

    public static <T> T deserialize(byte[] data, Class<T> expectedType) {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(data)) {
            return deserialize(bais, expectedType);
        } catch (IOException e) {
            String errorMessage = "Failed to deserialize byte array: " + new String(data);
            throw new DeserializationException(errorMessage, e);
        }
    }

    @SuppressWarnings("unchecked")
    private static <T> T deserialize(ByteArrayInputStream bais, Class<T> expectedType) throws IOException {
        ObjectInputStream ois = new ObjectInputStream(bais);
        try {
            return (T) ois.readObject();
        } catch (ClassNotFoundException e) {
            String errorMessage = "Expected class not found: " + expectedType.getName();
            ois.close();
            throw new DeserializationException(errorMessage, e);
        }
    }

    public static class DeserializationException extends Exception {

        public DeserializationException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
