// Function to create and manage a dynamic polygon array
Polygon* createPolygon(int initialSize, int maxCapacity) {
    Polygon* poly = (Polygon*)malloc(sizeof(Polygon));
    poly->nPoints = 0;
    poly->points = (Point*)malloc(initialSize * sizeof(Point));

    return poly;
}

// Function to resize the polygon array dynamically
void resizePolygon(Polygon* poly, int newSize) {
    if (newSize > maxCapacity) {
        printf("Side count exceeds maximum capacity. Skipping entries.\n");
        return;
    }

    Point* newPoints = (Point*)realloc(poly->points, newSize * sizeof(Point));
    if (!newPoints) {
        // Handle memory allocation failure
        free(poly->points);
        poly->points = NULL;
        return;
    }

    poly->points = newPoints;
    poly->nPoints = newSize;
}

// Function to insert a point into the polygon array
void addPoint(Polygon* poly, Point p) {
    if (poly->nPoints >= maxCapacity) {
        printf("Side count exceeds maximum capacity. Skipping entries.\n");
        return;
    }

    resizePolygon(poly, poly->nPoints + 1);
    poly->points[poly->nPoints] = p;
    poly->nPoints++;
}

// Function to delete a point from the polygon array
void removePoint(Polygon* poly) {
    if (poly->nPoints <= 0) return;

    Point* newPoints = (Point*)malloc((poly->nPoints - 1) * sizeof(Point));
    int i;
    for (i = 0; i < poly->nPoints - 1; i++) {
        newPoints[i] = poly->points[i];
    }

    free(poly->points);
    poly->points = newPoints;
    poly->nPoints--;
}

