    (*polygon_array)[*num_polygons].points = points;
    (*polygon_array)[*num_polygons].sides = sides;
    (*num_polygons)++;
}

// Function to delete a polygon from the array
void geom_mgmt_delete_polygon(polygon **polygon_array, int *num_polygons, int index) {
