// Initialize the system with the given configuration
void init_system(int config_max_profiles, int config_max_id_length) {
    if (config_max_profiles > MAX_USER_PROFILES || config_max_id_length > MAX_ID_LENGTH) {
        printf("Invalid configuration parameters. Limiting to %d profiles and %s ID length.\n", MAX_USER_PROFILES, MAX_ID_LENGTH);
    }

    max_profiles = config_max_profiles;
    max_id_length = config_max_id_length;

    // Allocate memory for the profiles array
    if ((profiles = (Profile*)malloc(max_profiles * PROFILE_MAX_SIZE)) == NULL) {
        printf("Memory allocation failed. Exiting.\n");
        exit(1);
    }

    num_profiles = 0;
}

// Add a new user profile with given attributes
int add_profile(int id, const char* name, double age, double lat, double lon) {
    if (num_profiles >= max_profiles) {
        printf("Maximum number of profiles reached. Cannot add more.\n");
        return -1;
    }

    // Calculate the index for the new profile
    int idx = num_profiles;

    // Copy the attributes to the profile structure
    strcpy(profiles[idx].name, name);
    profiles[idx].id = id;
    profiles[idx].age = age;
    profiles[idx].lat = lat;
    profiles[idx].lon = lon;

    num_profiles++;

    return 0;
}

// Update an existing user profile with given attributes
int update_profile(int id, const char* name, double age, double lat, double lon) {
    int i;
    for (i = 0; i < num_profiles; i++) {
        if (profiles[i].id == id) {
            // Copy the new attributes to the profile structure
            strcpy(profiles[i].name, name);
            profiles[i].age = age;
            profiles[i].lat = lat;
            profiles[i].lon = lon;

            return 0;
        }
    }

    printf("Profile not found. Cannot update.\n");
    return -1;
}

// Free the memory allocated for the user profiles
void free_profiles() {
    if (profiles != NULL) {
        free(profiles);
    }
}

