    int *keys = (int *)malloc(num_records * sizeof(int));

    for (int i = 0; i < num_records; i++) {
        offsets[i] = 0;
        keys[i] = 0;
    }

    record *records = (record *)malloc(num_records * sizeof(record));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100;
        records[i].name = (char *)malloc(50 * sizeof(char));
        strcpy(records[i].name, "Record ");
        for (int j = 0; j < 10; j++) {
            records[i].name[j] = 'a' + rand() % 26;
        }
        records[i].name[49] = '\0';
        records[i].values = (int *)malloc(100 * sizeof(int));
        for (int j = 0; j < 100; j++) {
            records[i].values[j] = j;
        }
    }

    return records;
}

void free_records(record *records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(records[i].name);
        free(records[i].values);
    }
    free(records);
    free((long *)keys);
    free(offsets);
