#include <time.h>

typedef struct {
    char c;
    short s;
    int i;
    struct record* next;
} record;

record* create_record(int max_records) {
    if (!max_records) return NULL;

    srand(time(NULL));
    record* head = NULL;
    record** records = (record**)malloc(max_records * sizeof(record*));

    for (int i = 0; i < max_records; i++) {
        record* curr = (record*)malloc(sizeof(record));
        if (!curr) return NULL;

        char c = 'a' + rand() % ('z' - 'a' + 1);
        short s = rand() % USHRT_MAX;
        int i = rand() % INT_MAX;

        curr->c = c;
        curr->s = s;
        curr->i = i;
        curr->next = (i < max_records - 1) ? records[i + 1] : NULL;

        if (!head) head = curr;
        records[i] = curr;
    }

    free(records);
    return head;
}
