// Function to create a new KVStore with initial capacity and growth increment
kvstore_t* kvstore_create(size_t initial_capacity, size_t grow_by) {
    kvstore_t* store = malloc(sizeof(kvstore_t));
    store->capacity = initial_capacity;
    store->keys = malloc(initial_capacity * sizeof(char));
    store->values = malloc(initial_capacity * sizeof(long));
    store->records = malloc(initial_capacity * sizeof(record_t));
