        char** new_keys = realloc(store->keys, new_capacity * sizeof(char));
        long* new_values = realloc(store->values, new_capacity * sizeof(long));
        record_t* new_records = realloc(store->records, new_capacity * sizeof(record_t));
        store->keys = new_keys;
