        store->values[index] = new_value;
        // Update metadata based on business rules
        // ...
    }
    pthread_mutex_unlock(&store->mutex);
}

// Function to delete a record from the KVStore
void kvstore_delete(kvstore_t* store, const char* key) {
    pthread_mutex_lock(&store->mutex);
    size_t index = strlen(key);
    if (index < store->capacity) {
        // Reclaim memory by shifting records and updating indices
        for (size_t i = index; i < store->capacity - 1; i++) {
            strcpy(store->keys + i, store->keys + i + 1);
            store->values[i] = store->values[i + 1];
            record_t* record = &store->records[i];
            record->value = store->records[i + 1].value;
        }
        store->capacity--;
    }
    pthread_mutex_unlock(&store->mutex);
}

