#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <unistd.h>
#include <openssl/sha.h>

char* generate_enhanced_filename(const char* input_filename) {
    if (input_filename == NULL || strlen(input_filename) > 512) {
        return "Error: Invalid filename";
    }

    // Calculate SHA-256 hash
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, input_filename, strlen(input_filename));
    SHA256_Final(hash, &sha256);

    // Convert SHA-256 hash to base64 encoded string
    int base64_len = 0;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        base64_len += 2 + ((hash[i] >> 4) % 64);
        if (i == 7 || i == 15 || i == 23 || i == 31) {
            base64_len++;
        }
    }
    char* base64_encoded = malloc((base64_len + 1) * sizeof(char));
    for (int i = 0, j = 0; i < SHA256_DIGEST_LENGTH; i++) {
        int val = hash[i];
        if (j % 2 == 0) {
            sprintf(&base64_encoded[j++], "%02x", (val >> 4));
        }
        if (j % 3 != 0 && j <= base64_len - 1) {
            sprintf(&base64_encoded[j++], ".");
        }
    }
    base64_encoded[base64_len] = '\0';

    // Generate random sequence of digits
    char* random_digits = malloc(10 * sizeof(char));
    srand(time(NULL));
    for (int i = 0; i < 10; i++) {
        sprintf(&random_digits[i], "%c", '0' + rand() % 10);
    }
    random_digits[10] = '\0';

    // Generate timestamp
    time_t now = time(NULL);
    char* timestamp = malloc(26 * sizeof(char));
    strftime(timestamp, 25, "%Y%m%d%H%M%S", localtime(&now));
    timestamp[25] = '\0';

    // Combine components to form the enhanced filename
    int enhanced_len = strlen(input_filename) + strlen(base64_encoded) + strlen(random_digits) + strlen(timestamp) + 1;
    char* enhanced_filename = malloc(enhanced_len * sizeof(char));
    sprintf(enhanced_filename, "%s-%s-%s", input_filename, base64_encoded, timestamp);
    free(base64_encoded);
    free(random_digits);
    free(timestamp);

    return enhanced_filename;
}
