#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <md5.h>

char* generate_extended_filename(const char* filename) {
    // Create a temporary directory for storing intermediate files
    char temp_dir[256];
    sprintf(temp_dir, "/tmp/%ld", time(NULL));
    mkdir(temp_dir, 0700);

    // Calculate the sequence of digits from ASCII values of characters in the original filename
    unsigned int ascii_sum = 0;
    for (int i = 0; i < strlen(filename); i++) {
        ascii_sum += (unsigned int)filename[i];
    }
    char* digit_sequence = malloc(10);
    sprintf(digit_sequence, "%u", ascii_sum);

    // Determine the specific file type derived from original filename's characters
    int type_id = 0;
    for (int i = 0; i < strlen(filename); i++) {
        type_id += (int)filename[i];
    }
    char* file_type = malloc(5);
    sprintf(file_type, ".%c", 'a' + (type_id % 26));

    // Calculate the MD5 hash of the original filename as a hexadecimal string
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, filename, strlen(filename));
    MD5_Final(md5_hash, &ctx);

    // Append the MD5 hash to the end of the extension
    char* extension = malloc(strlen(digit_sequence) + strlen(file_type) + 33);
    sprintf(extension, "%s%s%x", digit_sequence, file_type, md5_hash);

    // Create and return the new filename with extended extension
    char* new_filename = malloc(512);
    sprintf(new_filename, "/%s/%s", temp_dir, extension);

    // Clean up temporary files and directories
    unlink(new_filename);
    rmdir(temp_dir);

