ImageInfo parseImage(char* filePath) {
    ImageInfo info = {0};
    FILE* file = fopen(filePath, "rb");
    if (file == NULL) {
        printf("Error opening file: %s\n", filePath);
        return info;
    }

    // Read header and extract bits per sample and samples per pixel
    unsigned short int16le;
    fread(&int16le, sizeof(unsigned short), 1, file);
    info.bits_per_sample = (int)ntohs(int16le);
    if (info.bits_per_sample == 12 || info.bits_per_sample == 16) {
        // Check for extra samples
        unsigned int uint32le;
        fread(&uint32le, sizeof(unsigned int), 1, file);
        info.extra_samples = (int)ntohs(uint32le);
    }

    fclose(file);

    return info;
}

int main() {
    ImageInfo info = parseImage("path_to_your_image.tiff");
    printf("Bits per sample: %d\n", info.bits_per_sample);
    printf("Samples per pixel: %d\n", info.samples_per_pixel);
    if (info.extra_samples > 0) {
        printf("Extra samples: %d\n", info.extra_samples);
    }

    return 0;
}

