const asyncReduce = (arr, callback, options = {}) => {
  const { batchSize = 100, timeout = 5000 } = options;
  let accumulatedResult = null;

  const processBatch = async (start, end) => {
    try {
      const batch = arr.slice(start, end);
      const partialResult = await callback(batch);
      if (!partialResult) throw new Error("Invalid result");
      if (accumulatedResult === null) accumulatedResult = partialResult;
      else accumulatedResult += partialResult;
    } catch (err) {
      console.error(err);
      accumulatedResult = err;
    }
  };

  const trackProgress = async (start, end) => {
    try {
      await processBatch(start, end);
      return { status: "complete", start, end };
    } catch (err) {
      console.error(err);
      return { status: "failed", start, end };
    }
  };

  let taskQueue = [];
  const activeTasks = {};

  const addTask = async (start, end) => {
    if (taskQueue.length >= 10) await pauseResume();
    taskQueue.push({ start, end });
    const taskId = Math.floor(Math.random() * 10000);
    activeTasks[taskId] = trackProgress(start, end);
    console.log(`Added task ${taskId} for range (${start}, ${end})`);
  };

  const pauseResume = async () => {
    await Promise.all(Object.values(activeTasks).map((task) => task));
    await new Promise((resolve) => setTimeout(resolve, 1000)); // simulate pause
    console.log("Resumed");
  };

  let statusMap = {};
  const monitorStatus = async (taskId) => {
    if (!statusMap[taskId]) return;
    try {
      const { status } = await activeTasks[taskId];
      if (status === "complete") delete activeTasks[taskId];
      else console.log(`Task ${taskId} is still processing...`);
    } catch (err) {
      console.error(err);
    }
  };

  for (let i = 0; i < arr.length; i += batchSize) {
    addTask(i, Math.min(i + batchSize, arr.length));
  }

  const externalService = {
    async processBatch(batch) {
      try {
        const result = await processBatch(batch[0], batch[batch.length - 1]);
        return result;
      } catch (err) {
        console.error(err);
        return null;
      }
    },
  };

  const processExternalBatches = async () => {
    let batches = [];
    for await (const task of Object.values(activeTasks)) {
      if (task.status === "complete") continue;
      if (task.status === "failed") throw new Error("Batch failed");
      let start = task.start, end = task.end;
      while (start < end) {
        batches.push([start, Math.min(start + batchSize, end)]);
        start += batchSize;
      }
    }
    try {
      const results = await Promise.all(batches.map(externalService.processBatch));
      for (let i = 0; i < results.length; i++) {
        if (!results[i]) throw new Error("Invalid result");
        accumulatedResult += results[i];
      }
    } catch (err) {
      console.error(err);
      accumulatedResult = err;
    }
  };

  return { accumulate: () => accumulatedResult, monitorStatus };
};
