    public class WebsiteRunner
    {
        public static Process StartWebsite(string directoryPath, string siteName, bool validateWebConfig, bool logDetailedSteps)
        {
            if (Process.GetProcessesByName(siteName).Any())
            {
                Console.WriteLine("Warning: A website with the same name is already running. Returning null.");
                return null;
            }

            if (validateWebConfig && !File.Exists(Path.Combine(directoryPath, "web.config")))
            {
                throw new FileNotFoundException("Web.config file not found.", Path.Combine(directoryPath, "web.config"));
