                ProcessStartInfo processStartInfo = new ProcessStartInfo
                {
                    FileName = "IISExpress.exe",
                    Arguments = $"\"{siteName}\"",
                    WorkingDirectory = directoryPath,
                    RedirectStandardError = true,
                    UseShellExecute = false,
                    CreateNoWindow = true
                };

                Process process = Process.Start(processStartInfo);

                // Handle exceptions during process creation and termination
                try
                {
                    process.WaitForExit(30000); // timeout after 30 seconds
                    process.Dispose();
                }
                catch (Exception ex)
                {
                    Console.WriteLine("Error starting or terminating the website: " + ex.Message);
                }

                return process;
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error running the website: " + ex.Message);
