typedef struct {
    char filepath[256];
    char format[32];
    int converted;
} Image;

Image* image_array = NULL;
int image_count = 0;
int image_index = 0;

void process_image(Image* img) {
    // Convert the image to WebP
    system("third-party-tool --input-image=%s --output-image=/path/to/output.webp", img->filepath);

    if (strcmp(img->format, "JPEG") == 0 || strcmp(img->format, "PNG") == 0 || strcmp(img->format, "GIF") == 0) {
        // Update the image metadata
        system("external-api --refresh-metadata %s");

        img->converted = 1;
    } else {
        // Handle unknown file formats
        printf("Unknown file format: %s\n", img->filepath);
    }
}

int manage_images(const char* source_dir) {
    DIR* dir = opendir(source_dir);

    if (dir == NULL) {
        return 1; // Error opening directory
    }

    struct dirent* entry;

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        Image* img = (Image*)malloc(sizeof(Image));

        strcpy(img->filepath, source_dir);
        strcat(img->filepath, "/");
        strcat(img->filepath, entry->d_name);

        // Determine the file format
        char* dot = strrchr(entry->d_name, '.');

        if (dot != NULL) {
            strncpy(img->format, dot + 1, 32);
            img->format[31] = '\0';
        }

        img->converted = 0;

        image_array = realloc(image_array, (image_count + 1) * sizeof(Image));
        image_array[image_index++] = *img;
        image_count++;
    }

    closedir(dir);

    for (int i = 0; i < image_count; i++) {
        process_image(&image_array[i]);

        // Handle conversion errors
        if (!image_array[i].converted) {
            printf("Conversion failed: %s\n", image_array[i].filepath);
        }
    }

    free(image_array);
    image_array = NULL;
    image_index = 0;
    image_count = 0;

    return 0;
}
