} GraphDatabaseManager;

GraphDatabaseManager* graphDatabaseManagerCreate(int offsetSize, int keyValueSize, int recordCount, int minValue, int maxValue) {
    if (offsetSize <= 0 || keyValueSize <= 0 || recordCount <= 0 || minValue > maxValue) {
        return NULL; // Handle invalid configuration parameters
    }

    GraphDatabaseManager* manager = (GraphDatabaseManager*)malloc(sizeof(GraphDatabaseManager));
    if (!manager) {
        return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < offsetSize; i++) {
        manager->offset[i] = i;
    }
    for (int i = 0; i < keyValueSize; i++) {
        manager->key[i] = i;
    }
    for (int i = 0; i < recordCount; i++) {
        int randomValue = RandomValueGeneratorGenerateRandomInt(minValue, maxValue);
        manager->record[i].value = randomValue;
    }

    return manager;
}

void graphDatabaseManagerFree(GraphDatabaseManager* manager) {
    if (!manager) {
        return; // Handle null pointer
    }
    free(manager);
}

int graphDatabaseManagerGetRecordCount(GraphDatabaseManager* manager) {
    if (!manager) {
        return -1; // Handle null pointer
    }
    return sizeof(manager->record) / sizeof(manager->record[0]);
}

