    Record* records = NULL;
    size_t used = 0;
    size_t allocated = 0;

    // Dynamic memory allocation
    while (allocated < capacity) {
        void* block = malloc(offsetof(Record, identifier) + identifier_length * sizeof(char));
        if (!block) return -1; // Memory allocation failed

        records = realloc(records, (used + 1) * sizeof(Record) + allocated);
        if (!records) return -1; // Reallocation failed

        Record* record = block;
        char* identifier = ((char*)record) + offsetof(Record, identifier);
        record->identifier = identifier;

        for (size_t i = 0; i < identifier_length; i++) {
            identifier[i] = (i % 2 == 0 ? 'A' : 'B'); // Initialize with deterministic values
        }

        record->value = 1.23; // Initialize value
        record->timestamp = get_current_timestamp(); // Get high-resolution timestamp

        allocated += sizeof(Record) + identifier_length * sizeof(char);
        used++;
    }

    // Populate records
    for (size_t i = 0; i < used; i++) {
        // Update records with new data
    }

    return 0;
}

uint64_t get_current_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
}

