typedef struct {
    char* title;
    time_t deadline;
    double importance_factor;
} project;

project** projects = NULL;
int project_count = 0;
int project_capacity = 0;

void* my_malloc(size_t size) {
    return malloc(size);
}

void* my_realloc(void* ptr, size_t size) {
    return realloc(ptr, size);
}

void my_free(void* ptr) {
    free(ptr);
}

// Project Management Functions
project* get_project_by_title(const char* title) {
    for (int i = 0; i < project_count; i++) {
        if (strcmp(projects[i]->title, title) == 0) {
            return projects[i];
        }
    }
    return NULL;
}

void update_project_deadline_and_importance_factor(const char* title, time_t new_deadline, double new_importance_factor) {
    project* project = get_project_by_title(title);
    if (project != NULL) {
        project->deadline = new_deadline;
        project->importance_factor = new_importance_factor;
    }
}

void add_project(char* title, time_t deadline, double importance_factor) {
    // Handle duplicate titles
    if (get_project_by_title(title) != NULL) {
        printf("Error: Project title already exists.\n");
        return;
    }

    project* project = my_malloc(sizeof(project));
    if (project == NULL) {
        printf("Error: Memory allocation failed.\n");
        return;
    }

    project->title = my_strdup(title);
    if (project->title == NULL) {
        my_free(project);
        printf("Error: String duplication failed.\n");
        return;
    }
    project->deadline = deadline;
    project->importance_factor = importance_factor;

    // Resize the array if necessary
    if (project_count >= project_capacity) {
        project_capacity *= 2;
        projects = my_realloc(projects, project_capacity * sizeof(project*));
    }

    projects[project_count] = project;
    project_count++;
}

void remove_project(const char* title) {
    for (int i = 0; i < project_count; i++) {
        if (strcmp(projects[i]->title, title) == 0) {
            my_free(projects[i]->title);
            my_free(projects[i]);
            for (int j = i; j < project_count - 1; j++) {
                projects[j] = projects[j + 1];
            }
            project_count--;
            return;
        }
    }
}

void initialize_projects(int num_projects) {
    // Initialize the list with a specified number of projects
    project_capacity = num_projects * 2;
    projects = my_calloc(project_capacity, sizeof(project*));
    for (int i = 0; i < num_projects; i++) {
        char* title = my_strdup(rand_title());
        time_t deadline = rand_deadline();
        double importance_factor = rand_importance_factor();
        add_project(title, deadline, importance_factor);
        my_free(title);
    }
}

char* rand_title() {
    // Generate a random project title
    static char buffer[32];
    sprintf(buffer, "Project %d", (int)rand());
    return my_strdup(buffer);
}

time_t rand_deadline() {
    // Generate a random deadline within the next 30 days
    time_t now = time(NULL);
    return now + (rand() % 2592000); // 2592000 seconds is approximately 30 days
}

double rand_importance_factor() {
    // Generate a random importance factor between 0.5 and 1.0
    return (double)rand() / RAND_MAX * 0.5 + 0.5;
}

// Log function for debugging and monitoring
void log_operation(const char* operation, const char* title) {
    printf("%s: %s\n", operation, title);
}
