record* process_file(int num_records, long max_offset_value, int min_data_range, int max_data_range) {
    if (num_records <= 0 || max_offset_value < 0 || min_data_range > max_data_range) {
        return NULL; // Handle invalid input
    }

    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));

    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (max_offset_value + 1); // Validate and randomize offset values
        keys[i] = i;
    }

    // Sort the 'keys' array using merge sort
    int left = 0, right = num_records - 1;
    while (left < right) {
        int mid = (left + right) / 2;
        for (int j = 0; j <= mid; j++) {
            if (keys[j] > keys[mid]) {
                left = mid + 1;
                break;
            }
        }
        right = mid;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < num_records; i++) {
        records[i].data = rand() % ((max_data_range - min_data_range + 1)) + min_data_range; // Randomize record data values
    }

    free(offsets);
    free(keys);

    return records;
}
