    return 0;
}

void sort_keys(int low, int high) {
    if(low < high) {
        int mid = (low + high) / 2;

        // Sort the left half
        sort_keys(low, mid);

        // Sort the right half
        sort_keys(mid + 1, high);

        // Merge the two sorted halves
        merge(low, mid, high);
    }
}

void merge(int low, int mid, int high) {
    int i = low;
    int j = mid + 1;
    int k = low;

    while(i <= mid && j <= high) {
        if(keys[i] < keys[j]) {
            keys[k++] = keys[i++];
        } else {
            keys[k++] = keys[j++];
        }
    }

    // Copy remaining elements from left half, if any
    while(i <= mid) {
        keys[k++] = keys[i++];
    }

    // Copy remaining elements from right half, if any
    while(j <= high) {
        keys[k++] = keys[j++];
    }
}
