// Define a custom sorting algorithm for the keys array
void sort_keys(int* keys, size_t n) {
    int i, j;
    for (i = 0; i < n; i++) {
        for (j = i + 1; j < n; j++) {
            if (keys[i] > keys[j]) {
                int temp = keys[i];
                keys[i] = keys[j];
                keys[j] = temp;
            }
        }
    }
}

// Define a function to initialize the data structures
int init_data_structures(long* offsets, int* keys, Record** records, size_t n) {
    // Initialize memory pool for dynamic allocation
    void* memory_pool = malloc(1024 * 1024); // Allocate 1MB of memory

    // Validate and allocate memory for the offsets array
    long max_offset = 0;
    for (size_t i = 0; i < n; i++) {
        if (offsets[i] <= 0 || my_hash(offsets[i]) >= 10000000) {
            return -1; // Invalid offset or hash value
        }
        max_offset = offsets[i];
    }

    // Initialize and allocate memory for the keys array
    sort_keys(keys, n);

    // Initialize and allocate memory for the records array
    *records = (Record**)malloc(n * sizeof(Record));
    for (size_t i = 0; i < n; i++) {
        (*records)[i].key = keys[i];
        (*records)[i].data = rand() % 100; // Random data initialization
    }

    // Initialize and allocate memory for the hash table
