        identifiers[i] = (char*)malloc(identifier_length + 1);
        sprintf(identifiers[i], "%d", (*records)[i].key);
        values[i] = pow(((*records)[i].data % 10), 2); // Generate double value based on polynomial function
    }

    // Free memory pool and return success
    free(memory_pool);
    return 0;
}

