#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define a structure to represent a record
typedef struct {
    long offset;
    int key;
    bool flag;
} Record;

// Define a structure to manage the dynamic collection of records
typedef struct {
    pthread_mutex_t lock; // Mutex for thread safety
    Record** records; // Array of pointers to records
    int numRecords; // Number of records in the collection
} RecordCollection;

// Initialize the record collection
void initRecordCollection(RecordCollection* collection) {
    pthread_mutex_init(&collection->lock, NULL);
    collection->records = NULL;
    collection->numRecords = 0;
}

// Insert a new record into the collection
void insertRecord(RecordCollection* collection, long offset, int key, bool flag) {
    pthread_mutex_lock(&collection->lock);

    // Allocate memory for a new record and add it to the collection
    Record* record = malloc(sizeof(Record));
    record->offset = offset;
    record->key = key;
    record->flag = flag;

    collection->records = realloc(collection->records, (collection->numRecords + 1) * sizeof(Record*));
    collection->records[collection->numRecords] = record;
    collection->numRecords++;

    pthread_mutex_unlock(&collection->lock);
}

// Delete a record from the collection based on its key
void deleteRecord(RecordCollection* collection, int key) {
    pthread_mutex_lock(&collection->lock);

    // Find and remove the record with the given key
    for (int i = 0; i < collection->numRecords; i++) {
        if (collection->records[i]->key == key) {
            free(collection->records[i]);
            memmove(&collection->records[i], &collection->records[i + 1], (collection->numRecords - i - 1) * sizeof(Record*));
            collection->numRecords--;
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

// Update the flag of a record based on its key
void updateRecordFlag(RecordCollection* collection, int key, bool flag) {
    pthread_mutex_lock(&collection->lock);

    // Find and update the record with the given key
    for (int i = 0; i < collection->numRecords; i++) {
        if (collection->records[i]->key == key) {
            collection->records[i]->flag = flag;
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

// Serialize the record collection to a file
void serializeRecordCollection(RecordCollection* collection, FILE* file) {
    pthread_mutex_lock(&collection->lock);

    // Write the number of records and their contents to the file
    fwrite(&collection->numRecords, sizeof(int), 1, file);
    for (int i = 0; i < collection->numRecords; i++) {
        Record* record = collection->records[i];
        fwrite(&record->offset, sizeof(long), 1, file);
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->flag, sizeof(bool), 1, file);
    }

    pthread_mutex_unlock(&collection->lock);
}

// Deserialize the record collection from a file
void deserializeRecordCollection(RecordCollection* collection, FILE* file) {
    pthread_mutex_lock(&collection->lock);

    // Read the number of records and their contents from the file
    int numRecords;
    fread(&numRecords, sizeof(int), 1, file);
    collection->records = realloc(collection->records, numRecords * sizeof(Record*));
    for (int i = 0; i < numRecords; i++) {
        long offset;
        int key;
        bool flag;
        fread(&offset, sizeof(long), 1, file);
        fread(&key, sizeof(int), 1, file);
        fread(&flag, sizeof(bool), 1, file);

        Record* record = malloc(sizeof(Record));
        record->offset = offset;
        record->key = key;
        record->flag = flag;

        collection->records[i] = record;
    }
    collection->numRecords = numRecords;

    pthread_mutex_unlock(&collection->lock);
}

// Example usage:
int main() {
    RecordCollection collection;
    initRecordCollection(&collection);

    insertRecord(&collection, 10, 1, true);
    insertRecord(&collection, 20, 2, false);
    insertRecord(&collection, 30, 3, true);

    deleteRecord(&collection, 2);

    updateRecordFlag(&collection, 1, false);

    FILE* file = fopen("record_collection.bin", "wb");
    serializeRecordCollection(&collection, file);
    fclose(file);

    file = fopen("record_collection.bin", "rb");
