    int size2 = 200;
    int maxThreshold = 1024;

    unsigned long *timestamps;
    double *measurements;
    char **labels;

    initArrays(size1, &timestamps, &measurements, &labels);

    sensorData *data;
    initSlabAllocator(size1, &data);

    while (true) {
        updateMeasurements(size1, &measurements, &data);
        monitorMemoryUsage(maxThreshold, configParams);
    }

    return 0;
}
