class EventQueue {
public:
    void push(Event e) {
        unique_lock<mutex> lock(queue_mutex);
        while (!queue.empty()) {
            if (queue.front().timestamp <= e.timestamp)
                break; // Skip events with same or older timestamps
        }
        queue.push_back(e);
    }

    bool try_pop(Event& e) {
        lock_guard<mutex> lock(queue_mutex);
        if (queue.empty())
