void* allocate_array(size_t size) {
    void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        return NULL;
    }
    return ptr;
}

void deallocate_array(void* arr, size_t size) {
    munmap(arr, size);
}

int add_vertices_and_edges(int num_records, int max_threshold_kb) {
    int total_size = sizeof(record_t) * num_records + sizeof(long) * num_records + sizeof(int) * num_records;
    total_size += (num_records / 1024) * 4; // overhead of memory allocation and pointer management

    if (total_size > max_threshold_kb * 1024) {
        return -1; // error: memory threshold exceeded
    }

    void* records = allocate_array(total_size);
    if (!records) {
        return -2; // error: failed to allocate memory for records array
    }

    void* offsets = allocate_array(sizeof(long) * num_records);
    if (!offsets) {
        deallocate_array(records, total_size);
        return -3; // error: failed to allocate memory for offsets array
    }

    int i;
    for (i = 0; i < num_records; i++) {
        record_t* rec = (record_t*)records + i;
        rec->key = rand() % 100; // set random key value
        rec->offset = (long)i * sizeof(record_t); // set offset value based on record index
    }

    void* edges = allocate_array(sizeof(int) * num_records);
    if (!edges) {
        deallocate_array(records, total_size);
        deallocate_array(offsets, sizeof(long) * num_records);
        return -4; // error: failed to allocate memory for edges array
    }

    for (i = 0; i < num_records; i++) {
