#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <map>

class Record {
public:
    int key;
    long offset;

    Record(int k, long o) : key(k), offset(o) {}
};

class DynamicRecordCollection {
private:
    std::vector<Record> records;
    std::mutex recordMutex;
    std::condition_variable recordCond;
    bool shutdown;

public:
    DynamicRecordCollection() : shutdown(false) {}

    void addRecord(int key, long offset) {
        std::unique_lock<std::mutex> lock(recordMutex);
        while (!shutdown) {
            if (records.size() < 10000) {
                records.emplace_back(key, offset);
                break;
            }
            recordCond.wait(lock);
        }
    }

    void removeRecord(int key) {
        std::lock_guard<std::mutex> lock(recordMutex);
        for (auto it = records.begin(); it != records.end(); ++it) {
            if (it->key == key) {
                records.erase(it);
                break;
            }
        }
    }

    bool getRecord(int key, Record& record) {
        std::unique_lock<std::mutex> lock(recordMutex);
        for (const auto& r : records) {
            if (r.key == key) {
                record = r;
                return true;
            }
        }
        return false;
    }

    void shutdownFunction() {
        {
            std::lock_guard<std::mutex> lock(recordMutex);
            shutdown = true;
        }
        recordCond.notify_all();
    }

    bool isShutdown() const {
        return shutdown;
    }
};

