int custom_malloc(size_t size) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    void* ptr = malloc(size);
    if (!ptr && size > 0) {
        // fallback strategy: try to reuse memory
        for (size_t i = 0; i < size / sizeof(void*); i++) {
            ptr = *(void**)(i * sizeof(void*) + (void*)malloc(1));
            if (ptr) break;
        }
