public class TextProcessor {
    public static String processText(String input, int iterations) throws IOException {
        // Sanitize the input
        if (input == null || input.isEmpty()) {
            return "";
        }

        // Normalize and encode the text
        String normalizedInput = normalize(input);
        byte[] encodedBytes = encode(normalizedInput);

        // Compress the data using a custom algorithm
        ByteArrayOutputStream compressedStream = new ByteArrayOutputStream();
        compress(encodedBytes, compressedStream);

        // Generate SHA-256 hash for the compressed data
        MessageDigest sha256 = MessageDigest.getInstance("SHA-256");
        byte[] hashedBytes = sha256.digest(compressedStream.toByteArray());

        // Calculate the iteration count and generate multiple hashes if needed
        for (int i = 0; i < iterations; i++) {
            sha256.update(hashedBytes);
            hashedBytes = sha256.digest();
        }

        // Convert the hash bytes to a hexadecimal string
        StringBuilder hashString = new StringBuilder();
        for (byte b : hashedBytes) {
            String hex = Integer.toHexString(b & 0xFF);
            hashString.append(hex.length() == 1 ? "0" + hex : hex);
        }
        return hashString.toString();

