int max_records = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* allocate_record(int key, long offset) {
    pthread_mutex_lock(&lock);

    int i;
    for (i = 0; i < cache_size; i++) {
        if (!cache[i].key && !cache[i].offset) {
            break;
        }
    }

    if (i == cache_size) {
        pthread_cond_signal(&cond);
        // wait for signal
        pthread_mutex_unlock(&lock);
        return NULL;
    } else {
        record* rec = &cache[i];
        rec->key = key;
        rec->offset = offset;
        pthread_mutex_unlock(&lock);
        return rec;
    }
}

void deallocate_record(record* rec) {
    pthread_mutex_lock(&lock);

    int i;
    for (i = 0; i < cache_size; i++) {
        if (&cache[i] == rec) {
            break;
        }
    }

    if (i != cache_size) {
        cache[i].key = NULL;
        cache[i].offset = -1;
    } else {
        pthread_cond_signal(&cond);
    }
    pthread_mutex_unlock(&lock);
}

