// Custom data structure for storing name-value pairs
typedef struct {
    char *Name;
    int Value;
    float FloatValue;
    struct Node* left, *right;
} Node;

Node* create_node(char* name, int value, float float_value) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->Name = (char*)malloc(strlen(name) + 1);
    strcpy(node->Name, name);

    node->Value = value;
    node->FloatValue = float_value;

    node->left = node->right = NULL;

    return node;
}

// Function to perform binary search on the tree
Node* find_node(Node* root, char* target_name) {
    if (!root || !strcmp(root->Name, target_name)) {
        return root;
    }

    int cmp = strcmp(target_name, root->Name);
    if (cmp < 0) {
        return find_node(root->left, target_name);
    } else if (cmp > 0) {
        return find_node(root->right, target_name);
    }

    return NULL;
}

// Function to insert a new node into the tree
void insert_node(Node** root, char* name, int value, float float_value) {
    Node* node = create_node(name, value, float_value);

    if (!(*root)) {
        *root = node;
        return;
    }

    Node* current = *root;
    Node* parent = NULL;

    while (current) {
        parent = current;
        int cmp = strcmp(name, current->Name);
        if (cmp < 0) {
            current = current->left;
        } else if (cmp > 0) {
            current = current->right;
        } else {
            free(node); // Node already exists
            return;
        }
    }

    node->parent = parent;

    if (parent) {
        int cmp = strcmp(name, parent->Name);
        if (cmp < 0) {
            parent->left = node;
        } else {
            parent->right = node;
        }
    }

    // Rebalance the tree after insertion
}

// Function to free a node and its descendants
void free_node(Node* node) {
    if (!node) return;

    if (node->left) free_node(node->left);
    if (node->right) free_node(node->right);

    free(node->Name);
    free(node);
}

int main() {
    // Initialize the tree with some example nodes
    Node* root = NULL;
    insert_node(&root, "Node1", 10, 2.5f);
    insert_node(&root, "Node2", 20, 3.0f);
    insert_node(&root, "Node3", 30, 4.0f);

    // Perform a search for an existing node
    Node* found = find_node(root, "Node1");
    if (found) printf("Found: %s with value %d and float_value %.2f\n", found->Name, found->Value, found->FloatValue);

    return 0;
}
