#define MAX_MEMORY 1024 // Maximum allowed memory usage in MB
#define MEMORY_STEP 16   // Step size for adjusting memory allocation

typedef struct {
    int vertex_count;
    int edge_count;
    pthread_mutex_t lock; // Lock for concurrent access control
} GraphDatabase;

void* manage_memory(void* arg) {
    GraphDatabase* graph = (GraphDatabase*)arg;

    // Allocate initial memory
    size_t total_memory = MAX_MEMORY * 1024 * 1024; // Convert MB to bytes
    void* data = malloc(total_memory);
    if (!data) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    while (1) {
        // Monitor memory usage and adjust allocation as needed
        size_t used_memory = total_memory * 0.8; // Reserve 20% for future growth

        pthread_mutex_lock(&graph->lock);

        if (total_memory < used_memory) {
            total_memory *= 2;
            free(data);
            data = realloc(NULL, total_memory);
            if (!data) {
                printf("Memory allocation failed\n");
                break;
            }
        }

        pthread_mutex_unlock(&graph->lock);
    }

    free(data);
    return NULL;
}

void graph_database_init(GraphDatabase* graph) {
    graph->vertex_count = 0;
    graph->edge_count = 0;
    pthread_mutex_init(&graph->lock, NULL);
}

int main() {
    GraphDatabase graph;
    pthread_t thread;

    graph_database_init(&graph);

    if (pthread_create(&thread, NULL, manage_memory, &graph) != 0) {
        printf("Thread creation failed\n");
