    long *offsets = NULL;
    int *keys = NULL;
    Record **records = NULL;

    // Allocate memory for arrays
    if ((offsets = (long *)malloc(num_records * sizeof(long))) == NULL)
        return -1;  // Out of memory
    memset(offsets, 0, num_records * sizeof(long));

    if ((keys = (int *)malloc(num_records * sizeof(int))) == NULL) {
        free(offsets);
        return -2;  // Out of memory
    }
    memset(keys, 0, num_records * sizeof(int));

    if ((records = (Record **)malloc(num_records * sizeof(Record *))) == NULL) {
        free(offsets);
        free(keys);
        return -3;  // Out of memory
    }
    for (int i = 0; i < num_records; i++) {
        records[i] = (Record *)malloc(sizeof(Record) + max_buffer_size);
        if (records[i] == NULL) {
            for (int j = 0; j <= i; j++)
                free(records[j]);
            free(offsets);
            free(keys);
            return -4;  // Out of memory
        }
        memset(records[i]->buffer, 0, max_buffer_size + 1);
        records[i]->value = rand() % 100;
    }

    for (int i = 0; i < num_records; i++) {
        srand(time(NULL) + i);  // Seed for randomization
        for (int j = 0; j < max_buffer_size; j++)
            ((char *)records[i]->buffer)[j] = (rand() % 26) + 'a';
    }

    free(offsets);
    return 0;
}
