    }

    fclose(file);

    int config_fd = open((char*)strcat((char*)malloc(strlen("settings.conf_") + strlen(timestamp) + 1), "settings.conf_"), O_RDWR | O_CREAT, 0666);

    if (config_fd > -1) {
        fwrite((void*)timestamp, sizeof(char), strlen(timestamp), config_fd);
        fclose(fdopen(config_fd, "w"));

        close(config_fd);
    }

}

int main() {
