    record** data = malloc(sizeof(record*) * size);
    long* offset = malloc(sizeof(long) * size);
    int* keys = malloc(sizeof(int) * size);

    // Initialize the arrays
    for (int i = 0; i < size; ++i) {
        data[i] = malloc(sizeof(record));
        offset[i] = rand() % 100;
        keys[i] = rand() % 10;
        data[i]->value = rand() % 200;
