#include <stdlib.h>
#include <stdio.h>

// Define the data_entry structure
typedef struct {
    int key;
    char* value;
} data_entry;

// Define a custom hash table type
typedef struct {
    size_t capacity;
    size_t size;
    int** buckets;
    data_entry** entries;
} hash_table;

// Initialize an empty hash table with a given initial capacity
hash_table* init_hash_table(size_t capacity) {
    hash_table* ht = (hash_table*)malloc(sizeof(hash_table));
    ht->capacity = capacity;
    ht->size = 0;
    ht->buckets = (int**)calloc(capacity, sizeof(int*));
    ht->entries = (data_entry**)calloc(capacity, sizeof(data_entry*));
    return ht;
}

// Resize the hash table when necessary
void resize_hash_table(hash_table* ht) {
    size_t new_capacity = ht->capacity * 2;
    int** new_buckets = (int**)realloc(ht->buckets, new_capacity * sizeof(int*));
    data_entry** new_entries = (data_entry**)realloc(ht->entries, new_capacity * sizeof(data_entry*));
    for (size_t i = 0; i < new_capacity; ++i) {
        new_buckets[i] = NULL;
        new_entries[i] = NULL;
    }
    ht->capacity = new_capacity;
    ht->buckets = new_buckets;
    ht->entries = new_entries;
}

// Insert a data entry into the hash table
void insert_data_entry(hash_table* ht, int key, const char* value) {
    size_t index = key % ht->capacity;
    if (ht->buckets[index] == NULL) {
        ht->buckets[index] = (int*)malloc(sizeof(int));
        ht->entries[index] = (data_entry*)malloc(sizeof(data_entry));
        *ht->buckets[index] = key;
        ((data_entry*)ht->entries[index])->key = key;
        ((data_entry*)ht->entries[index])->value = strdup(value);
    } else {
        // Handle collision using separate chaining
        data_entry* entry = (data_entry*)malloc(sizeof(data_entry));
        entry->key = key;
        entry->value = strdup(value);
        data_entry** current_entries = &((data_entry*)ht->entries[index])->next;
        while (*current_entries) {
            if ((*current_entries)->key == key) {
                free((*current_entries)->value);
                *current_entries = entry;
                return;
            }
            current_entries = &(*current_entries)->next;
        }
        *current_entries = entry;
    }
}

// Retrieve a data entry from the hash table
data_entry* get_data_entry(hash_table* ht, int key) {
    size_t index = key % ht->capacity;
    if (ht->buckets[index] != NULL) {
        data_entry* entry = (data_entry*)ht->entries[index];
        while (entry && entry->key != key) {
            entry = ((data_entry*)ht->entries[index])->next;
        }
        return entry ? entry : NULL;
    } else {
        return NULL;
    }
}

// Delete a data entry from the hash table
void delete_data_entry(hash_table* ht, int key) {
    size_t index = key % ht->capacity;
    if (ht->buckets[index] != NULL) {
        data_entry** current_entries = &((data_entry*)ht->entries[index]);
        while (*current_entries && (*current_entries)->key != key) {
            current_entries = &(*current_entries)->next;
        }
        if (*current_entries) {
            free((*current_entries)->value);
            *current_entries = NULL;
        }
    }
}

// Free the memory allocated for a hash table
void free_hash_table(hash_table* ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        if (ht->buckets[i] != NULL) {
            data_entry* entry = (data_entry*)ht->entries[i];
            while (entry) {
                free(entry->value);
                data_entry* next = entry->next;
                free(entry);
                entry = next;
            }
        }
    }
    free(ht->entries);
    free(ht->buckets);
    free(ht);
}

// Iterate over all entries in the hash table
void iterate_hash_table(hash_table* ht, void (*callback)(data_entry*)) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        data_entry* entry = (data_entry*)ht->entries[i];
        while (entry) {
            callback(entry);
            entry = ((data_entry*)ht->entries[i])->next;
        }
    }
}
