#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct record {
    int key;
    long offset;
} Record;

typedef struct node {
    Record record;
    struct node* prev;
    struct node* next;
} Node;

Node* create_node(int key, long offset) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->record.key = key;
    node->record.offset = offset;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void insert_node(Node** head, int key, long offset) {
    Node* new_node = create_node(key, offset);
    if (*head == NULL) {
        *head = new_node;
        new_node->prev = NULL;
        new_node->next = NULL;
    } else {
        new_node->next = *head;
        (*head)->prev = &new_node;
        *head = new_node;
    }
}

Record* search_list(Node* head, int key) {
    Node* current = head;
    while (current != NULL) {
        if (current->record.key == key) {
            return &current->record;
        }
        current = current->next;
    }
    return NULL;
}
