  authService.authenticate().then(() => {
    // send logs to the external service
  });
};

const handleErrors = (test) => {
  return test().catch((error) => {
    console.error(error);
    // mark for attention and log separately
  });
};

const runTestsInParallel = (tests, concurrencyLimit) => {
  const queue = [];
  let activeCount = 0;
  tests.forEach((test) => {
    queue.push(test());
  });
  return new Promise((resolve) => {
    (function loop() {
      if (activeCount < concurrencyLimit) {
        activeCount++;
        const test = queue.shift();
        test.then(() => {
          activeCount--;
          loop();
        }).catch((error) => {
          console.error(error);
          activeCount--;
          loop();
        });
      } else {
        setTimeout(() => {
          resolve();
        }, 0);
      }
    })();
  });
};

const configureTestSuite = () => {
  // implement test suite configuration
  const config = require('./test-config.json');
  return config;
};

