// Node structure for linked list
typedef struct node {
    record* data;
    struct node* next;
} node;

// Function to manage dynamic memory allocation
int* manageMemory(int numRecords) {
    // Initialize pointers and variables
    long* offsets = NULL;
    int* keys = NULL;
    record** records = NULL;
    node* head = NULL;
    node* current = NULL;
    int failureCount = 0;

    while (failureCount < 3) {
        try {
            // Allocate memory for offsets, keys, and records
            offsets = (long*)malloc(numRecords * sizeof(long));
            keys = (int*)malloc(numRecords * sizeof(int));
            records = (record**)malloc(numRecords * sizeof(record*));

            // Initialize linked list
            head = NULL;
            current = NULL;

            break;
        } catch (error) {
            if (failureCount < 2) {
                // Log error and attempt to reallocate
                printf("Error: Memory allocation failed. Attempting to reallocate...\n");
                free(offsets);
                free(keys);
                free(records);

                numRecords /= 2; // Reduce record count for next attempt

                continue;
            } else {
                // Log final error and return failure indicator
                printf("Fatal error: Unable to allocate memory. Returning failure.\n");
                return -1;
            }
        }
    }

    // Initialize key values
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        keys[i] = rand() % 100 + 1;
    }

    // Create record structures and initialize data
    for (int i = 0; i < numRecords; i++) {
        records[i] = (record*)malloc(sizeof(record));
        records[i]->value = rand() % 100 + 1;
    }

    return 0;
}

// Function to update key for a specific record
void updateKey(int* keys, int index, int newKey) {
    // Check if the index is within valid range
    if (index < 0 || index >= sizeof(keys) / sizeof(*keys)) {
        printf("Error: Index out of bounds.\n");
        return;
    }

    keys[index] = newKey;
}

// Function to retrieve current key for a given index
int getCurrentKey(int* keys, int index) {
    // Check if the index is within valid range
    if (index < 0 || index >= sizeof(keys) / sizeof(*keys)) {
        printf("Error: Index out of bounds.\n");
        return -1;
    }

    return keys[index];
}

// Function to create a new node and add it to the linked list
void addNode(node** head, record* data) {
    // Create new node
    node* newNode = (node*)malloc(sizeof(node));
    newNode->data = data;

    if (*head == NULL) {
        *head = newNode;
    } else {
        current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
}

// Function to undo changes in the record structure and its associated keys
void undo(int* keys, record** records, node* head) {
    // Create a copy of the original key values
    int* origKeys = (int*)malloc(sizeof(int) * sizeof(keys));
    memcpy(origKeys, keys, sizeof(int) * sizeof(keys));

    // Revert changes to key values and record structures
    for (int i = 0; i < sizeof(keys) / sizeof(*keys); i++) {
        records[i]->value = origKeys[i];
    }

    // Revert changes in the linked list
    node* current = head;
    while (current != NULL) {
        free(current->data);
        current = current->next;
    }
    free(head);

    // Free allocated memory
    free(origKeys);
}
