};

// Class managing a dynamic list of 'Item's with customizable growth policy and cache subsystem
class DynamicList {
public:
    // Constructor
    DynamicList(size_t initialCapacity, size_t initialSize);

    // Destructor
    ~DynamicList();

    // Add an item to the end of the list
    void add(const Item& item);

    // Get the current size of the list
    size_t size() const;

    // Clear the list
