    class Cache {
    public:
        Cache(size_t cacheSize);
        ~Cache();

        // Add an item to the cache
        void add(const Item& item);

        // Get the most recently used item from the cache
        Item getMostRecentlyUsedItem();

        // Evict the least recently used item from the cache if it exceeds the maximum size
        void evict();

