// Linked list node for events
class Node {
public:
    Event event;
    Node* next;
};

// Thread-safe linked list for events
class EventList {
private:
    mutex mtx;
    condition_variable cv;
    Node* head;
    int size;

public:
    EventList() : head(nullptr), size(0) {}

    void addEvent(Event e) {
        unique_lock<mutex> lock(mtx);
        Node* newNode = new Node();
        newNode->event = e;
        newNode->next = head;
        head = newNode;
        size++;
        cv.notify_all();
    }

    Event getFirstEvent() {
        unique_lock<mutex> lock(mtx);
        if (head == nullptr) return Event();
        Event e = head->event;
        delete head;
        head = head->next;
        size--;
        return e;
    }
};

