// Class for caching subsystem using LRU eviction policy
class Cache {
public:
    // Constructor to initialize cache size and max load factor
    Cache(size_t cacheSize, double maxLoadFactor) : 
        cacheSize_(cacheSize), 
        maxLoadFactor_(maxLoadFactor),
        cacheHitCount_(0),
        cacheMissCount_(0),
        cacheLoadFactor_(0.0f) {}

    // Method to add an item to the cache
    void addItem(const std::string& key, const Item& item) {
        if (cache_.find(key) != cache_.end()) {
            return;  // Already in cache, do nothing
        }

        if (cacheLoadFactor_ + 1.0f / cacheSize_ > maxLoadFactor_) {
            evictItem();  // LRU eviction policy
        }

        cache_[key] = item;
    }

    // Method to get an item from the cache or calculate it on demand
    Item getItem(const std::string& key) {
        auto itemIt = cache_.find(key);
        if (itemIt != cache_.end()) {
            cacheHitCount_++;
            return itemIt->second;
        } else {
            cacheMissCount_++;
            // Calculate the item on demand and add it to cache
            Item item;
            // ... calculate item ...
            addItem(key, item);
            return item;
        }
    }

private:
    size_t cacheSize_;
    double maxLoadFactor_;
    uint64_t cacheHitCount_;
    uint64_t cacheMissCount_;
    double cacheLoadFactor_;
    std::unordered_map<std::string, Item> cache_;

    // Method to evict an LRU item from the cache
    void evictItem() {
        if (cache_.empty()) return;  // No items in cache

        auto it = cache_.begin();
        for (auto endIt = cache_.end(); it != endIt; ++it) {
            if (!it->second.strRep.empty()) break;
        }
        cache_.erase(it);
    }
};

