// LRU caching mechanism
class LRUCache {
public:
    LRUCache(size_t capacity) : capacity_(capacity), cache_{} {}

    void put(const Item& item) {
        if (cache_.size() >= capacity_) {
            // Evict least recently used item
            auto it = cache_.begin();
            cache_.erase(it);
        }
        cache_[item.strRepresentation] = item;
    }

    bool get(const std::string& key, Item& result) {
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            // Mark as recently used
            cache_[key] = result;
            return true;
        }
        return false;
    }

private:
    size_t capacity_;
    std::unordered_map<std::string, Item> cache_;
};

