typedef struct {
    int val;
} record_t;

record_t* records = NULL;
long* offsets = NULL;
int* keys = NULL;
size_t record_count = 0;

char* compute_hashes(const char* file_path) {
    FILE* file = fopen(file_path, "rb");
    if (file == NULL) {
        return NULL; // Error handling
    }

    uint8_t buffer[65536]; // Chunk size for efficient reading
    size_t total_bytes_read = 0;

    while (fread(buffer, 1, sizeof(buffer), file)) {
        total_bytes_read += fread(buffer, 1, sizeof(buffer), file);

        // Initialize and populate records array
        record_count++;
        records = realloc(records, record_count * sizeof(record_t));
        for (size_t i = 0; i < record_count - 1; i++) {
            records[i].val = rand() % 100 + 1; // Random value within range [1, 100]
        }
        records[record_count - 1].val = rand() % 100 + 1;

        // Compute MD5 and SHA-256 hashes
        uint8_t* hash_data = malloc(total_bytes_read);
        memcpy(hash_data, buffer, total_bytes_read);
        uint8_t md5_hash[MD5_DIGEST_LENGTH];
        uint8_t sha256_hash[SHA256_DIGEST_LENGTH];
        MD5_CTX ctx;
        SHA256_CTX sctx;
        MD5_Init(&ctx);
        SHA256_Init(&sctx);
        for (size_t i = 0; i < total_bytes_read; i++) {
            MD5_Update(&ctx, &hash_data[i], 1);
            SHA256_Update(&sctx, &hash_data[i], 1);
        }
        MD5_Final(md5_hash, &ctx);
        SHA256_Final(sha256_hash, &sctx);
        free(hash_data);

        // Verify hashes match expected values
        uint8_t* expected_md5 = malloc(MD5_DIGEST_LENGTH);
        uint8_t* expected_sha256 = malloc(SHA256_DIGEST_LENGTH);
        fread(expected_md5, 1, MD5_DIGEST_LENGTH, file);
        fread(expected_sha256, 1, SHA256_DIGEST_LENGTH, file);

        bool hashes_match = (memcmp(md5_hash, expected_md5, MD5_DIGEST_LENGTH) == 0 &&
                             memcmp(sha256_hash, expected_sha256, SHA256_DIGEST_LENGTH) == 0);
        free(expected_md5);
        free(expected_sha256);

        // Log processing status
        printf("Processed %zu bytes, computed hashes: MD5 - %02x%02x%02x%02x%02x%02x%02x%02x, SHA-256 - %02x%02x%02x%02x%02x%02x%02x%02x\n",
               total_bytes_read, md5_hash[0], md5_hash[1], md5_hash[2], md5_hash[3],
               sha256_hash[0], sha256_hash[1], sha256_hash[2], sha256_hash[3], sha256_hash[4],
               sha256_hash[5], sha256_hash[6], sha256_hash[7]);
    }

    fclose(file);
    return (hashes_match ? "MATCH" : "MISMATCH");
}
