    if (new_num_records > 0 && new_num_records < MAX_RECORDS) {
        int *temp_record_array = malloc(sizeof(record)*new_num_records);
        for (int i = 0; i < new_num_records; i++) {
            temp_record_array[i].key = record_array[i].key;
        }
        record_array = realloc(record_array, sizeof(record)*new_num_records);
        memcpy(record_array, temp_record_array, sizeof(record)*new_num_records);
        free(temp_record_array);
    }
}

int main() {
    int num_records = 1000;
    int *record_array = malloc(sizeof(record)*num_records);

    // Initialize matrix with zeros
    int **offsets = malloc(sizeof(long*)*num_records);
    int **keys = malloc(sizeof(int*)*num_records);
    init_matrix(offsets, keys, record_array, num_records);

