        }
    }
}

void adjust_memory_usage(float* total_used, float max_threshold) {
    // Monitor and adjust memory usage
    while (*total_used > max_threshold) {
        free((*arr_float));
        *arr_float = (float*)malloc((int)(*total_used / 2.0f) * sizeof(float));
        *total_used /= 2.0f;
    }
}

void load_data(float** arr_float, char*** arr_char, record_t*** arr_record, int* config) {
    // Load data from pre-defined dataset file
    FILE* file = fopen("data.txt", "rb");
    if (file == NULL) return;

    // Read and store data
    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);
    fread(*arr_float, sizeof(float), *config[0] * *config[1], file);
    fread((*arr_char)[0], sizeof(char), *config[2] * *config[3], file);

    fclose(file);
}

void update_config(int* config) {
    // Update configuration parameters
    if (config[4] > 0) {
        // Add new dimensions to tensors
        int new_size = config[4];
        float** arr_float_new = (float*)malloc(new_size * sizeof(float));
        char*** arr_char_new = (char**)malloc(config[2] * sizeof(char*));
