}

void convert_labels(char** arr_char, int* config) {
    // Convert labels from one system to another
    char* mapping = "mapping.txt";
    FILE* file = fopen(mapping, "rb");
    if (file == NULL) return;

    fread(arr_char, sizeof(char), *config[2] * *config[3], file);
}

void cleanup(float** arr_float, char*** arr_char, record_t*** arr_record) {
    // Clean up allocated memory
    free(*arr_float);
    for (int i = 0; i < *config[2]; i++) {
        free((*arr_char)[i]);
    }
    free(*arr_char);
    for (int i = 0; i < *config[0] * *config[1]; i++) {
        free(&((*arr_record)[i]));
    }
    free(*arr_record);
}

void main_function(int* config) {
    float* arr_float;
    char** arr_char;
    record_t** arr_record;

    init_arrays(config, &arr_float, &arr_char, &arr_record);

    // Monitor and adjust memory usage
    float total_used = 0.0f;
    while (total_used < *config[5]) {
        load_data(&arr_float, &arr_char, &arr_record, config);
        total_used += (float)(*config[4]);
    }

    // Update configuration parameters dynamically
    update_config(config);

    // Convert labels from one system to another
    convert_labels(arr_char, config);

    // Clean up allocated memory
    cleanup(&arr_float, &arr_char, &arr_record);
}
