void* GraphDynamicEntryManager(void* config_params) {
    // Initialize configuration parameters from the input void pointer
    ConfigParams* params = (ConfigParams*)config_params;

    // Allocate memory for offset values, keys, and records
    long* offset_values = NULL;
    int* keys = NULL;
    Record** records = NULL;

    try {
        offset_values = (long*)malloc(params->num_offset_values * sizeof(long));
        keys = (int*)malloc(params->num_keys * sizeof(int));
        records = (Record**)malloc(params->num_records * sizeof(Record*));

        // Initialize offset values and keys
        for (int i = 0; i < params->num_offset_values; i++) {
            offset_values[i] = rand() % (params->record_value_range_max - params->record_value_range_min + 1) + params->record_value_range_min;
        }

        for (int i = 0; i < params->num_keys; i++) {
            keys[i] = rand() % (params->record_value_range_max - params->record_value_range_min + 1) + params->record_value_range_min;
        }

        // Initialize records
        for (int i = 0; i < params->num_records; i++) {
            records[i] = (Record*)malloc(sizeof(Record));
            records[i]->value = rand() % (params->record_value_range_max - params->record_value_range_min + 1) + params->record_value_range_min;
        }

        // Free any partially allocated resources in case of memory allocation failure
        free(offset_values);
        free(keys);
        free(records);

        return NULL; // Return success status
    } catch (const std::runtime_error& e) {
        // Handle memory allocation failures by returning an error status and cleaning up partially allocated resources
        if (offset_values) free(offset_values);
        if (keys) free(keys);
        if (records) {
            for (int i = 0; i < params->num_records; i++) {
