#include <time.h>

typedef struct {
    float x;
    float y;
} Point;

typedef struct {
    Point start;
    Point end;
} LineSegment;

void* mem_pool = NULL;
size_t pool_size = 0;

double calculate_segment_length(const Point* p1, const Point* p2) {
    double dx = (p2->x - p1->x);
    double dy = (p2->y - p1->y);
    return sqrt((dx * dx) + (dy * dy));
}

int init_memory_pool(size_t size) {
    if (!mem_pool && !size) {
        mem_pool = malloc(0);
        pool_size = 0;
    } else if (!mem_pool) {
        mem_pool = malloc(size);
        pool_size = size;
    }
    return (mem_pool != NULL);
}

void* alloc_record(int key, long offset) {
    void* record = mem_pool;
    if (!record || !pool_size) {
        record = malloc(sizeof(int) + sizeof(long));
        *(((int*)record)) = key;
        *(long*)((char*)record + sizeof(int)) = offset;
        pool_size -= sizeof(int) + sizeof(long);
    }
    return record;
}

void free_record(void* record) {
    if (record) {
        mem_pool = ((char*)mem_pool) + sizeof(int) + sizeof(long);
        pool_size += sizeof(int) + sizeof(long);
        free(record);
    }
}

int main() {
    srand(time(NULL));

    // Initialize memory pool
    init_memory_pool(1024 * 1024); // Start with a reasonable size

    for (int i = 0; i < 10000; i++) {
        int key = rand() % 100;
        long offset = rand();
        void* record = alloc_record(key, offset);
        printf("Allocated memory: %p, Key: %d, Offset: %ld\n", record, key, offset);

        Point p1 = (Point){(float)rand() / RAND_MAX, (float)rand() / RAND_MAX};
        Point p2 = (Point){(float)rand() / RAND_MAX, (float)rand() / RAND_MAX};
        LineSegment segment = (LineSegment){p1, p2};
        double length = calculate_segment_length(&segment.start, &segment.end);
        printf("Segment length: %.2f\n", length);

        free_record(record);
    }

    return 0;
}
