#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <resolv.h>

#define MAX_DOMAINS 1000
#define MAX_IPADDR_LENGTH 50
#define MAX_HOSTNAME_LENGTH 256

typedef struct {
    char *domain;
    char *ipaddr;
} domain_ip_t;

int resolve_dns(const char *hostname, char **allowed_domains) {
    // Perform DNS resolution using gethostbyname()
    struct hostent *host = gethostbyname(hostname);
    if (host == NULL)
        return -1; // Error resolving hostname

    for (int i = 0; i < MAX_DOMAINS; i++) {
        if (strcasecmp(allowed_domains[i], host->h_name) == 0) {
            char ipaddr[MAX_IPADDR_LENGTH];
            inet_ntop(AF_INET, &host->h_addr_list[0], ipaddr, sizeof(ipaddr));
            return 1; // Successfully resolved hostname
        }
    }

    return -2; // Hostname not found in allowed domains
}

void process_file(const char *filename, int max_threshold_kb) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL)
        return; // Error opening file

    char buffer[1024];
    int lines_processed = 0;
    int total_memory_used = 0;

    while (fgets(buffer, sizeof(buffer), fp)) {
        char *line = strdup(buffer);
        if (line == NULL) {
            fprintf(stderr, "Error allocating memory for line.\n");
            continue; // Skip invalid line
        }

        int num_fields = 1;
        double sum = 0.0;

        for (char *p = buffer; *p != '\0'; p++) {
            if (*p == ',') {
                num_fields++;
                break;
            }
        }

        for (int i = num_fields - 2; i >= 0; i--) {
            char *field = strtok(line, ",");
            while (field) {
                int val = atoi(field);
                sum += val;
                if (errno != 0 || val < 0)
                    break; // Invalid numeric value
                field = strtok(NULL, ",");
            }
        }

        double avg = sum / num_fields;
        printf("%s,%lf\n", line, avg);

        free(line);

        lines_processed++;
        total_memory_used += strlen(buffer) + 1;

        if (total_memory_used > max_threshold_kb * 1024)
            break; // Exceeded memory threshold
    }

    fclose(fp);
}

int main() {
    const char *allowed_domains[] = {"example.com", "anotherdomain.net"};
    int num_allowed_domains = sizeof(allowed_domains) / sizeof(allowed_domains[0]);

    // Initialize DNS resolution
    for (int i = 0; i < num_allowed_domains; i++) {
        domain_ip_t *dp = malloc(sizeof(domain_ip_t));
        dp->domain = strdup(allowed_domains[i]);
        // Perform DNS resolution and store IP address
        char *ipaddr = malloc(MAX_IPADDR_LENGTH);
        int status = resolve_dns(dp->domain, allowed_domains);
        if (status == 1) {
            inet_ntop(AF_INET, &dp->ipaddr, ipaddr, sizeof(ipaddr));
            dp->ipaddr = strdup(ipaddr);
        } else
            free(ipaddr);

        // Store DNS resolution result
        printf("Domain: %s, IP Address: %s\n", dp->domain, dp->ipaddr);
    }

    for (int i = 0; i < num_allowed_domains; i++) {
        free(allowed_domains[i]);
        free(dp->domain);
        free(dp->ipaddr);
        free(dp);
    }

    // Process file
    process_file("data.txt", 100);

    return 0;
}
