    int num_lists = 0;
    while (num_lists < MAX_LISTS && fgets(line, sizeof(line), stdin)) {
        lists[num_lists].size = 0;
        lists[num_lists].ints = malloc(MAX_INTS_PER_LIST * sizeof(int));
