        double sum = 0.0;
        for (size_t i = 0; i < dataSize && i < 10; i++) {
            sum += (*events.front())->data[i];
        }
        return sum / 10.0;
    }

    double computeMaxLast Fifteen(int id) {
        size_t dataSize = idToDataSize.at(id);
        double max = -INFINITY;
        for (size_t i = 0; i < dataSize && i < 15; i++) {
            if ((*events.front())->data[i] > max) {
