    if (!records) return NULL; // Handle memory allocation failure
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 100; // Set random value within range [0, 99]
    }
    return records;
}

void* addVertexAndEdge(void* config) {
    struct {
        int maxMemoryUsageInKB;
        int numRecords;
        int vertexKeyRangeMin;
        int vertexKeyRangeMax;
        int edgeKeyRangeMin;
        int edgeKeyRangeMax;
    } *configData = (struct *)config;

    // Initialize memory for arrays
    long* vertexOffsets = (long*)malloc(configData->numRecords * sizeof(long));
    int* vertexKeys = (int*)malloc(configData->numRecords * sizeof(int));
    record_t* records = initializeRecords(configData->numRecords);

    // Dynamic configuration adjustments
    while (1) {
        printf("Enter new value for max memory usage in KB (or -1 to quit): ");
        int newMaxMemoryUsageInKB;
        scanf("%d", &newMaxMemoryUsageInKB);
        if (newMaxMemoryUsageInKB == -1) break;

        // Update configuration and reallocate memory as needed
        configData->maxMemoryUsageInKB = newMaxMemoryUsageInKB;
        free(vertexOffsets);
        free(vertexKeys);

        vertexOffsets = (long*)malloc((configData->numRecords + 100) * sizeof(long));
        vertexKeys = (int*)malloc((configData->numRecords + 100) * sizeof(int));

        // Reset records
        records = initializeRecords(configData->numRecords);
    }

    free(records);
    free(vertexOffsets);
    free(vertexKeys);

    return NULL;
}

void convertKeyToExistingSystem(int key, char* outputBuffer) {
    // Map between current system's key type and existing system's data structure
    sprintf(outputBuffer, "%d", key);
}

