    pthread_t thread;

    // Initialize configuration parameters
    struct {
        int maxMemoryUsageInKB;
        int numRecords;
        int vertexKeyRangeMin;
        int vertexKeyRangeMax;
        int edgeKeyRangeMin;
        int edgeKeyRangeMax;
    } config = {0, 10000, 1, 100, 101, 200};

    // Start thread for concurrent updates
