    {
        await _repository.LockoutUserAsync(username);

        if (isManualReviewRequired)
            await LogAuditEventAsync("Manual review required for locked out user", username);
    }
}

public class UserAccountController : Controller
{
    private readonly IUserAccountService _service;

    public UserAccountController(IUserAccountService service, IThreatIntelligenceService threatIntelligenceService)
    {
        _service = service;
        _threatIntelligenceService = threatIntelligenceService;
    }

    [HttpPost]
    public async Task<IActionResult> LoginAsync(LoginModel model)
