```java
import java.util.*;
import java.io.*;

public class DistributedMap<K, V> extends AbstractMap<K, V> {
    private Map<K, V> map;
    private Map<K, V> cache;

    public DistributedMap(int maxSize, int growthRate) {
        map = new LinkedHashMap<K, V>(maxSize, 0.75f, true);
        cache = new LRUHashMap<K, V>(maxSize, growthRate);
    }

    @Override
    public void put(K key, V value) {
        if (!map.containsKey(key)) {
            map.put(key, value);
            cache.put(key, value);
        }
    }

    @Override
    public V get(Object key) {
        K k = (K) key;
        return cache.getOrDefault(k, map.getOrDefault(k, null));
    }

    @Override
    public void clear() {
        map.clear();
        cache.clear();
    }

    private class LRUHashMap<K, V> extends LinkedHashMap<K, V> {
        private int maxSize;

        public LRUHashMap(int maxSize, int growthRate) {
            super(maxSize / 10, 0.75f, true);
            this.maxSize = maxSize;
        }

        @Override
        protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            if (size() > maxSize && size() >= maxSize / 2) {
                return false;
            }
            return super.removeEldestEntry(eldest);
        }
    }
}

import org.apache.commons.pool2.PooledObject;
import org.apache.commons.pool2.impl.GenericObjectPool;

public class DistributedMapPool {
    private GenericObjectPool<DistributedMap> pool;

    public DistributedMapPool(int maxSize, int growthRate) {
        pool = new GenericObjectPool<>(new DistributedMapFactory(maxSize, growthRate));
    }

    public PooledObject<DistributedMap> borrowObject() throws Exception {
        return pool.borrowObject();
    }
}

