import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class EntityIngestionService {
    private ExecutorService executor;

    public EntityIngestionService(int numThreads) {
        executor = Executors.newFixedThreadPool(numThreads);
    }

    public void ingestEntities(EntityProcessor[] processors, List<Runnable> tasks) {
        for (int i = 0; i < tasks.size(); i++) {
            Runnable task = tasks.get(i);
            executor.submit(() -> task.run());
        }
    }
}

import java.util.concurrent.locks.ReentrantLock;
import java.util.concurrent.locks.Lock;

public class PredictiveAnalyticsModel {
    private Lock lock;
    private Map<String, Double> forecastMap;

    public PredictiveAnalyticsModel() {
        lock = new ReentrantLock();
        forecastMap = new HashMap<>();
    }

    public void train(Map<String, List<Double>> data) {
        lock.lock();
        try {
            for (String entityId : data.keySet()) {
                List<Double> values = data.get(entityId);
                // implement training logic
                forecastMap.put(entityId, calculateForecast(values));
            }
        } finally {
            lock.unlock();
        }
    }

    public Double getForecast(String entityId) {
        return forecastMap.getOrDefault(entityId, null);
    }
}

