public class ResourceMonitoringService {
    private ScheduledExecutorService scheduler;
    private Map<String, Long> resourceUsage;

    public ResourceMonitoringService(int pollingInterval) {
        scheduler = Executors.newSingleThreadScheduledExecutor();
        resourceUsage = new HashMap<>();
        scheduler.scheduleAtFixedRate(() -> {
            // implement monitoring logic
            for (String resourceId : resourceUsage.keySet()) {
                long usage = getUsage(resourceId);
                resourceUsage.put(resourceId, usage);
            }
        }, 0, TimeUnit.SECONDS.toMillis(pollingInterval), TimeUnit.MILLISECONDS);
    }

    public void startMonitoring() {
        scheduler.start();
    }

    public void stopMonitoring() {
        scheduler.shutdown();
    }
}

import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.Lock;

public class SelfHealingService {
    private Lock lock;
    private Condition condition;

    public SelfHealingService() {
        lock = new ReentrantLock();
        condition = lock.newCondition();
    }

    public void startSelfHealing() {
        lock.lock();
        try {
            while (true) {
                // implement self-healing logic
                if (isTransientFailure()) {
                    recoverFromFailure();
                    condition.signalAll();
                }
                lock.unlock();
                Thread.sleep(1000);
                lock.lock();
            }
        } finally {
            lock.unlock();
        }
    }

    public void awaitRecovery() throws InterruptedException {
        lock.lock();
        try {
            condition.await();
        } finally {
            lock.unlock();
        }
    }
}
