Node* init_linked_list() {
    Node* head = create_node(sizeof(int));
    head->data = &((int*)1);  // placeholder data
    return head;
}

void add_node(Node** head, void* data) {
    Node* new_node = create_node(strlen(data) + 1);
    new_node->data = data;
    if (*head == NULL) *head = new_node;
    else {
        Node* current = *head;
        while (current->next) current = current->next;
        current->next = new_node;
    }
}

void remove_node(Node** head, void* data) {
    if (*head == NULL) return;
    Node* current = *head;
    Node* prev = NULL;
    while (current && current->data != data) {
        prev = current;
        current = current->next;
    }
    if (current) {
        if (prev) prev->next = current->next;
        else *head = current->next;
        destroy_node(current);
    }
}

void traverse_list(Node* head, void (*callback)(Node*, void*)) {
    Node* current = head;
    while (current) {
        callback(current, current->data);
        current = current->next;
    }
}
